window.SHAKESPEARE_CHINESE["part0031"]={"id":"part0031","title":"科利奥兰纳斯","translator":"朱生豪","translatorCredit":"朱生豪 译","attributionStatus":"explicit","kind":"play","englishId":"coriolanus","sections":[{"id":"part0031-section-000","label":"书前与人物","kind":"preface","blocks":[{"id":"part0031-00000","html":"\n\u003ch2 id=\"epub-part0031-a721\" class=\"epub-calibre15\">科利奥兰纳斯\u003c/h2>\n","text":"\n科利奥兰纳斯\n","sourceAnchor":"a721","tag":"h2"},{"id":"part0031-00001","html":"\u003cp class=\"epub-center\">朱生豪 译\u003c/p>\n","text":"朱生豪 译\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00002","html":"\u003cp class=\"epub-center\">方重 校\u003c/p>\n","text":"方重 校\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00003","html":"\u003cp class=\"epub-center\">\u003cimg src=\"data/chinese-collection/images/00151.jpeg\" alt=\"\" loading=\"lazy\" class=\"epub-calibre2 epub-image\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00004","html":"\u003cp class=\"epub-center\">\u003cb class=\"epub-calibre3\">剧中人物\u003c/b>\u003c/p>\n","text":"剧中人物\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00005","html":"\u003cp class=\"epub-calibre1\">卡厄斯·马歇斯 后称卡厄斯·马歇斯·科利奥兰纳斯\u003c/p>\n","text":"卡厄斯·马歇斯 后称卡厄斯·马歇斯·科利奥兰纳斯\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00006","html":"\u003cp class=\"epub-center\">\u003cimg src=\"data/chinese-collection/images/00152.jpeg\" alt=\"\" loading=\"lazy\" class=\"epub-calibre2 epub-image\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00007","html":"\u003cp class=\"epub-calibre1\">米尼涅斯·阿格立巴 科利奥兰纳斯之友\u003c/p>\n","text":"米尼涅斯·阿格立巴 科利奥兰纳斯之友\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00008","html":"\u003cp class=\"epub-center\">\u003cimg src=\"data/chinese-collection/images/00153.jpeg\" alt=\"\" loading=\"lazy\" class=\"epub-calibre2 epub-image\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00009","html":"\u003cp class=\"epub-calibre1\">小马歇斯 科利奥兰纳斯之子\u003c/p>\n","text":"小马歇斯 科利奥兰纳斯之子\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00010","html":"\u003cp class=\"epub-calibre1\">罗马传令官\u003c/p>\n","text":"罗马传令官\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00011","html":"\u003cp class=\"epub-calibre1\">塔勒斯·奥菲狄乌斯 伏尔斯人的大将\u003c/p>\n","text":"塔勒斯·奥菲狄乌斯 伏尔斯人的大将\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00012","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯的副将\u003c/p>\n","text":"奥菲狄乌斯的副将\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00013","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯的党羽们\u003c/p>\n","text":"奥菲狄乌斯的党羽们\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00014","html":"\u003cp class=\"epub-calibre1\">尼凯诺 罗马人\u003c/p>\n","text":"尼凯诺 罗马人\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00015","html":"\u003cp class=\"epub-calibre1\">安息市民\u003c/p>\n","text":"安息市民\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00016","html":"\u003cp class=\"epub-calibre1\">阿德里安 伏尔斯人\u003c/p>\n","text":"阿德里安 伏尔斯人\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00017","html":"\u003cp class=\"epub-calibre1\">二伏尔斯守卒\u003c/p>\n","text":"二伏尔斯守卒\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00018","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00019","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 科利奥兰纳斯之母\u003c/p>\n","text":"伏伦妮娅 科利奥兰纳斯之母\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00020","html":"\u003cp class=\"epub-calibre1\">维吉利娅 科利奥兰纳斯之妻\u003c/p>\n","text":"维吉利娅 科利奥兰纳斯之妻\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00021","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 维吉利娅之友\u003c/p>\n","text":"凡勒利娅 维吉利娅之友\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00022","html":"\u003cp class=\"epub-calibre1\">维吉利娅的侍女\u003c/p>\n","text":"维吉利娅的侍女\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00023","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00024","html":"\u003cp class=\"epub-calibre1\">罗马及伏尔斯元老、贵族、警吏、侍卫、兵士、市民、使者、奥菲狄乌斯的仆人及其他侍从等\u003c/p>\n","text":"罗马及伏尔斯元老、贵族、警吏、侍卫、兵士、市民、使者、奥菲狄乌斯的仆人及其他侍从等\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00025","html":"\u003cp class=\"epub-center\">\u003cb class=\"epub-calibre3\">地点\u003c/b>\u003c/p>\n","text":"地点\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00026","html":"\u003cp class=\"epub-center\">罗马及其附近；科利奥里及其附近；安息\u003c/p>\n","text":"罗马及其附近；科利奥里及其附近；安息\n","sourceAnchor":null,"tag":"p"}]},{"id":"part0031-section-001","label":"第一幕","kind":"act","blocks":[{"id":"part0031-00027","html":"\u003ch3 id=\"epub-part0031-a722\" class=\"epub-calibre11\">第一幕\u003c/h3>\n","text":"第一幕\n","sourceAnchor":"a722","tag":"h3"}],"heading":"第一幕","headingLevel":3,"sourceAnchor":"a722","actNumber":1},{"id":"part0031-section-002","label":"第一幕 · 第一场 罗马。街道","kind":"scene","blocks":[{"id":"part0031-00028","html":"\u003ch4 id=\"epub-part0031-a723\" class=\"epub-calibre12\">第一场 罗马。街道\u003c/h4>\n","text":"第一场 罗马。街道\n","sourceAnchor":"a723","tag":"h4"},{"id":"part0031-00029","html":"\u003cp class=\"epub-block1\">一群暴动的市民各持棍棒及其他武器上。\u003c/p>\n","text":"一群暴动的市民各持棍棒及其他武器上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00030","html":"\u003cp class=\"epub-calibre1\">市民甲 在我们继续前进之前，先听我说句话。\u003c/p>\n","text":"市民甲 在我们继续前进之前，先听我说句话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00031","html":"\u003cp class=\"epub-calibre1\">众人 说，说。\u003c/p>\n","text":"众人 说，说。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00032","html":"\u003cp class=\"epub-calibre1\">市民甲 你们都下了决心，宁愿死，不愿挨饿吗？\u003c/p>\n","text":"市民甲 你们都下了决心，宁愿死，不愿挨饿吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00033","html":"\u003cp class=\"epub-calibre1\">众人 我们都下了决心了，我们都下了决心了。\u003c/p>\n","text":"众人 我们都下了决心了，我们都下了决心了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00034","html":"\u003cp class=\"epub-calibre1\">市民甲 第一，你们知道卡厄斯·马歇斯是人民的最大公敌。\u003c/p>\n","text":"市民甲 第一，你们知道卡厄斯·马歇斯是人民的最大公敌。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00035","html":"\u003cp class=\"epub-calibre1\">众人 我们知道，我们知道。\u003c/p>\n","text":"众人 我们知道，我们知道。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00036","html":"\u003cp class=\"epub-calibre1\">市民甲 让我们杀死他，然后我们要多少谷就有多少谷。我们就这样决定了吗？\u003c/p>\n","text":"市民甲 让我们杀死他，然后我们要多少谷就有多少谷。我们就这样决定了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00037","html":"\u003cp class=\"epub-calibre1\">众人 不用多说；就这么干。走，走！\u003c/p>\n","text":"众人 不用多说；就这么干。走，走！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00038","html":"\u003cp class=\"epub-calibre1\">市民乙 各位好市民，听我说一句话。\u003c/p>\n","text":"市民乙 各位好市民，听我说一句话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00039","html":"\u003cp class=\"epub-calibre1\">市民甲 我们都是苦百姓，贵族才是好市民。那些有权有势的人吃饱了，装不下的东西就可以救济我们。他们只要把吃剩下来的东西趁着新鲜的时候赏给我们，我们就会以为他们是出于人道之心来救济我们；可是在他们看来，我们都是不值得救济的。我们的痛苦饥寒，我们的枯瘦憔悴，就像是列载着他们的富裕的一张清单；他们享福就是靠了我们受苦。让我们举起我们的武器来复仇，趁我们还没有瘦得只剩几根骨头。天神知道我说这样的话，只是迫于没有面包吃的饥饿，不是因为渴于复仇。\u003c/p>\n","text":"市民甲 我们都是苦百姓，贵族才是好市民。那些有权有势的人吃饱了，装不下的东西就可以救济我们。他们只要把吃剩下来的东西趁着新鲜的时候赏给我们，我们就会以为他们是出于人道之心来救济我们；可是在他们看来，我们都是不值得救济的。我们的痛苦饥寒，我们的枯瘦憔悴，就像是列载着他们的富裕的一张清单；他们享福就是靠了我们受苦。让我们举起我们的武器来复仇，趁我们还没有瘦得只剩几根骨头。天神知道我说这样的话，只是迫于没有面包吃的饥饿，不是因为渴于复仇。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00040","html":"\u003cp class=\"epub-calibre1\">市民乙 你特别提出卡厄斯·马歇斯来作为攻击的对象吗？\u003c/p>\n","text":"市民乙 你特别提出卡厄斯·马歇斯来作为攻击的对象吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00041","html":"\u003cp class=\"epub-calibre1\">市民甲 我们第一要攻击他；他是出卖群众的狗。\u003c/p>\n","text":"市民甲 我们第一要攻击他；他是出卖群众的狗。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00042","html":"\u003cp class=\"epub-calibre1\">市民乙 你不想到他替祖国立下了什么功劳吗？\u003c/p>\n","text":"市民乙 你不想到他替祖国立下了什么功劳吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00043","html":"\u003cp class=\"epub-calibre1\">市民甲 我知道得很清楚，我也不愿抹煞他的功劳；可是他因为过于骄傲，已经把他的功劳抵销了。\u003c/p>\n","text":"市民甲 我知道得很清楚，我也不愿抹煞他的功劳；可是他因为过于骄傲，已经把他的功劳抵销了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00044","html":"\u003cp class=\"epub-calibre1\">市民乙 你不要恶意诽谤。\u003c/p>\n","text":"市民乙 你不要恶意诽谤。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00045","html":"\u003cp class=\"epub-calibre1\">市民甲 我对你说，他所做的轰轰烈烈的事情，都只有一个目的：虽然心肠仁厚的人愿意承认那是为了他的国家，其实他只是要取悦于他的母亲，同时使他自己可以对人骄傲；骄傲便是他的美德的顶点。\u003c/p>\n","text":"市民甲 我对你说，他所做的轰轰烈烈的事情，都只有一个目的：虽然心肠仁厚的人愿意承认那是为了他的国家，其实他只是要取悦于他的母亲，同时使他自己可以对人骄傲；骄傲便是他的美德的顶点。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00046","html":"\u003cp class=\"epub-calibre1\">市民乙 他自己也无能为力的天生的癖性，你却认为是他的罪恶。你不能说他是个贪心的人。\u003c/p>\n","text":"市民乙 他自己也无能为力的天生的癖性，你却认为是他的罪恶。你不能说他是个贪心的人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00047","html":"\u003cp class=\"epub-calibre1\">市民甲 要是我不能这样说他，我也不会缺少攻击他的理由；他有数不清的过失，说来也会叫人口酸。\u003cb class=\"epub-calibre3\">（内呼声）\u003c/b>这是什么呼声？城那面的人们也起来了。我们还在这儿多说什么？到议会去！\u003c/p>\n","text":"市民甲 要是我不能这样说他，我也不会缺少攻击他的理由；他有数不清的过失，说来也会叫人口酸。（内呼声）这是什么呼声？城那面的人们也起来了。我们还在这儿多说什么？到议会去！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00048","html":"\u003cp class=\"epub-calibre1\">众人 来，来。\u003c/p>\n","text":"众人 来，来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00049","html":"\u003cp class=\"epub-calibre1\">市民甲 且慢！谁来啦？\u003c/p>\n","text":"市民甲 且慢！谁来啦？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00050","html":"\u003cp class=\"epub-block1\">米尼涅斯·阿格立巴上。\u003c/p>\n","text":"米尼涅斯·阿格立巴上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00051","html":"\u003cp class=\"epub-calibre1\">市民乙 尊贵的米尼涅斯·阿格立巴；他是常常爱护着平民的。\u003c/p>\n","text":"市民乙 尊贵的米尼涅斯·阿格立巴；他是常常爱护着平民的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00052","html":"\u003cp class=\"epub-calibre1\">市民甲 他是个好人；要是别人都像他一样就好了！\u003c/p>\n","text":"市民甲 他是个好人；要是别人都像他一样就好了！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00053","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 同胞们，你们现在要干些什么事？你们拿着这些棍棒到什么地方去？为了什么事？请你们告诉我。\u003c/p>\n","text":"米尼涅斯 同胞们，你们现在要干些什么事？你们拿着这些棍棒到什么地方去？为了什么事？请你们告诉我。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00054","html":"\u003cp class=\"epub-calibre1\">市民甲 我们的事情元老院并不是不知道；他们这半个月来早已得到消息，知道我们将要有什么行动，现在我们就要做给他们看。人家说，穷人诉苦的时候，嘴里会发出一股可怕的气息；我们要让他们知道，我们还有一双可怕的胳臂哩。\u003c/p>\n","text":"市民甲 我们的事情元老院并不是不知道；他们这半个月来早已得到消息，知道我们将要有什么行动，现在我们就要做给他们看。人家说，穷人诉苦的时候，嘴里会发出一股可怕的气息；我们要让他们知道，我们还有一双可怕的胳臂哩。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00055","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 哎哟，列位，我的好朋友们，你们不要活命了吗？\u003c/p>\n","text":"米尼涅斯 哎哟，列位，我的好朋友们，你们不要活命了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00056","html":"\u003cp class=\"epub-calibre1\">市民甲 先生，我们早就没有命活了。\u003c/p>\n","text":"市民甲 先生，我们早就没有命活了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00057","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我告诉你们，朋友们，贵族们对于你们是非常关切的。你们要是把你们的穷困和饥荒归罪政府，还不如举起你们的棍棒来打天；因为这次饥荒是天神的意旨，不是贵族们造成的。政府总是尽心竭力，替你们解除种种重大的困难；你们应该屈膝哀求，不该举手反抗，这才会对你们有好处。唉！灾祸使你们迷失了本性，引导你们到更大的灾祸的路上；你们诽谤着国家的领导者，他们像慈父一样爱护你们，你们却像仇敌一样咒诅他们。\u003c/p>\n","text":"米尼涅斯 我告诉你们，朋友们，贵族们对于你们是非常关切的。你们要是把你们的穷困和饥荒归罪政府，还不如举起你们的棍棒来打天；因为这次饥荒是天神的意旨，不是贵族们造成的。政府总是尽心竭力，替你们解除种种重大的困难；你们应该屈膝哀求，不该举手反抗，这才会对你们有好处。唉！灾祸使你们迷失了本性，引导你们到更大的灾祸的路上；你们诽谤着国家的领导者，他们像慈父一样爱护你们，你们却像仇敌一样咒诅他们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00058","html":"\u003cp class=\"epub-calibre1\">市民甲 爱护我们！真的！他们从来没有爱护过我们：让我们忍受饥寒，他们的仓库里却堆满了谷粒；颁布保护高利贷的法令；每天都在忙着取消那些不利于富人的正当的法律，重新制定束缚穷人的苛酷的条文。我们要是不死在战争里，也会死在他们手里；这就是他们对我们的爱护！\u003c/p>\n","text":"市民甲 爱护我们！真的！他们从来没有爱护过我们：让我们忍受饥寒，他们的仓库里却堆满了谷粒；颁布保护高利贷的法令；每天都在忙着取消那些不利于富人的正当的法律，重新制定束缚穷人的苛酷的条文。我们要是不死在战争里，也会死在他们手里；这就是他们对我们的爱护！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00059","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 你们必须承认你们自己太会恶意猜疑，否则你们就是一群不懂好坏的傻子。我要讲一个有趣的故事给你们听，也许你们已经听见过；可是因为它适合我的目的，我要把它的意思再引申一下。\u003c/p>\n","text":"米尼涅斯 你们必须承认你们自己太会恶意猜疑，否则你们就是一群不懂好坏的傻子。我要讲一个有趣的故事给你们听，也许你们已经听见过；可是因为它适合我的目的，我要把它的意思再引申一下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00060","html":"\u003cp class=\"epub-calibre1\">市民甲 好，我倒要听听，先生；可是你不要以为用一个故事就可以把我们的耻辱蒙混过去。请你讲吧。\u003c/p>\n","text":"市民甲 好，我倒要听听，先生；可是你不要以为用一个故事就可以把我们的耻辱蒙混过去。请你讲吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00061","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 从前有一个时候，身体上的各部器官联合向肚子反抗；它们申斥它像一个无底洞似的占据在身体的中央，无所事事，其余的器官有的管看，有的管听，有的管思想，有的管教训，有的管步行，有的管感觉，分工合作，共同应付着全身的需要，只有它只知容纳食物，不知分担劳苦。肚子回答说——\u003c/p>\n","text":"米尼涅斯 从前有一个时候，身体上的各部器官联合向肚子反抗；它们申斥它像一个无底洞似的占据在身体的中央，无所事事，其余的器官有的管看，有的管听，有的管思想，有的管教训，有的管步行，有的管感觉，分工合作，共同应付着全身的需要，只有它只知容纳食物，不知分担劳苦。肚子回答说——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00062","html":"\u003cp class=\"epub-calibre1\">市民甲 好，先生，那肚子怎么回答？\u003c/p>\n","text":"市民甲 好，先生，那肚子怎么回答？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00063","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 别急，让我讲给你听。——那肚子，而决非肺部，微微地露出一丝冷笑——因为你瞧，我既然可以叫肚子说话，那么当然也可以叫它微笑——带着讥讽的口气回答那些愤愤不平的、嫉妒它的收入的作乱的器官，正像你们因为元老们跟你们地位不同，所以把他们信口诽谤一样。\u003c/p>\n","text":"米尼涅斯 别急，让我讲给你听。——那肚子，而决非肺部，微微地露出一丝冷笑——因为你瞧，我既然可以叫肚子说话，那么当然也可以叫它微笑——带着讥讽的口气回答那些愤愤不平的、嫉妒它的收入的作乱的器官，正像你们因为元老们跟你们地位不同，所以把他们信口诽谤一样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00064","html":"\u003cp class=\"epub-calibre1\">市民甲 你那肚子怎么回答？哼！那戴着王冠的头，那视察一切的眼睛，那运筹决策的心，那胳臂——我们的兵士，那腿——我们的坐骑，那舌头——我们的吹号人，以及其他在我们这一个组织里各尽寸劳的属僚佐贰，要是他们——\u003c/p>\n","text":"市民甲 你那肚子怎么回答？哼！那戴着王冠的头，那视察一切的眼睛，那运筹决策的心，那胳臂——我们的兵士，那腿——我们的坐骑，那舌头——我们的吹号人，以及其他在我们这一个组织里各尽寸劳的属僚佐贰，要是他们——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00065","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 要是他们怎样？这家伙抢在我的前面说话！要是他们怎样？要是他们怎样？\u003c/p>\n","text":"米尼涅斯 要是他们怎样？这家伙抢在我的前面说话！要是他们怎样？要是他们怎样？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00066","html":"\u003cp class=\"epub-calibre1\">市民甲 要是他们受制于饕餮的肚子，那不过是身体上的一个藏污纳垢的地方——\u003c/p>\n","text":"市民甲 要是他们受制于饕餮的肚子，那不过是身体上的一个藏污纳垢的地方——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00067","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 好，那便怎样？\u003c/p>\n","text":"米尼涅斯 好，那便怎样？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00068","html":"\u003cp class=\"epub-calibre1\">市民甲 要是他们提出抗议，那肚子有什么话好回答呢？\u003c/p>\n","text":"市民甲 要是他们提出抗议，那肚子有什么话好回答呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00069","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我会告诉你的；只要你略微忍耐片刻，不要这么性急，你就可以听到肚子的回答。\u003c/p>\n","text":"米尼涅斯 我会告诉你的；只要你略微忍耐片刻，不要这么性急，你就可以听到肚子的回答。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00070","html":"\u003cp class=\"epub-calibre1\">市民甲 你讲话太不痛快。\u003c/p>\n","text":"市民甲 你讲话太不痛快。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00071","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 听着，好朋友；这位庄严的肚子是很从容不迫的，不像攻击他的人们那样卤莽轻率，他这样回答：“不错，我的全体的朋友们，”他说，“你们全体赖以生活的食物，是由我最先收纳下来的；这是理所当然的事，因为我是整个身体的仓库和工场；可是你们应该记得，那些食物就是我把它们从你们血液的河流里一路运输过去，一直传达到心的宫廷和脑的宝座；经过人身的五官百窍，最强韧的神经和最微细的血管都从我得到保持他们活力的资粮。你们，我的好朋友们，虽然在一时之间——”听着，这是那肚子说的话——\u003c/p>\n","text":"米尼涅斯 听着，好朋友；这位庄严的肚子是很从容不迫的，不像攻击他的人们那样卤莽轻率，他这样回答：“不错，我的全体的朋友们，”他说，“你们全体赖以生活的食物，是由我最先收纳下来的；这是理所当然的事，因为我是整个身体的仓库和工场；可是你们应该记得，那些食物就是我把它们从你们血液的河流里一路运输过去，一直传达到心的宫廷和脑的宝座；经过人身的五官百窍，最强韧的神经和最微细的血管都从我得到保持他们活力的资粮。你们，我的好朋友们，虽然在一时之间——”听着，这是那肚子说的话——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00072","html":"\u003cp class=\"epub-calibre1\">市民甲 好，好，他怎么说？\u003c/p>\n","text":"市民甲 好，好，他怎么说？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00073","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 “虽然在一时之间，不能看见我怎样把食物分送到各部分去，可是我可以清算我的收支，大家都从我领回食物的精华，剩下给我自己的只是一些糟粕。”你们觉得他的话说得怎样？\u003c/p>\n","text":"米尼涅斯 “虽然在一时之间，不能看见我怎样把食物分送到各部分去，可是我可以清算我的收支，大家都从我领回食物的精华，剩下给我自己的只是一些糟粕。”你们觉得他的话说得怎样？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00074","html":"\u003cp class=\"epub-calibre1\">市民甲 那也回答得有理。你说这一段话是什么用意呢？\u003c/p>\n","text":"市民甲 那也回答得有理。你说这一段话是什么用意呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00075","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 罗马的元老们就是这一个好肚子，你们就是那一群作乱的器官；因为你们要是把他们所讨论、所关切的问题仔细检讨一下，把有关大众幸福的事情彻底想一想，你们就会知道你们所享受的一切公共的利益，都是从他们手里得到，完全不是靠着你们自己的力量。你以为怎样，你这一群人中间的大拇脚趾头？\u003c/p>\n","text":"米尼涅斯 罗马的元老们就是这一个好肚子，你们就是那一群作乱的器官；因为你们要是把他们所讨论、所关切的问题仔细检讨一下，把有关大众幸福的事情彻底想一想，你们就会知道你们所享受的一切公共的利益，都是从他们手里得到，完全不是靠着你们自己的力量。你以为怎样，你这一群人中间的大拇脚趾头？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00076","html":"\u003cp class=\"epub-calibre1\">市民甲 我是大拇脚趾头？为什么我是大拇脚趾头？\u003c/p>\n","text":"市民甲 我是大拇脚趾头？为什么我是大拇脚趾头？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00077","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 因为你在这一场最聪明的叛乱里，是一个最低微、最卑鄙的人，却跑在众人的最前面；你这最下贱的恶棍，为了妄图非分的利益，竟敢自居于领导的地位。可是你们准备好举起你们粗硬的棍棒来吧；罗马和她的群鼠已经到了决战的关头；总有一方不免遭殃。\u003c/p>\n","text":"米尼涅斯 因为你在这一场最聪明的叛乱里，是一个最低微、最卑鄙的人，却跑在众人的最前面；你这最下贱的恶棍，为了妄图非分的利益，竟敢自居于领导的地位。可是你们准备好举起你们粗硬的棍棒来吧；罗马和她的群鼠已经到了决战的关头；总有一方不免遭殃。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00078","html":"\u003cp class=\"epub-block1\">卡厄斯·马歇斯上。\u003c/p>\n","text":"卡厄斯·马歇斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00079","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 祝福，尊荣的马歇斯！\u003c/p>\n","text":"米尼涅斯 祝福，尊荣的马歇斯！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00080","html":"\u003cp class=\"epub-calibre1\">马歇斯 谢谢。——什么事，你们这些违法乱纪的流氓，凭着你们那些龌龊有毒的意见，使你们自己变成了社会上的疥癣？\u003c/p>\n","text":"马歇斯 谢谢。——什么事，你们这些违法乱纪的流氓，凭着你们那些龌龊有毒的意见，使你们自己变成了社会上的疥癣？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00081","html":"\u003cp class=\"epub-calibre1\">市民甲 我们一向多承您温语相加。\u003c/p>\n","text":"市民甲 我们一向多承您温语相加。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00082","html":"\u003cp class=\"epub-calibre1\">马歇斯 谁要是对你们温语相加，他也会恭维他心里所痛恨的人了。你们究竟要什么，你们这些恶狗？你们既不喜欢和平，又不喜欢战争；战争会使你们害怕，和平又使你们妄自尊大。谁要是信任你们，他将会发现他所寻找的狮子不过是一群野兔，他所寻找的狐狸不过是一群鹅；你们比冰上的炭火、阳光中的雹点更不可靠。你们的美德是尊敬那犯罪的囚徒，咒诅那执法的刑官。谁立下了功德，就应该受你们的憎恨；你们的欢心就像病人的口味，只爱吃那些足以加重他的病症的食物。谁要是信赖着你们的欢心，就等于用铅造的鳍游泳，用灯心草去斩伐橡树。该死的东西！相信你们？你们每一分钟都要变换一个心，你们会称颂你们刚才所痛恨的人，唾骂你们刚才所赞美的人。你们在城里到处鼓噪，攻击尊贵的元老院，究竟是怎么一回事？倘使没有他们帮助神明把你们约束住了，使你们有一点畏惧，你们早就彼此相食了。他们究竟是什么目的？\u003c/p>\n","text":"马歇斯 谁要是对你们温语相加，他也会恭维他心里所痛恨的人了。你们究竟要什么，你们这些恶狗？你们既不喜欢和平，又不喜欢战争；战争会使你们害怕，和平又使你们妄自尊大。谁要是信任你们，他将会发现他所寻找的狮子不过是一群野兔，他所寻找的狐狸不过是一群鹅；你们比冰上的炭火、阳光中的雹点更不可靠。你们的美德是尊敬那犯罪的囚徒，咒诅那执法的刑官。谁立下了功德，就应该受你们的憎恨；你们的欢心就像病人的口味，只爱吃那些足以加重他的病症的食物。谁要是信赖着你们的欢心，就等于用铅造的鳍游泳，用灯心草去斩伐橡树。该死的东西！相信你们？你们每一分钟都要变换一个心，你们会称颂你们刚才所痛恨的人，唾骂你们刚才所赞美的人。你们在城里到处鼓噪，攻击尊贵的元老院，究竟是怎么一回事？倘使没有他们帮助神明把你们约束住了，使你们有一点畏惧，你们早就彼此相食了。他们究竟是什么目的？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00083","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 他们要求照他们所索取的数量给他们谷物；他们说这城里藏着很多的谷物。\u003c/p>\n","text":"米尼涅斯 他们要求照他们所索取的数量给他们谷物；他们说这城里藏着很多的谷物。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00084","html":"\u003cp class=\"epub-calibre1\">马歇斯 该死的东西！他们说！他们只会坐在火炉旁边，假充知道议会里所干的事；谁将要升起，谁正在得势，谁将要没落；宣布他们猜想中的婚姻；党同伐异，凡是他们所赞成的一方面，就夸赞它的强大；凡是他们所反对的一方面，就放在他们的破鞋子底下踹踏。他们说有很多的谷！要是那些贵族们愿意放下他们的慈悲，让我运用我的剑，我要尽我的枪尖所能挑到，把几千个这样的奴才杀死了堆成一座高高的尸山。\u003c/p>\n","text":"马歇斯 该死的东西！他们说！他们只会坐在火炉旁边，假充知道议会里所干的事；谁将要升起，谁正在得势，谁将要没落；宣布他们猜想中的婚姻；党同伐异，凡是他们所赞成的一方面，就夸赞它的强大；凡是他们所反对的一方面，就放在他们的破鞋子底下踹踏。他们说有很多的谷！要是那些贵族们愿意放下他们的慈悲，让我运用我的剑，我要尽我的枪尖所能挑到，把几千个这样的奴才杀死了堆成一座高高的尸山。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00085","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 不，这些人差不多已经完全悔悟了；因为他们虽然行事十分卤莽，然而他们都是非常懦怯的。可是请问，还有那一群怎么说？\u003c/p>\n","text":"米尼涅斯 不，这些人差不多已经完全悔悟了；因为他们虽然行事十分卤莽，然而他们都是非常懦怯的。可是请问，还有那一群怎么说？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00086","html":"\u003cp class=\"epub-calibre1\">马歇斯 他们已经解散了，该死的东西！他们说他们肚子饿；叹息出一些陈腐的老话：什么饥饿可以摧毁石墙；什么狗也要吃东西；什么肉是供口腹享受的；什么天神降下五谷，不是单为富人。用这种陈词滥调，倾吐他们的不平；他们的申诉是接受了，他们的请愿也得到了准许——一个奇怪的请愿，最慷慨的人听见了也会伤心，最大胆的人瞧见了也会失色——于是他们抛掷他们的帽子，高声欢呼，好像赌赛谁可以把他的帽子挂到月亮的钩上去似的。\u003c/p>\n","text":"马歇斯 他们已经解散了，该死的东西！他们说他们肚子饿；叹息出一些陈腐的老话：什么饥饿可以摧毁石墙；什么狗也要吃东西；什么肉是供口腹享受的；什么天神降下五谷，不是单为富人。用这种陈词滥调，倾吐他们的不平；他们的申诉是接受了，他们的请愿也得到了准许——一个奇怪的请愿，最慷慨的人听见了也会伤心，最大胆的人瞧见了也会失色——于是他们抛掷他们的帽子，高声欢呼，好像赌赛谁可以把他的帽子挂到月亮的钩上去似的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00087","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 准许了他们什么请愿？\u003c/p>\n","text":"米尼涅斯 准许了他们什么请愿？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00088","html":"\u003cp class=\"epub-calibre1\">马歇斯 由他们自己选出五个护民官，保护他们下贱的智慧：一个是裘涅斯·勃鲁托斯，一个是西西涅斯·维鲁特斯，还有那几个我不知道——哼！如果是我的话，就让这些乌合之众把城头上的天拆毁了，也决不答应他们；这样会使他们渐渐扩展势力，引起更大的叛乱。\u003c/p>\n","text":"马歇斯 由他们自己选出五个护民官，保护他们下贱的智慧：一个是裘涅斯·勃鲁托斯，一个是西西涅斯·维鲁特斯，还有那几个我不知道——哼！如果是我的话，就让这些乌合之众把城头上的天拆毁了，也决不答应他们；这样会使他们渐渐扩展势力，引起更大的叛乱。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00089","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 真是怪事。\u003c/p>\n","text":"米尼涅斯 真是怪事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00090","html":"\u003cp class=\"epub-calibre1\">马歇斯 去，滚回家去，你们这些废物！\u003c/p>\n","text":"马歇斯 去，滚回家去，你们这些废物！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00091","html":"\u003cp class=\"epub-block1\">一使者匆匆上。\u003c/p>\n","text":"一使者匆匆上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00092","html":"\u003cp class=\"epub-calibre1\">使者 卡厄斯·马歇斯呢？\u003c/p>\n","text":"使者 卡厄斯·马歇斯呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00093","html":"\u003cp class=\"epub-calibre1\">马歇斯 这儿；什么事？\u003c/p>\n","text":"马歇斯 这儿；什么事？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00094","html":"\u003cp class=\"epub-calibre1\">使者 将军，伏尔斯人起兵了。\u003c/p>\n","text":"使者 将军，伏尔斯人起兵了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00095","html":"\u003cp class=\"epub-calibre1\">马歇斯 我很高兴；我们可以有机会发泄发泄我们剩余下来的朽腐的精力了。瞧，我们的元老们来了。\u003c/p>\n","text":"马歇斯 我很高兴；我们可以有机会发泄发泄我们剩余下来的朽腐的精力了。瞧，我们的元老们来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00096","html":"\u003cp class=\"epub-block1\">考密涅斯、泰特斯·拉歇斯及其他元老；裘涅斯·勃鲁托斯、西西涅斯·维鲁特斯等同上。\u003c/p>\n","text":"考密涅斯、泰特斯·拉歇斯及其他元老；裘涅斯·勃鲁托斯、西西涅斯·维鲁特斯等同上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00097","html":"\u003cp class=\"epub-calibre1\">元老甲 马歇斯，您最近对我们说的话不错；伏尔斯人果然起兵了。\u003c/p>\n","text":"元老甲 马歇斯，您最近对我们说的话不错；伏尔斯人果然起兵了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00098","html":"\u003cp class=\"epub-calibre1\">马歇斯 他们有一个领袖，塔勒斯·奥菲狄乌斯，你们就会知道他的厉害。我很嫉妒他的高贵的品格，倘然我不是我，我就希望我是他。\u003c/p>\n","text":"马歇斯 他们有一个领袖，塔勒斯·奥菲狄乌斯，你们就会知道他的厉害。我很嫉妒他的高贵的品格，倘然我不是我，我就希望我是他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00099","html":"\u003cp class=\"epub-calibre1\">考密涅斯 您曾经跟他交战过。\u003c/p>\n","text":"考密涅斯 您曾经跟他交战过。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00100","html":"\u003cp class=\"epub-calibre1\">马歇斯 要是整个世界分成两半，互相厮杀，而他竟站在我这一方面，那么我为了要跟他交战的缘故，也会向自己的一方叛变：能够猎逐像他这样一头狮子，是我所认为一件可以自傲的事。\u003c/p>\n","text":"马歇斯 要是整个世界分成两半，互相厮杀，而他竟站在我这一方面，那么我为了要跟他交战的缘故，也会向自己的一方叛变：能够猎逐像他这样一头狮子，是我所认为一件可以自傲的事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00101","html":"\u003cp class=\"epub-calibre1\">元老甲 那么，尊贵的马歇斯，跟随考密涅斯出征去吧。\u003c/p>\n","text":"元老甲 那么，尊贵的马歇斯，跟随考密涅斯出征去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00102","html":"\u003cp class=\"epub-calibre1\">考密涅斯 这是您已经答应过的。\u003c/p>\n","text":"考密涅斯 这是您已经答应过的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00103","html":"\u003cp class=\"epub-calibre1\">马歇斯 是的，我决不食言。泰特斯·拉歇斯，你将要再见我向塔勒斯挥剑。怎么！你动也不动？你想置身事外吗？\u003c/p>\n","text":"马歇斯 是的，我决不食言。泰特斯·拉歇斯，你将要再见我向塔勒斯挥剑。怎么！你动也不动？你想置身事外吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00104","html":"\u003cp class=\"epub-calibre1\">拉歇斯 不，卡厄斯·马歇斯；即使我必须一手扶杖而行，我也要用另一手挥杖从征，决不后人。\u003c/p>\n","text":"拉歇斯 不，卡厄斯·马歇斯；即使我必须一手扶杖而行，我也要用另一手挥杖从征，决不后人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00105","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 啊！这才是英雄本色！\u003c/p>\n","text":"米尼涅斯 啊！这才是英雄本色！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00106","html":"\u003cp class=\"epub-calibre1\">元老甲 请你们各位驾临议会；我们那些最高贵的朋友们都在那里等着我们。\u003c/p>\n","text":"元老甲 请你们各位驾临议会；我们那些最高贵的朋友们都在那里等着我们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00107","html":"\u003cp class=\"epub-calibre1\">拉歇斯 \u003cb class=\"epub-calibre3\">（向考密涅斯）\u003c/b>您先走；\u003cb class=\"epub-calibre3\">（向马歇斯）\u003c/b>您跟在考密涅斯后面；我们必须跟在您的后面。\u003c/p>\n","text":"拉歇斯 （向考密涅斯）您先走；（向马歇斯）您跟在考密涅斯后面；我们必须跟在您的后面。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00108","html":"\u003cp class=\"epub-calibre1\">考密涅斯 尊贵的马歇斯！\u003c/p>\n","text":"考密涅斯 尊贵的马歇斯！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00109","html":"\u003cp class=\"epub-calibre1\">元老甲 \u003cb class=\"epub-calibre3\">（向众市民）\u003c/b>去！各人回家去！去！\u003c/p>\n","text":"元老甲 （向众市民）去！各人回家去！去！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00110","html":"\u003cp class=\"epub-calibre1\">马歇斯 不，让他们跟着来吧。伏尔斯人有许多谷；带这些耗子去吃空他们的谷仓吧。敬天畏上的叛徒们，你们已经表现了非常的勇敢；请你们跟着来吧。\u003cb class=\"epub-calibre3\">（众元老、考密涅斯、马歇斯、泰特斯、米尼涅斯同下；众市民偷偷散开。）\u003c/b>\u003c/p>\n","text":"马歇斯 不，让他们跟着来吧。伏尔斯人有许多谷；带这些耗子去吃空他们的谷仓吧。敬天畏上的叛徒们，你们已经表现了非常的勇敢；请你们跟着来吧。（众元老、考密涅斯、马歇斯、泰特斯、米尼涅斯同下；众市民偷偷散开。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00111","html":"\u003cp class=\"epub-calibre1\">西西涅斯 你见过像这个马歇斯一样骄傲的人吗？\u003c/p>\n","text":"西西涅斯 你见过像这个马歇斯一样骄傲的人吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00112","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 没有人可以和他相比。\u003c/p>\n","text":"勃鲁托斯 没有人可以和他相比。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00113","html":"\u003cp class=\"epub-calibre1\">西西涅斯 当我们被选为护民官的时候——\u003c/p>\n","text":"西西涅斯 当我们被选为护民官的时候——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00114","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 你没有留心到他的嘴唇和眼睛吗？\u003c/p>\n","text":"勃鲁托斯 你没有留心到他的嘴唇和眼睛吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00115","html":"\u003cp class=\"epub-calibre1\">西西涅斯 他那种冷嘲热讽才叫人难堪呢。\u003c/p>\n","text":"西西涅斯 他那种冷嘲热讽才叫人难堪呢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00116","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 碰到他动怒的时候，天神也免不了挨他一顿骂。\u003c/p>\n","text":"勃鲁托斯 碰到他动怒的时候，天神也免不了挨他一顿骂。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00117","html":"\u003cp class=\"epub-calibre1\">西西涅斯 温柔的月亮也要遭他的讥笑。\u003c/p>\n","text":"西西涅斯 温柔的月亮也要遭他的讥笑。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00118","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 这些战争把他葬送了；他已经变得这样骄傲，不会再像从前那样勇敢了。\u003c/p>\n","text":"勃鲁托斯 这些战争把他葬送了；他已经变得这样骄傲，不会再像从前那样勇敢了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00119","html":"\u003cp class=\"epub-calibre1\">西西涅斯 这样一种性格，在受到胜利的煽动以后，会瞧不起正午时候他所践踏的自己的影子。可是我不知道凭着他这种傲慢的脾气，怎么能够俯首接受考密涅斯的号令。\u003c/p>\n","text":"西西涅斯 这样一种性格，在受到胜利的煽动以后，会瞧不起正午时候他所践踏的自己的影子。可是我不知道凭着他这种傲慢的脾气，怎么能够俯首接受考密涅斯的号令。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00120","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 他的目的只是争取名誉，他现在也已经有很好的名誉；一个人要保持固有的名誉，获得更大的名誉，最好的办法就是处在亚于领袖的地位；因为要是有过错的话，就可以归咎于主将，虽然他已经尽了最大的能力；盲目的舆论就会替马歇斯发出惋惜的呼声，“啊！要是他担负了这个责任就好了！”\u003c/p>\n","text":"勃鲁托斯 他的目的只是争取名誉，他现在也已经有很好的名誉；一个人要保持固有的名誉，获得更大的名誉，最好的办法就是处在亚于领袖的地位；因为要是有过错的话，就可以归咎于主将，虽然他已经尽了最大的能力；盲目的舆论就会替马歇斯发出惋惜的呼声，“啊！要是他担负了这个责任就好了！”\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00121","html":"\u003cp class=\"epub-calibre1\">西西涅斯 而且，要是事情进行得顺利的话，舆论因为一向认定马歇斯是他们的英雄，考密涅斯的功劳也会被他埋没。\u003c/p>\n","text":"西西涅斯 而且，要是事情进行得顺利的话，舆论因为一向认定马歇斯是他们的英雄，考密涅斯的功劳也会被他埋没。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00122","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 对了，即使马歇斯没有出一点力，考密涅斯的一半的光荣也是属于他的；考密涅斯的一切错处，对于马歇斯也会变成光荣，虽然他不曾立下一点功劳。\u003c/p>\n","text":"勃鲁托斯 对了，即使马歇斯没有出一点力，考密涅斯的一半的光荣也是属于他的；考密涅斯的一切错处，对于马歇斯也会变成光荣，虽然他不曾立下一点功劳。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00123","html":"\u003cp class=\"epub-calibre1\">西西涅斯 让我们去听听他们怎样调兵遣将；还要看看他除了这一副孤僻的神气以外，是用怎样的态度出发作战的。\u003c/p>\n","text":"西西涅斯 让我们去听听他们怎样调兵遣将；还要看看他除了这一副孤僻的神气以外，是用怎样的态度出发作战的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00124","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 我们去吧。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"勃鲁托斯 我们去吧。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第一场 罗马。街道","headingLevel":4,"sourceAnchor":"a723","actNumber":1,"sceneNumber":1},{"id":"part0031-section-003","label":"第一幕 · 第二场 科利奥里。元老院","kind":"scene","blocks":[{"id":"part0031-00125","html":"\u003ch4 id=\"epub-part0031-a724\" class=\"epub-calibre12\">第二场 科利奥里。元老院\u003c/h4>\n","text":"第二场 科利奥里。元老院\n","sourceAnchor":"a724","tag":"h4"},{"id":"part0031-00126","html":"\u003cp class=\"epub-block1\">塔勒斯·奥菲狄乌斯及众元老上。\u003c/p>\n","text":"塔勒斯·奥菲狄乌斯及众元老上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00127","html":"\u003cp class=\"epub-calibre1\">元老甲 所以照您看来，奥菲狄乌斯，罗马人已经预闻我们的计谋，知道我们行动的情形了。\u003c/p>\n","text":"元老甲 所以照您看来，奥菲狄乌斯，罗马人已经预闻我们的计谋，知道我们行动的情形了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00128","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 那不也是您的意见吗？凡是我们这儿所想到的事情，哪一件不是在我们还没有把它实行以前，罗马就已经准备好对策了？自从我得到那边来的消息以后，到现在还不满四天；那消息是这样的：我想这封信还在我身边；是的，在这儿。“他们已经调遣一支军队，不知道是开向东方去的还是开向西方去的。饥荒很是严重；民不聊生，人心思乱。据闻那支军队由考密涅斯、马歇斯——你的旧日的敌人，罗马人恨他比你还要厉害——和泰特斯·拉歇斯——一个非常勇敢的罗马人——这三个人率领；大概是要开到你们边境上来的，请考虑考虑吧。”\u003c/p>\n","text":"奥菲狄乌斯 那不也是您的意见吗？凡是我们这儿所想到的事情，哪一件不是在我们还没有把它实行以前，罗马就已经准备好对策了？自从我得到那边来的消息以后，到现在还不满四天；那消息是这样的：我想这封信还在我身边；是的，在这儿。“他们已经调遣一支军队，不知道是开向东方去的还是开向西方去的。饥荒很是严重；民不聊生，人心思乱。据闻那支军队由考密涅斯、马歇斯——你的旧日的敌人，罗马人恨他比你还要厉害——和泰特斯·拉歇斯——一个非常勇敢的罗马人——这三个人率领；大概是要开到你们边境上来的，请考虑考虑吧。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00129","html":"\u003cp class=\"epub-calibre1\">元老甲 我们的军队已经在战场上；我们相信罗马一定准备着迎战了。\u003c/p>\n","text":"元老甲 我们的军队已经在战场上；我们相信罗马一定准备着迎战了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00130","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 你们以为把你们伟大的计划遮掩一下，让它到最后的关头方才暴露出来，是一个很聪明的办法；可是当它正在进行的时候，就已经被罗马人知晓了。我们本来预备趁罗马还没有知道我们计划以前，就用迅雷不及掩耳的手段，占领许多城市，现在消息已经泄露，我们的计划也要受到影响了。\u003c/p>\n","text":"奥菲狄乌斯 你们以为把你们伟大的计划遮掩一下，让它到最后的关头方才暴露出来，是一个很聪明的办法；可是当它正在进行的时候，就已经被罗马人知晓了。我们本来预备趁罗马还没有知道我们计划以前，就用迅雷不及掩耳的手段，占领许多城市，现在消息已经泄露，我们的计划也要受到影响了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00131","html":"\u003cp class=\"epub-calibre1\">元老乙 尊贵的奥菲狄乌斯，请您接受我们的委任，赶快到军前去；让我们守卫科利奥里。要是他们兵临我们城下，您就带领军队回来把他们赶走；可是我想他们一定还没有防备我们的进攻。\u003c/p>\n","text":"元老乙 尊贵的奥菲狄乌斯，请您接受我们的委任，赶快到军前去；让我们守卫科利奥里。要是他们兵临我们城下，您就带领军队回来把他们赶走；可是我想他们一定还没有防备我们的进攻。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00132","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 啊！那可不能这么说；我可以确定说他们已经有充分的准备。不但如此，他们一部分军队已经出发，把我们这儿作为唯一的目标。我去了。要是我有机会碰见卡厄斯·马歇斯，那么我们曾经立誓在先，一定要战到精疲力尽方才罢手。\u003c/p>\n","text":"奥菲狄乌斯 啊！那可不能这么说；我可以确定说他们已经有充分的准备。不但如此，他们一部分军队已经出发，把我们这儿作为唯一的目标。我去了。要是我有机会碰见卡厄斯·马歇斯，那么我们曾经立誓在先，一定要战到精疲力尽方才罢手。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00133","html":"\u003cp class=\"epub-calibre1\">众元老 愿神明帮助您！\u003c/p>\n","text":"众元老 愿神明帮助您！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00134","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 愿你们各位平安！\u003c/p>\n","text":"奥菲狄乌斯 愿你们各位平安！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00135","html":"\u003cp class=\"epub-calibre1\">元老甲 再会！\u003c/p>\n","text":"元老甲 再会！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00136","html":"\u003cp class=\"epub-calibre1\">元老乙 再会！\u003c/p>\n","text":"元老乙 再会！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00137","html":"\u003cp class=\"epub-calibre1\">众元老 再会！\u003cb class=\"epub-calibre3\">（各下。）\u003c/b>\u003c/p>\n","text":"众元老 再会！（各下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第二场 科利奥里。元老院","headingLevel":4,"sourceAnchor":"a724","actNumber":1,"sceneNumber":2},{"id":"part0031-section-004","label":"第一幕 · 第三场 罗马。马歇斯家中一室","kind":"scene","blocks":[{"id":"part0031-00138","html":"\u003ch4 id=\"epub-part0031-a725\" class=\"epub-calibre12\">第三场 罗马。马歇斯家中一室\u003c/h4>\n","text":"第三场 罗马。马歇斯家中一室\n","sourceAnchor":"a725","tag":"h4"},{"id":"part0031-00139","html":"\u003cp class=\"epub-block1\">伏伦妮娅及维吉利娅上，各坐矮凳上做针线。\u003c/p>\n","text":"伏伦妮娅及维吉利娅上，各坐矮凳上做针线。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00140","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 媳妇，你唱一支歌吧，或者让你自己高兴一点儿。倘然我的儿子是我的丈夫，我宁愿他出外去争取光荣，不愿他贪恋着闺房中的儿女私情。当年，他还只是一个身体娇嫩的孩子，我膝下还只有他这么一个儿子，他的青春和美貌正吸引着众人的注目，就在这种连帝王们的整天请求也都不能使一个母亲答应让她的儿子离开她眼前一小时的时候，我因为想到名誉对于这样一个人是多么重要，要是让他默默无闻地株守家园，岂不等于一幅悬挂在墙上的画像？所以就放他出去追寻危险，从危险中间博取他的声名。我让他参加一场残酷的战争；当他回来的时候，他的头上戴着橡叶的荣冠。我告诉你，媳妇，我第一次知道他是个男孩子的时候，还不及第一次看见他已经变成一个堂堂男子的时候那样喜欢得跳跃起来。\u003c/p>\n","text":"伏伦妮娅 媳妇，你唱一支歌吧，或者让你自己高兴一点儿。倘然我的儿子是我的丈夫，我宁愿他出外去争取光荣，不愿他贪恋着闺房中的儿女私情。当年，他还只是一个身体娇嫩的孩子，我膝下还只有他这么一个儿子，他的青春和美貌正吸引着众人的注目，就在这种连帝王们的整天请求也都不能使一个母亲答应让她的儿子离开她眼前一小时的时候，我因为想到名誉对于这样一个人是多么重要，要是让他默默无闻地株守家园，岂不等于一幅悬挂在墙上的画像？所以就放他出去追寻危险，从危险中间博取他的声名。我让他参加一场残酷的战争；当他回来的时候，他的头上戴着橡叶的荣冠。我告诉你，媳妇，我第一次知道他是个男孩子的时候，还不及第一次看见他已经变成一个堂堂男子的时候那样喜欢得跳跃起来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00141","html":"\u003cp class=\"epub-calibre1\">维吉利娅 婆婆，要是他战死了呢？\u003c/p>\n","text":"维吉利娅 婆婆，要是他战死了呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00142","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 那么他的不朽的声名就是我的儿子，就是我的后裔。听我说句真心话：要是我有十二个儿子，我都同样爱着他们，就像爱着我们亲爱的马歇斯一样，我也宁愿十一个儿子为了他们的国家而光荣地战死，不愿一个儿子闲弃他的大好的身子。\u003c/p>\n","text":"伏伦妮娅 那么他的不朽的声名就是我的儿子，就是我的后裔。听我说句真心话：要是我有十二个儿子，我都同样爱着他们，就像爱着我们亲爱的马歇斯一样，我也宁愿十一个儿子为了他们的国家而光荣地战死，不愿一个儿子闲弃他的大好的身子。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00143","html":"\u003cp class=\"epub-block1\">侍女上。\u003c/p>\n","text":"侍女上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00144","html":"\u003cp class=\"epub-calibre1\">侍女 太太，凡勒利娅夫人来瞧您来啦。\u003c/p>\n","text":"侍女 太太，凡勒利娅夫人来瞧您来啦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00145","html":"\u003cp class=\"epub-calibre1\">维吉利娅 请您准许我进去。\u003c/p>\n","text":"维吉利娅 请您准许我进去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00146","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 不，你不要进去。我仿佛已经听见你丈夫的鼓声，看见他拉着奥菲狄乌斯的头发把他摔下马来，那些伏尔斯人见了他就像小孩子见了一头熊似的纷纷逃避；我仿佛看见他这样顿足高呼，“上前，你们这些懦夫！虽然你们是罗马人，你们却是在恐惧中生下来的。”他用套着甲的手揩去他额角上的血，奋勇前进，好像一个割稻的农夫，倘使不把所有的稻一起割下，主人就要把他解雇一样。\u003c/p>\n","text":"伏伦妮娅 不，你不要进去。我仿佛已经听见你丈夫的鼓声，看见他拉着奥菲狄乌斯的头发把他摔下马来，那些伏尔斯人见了他就像小孩子见了一头熊似的纷纷逃避；我仿佛看见他这样顿足高呼，“上前，你们这些懦夫！虽然你们是罗马人，你们却是在恐惧中生下来的。”他用套着甲的手揩去他额角上的血，奋勇前进，好像一个割稻的农夫，倘使不把所有的稻一起割下，主人就要把他解雇一样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00147","html":"\u003cp class=\"epub-calibre1\">维吉利娅 他额角上的血！朱庇特啊！不要让他流血！\u003c/p>\n","text":"维吉利娅 他额角上的血！朱庇特啊！不要让他流血！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00148","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 去，你这傻子！那样才更可以显出他的英武的雄姿，远胜于那些辉煌的战利品，当赫卡柏乳哺着赫克托的时候，她的丰美的乳房还不及赫克托流血的额角好看，当他轻蔑地迎着希腊人的剑锋的时候。——请凡勒利娅夫人进来。\u003cb class=\"epub-calibre3\">（侍女下。）\u003c/b>\u003c/p>\n","text":"伏伦妮娅 去，你这傻子！那样才更可以显出他的英武的雄姿，远胜于那些辉煌的战利品，当赫卡柏乳哺着赫克托的时候，她的丰美的乳房还不及赫克托流血的额角好看，当他轻蔑地迎着希腊人的剑锋的时候。——请凡勒利娅夫人进来。（侍女下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00149","html":"\u003cp class=\"epub-calibre1\">维吉利娅 上天保佑我的丈夫不要遭奥菲狄乌斯的毒手！\u003c/p>\n","text":"维吉利娅 上天保佑我的丈夫不要遭奥菲狄乌斯的毒手！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00150","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 他会把奥菲狄乌斯的头打到他膝盖底下去，在他的脖子上践踏。\u003c/p>\n","text":"伏伦妮娅 他会把奥菲狄乌斯的头打到他膝盖底下去，在他的脖子上践踏。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00151","html":"\u003cp class=\"epub-block1\">侍女率凡勒利娅及阍者重上。\u003c/p>\n","text":"侍女率凡勒利娅及阍者重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00152","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 两位夫人早安。\u003c/p>\n","text":"凡勒利娅 两位夫人早安。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00153","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 好夫人。\u003c/p>\n","text":"伏伦妮娅 好夫人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00154","html":"\u003cp class=\"epub-calibre1\">维吉利娅 今天幸会夫人，不胜欣慰。\u003c/p>\n","text":"维吉利娅 今天幸会夫人，不胜欣慰。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00155","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 你们两位都好？真是一对贤主妇！你们在这儿缝些什么？好一处清净的所在。小哥儿好吗？\u003c/p>\n","text":"凡勒利娅 你们两位都好？真是一对贤主妇！你们在这儿缝些什么？好一处清净的所在。小哥儿好吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00156","html":"\u003cp class=\"epub-calibre1\">维吉利娅 谢谢夫人，他很好。\u003c/p>\n","text":"维吉利娅 谢谢夫人，他很好。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00157","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 他宁愿看刀剑听鼓声，不愿见教书先生的面。\u003c/p>\n","text":"伏伦妮娅 他宁愿看刀剑听鼓声，不愿见教书先生的面。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00158","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 真是有其父必有其子；我可以发誓他是一个很可爱的孩子。不瞒你们说，星期三那天我曾经瞧了他足足半个钟头；他有这么一副坚决的面孔。我见他追赶着一只金翅的蝴蝶，捉到了手又把它放走，放走了又去追它；这么奔来奔去，捉了放、放了捉，也不知道是因为跌了一跤呢，还是因为别的缘故，他发起脾气来，咬紧了牙关，把那蝴蝶撕碎了；啊！瞧他撕的时候那股劲儿！\u003c/p>\n","text":"凡勒利娅 真是有其父必有其子；我可以发誓他是一个很可爱的孩子。不瞒你们说，星期三那天我曾经瞧了他足足半个钟头；他有这么一副坚决的面孔。我见他追赶着一只金翅的蝴蝶，捉到了手又把它放走，放走了又去追它；这么奔来奔去，捉了放、放了捉，也不知道是因为跌了一跤呢，还是因为别的缘故，他发起脾气来，咬紧了牙关，把那蝴蝶撕碎了；啊！瞧他撕的时候那股劲儿！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00159","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 他父亲也是这样的脾气。\u003c/p>\n","text":"伏伦妮娅 他父亲也是这样的脾气。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00160","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 真是一个不同凡俗的孩子。\u003c/p>\n","text":"凡勒利娅 真是一个不同凡俗的孩子。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00161","html":"\u003cp class=\"epub-calibre1\">维吉利娅 一个顽皮的孩子，夫人。\u003c/p>\n","text":"维吉利娅 一个顽皮的孩子，夫人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00162","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 来，放下你们的针线；今天下午我要你们陪我玩去。\u003c/p>\n","text":"凡勒利娅 来，放下你们的针线；今天下午我要你们陪我玩去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00163","html":"\u003cp class=\"epub-calibre1\">维吉利娅 不，好夫人，今天我不出去。\u003c/p>\n","text":"维吉利娅 不，好夫人，今天我不出去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00164","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 不出去！\u003c/p>\n","text":"凡勒利娅 不出去！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00165","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 偏要她出去。\u003c/p>\n","text":"伏伦妮娅 偏要她出去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00166","html":"\u003cp class=\"epub-calibre1\">维吉利娅 不，真的，请您原谅；在我的丈夫打仗没有回来以前，我决不迈出门槛一步。\u003c/p>\n","text":"维吉利娅 不，真的，请您原谅；在我的丈夫打仗没有回来以前，我决不迈出门槛一步。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00167","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 胡说！你不应该这样毫无理由地把你自己关在家里。来，你必须去访问访问那位害病的好夫人。\u003c/p>\n","text":"伏伦妮娅 胡说！你不应该这样毫无理由地把你自己关在家里。来，你必须去访问访问那位害病的好夫人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00168","html":"\u003cp class=\"epub-calibre1\">维吉利娅 我愿意祝她早日恢复健康，替她诚心祈祷；可是我不能去。\u003c/p>\n","text":"维吉利娅 我愿意祝她早日恢复健康，替她诚心祈祷；可是我不能去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00169","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 为什么呢，请问？\u003c/p>\n","text":"伏伦妮娅 为什么呢，请问？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00170","html":"\u003cp class=\"epub-calibre1\">维吉利娅 不是因为偷懒，也不是因为我冷酷无情。\u003c/p>\n","text":"维吉利娅 不是因为偷懒，也不是因为我冷酷无情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00171","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 你要做珀涅罗珀\u003ca id=\"epub-part0031-w001\">\u003c/a>\u003ca href=\"#epub-part0031-m001\" data-source-anchor=\"m001\">\u003csup class=\"epub-calibre13\">[1]\u003c/sup>\u003c/a>第二吗？可是人家说，她在俄底修斯出去以后所纺的纱线，不过使伊塔刻充满了飞蛾一般的食客而已。来；我希望你手里的布也像你的手指一样有知觉，那么你因为心怀不忍，也许不会再用针去刺它了。来，你必须跟我们一块儿去。\u003c/p>\n","text":"凡勒利娅 你要做珀涅罗珀[1]第二吗？可是人家说，她在俄底修斯出去以后所纺的纱线，不过使伊塔刻充满了飞蛾一般的食客而已。来；我希望你手里的布也像你的手指一样有知觉，那么你因为心怀不忍，也许不会再用针去刺它了。来，你必须跟我们一块儿去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00172","html":"\u003cp class=\"epub-calibre1\">维吉利娅 不，好夫人，原谅我；真的，我不想出去。\u003c/p>\n","text":"维吉利娅 不，好夫人，原谅我；真的，我不想出去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00173","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 真的，你跟我去吧；我会告诉你关于尊夫的好消息。\u003c/p>\n","text":"凡勒利娅 真的，你跟我去吧；我会告诉你关于尊夫的好消息。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00174","html":"\u003cp class=\"epub-calibre1\">维吉利娅 啊，好夫人，现在还不会就有好消息哩。\u003c/p>\n","text":"维吉利娅 啊，好夫人，现在还不会就有好消息哩。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00175","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 真的，我不是对你说笑话；昨天晚上他有信来。\u003c/p>\n","text":"凡勒利娅 真的，我不是对你说笑话；昨天晚上他有信来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00176","html":"\u003cp class=\"epub-calibre1\">维吉利娅 真的吗，夫人？\u003c/p>\n","text":"维吉利娅 真的吗，夫人？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00177","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 真的，不骗你；我听见一个元老说起。据说，伏尔斯人有一支军队开了过来，我们的主将考密涅斯已经带了一部分罗马军队前去迎敌了；尊夫和泰特斯·拉歇斯两人已经在他们的科利奥里城前扎下营寨，他们深信一定会在短时期内获得胜利。凭着我的名誉发誓，这是真的；所以请你陪我们去吧。\u003c/p>\n","text":"凡勒利娅 真的，不骗你；我听见一个元老说起。据说，伏尔斯人有一支军队开了过来，我们的主将考密涅斯已经带了一部分罗马军队前去迎敌了；尊夫和泰特斯·拉歇斯两人已经在他们的科利奥里城前扎下营寨，他们深信一定会在短时期内获得胜利。凭着我的名誉发誓，这是真的；所以请你陪我们去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00178","html":"\u003cp class=\"epub-calibre1\">维吉利娅 请您多多原谅，好夫人；我以后什么都听从您就是了。\u003c/p>\n","text":"维吉利娅 请您多多原谅，好夫人；我以后什么都听从您就是了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00179","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 随她去，夫人；照她现在这种样子，叫她同去也会扫我们的兴。\u003c/p>\n","text":"伏伦妮娅 随她去，夫人；照她现在这种样子，叫她同去也会扫我们的兴。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00180","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 真的，我也这样想。那么再见吧。来，好夫人。维吉利娅，请你还是把你的忧愁撵出门外，跟我们一块儿去吧。\u003c/p>\n","text":"凡勒利娅 真的，我也这样想。那么再见吧。来，好夫人。维吉利娅，请你还是把你的忧愁撵出门外，跟我们一块儿去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00181","html":"\u003cp class=\"epub-calibre1\">维吉利娅 不，夫人，我真的不去。我愿您快乐。\u003c/p>\n","text":"维吉利娅 不，夫人，我真的不去。我愿您快乐。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00182","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 那么好，再见。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"凡勒利娅 那么好，再见。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第三场 罗马。马歇斯家中一室","headingLevel":4,"sourceAnchor":"a725","actNumber":1,"sceneNumber":3},{"id":"part0031-section-005","label":"第一幕 · 第四场 科利奥里城前","kind":"scene","blocks":[{"id":"part0031-00183","html":"\u003ch4 id=\"epub-part0031-a726\" class=\"epub-calibre12\">第四场 科利奥里城前\u003c/h4>\n","text":"第四场 科利奥里城前\n","sourceAnchor":"a726","tag":"h4"},{"id":"part0031-00184","html":"\u003cp class=\"epub-block1\">旗鼓前导；马歇斯、泰特斯·拉歇斯、军官、兵士等上；一使者自对面上。\u003c/p>\n","text":"旗鼓前导；马歇斯、泰特斯·拉歇斯、军官、兵士等上；一使者自对面上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00185","html":"\u003cp class=\"epub-calibre1\">马歇斯 有人带消息来了；我可以打赌他们已经相遇了。\u003c/p>\n","text":"马歇斯 有人带消息来了；我可以打赌他们已经相遇了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00186","html":"\u003cp class=\"epub-calibre1\">拉歇斯 我用我的马赌你的马，他们还没有相遇。\u003c/p>\n","text":"拉歇斯 我用我的马赌你的马，他们还没有相遇。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00187","html":"\u003cp class=\"epub-calibre1\">马歇斯 好，一言为定。\u003c/p>\n","text":"马歇斯 好，一言为定。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00188","html":"\u003cp class=\"epub-calibre1\">拉歇斯 算数。\u003c/p>\n","text":"拉歇斯 算数。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00189","html":"\u003cp class=\"epub-calibre1\">马歇斯 喂，我们的元帅有没有跟敌人相遇？\u003c/p>\n","text":"马歇斯 喂，我们的元帅有没有跟敌人相遇？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00190","html":"\u003cp class=\"epub-calibre1\">使者 他们已经彼此相望，可是还没有交锋。\u003c/p>\n","text":"使者 他们已经彼此相望，可是还没有交锋。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00191","html":"\u003cp class=\"epub-calibre1\">拉歇斯 这匹好马是我的啦。\u003c/p>\n","text":"拉歇斯 这匹好马是我的啦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00192","html":"\u003cp class=\"epub-calibre1\">马歇斯 我向你买回来。\u003c/p>\n","text":"马歇斯 我向你买回来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00193","html":"\u003cp class=\"epub-calibre1\">拉歇斯 不，我不愿把它出卖或是送人；可是我愿意借给你骑五十年。让我们招降这城市吧。\u003c/p>\n","text":"拉歇斯 不，我不愿把它出卖或是送人；可是我愿意借给你骑五十年。让我们招降这城市吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00194","html":"\u003cp class=\"epub-calibre1\">马歇斯 那两支军队离这儿有多远？\u003c/p>\n","text":"马歇斯 那两支军队离这儿有多远？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00195","html":"\u003cp class=\"epub-calibre1\">使者 有一哩半光景。\u003c/p>\n","text":"使者 有一哩半光景。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00196","html":"\u003cp class=\"epub-calibre1\">马歇斯 那么我们可以互相听见鼓角的声音了。战神啊，请你默佑我们马到成功，好让我们立刻转过头来，挥舞我们热腾腾的利剑，去帮助我们战地上的友人！来，吹起喇叭来。\u003c/p>\n","text":"马歇斯 那么我们可以互相听见鼓角的声音了。战神啊，请你默佑我们马到成功，好让我们立刻转过头来，挥舞我们热腾腾的利剑，去帮助我们战地上的友人！来，吹起喇叭来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00197","html":"\u003cp class=\"epub-block1\">吹议和信号；二元老及余人等在城墙上出现。\u003c/p>\n","text":"吹议和信号；二元老及余人等在城墙上出现。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00198","html":"\u003cp class=\"epub-calibre1\">马歇斯 塔勒斯·奥菲狄乌斯在你们城里吗？\u003c/p>\n","text":"马歇斯 塔勒斯·奥菲狄乌斯在你们城里吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00199","html":"\u003cp class=\"epub-calibre1\">元老甲 不，没有一个人比他更不把你放在心上了。听，我们的鼓声\u003cb class=\"epub-calibre3\">（远处鼓声）\u003c/b>正在召唤我们的青年们杀出去；我们宁愿推倒我们自己的城墙，也不愿被困在城内；我们的城门瞧上去虽然还是关得紧紧的，可是它们不过是用灯心草拴住的，等会儿就会自己打开。你听，远方的声音！\u003cb class=\"epub-calibre3\">（远处号角声）\u003c/b>那是奥菲狄乌斯；听，他正在向你们那七零八落的军队大施挞伐。\u003c/p>\n","text":"元老甲 不，没有一个人比他更不把你放在心上了。听，我们的鼓声（远处鼓声）正在召唤我们的青年们杀出去；我们宁愿推倒我们自己的城墙，也不愿被困在城内；我们的城门瞧上去虽然还是关得紧紧的，可是它们不过是用灯心草拴住的，等会儿就会自己打开。你听，远方的声音！（远处号角声）那是奥菲狄乌斯；听，他正在向你们那七零八落的军队大施挞伐。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00200","html":"\u003cp class=\"epub-calibre1\">马歇斯 啊！他们在交战了！\u003c/p>\n","text":"马歇斯 啊！他们在交战了！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00201","html":"\u003cp class=\"epub-calibre1\">拉歇斯 让他们喧呼的声音鼓起我们的勇气。来，梯子！\u003c/p>\n","text":"拉歇斯 让他们喧呼的声音鼓起我们的勇气。来，梯子！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00202","html":"\u003cp class=\"epub-block1\">一队伏尔斯兵士上，自台前经过。\u003c/p>\n","text":"一队伏尔斯兵士上，自台前经过。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00203","html":"\u003cp class=\"epub-calibre1\">马歇斯 他们不怕我们，却从城里蜂拥而出。现在把你们的盾牌挡在胸前，鼓起你们比盾牌更坚强的斗志，努力杀敌吧！上去，勇敢的泰特斯；想不到他们竟会这样藐视我们，把我气得出了一身汗。来啊，弟兄们；谁要是退缩不前，我就把他当作一个伏尔斯人，叫他死在我的剑下。\u003c/p>\n","text":"马歇斯 他们不怕我们，却从城里蜂拥而出。现在把你们的盾牌挡在胸前，鼓起你们比盾牌更坚强的斗志，努力杀敌吧！上去，勇敢的泰特斯；想不到他们竟会这样藐视我们，把我气得出了一身汗。来啊，弟兄们；谁要是退缩不前，我就把他当作一个伏尔斯人，叫他死在我的剑下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00204","html":"\u003cp class=\"epub-block1\">号角声；罗马人败退；马歇斯重上。\u003c/p>\n","text":"号角声；罗马人败退；马歇斯重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00205","html":"\u003cp class=\"epub-calibre1\">马歇斯 南方的一切瘟疫都降在你们身上，你们这些罗马的耻辱！愿你们浑身长满毒疮恶病，在逆风的一哩路之外就会互相传染，人家只要一闻到你们的气息就会远远退避。你们这些套着人类躯壳的蠢鹅的灵魂！猴子们都会把他们打退的一群奴才，也会把你们吓得乱奔乱窜！该死！你们都是背后受伤；背上流着鲜红的血，脸却因为奔逃和恐惧而变成了灰白！提起勇气来，向他们反攻！否则凭着天上的神火起誓，我要丢下敌人，向你们作战了；留心着吧。上去；要是你们奋勇坚持，我们一定要把他们打回他们妻子的怀抱里去。\u003c/p>\n","text":"马歇斯 南方的一切瘟疫都降在你们身上，你们这些罗马的耻辱！愿你们浑身长满毒疮恶病，在逆风的一哩路之外就会互相传染，人家只要一闻到你们的气息就会远远退避。你们这些套着人类躯壳的蠢鹅的灵魂！猴子们都会把他们打退的一群奴才，也会把你们吓得乱奔乱窜！该死！你们都是背后受伤；背上流着鲜红的血，脸却因为奔逃和恐惧而变成了灰白！提起勇气来，向他们反攻！否则凭着天上的神火起誓，我要丢下敌人，向你们作战了；留心着吧。上去；要是你们奋勇坚持，我们一定要把他们打回他们妻子的怀抱里去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00206","html":"\u003cp class=\"epub-block1\">号角声；伏尔斯人及罗马人重上交战；伏尔斯人败退城内，马歇斯追至城门口。\u003c/p>\n","text":"号角声；伏尔斯人及罗马人重上交战；伏尔斯人败退城内，马歇斯追至城门口。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00207","html":"\u003cp class=\"epub-calibre1\">马歇斯 现在城门开了；大家出力！命运打开它们，是为了追赶的人，不是为了逃走的人；瞧着我的样子，跟我来吧！\u003cb class=\"epub-calibre3\">（进城门。）\u003c/b>\u003c/p>\n","text":"马歇斯 现在城门开了；大家出力！命运打开它们，是为了追赶的人，不是为了逃走的人；瞧着我的样子，跟我来吧！（进城门。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00208","html":"\u003cp class=\"epub-calibre1\">兵士甲 简直是蛮干！我可不来。\u003c/p>\n","text":"兵士甲 简直是蛮干！我可不来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00209","html":"\u003cp class=\"epub-calibre1\">兵士乙 我也不高兴。\u003cb class=\"epub-calibre3\">（马歇斯被关在城内。）\u003c/b>\u003c/p>\n","text":"兵士乙 我也不高兴。（马歇斯被关在城内。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00210","html":"\u003cp class=\"epub-calibre1\">兵士丙 瞧，他们把他关在里面了。\u003c/p>\n","text":"兵士丙 瞧，他们把他关在里面了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00211","html":"\u003cp class=\"epub-calibre1\">众人 他这回准要送命了。\u003cb class=\"epub-calibre3\">（号角声继续吹响。）\u003c/b>\u003c/p>\n","text":"众人 他这回准要送命了。（号角声继续吹响。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00212","html":"\u003cp class=\"epub-block1\">泰特斯·拉歇斯重上。\u003c/p>\n","text":"泰特斯·拉歇斯重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00213","html":"\u003cp class=\"epub-calibre1\">拉歇斯 马歇斯怎样啦？\u003c/p>\n","text":"拉歇斯 马歇斯怎样啦？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00214","html":"\u003cp class=\"epub-calibre1\">众人 他一定被杀了，将军。\u003c/p>\n","text":"众人 他一定被杀了，将军。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00215","html":"\u003cp class=\"epub-calibre1\">兵士甲 他紧紧追赶着那些逃走的敌人，一直追进了城里，突然之间他们把城门关上了，剩下他一个人在里面应付全城的敌人。\u003c/p>\n","text":"兵士甲 他紧紧追赶着那些逃走的敌人，一直追进了城里，突然之间他们把城门关上了，剩下他一个人在里面应付全城的敌人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00216","html":"\u003cp class=\"epub-calibre1\">拉歇斯 啊，英勇的壮士！当他的无情的刀剑锋摧刃折的时候，他那有知的血肉之躯依旧昂然不屈。你被我们遗弃了，马歇斯；一颗像你的身体那么大的完整的红玉，也比不上你珍贵。你是一个恰如凯图\u003ca id=\"epub-part0031-w002\">\u003c/a>\u003ca href=\"#epub-part0031-m002\" data-source-anchor=\"m002\">\u003csup class=\"epub-calibre13\">[2]\u003c/sup>\u003c/a>理想的军人，不但在挥舞刀剑的时候勇猛惊人，你的威严的怒容，你的雷鸣一样的声音，也会使敌人丧胆，就像整个世界在害着热病而颤栗一样。\u003c/p>\n","text":"拉歇斯 啊，英勇的壮士！当他的无情的刀剑锋摧刃折的时候，他那有知的血肉之躯依旧昂然不屈。你被我们遗弃了，马歇斯；一颗像你的身体那么大的完整的红玉，也比不上你珍贵。你是一个恰如凯图[2]理想的军人，不但在挥舞刀剑的时候勇猛惊人，你的威严的怒容，你的雷鸣一样的声音，也会使敌人丧胆，就像整个世界在害着热病而颤栗一样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00217","html":"\u003cp class=\"epub-block1\">马歇斯被敌众围攻流血重上。\u003c/p>\n","text":"马歇斯被敌众围攻流血重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00218","html":"\u003cp class=\"epub-calibre1\">兵士甲 将军，瞧！\u003c/p>\n","text":"兵士甲 将军，瞧！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00219","html":"\u003cp class=\"epub-calibre1\">拉歇斯 啊！那是马歇斯！让我们救他出来，否则大家都要像他一样了。\u003cb class=\"epub-calibre3\">（众人上前激战，同进城内。）\u003c/b>\u003c/p>\n","text":"拉歇斯 啊！那是马歇斯！让我们救他出来，否则大家都要像他一样了。（众人上前激战，同进城内。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第四场 科利奥里城前","headingLevel":4,"sourceAnchor":"a726","actNumber":1,"sceneNumber":4},{"id":"part0031-section-006","label":"第一幕 · 第五场 科利奥里。街道","kind":"scene","blocks":[{"id":"part0031-00220","html":"\u003ch4 id=\"epub-part0031-a727\" class=\"epub-calibre12\">第五场 科利奥里。街道\u003c/h4>\n","text":"第五场 科利奥里。街道\n","sourceAnchor":"a727","tag":"h4"},{"id":"part0031-00221","html":"\u003cp class=\"epub-block1\">若干罗马兵士携战利品上。\u003c/p>\n","text":"若干罗马兵士携战利品上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00222","html":"\u003cp class=\"epub-calibre1\">兵士甲 我要把这带回罗马去。\u003c/p>\n","text":"兵士甲 我要把这带回罗马去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00223","html":"\u003cp class=\"epub-calibre1\">兵士乙 我要把这带回去。\u003c/p>\n","text":"兵士乙 我要把这带回去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00224","html":"\u003cp class=\"epub-calibre1\">兵士丙 倒霉！我还以为这是银子哩。\u003cb class=\"epub-calibre3\">（远处号角声仍继续不断。）\u003c/b>\u003c/p>\n","text":"兵士丙 倒霉！我还以为这是银子哩。（远处号角声仍继续不断。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00225","html":"\u003cp class=\"epub-block1\">马歇斯及泰特斯·拉歇斯上，一喇叭手随上。\u003c/p>\n","text":"马歇斯及泰特斯·拉歇斯上，一喇叭手随上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00226","html":"\u003cp class=\"epub-calibre1\">马歇斯 瞧这些家伙倒是一分钟也不肯放松！垫子、铅汤匙、小小的铁器、刽子手也懒得剥下来的死刑犯身上的囚衣，这些下贱的奴才不等打完仗，就忙着收拾起来了。都是该死的东西！听，元帅在那边厮杀得那么热闹！我们也去助战去！我灵魂里痛恨的仇人，奥菲狄乌斯，正在那儿杀戮着我们的罗马人。勇敢的泰特斯，你分一部分军队在城里扫荡扫荡，我再带着那些有勇气的，立刻就去接应考密涅斯。\u003c/p>\n","text":"马歇斯 瞧这些家伙倒是一分钟也不肯放松！垫子、铅汤匙、小小的铁器、刽子手也懒得剥下来的死刑犯身上的囚衣，这些下贱的奴才不等打完仗，就忙着收拾起来了。都是该死的东西！听，元帅在那边厮杀得那么热闹！我们也去助战去！我灵魂里痛恨的仇人，奥菲狄乌斯，正在那儿杀戮着我们的罗马人。勇敢的泰特斯，你分一部分军队在城里扫荡扫荡，我再带着那些有勇气的，立刻就去接应考密涅斯。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00227","html":"\u003cp class=\"epub-calibre1\">拉歇斯 将军，你在流血呢；你已经战得太辛苦啦，该休息休息才是。\u003c/p>\n","text":"拉歇斯 将军，你在流血呢；你已经战得太辛苦啦，该休息休息才是。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00228","html":"\u003cp class=\"epub-calibre1\">马歇斯 不要恭维我；我还没有杀上劲来呢。再见。这一点点血，可以鼓起我的勇气，有什么要紧；我要照这样子去和奥菲狄乌斯交战。\u003c/p>\n","text":"马歇斯 不要恭维我；我还没有杀上劲来呢。再见。这一点点血，可以鼓起我的勇气，有什么要紧；我要照这样子去和奥菲狄乌斯交战。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00229","html":"\u003cp class=\"epub-calibre1\">拉歇斯 但愿命运女神深深地恋爱着你；凭着她的无边的法力，使你的敌人的剑每击不中！勇敢的将军，愿胜利伴随着你！\u003c/p>\n","text":"拉歇斯 但愿命运女神深深地恋爱着你；凭着她的无边的法力，使你的敌人的剑每击不中！勇敢的将军，愿胜利伴随着你！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00230","html":"\u003cp class=\"epub-calibre1\">马歇斯 愿命运同样照顾着你！再见。\u003c/p>\n","text":"马歇斯 愿命运同样照顾着你！再见。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00231","html":"\u003cp class=\"epub-calibre1\">拉歇斯 英勇绝伦的马歇斯！\u003cb class=\"epub-calibre3\">（马歇斯下）\u003c/b>去，在市场上吹起你的喇叭来；召集全城的官吏，让他们明白我们的意旨。去！\u003cb class=\"epub-calibre3\">（各下。）\u003c/b>\u003c/p>\n","text":"拉歇斯 英勇绝伦的马歇斯！（马歇斯下）去，在市场上吹起你的喇叭来；召集全城的官吏，让他们明白我们的意旨。去！（各下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第五场 科利奥里。街道","headingLevel":4,"sourceAnchor":"a727","actNumber":1,"sceneNumber":5},{"id":"part0031-section-007","label":"第一幕 · 第六场 考密涅斯营帐附近","kind":"scene","blocks":[{"id":"part0031-00232","html":"\u003ch4 id=\"epub-part0031-a728\" class=\"epub-calibre12\">第六场 考密涅斯营帐附近\u003c/h4>\n","text":"第六场 考密涅斯营帐附近\n","sourceAnchor":"a728","tag":"h4"},{"id":"part0031-00233","html":"\u003cp class=\"epub-block1\">考密涅斯率军队自前线退却。\u003c/p>\n","text":"考密涅斯率军队自前线退却。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00234","html":"\u003cp class=\"epub-calibre1\">考密涅斯 弟兄们，休息一会儿；你们打得不错。我们没有失去罗马人的精神，既不愚蠢地作无益的牺牲，在退却的时候，也没有露出懦怯的丑态。相信我，诸位，敌人一定还要向我们进攻。我们正在激战的时候，可以断断续续地听到从风里传来的我们友军和敌人激战的声音。罗马的神明啊！愿你们护佑他们获得胜利，正像我们希望自己获得胜利一样；当我们含笑相遇的时候，我们一定会向你们呈献感谢的祭礼。\u003c/p>\n","text":"考密涅斯 弟兄们，休息一会儿；你们打得不错。我们没有失去罗马人的精神，既不愚蠢地作无益的牺牲，在退却的时候，也没有露出懦怯的丑态。相信我，诸位，敌人一定还要向我们进攻。我们正在激战的时候，可以断断续续地听到从风里传来的我们友军和敌人激战的声音。罗马的神明啊！愿你们护佑他们获得胜利，正像我们希望自己获得胜利一样；当我们含笑相遇的时候，我们一定会向你们呈献感谢的祭礼。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00235","html":"\u003cp class=\"epub-block1\">一使者上。\u003c/p>\n","text":"一使者上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00236","html":"\u003cp class=\"epub-calibre1\">考密涅斯 你带什么消息来了？\u003c/p>\n","text":"考密涅斯 你带什么消息来了？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00237","html":"\u003cp class=\"epub-calibre1\">使者 科利奥里的市民从城里蜂拥而出，和拉歇斯、马歇斯两人的军队交战；我看见我们的军队被他们击退，就离开那儿了。\u003c/p>\n","text":"使者 科利奥里的市民从城里蜂拥而出，和拉歇斯、马歇斯两人的军队交战；我看见我们的军队被他们击退，就离开那儿了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00238","html":"\u003cp class=\"epub-calibre1\">考密涅斯 你的话虽然是真，却不是好消息。那是多久以前的事？\u003c/p>\n","text":"考密涅斯 你的话虽然是真，却不是好消息。那是多久以前的事？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00239","html":"\u003cp class=\"epub-calibre1\">使者 一个多钟头了，元帅。\u003c/p>\n","text":"使者 一个多钟头了，元帅。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00240","html":"\u003cp class=\"epub-calibre1\">考密涅斯 一共不到一哩路，我们曾经听到过一阵短促的鼓声；你怎么一哩路要走一个钟头，到现在才把这消息送来？\u003c/p>\n","text":"考密涅斯 一共不到一哩路，我们曾经听到过一阵短促的鼓声；你怎么一哩路要走一个钟头，到现在才把这消息送来？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00241","html":"\u003cp class=\"epub-calibre1\">使者 伏尔斯人的探子跟住了我，我不得不绕圈子走了三四哩路；要不然的话，元帅，我在半点钟以前早就把消息送来了。\u003c/p>\n","text":"使者 伏尔斯人的探子跟住了我，我不得不绕圈子走了三四哩路；要不然的话，元帅，我在半点钟以前早就把消息送来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00242","html":"\u003cp class=\"epub-calibre1\">考密涅斯 那边来的是谁？瞧他的样子，好像碰见过强盗一般。嗳哟！他的神气有点儿像马歇斯；我从前也见过他这副模样的。\u003c/p>\n","text":"考密涅斯 那边来的是谁？瞧他的样子，好像碰见过强盗一般。嗳哟！他的神气有点儿像马歇斯；我从前也见过他这副模样的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00243","html":"\u003cp class=\"epub-calibre1\">马歇斯 \u003cb class=\"epub-calibre3\">（在内）\u003c/b>我来得太迟了吗？\u003c/p>\n","text":"马歇斯 （在内）我来得太迟了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00244","html":"\u003cp class=\"epub-calibre1\">考密涅斯 正像牧羊人听见雷声就知道它不是鼓声一样，我一听见马歇斯讲话的声音，就知道那不会是一个卑微的人在讲话。\u003c/p>\n","text":"考密涅斯 正像牧羊人听见雷声就知道它不是鼓声一样，我一听见马歇斯讲话的声音，就知道那不会是一个卑微的人在讲话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00245","html":"\u003cp class=\"epub-block1\">马歇斯上。\u003c/p>\n","text":"马歇斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00246","html":"\u003cp class=\"epub-calibre1\">马歇斯 我来得太迟了吗？\u003c/p>\n","text":"马歇斯 我来得太迟了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00247","html":"\u003cp class=\"epub-calibre1\">考密涅斯 是的，要是你身上染着的不是别人的血，而是你自己的血，那么你是来得太迟了。\u003c/p>\n","text":"考密涅斯 是的，要是你身上染着的不是别人的血，而是你自己的血，那么你是来得太迟了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00248","html":"\u003cp class=\"epub-calibre1\">马歇斯 啊！让我用就像我求婚时候一样坚强的胳臂拥抱你，让我用花烛送我们进入洞房的时候那样喜悦的心拥抱你！\u003c/p>\n","text":"马歇斯 啊！让我用就像我求婚时候一样坚强的胳臂拥抱你，让我用花烛送我们进入洞房的时候那样喜悦的心拥抱你！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00249","html":"\u003cp class=\"epub-calibre1\">考密涅斯 战士中的英华！泰特斯·拉歇斯怎样啦？\u003c/p>\n","text":"考密涅斯 战士中的英华！泰特斯·拉歇斯怎样啦？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00250","html":"\u003cp class=\"epub-calibre1\">马歇斯 他正在忙得像一个法官一样：把有的人处死、有的人放逐、有的人罚款，有的人得到了赦免，有的人受到了警告；科利奥里已经隶属于罗马的名义之下，像一头用皮带束住的摇尾乞怜的猎狗，不怕它逃到哪儿去了。\u003c/p>\n","text":"马歇斯 他正在忙得像一个法官一样：把有的人处死、有的人放逐、有的人罚款，有的人得到了赦免，有的人受到了警告；科利奥里已经隶属于罗马的名义之下，像一头用皮带束住的摇尾乞怜的猎狗，不怕它逃到哪儿去了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00251","html":"\u003cp class=\"epub-calibre1\">考密涅斯 告诉我说他们已经把你们击退的那个奴才呢？他到哪儿去了？叫他来。\u003c/p>\n","text":"考密涅斯 告诉我说他们已经把你们击退的那个奴才呢？他到哪儿去了？叫他来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00252","html":"\u003cp class=\"epub-calibre1\">马歇斯 不要责骂他；他并没有虚报事实。可是我们的那些士兵——死东西！他们还要护民官！——他们见了比他们自己更不中用的家伙，也会逃得像耗子见了猫儿似的。\u003c/p>\n","text":"马歇斯 不要责骂他；他并没有虚报事实。可是我们的那些士兵——死东西！他们还要护民官！——他们见了比他们自己更不中用的家伙，也会逃得像耗子见了猫儿似的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00253","html":"\u003cp class=\"epub-calibre1\">考密涅斯 可是你们怎么会得胜呢？\u003c/p>\n","text":"考密涅斯 可是你们怎么会得胜呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00254","html":"\u003cp class=\"epub-calibre1\">马歇斯 现在还有时间讲话吗？敌人呢？你们是不是已经占到优势？倘然不是，那么你们为什么停了下来？\u003c/p>\n","text":"马歇斯 现在还有时间讲话吗？敌人呢？你们是不是已经占到优势？倘然不是，那么你们为什么停了下来？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00255","html":"\u003cp class=\"epub-calibre1\">考密涅斯 马歇斯，我们因为实力不及敌人，所以暂避锋芒，以退为进。\u003c/p>\n","text":"考密涅斯 马歇斯，我们因为实力不及敌人，所以暂避锋芒，以退为进。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00256","html":"\u003cp class=\"epub-calibre1\">马歇斯 他们的阵地布置得怎样？你知道他们的主力是在哪一方面？\u003c/p>\n","text":"马歇斯 他们的阵地布置得怎样？你知道他们的主力是在哪一方面？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00257","html":"\u003cp class=\"epub-calibre1\">考密涅斯 照我的推测，马歇斯，他们的先锋部队是他们最信任的安息地方部队，统辖他们的将领就是他们全军希望所寄的奥菲狄乌斯。\u003c/p>\n","text":"考密涅斯 照我的推测，马歇斯，他们的先锋部队是他们最信任的安息地方部队，统辖他们的将领就是他们全军希望所寄的奥菲狄乌斯。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00258","html":"\u003cp class=\"epub-calibre1\">马歇斯 为了我们过去并肩作战的历次战役，为了我们共同流过的血，为了我们永矢友好的盟誓，我请求你立刻派我去向奥菲狄乌斯和他的安息地方部队挑战；让我们不要坐失时机，赶快挺起我们的刀剑枪矛来，就在这一小时内和他们决一胜负。\u003c/p>\n","text":"马歇斯 为了我们过去并肩作战的历次战役，为了我们共同流过的血，为了我们永矢友好的盟誓，我请求你立刻派我去向奥菲狄乌斯和他的安息地方部队挑战；让我们不要坐失时机，赶快挺起我们的刀剑枪矛来，就在这一小时内和他们决一胜负。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00259","html":"\u003cp class=\"epub-calibre1\">考密涅斯 我虽然希望用香汤替你沐浴，用油膏敷擦你的伤痕，可是我决不敢拒绝你的请求；请你自己选择一队最得力的人马带领前去吧。\u003c/p>\n","text":"考密涅斯 我虽然希望用香汤替你沐浴，用油膏敷擦你的伤痕，可是我决不敢拒绝你的请求；请你自己选择一队最得力的人马带领前去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00260","html":"\u003cp class=\"epub-calibre1\">马歇斯 只要是有胆量跟我去的，就是我所要选择的人。我相信在这儿一定有喜欢像我身上所涂染的这种油彩的人；我也相信在这儿一定有畏惧恶名甚于生命危险的人；我更相信在这儿一定有认为蒙耻偷生不如慷慨就义、祖国的荣誉胜过个人幸福的人：要是在你们中间有一个这样的人，或是有许多人都抱着这样的思想，就请挥起剑来，跟随马歇斯去。\u003cb class=\"epub-calibre3\">（众人高呼挥剑，将马歇斯举起，脱帽抛掷）\u003c/b>啊！只有我一个人吗？你们把我当作你们的剑吗？要是这不单单是形式上的表示，那么你们中间哪一个人不可以抵得过四个伏尔斯人？哪一个人不可以举起坚强的盾牌来，抵御伟大的奥菲狄乌斯？谢谢你们全体，可是我只要选择一部分人就够了；其余的必须静候号令，在别的战争里担起你们的任务来。现在请大家开步前进；我要立刻挑选那些最胜任的人。\u003c/p>\n","text":"马歇斯 只要是有胆量跟我去的，就是我所要选择的人。我相信在这儿一定有喜欢像我身上所涂染的这种油彩的人；我也相信在这儿一定有畏惧恶名甚于生命危险的人；我更相信在这儿一定有认为蒙耻偷生不如慷慨就义、祖国的荣誉胜过个人幸福的人：要是在你们中间有一个这样的人，或是有许多人都抱着这样的思想，就请挥起剑来，跟随马歇斯去。（众人高呼挥剑，将马歇斯举起，脱帽抛掷）啊！只有我一个人吗？你们把我当作你们的剑吗？要是这不单单是形式上的表示，那么你们中间哪一个人不可以抵得过四个伏尔斯人？哪一个人不可以举起坚强的盾牌来，抵御伟大的奥菲狄乌斯？谢谢你们全体，可是我只要选择一部分人就够了；其余的必须静候号令，在别的战争里担起你们的任务来。现在请大家开步前进；我要立刻挑选那些最胜任的人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00261","html":"\u003cp class=\"epub-calibre1\">考密涅斯 前进，弟兄们；把你们所表示的雄心壮志付诸实践，你们将和我们分享一切。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"考密涅斯 前进，弟兄们；把你们所表示的雄心壮志付诸实践，你们将和我们分享一切。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第六场 考密涅斯营帐附近","headingLevel":4,"sourceAnchor":"a728","actNumber":1,"sceneNumber":6},{"id":"part0031-section-008","label":"第一幕 · 第七场 科利奥里城门","kind":"scene","blocks":[{"id":"part0031-00262","html":"\u003ch4 id=\"epub-part0031-a729\" class=\"epub-calibre12\">第七场 科利奥里城门\u003c/h4>\n","text":"第七场 科利奥里城门\n","sourceAnchor":"a729","tag":"h4"},{"id":"part0031-00263","html":"\u003cp class=\"epub-block1\">泰特斯·拉歇斯在科利奥里布防完毕后，率兵士及鼓角等出城往考密涅斯及马歇斯处会合，一副将及一探子随上。\u003c/p>\n","text":"泰特斯·拉歇斯在科利奥里布防完毕后，率兵士及鼓角等出城往考密涅斯及马歇斯处会合，一副将及一探子随上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00264","html":"\u003cp class=\"epub-calibre1\">拉歇斯 就是这样；各个城门都要用心防守，按照我的命令行事，不可怠忽职务。要是我差人来，你就传令这些队伍开拔赴援，留少数人暂时驻守：要是我们在战场上失败了，这一个城也是守不住的。\u003c/p>\n","text":"拉歇斯 就是这样；各个城门都要用心防守，按照我的命令行事，不可怠忽职务。要是我差人来，你就传令这些队伍开拔赴援，留少数人暂时驻守：要是我们在战场上失败了，这一个城也是守不住的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00265","html":"\u003cp class=\"epub-calibre1\">副将 我们一定尽我们的责任，将军。\u003c/p>\n","text":"副将 我们一定尽我们的责任，将军。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00266","html":"\u003cp class=\"epub-calibre1\">拉歇斯 去，把城门关上。带路的人，来，领我们到罗马军队的阵地上去。\u003cb class=\"epub-calibre3\">（各下。）\u003c/b>\u003c/p>\n","text":"拉歇斯 去，把城门关上。带路的人，来，领我们到罗马军队的阵地上去。（各下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第七场 科利奥里城门","headingLevel":4,"sourceAnchor":"a729","actNumber":1,"sceneNumber":7},{"id":"part0031-section-009","label":"第一幕 · 第八场 罗马及伏尔斯营地之间的战场","kind":"scene","blocks":[{"id":"part0031-00267","html":"\u003ch4 id=\"epub-part0031-a730\" class=\"epub-calibre12\">第八场 罗马及伏尔斯营地之间的战场\u003c/h4>\n","text":"第八场 罗马及伏尔斯营地之间的战场\n","sourceAnchor":"a730","tag":"h4"},{"id":"part0031-00268","html":"\u003cp class=\"epub-block1\">号角声；马歇斯及奥菲狄乌斯自相对方向上。\u003c/p>\n","text":"号角声；马歇斯及奥菲狄乌斯自相对方向上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00269","html":"\u003cp class=\"epub-calibre1\">马歇斯 我只要跟你厮杀，因为我恨你比恨一个背约的人还厉害。\u003c/p>\n","text":"马歇斯 我只要跟你厮杀，因为我恨你比恨一个背约的人还厉害。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00270","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 我也同样恨你；没有一条非洲的毒蛇比你的名誉和狠毒更使我憎恨。站定你的脚跟。\u003c/p>\n","text":"奥菲狄乌斯 我也同样恨你；没有一条非洲的毒蛇比你的名誉和狠毒更使我憎恨。站定你的脚跟。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00271","html":"\u003cp class=\"epub-calibre1\">马歇斯 要是谁先动脚跑，让他做对方的奴隶而死去，死后永远不得超生！\u003c/p>\n","text":"马歇斯 要是谁先动脚跑，让他做对方的奴隶而死去，死后永远不得超生！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00272","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 马歇斯，要是我逃走，你就把我当做一头兔子一样呼唤。\u003c/p>\n","text":"奥菲狄乌斯 马歇斯，要是我逃走，你就把我当做一头兔子一样呼唤。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00273","html":"\u003cp class=\"epub-calibre1\">马歇斯 塔勒斯，过去三小时以内，我独自在你们科利奥里城里奋战，所向无敌；你看见我脸上所涂着的，不是我自己的血；你要是不服气的话，快来跟我拼命吧。\u003c/p>\n","text":"马歇斯 塔勒斯，过去三小时以内，我独自在你们科利奥里城里奋战，所向无敌；你看见我脸上所涂着的，不是我自己的血；你要是不服气的话，快来跟我拼命吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00274","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 即使你就是你们所夸耀的老祖宗赫克托自己，我今天也不放你活命。\u003cb class=\"epub-calibre3\">（二人交战，若干伏尔斯人趋前援助奥菲狄乌斯），\u003c/b>你们这些多事的、没有勇气的东西，谁要你们来帮我，丢我的脸。\u003cb class=\"epub-calibre3\">（马歇斯驱众人入内且战且下。）\u003c/b>\u003c/p>\n","text":"奥菲狄乌斯 即使你就是你们所夸耀的老祖宗赫克托自己，我今天也不放你活命。（二人交战，若干伏尔斯人趋前援助奥菲狄乌斯），你们这些多事的、没有勇气的东西，谁要你们来帮我，丢我的脸。（马歇斯驱众人入内且战且下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第八场 罗马及伏尔斯营地之间的战场","headingLevel":4,"sourceAnchor":"a730","actNumber":1,"sceneNumber":8},{"id":"part0031-section-010","label":"第一幕 · 第九场 罗马营地","kind":"scene","blocks":[{"id":"part0031-00275","html":"\u003ch4 id=\"epub-part0031-a731\" class=\"epub-calibre12\">第九场 罗马营地\u003c/h4>\n","text":"第九场 罗马营地\n","sourceAnchor":"a731","tag":"h4"},{"id":"part0031-00276","html":"\u003cp class=\"epub-block1\">号角声；吹归营号；喇叭奏花腔。考密涅斯及罗马兵士一队自一方上，马歇斯以巾裹臂伤，率另一队罗马兵士自另一方上。\u003c/p>\n","text":"号角声；吹归营号；喇叭奏花腔。考密涅斯及罗马兵士一队自一方上，马歇斯以巾裹臂伤，率另一队罗马兵士自另一方上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00277","html":"\u003cp class=\"epub-calibre1\">考密涅斯 要是我向你追叙你这一天来的工作，你一定不会相信你自己所干的事。可是我要回去向他们报告，让那些元老们的喜笑里掺杂着眼泪；让那些贵族们耸肩倾听，终于赞叹；让那些贵妇们惊怖失色，欢喜战栗，要求再闻其详；让那些麻木不仁、和顽固的平民一鼻孔出气、痛恨着你的尊荣的护民官们，也不得不违背他们的本心，说，“感谢神明，我们罗马有这样一位军人！”\u003c/p>\n","text":"考密涅斯 要是我向你追叙你这一天来的工作，你一定不会相信你自己所干的事。可是我要回去向他们报告，让那些元老们的喜笑里掺杂着眼泪；让那些贵族们耸肩倾听，终于赞叹；让那些贵妇们惊怖失色，欢喜战栗，要求再闻其详；让那些麻木不仁、和顽固的平民一鼻孔出气、痛恨着你的尊荣的护民官们，也不得不违背他们的本心，说，“感谢神明，我们罗马有这样一位军人！”\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00278","html":"\u003cp class=\"epub-block1\">泰特斯·拉歇斯率所部兵士追踪而至。\u003c/p>\n","text":"泰特斯·拉歇斯率所部兵士追踪而至。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00279","html":"\u003cp class=\"epub-calibre1\">拉歇斯 啊，元帅，这儿才是一匹骏马，我们都不过是些鞍鞯缰勒；要是你看见——\u003c/p>\n","text":"拉歇斯 啊，元帅，这儿才是一匹骏马，我们都不过是些鞍鞯缰勒；要是你看见——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00280","html":"\u003cp class=\"epub-calibre1\">马歇斯 请你别说了。当我的母亲赞美我的时候，我就会心中不安，虽然她是有夸扬她自己骨肉的特权的。我所做的事情不过跟你们所做的一样，各人尽各人的能力；我们的动机也只有一个，大家都是为了自己的国家。谁只要克尽他良心上的天职，他的功劳就应该在我之上。\u003c/p>\n","text":"马歇斯 请你别说了。当我的母亲赞美我的时候，我就会心中不安，虽然她是有夸扬她自己骨肉的特权的。我所做的事情不过跟你们所做的一样，各人尽各人的能力；我们的动机也只有一个，大家都是为了自己的国家。谁只要克尽他良心上的天职，他的功劳就应该在我之上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00281","html":"\u003cp class=\"epub-calibre1\">考密涅斯 你的功劳是不能埋没的；罗马必须知道她自己的健儿的价值。隐蔽你的勋绩，比偷窃诽谤的罪恶更大。所以我请求你，为了表扬你的本身，不是酬答你的辛劳，听我在全军将士面前说几句话。\u003c/p>\n","text":"考密涅斯 你的功劳是不能埋没的；罗马必须知道她自己的健儿的价值。隐蔽你的勋绩，比偷窃诽谤的罪恶更大。所以我请求你，为了表扬你的本身，不是酬答你的辛劳，听我在全军将士面前说几句话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00282","html":"\u003cp class=\"epub-calibre1\">马歇斯 我身上的剑痕尚新，它们听见人家提起它们的时候，就会作痛的。\u003c/p>\n","text":"马歇斯 我身上的剑痕尚新，它们听见人家提起它们的时候，就会作痛的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00283","html":"\u003cp class=\"epub-calibre1\">考密涅斯 它们不应该因此作痛；它们只会因忘恩负义而溃烂，因死亡而治愈。在我们所虏获的无数强壮的战马之中，在我们从战地上和城中所搜得的一切珍宝财物之中，我们把十分之一分送给你；你可以在当众分配的时候，凭你自己的意思挑选。\u003c/p>\n","text":"考密涅斯 它们不应该因此作痛；它们只会因忘恩负义而溃烂，因死亡而治愈。在我们所虏获的无数强壮的战马之中，在我们从战地上和城中所搜得的一切珍宝财物之中，我们把十分之一分送给你；你可以在当众分配的时候，凭你自己的意思挑选。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00284","html":"\u003cp class=\"epub-calibre1\">马歇斯 谢谢你，元帅；可是我不能同意让我的剑受人贿赂。恕我拒绝你的盛情；我愿意和参与这次战役的人受同等的待遇。\u003cb class=\"epub-calibre3\">（喇叭奏长花腔；众高呼“马歇斯！马歇斯！”抛掷帽、枪；考密涅斯、拉歇斯脱帽立）\u003c/b>愿这些被你们亵渎的乐器不再发出声音！当战地上的鼓角变成媚人的工具的时候，让宫廷和城市里都充斥着口是心非的阿谀趋奉吧！快别这样了！我只是没有洗净我流血的鼻子，我只是打败了几个孱弱的家伙，这是这儿的许多弟兄都跟我同样干过的事，虽然没有人注意到他们；你们就这样把我过分吹捧，好像我喜欢让我这一点儿微功薄能，用掺和着谎语的赞美大加渲染似的。\u003c/p>\n","text":"马歇斯 谢谢你，元帅；可是我不能同意让我的剑受人贿赂。恕我拒绝你的盛情；我愿意和参与这次战役的人受同等的待遇。（喇叭奏长花腔；众高呼“马歇斯！马歇斯！”抛掷帽、枪；考密涅斯、拉歇斯脱帽立）愿这些被你们亵渎的乐器不再发出声音！当战地上的鼓角变成媚人的工具的时候，让宫廷和城市里都充斥着口是心非的阿谀趋奉吧！快别这样了！我只是没有洗净我流血的鼻子，我只是打败了几个孱弱的家伙，这是这儿的许多弟兄都跟我同样干过的事，虽然没有人注意到他们；你们就这样把我过分吹捧，好像我喜欢让我这一点儿微功薄能，用掺和着谎语的赞美大加渲染似的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00285","html":"\u003cp class=\"epub-calibre1\">考密涅斯 你太谦虚了；你不但蔑视我们对你的至诚的称颂，尤其对于你自己的美好的声名，也未免过于苛刻。请不要见怪，要是你会对你自己动怒，那么我们要把你当作一个危险人物一样，替你加上镣铐，然后放胆跟你辩论。让全世界知道，卡厄斯·马歇斯戴着这一次战争的荣冠，为了纪念他的功勋，我送给他我这一匹全军知名的骏马，以及它所附带的一切装具；从今以后，为了他在科利奥里所建树的奇功，在我们全军欢呼声中，他将被称为卡厄斯·马歇斯·科利奥兰纳斯！让他永远光荣地戴上这一个名字！\u003c/p>\n","text":"考密涅斯 你太谦虚了；你不但蔑视我们对你的至诚的称颂，尤其对于你自己的美好的声名，也未免过于苛刻。请不要见怪，要是你会对你自己动怒，那么我们要把你当作一个危险人物一样，替你加上镣铐，然后放胆跟你辩论。让全世界知道，卡厄斯·马歇斯戴着这一次战争的荣冠，为了纪念他的功勋，我送给他我这一匹全军知名的骏马，以及它所附带的一切装具；从今以后，为了他在科利奥里所建树的奇功，在我们全军欢呼声中，他将被称为卡厄斯·马歇斯·科利奥兰纳斯！让他永远光荣地戴上这一个名字！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00286","html":"\u003cp class=\"epub-calibre1\">众人 卡厄斯·马歇斯·科利奥兰纳斯！\u003cb class=\"epub-calibre3\">（喇叭奏花腔；鼓角齐鸣。）\u003c/b>\u003c/p>\n","text":"众人 卡厄斯·马歇斯·科利奥兰纳斯！（喇叭奏花腔；鼓角齐鸣。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00287","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我要去洗个脸；等我把脸洗净以后，你们就可以看见我有没有惭愧的颜色。可是我谢谢你们。我准备跨上你的骏马，尽我所有的能力，永远保持着你们加于我的美名。\u003c/p>\n","text":"科利奥兰纳斯 我要去洗个脸；等我把脸洗净以后，你们就可以看见我有没有惭愧的颜色。可是我谢谢你们。我准备跨上你的骏马，尽我所有的能力，永远保持着你们加于我的美名。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00288","html":"\u003cp class=\"epub-calibre1\">考密涅斯 好，我们回营去；在我们解甲安息以前，还要先给罗马去信，报告我们的胜利。泰特斯·拉歇斯，你必须回到科利奥里，叫他们派代表到罗马去，为了彼此双方的利益，和我们商订议和的条款。\u003c/p>\n","text":"考密涅斯 好，我们回营去；在我们解甲安息以前，还要先给罗马去信，报告我们的胜利。泰特斯·拉歇斯，你必须回到科利奥里，叫他们派代表到罗马去，为了彼此双方的利益，和我们商订议和的条款。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00289","html":"\u003cp class=\"epub-calibre1\">拉歇斯 是，元帅。\u003c/p>\n","text":"拉歇斯 是，元帅。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00290","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 天神要开始讥笑我了。我刚才拒绝了最尊荣的礼物，现在却不得不向元帅请求一个小惠。\u003c/p>\n","text":"科利奥兰纳斯 天神要开始讥笑我了。我刚才拒绝了最尊荣的礼物，现在却不得不向元帅请求一个小惠。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00291","html":"\u003cp class=\"epub-calibre1\">考密涅斯 无论什么要求，我都可以允许你。你说吧。\u003c/p>\n","text":"考密涅斯 无论什么要求，我都可以允许你。你说吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00292","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我从前曾经在这儿科利奥里城里向一个穷汉借宿过一宵，他招待我非常殷勤。我看见他已经成为我们的俘虏，他见了我就向我高呼求助；可是因为那时奥菲狄乌斯在我的眼前，愤怒吞噬了我的怜悯，我没有理会他；请您让我的可怜的居停主人恢复自由吧。\u003c/p>\n","text":"科利奥兰纳斯 我从前曾经在这儿科利奥里城里向一个穷汉借宿过一宵，他招待我非常殷勤。我看见他已经成为我们的俘虏，他见了我就向我高呼求助；可是因为那时奥菲狄乌斯在我的眼前，愤怒吞噬了我的怜悯，我没有理会他；请您让我的可怜的居停主人恢复自由吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00293","html":"\u003cp class=\"epub-calibre1\">考密涅斯 啊！这是一个很好的请求！即使他是杀死我儿子的凶手，我也要让他像风一样自由。泰特斯，把他放了。\u003c/p>\n","text":"考密涅斯 啊！这是一个很好的请求！即使他是杀死我儿子的凶手，我也要让他像风一样自由。泰特斯，把他放了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00294","html":"\u003cp class=\"epub-calibre1\">拉歇斯 马歇斯，他的名字呢？\u003c/p>\n","text":"拉歇斯 马歇斯，他的名字呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00295","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 天哪！我忘了。我很疲倦；嗯，我懒得记忆。我们这儿没有酒吗？\u003c/p>\n","text":"科利奥兰纳斯 天哪！我忘了。我很疲倦；嗯，我懒得记忆。我们这儿没有酒吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00296","html":"\u003cp class=\"epub-calibre1\">考密涅斯 我们回营去。你脸上的血也干了；我们应当赶快替你调护调护。来。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"考密涅斯 我们回营去。你脸上的血也干了；我们应当赶快替你调护调护。来。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第九场 罗马营地","headingLevel":4,"sourceAnchor":"a731","actNumber":1,"sceneNumber":9},{"id":"part0031-section-011","label":"第一幕 · 第十场 伏尔斯人营地","kind":"scene","blocks":[{"id":"part0031-00297","html":"\u003ch4 id=\"epub-part0031-a732\" class=\"epub-calibre12\">第十场 伏尔斯人营地\u003c/h4>\n","text":"第十场 伏尔斯人营地\n","sourceAnchor":"a732","tag":"h4"},{"id":"part0031-00298","html":"\u003cp class=\"epub-block1\">喇叭奏花腔；吹号筒。塔勒斯·奥菲狄乌斯流血上，二三兵士随上。\u003c/p>\n","text":"喇叭奏花腔；吹号筒。塔勒斯·奥菲狄乌斯流血上，二三兵士随上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00299","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 我们的城市被占领了！\u003c/p>\n","text":"奥菲狄乌斯 我们的城市被占领了！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00300","html":"\u003cp class=\"epub-calibre1\">兵士甲 只要条件讲得好，它会还给我们的。\u003c/p>\n","text":"兵士甲 只要条件讲得好，它会还给我们的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00301","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 条件！把自己的运命听任他人支配的一方，还会有什么好条件！马歇斯，我已经跟你交战过五次了，五次我都被你打败；要是我们相会的次数就像吃饭的次数一样多，我相信你也会每次把我打败的。天地为证，要是我再有机会当面看见他，不是我杀死他，就是他杀死我。我对他的敌视已经使我不能再顾全我的荣誉；因为我既不能堂堂正正地以剑对剑，用同等的力量取胜他，凭着愤怒和阴谋，也要设法叫他落在我的手里。\u003c/p>\n","text":"奥菲狄乌斯 条件！把自己的运命听任他人支配的一方，还会有什么好条件！马歇斯，我已经跟你交战过五次了，五次我都被你打败；要是我们相会的次数就像吃饭的次数一样多，我相信你也会每次把我打败的。天地为证，要是我再有机会当面看见他，不是我杀死他，就是他杀死我。我对他的敌视已经使我不能再顾全我的荣誉；因为我既不能堂堂正正地以剑对剑，用同等的力量取胜他，凭着愤怒和阴谋，也要设法叫他落在我的手里。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00302","html":"\u003cp class=\"epub-calibre1\">兵士甲 他简直是个魔鬼。\u003c/p>\n","text":"兵士甲 他简直是个魔鬼。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00303","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 他比魔鬼还大胆，虽然没有魔鬼狡猾。他使我的勇气受到了毁损；我的怨毒一见了他，就会自己飞出来。不论在他睡觉、害病或是解除武装的时候，不论在圣殿或神庙里，不论在教士的祈祷或在献祭的时辰，所有这一切阻止复仇的障碍，都不能运用它们陈腐的特权和惯例，禁止我向马歇斯发泄我的仇恨。要是我在无论什么地方找到了他，即使他是在我自己的家里，在我的兄弟的保护之下，我也要违反好客的礼仪，在他的胸膛里洗我的凶暴的手。你们到城里去探听探听敌人占领的情形，以及将要到罗马去做人质的是哪一些人。\u003c/p>\n","text":"奥菲狄乌斯 他比魔鬼还大胆，虽然没有魔鬼狡猾。他使我的勇气受到了毁损；我的怨毒一见了他，就会自己飞出来。不论在他睡觉、害病或是解除武装的时候，不论在圣殿或神庙里，不论在教士的祈祷或在献祭的时辰，所有这一切阻止复仇的障碍，都不能运用它们陈腐的特权和惯例，禁止我向马歇斯发泄我的仇恨。要是我在无论什么地方找到了他，即使他是在我自己的家里，在我的兄弟的保护之下，我也要违反好客的礼仪，在他的胸膛里洗我的凶暴的手。你们到城里去探听探听敌人占领的情形，以及将要到罗马去做人质的是哪一些人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00304","html":"\u003cp class=\"epub-calibre1\">兵士甲 您不去吗？\u003c/p>\n","text":"兵士甲 您不去吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00305","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 我在柏树林里等着，它就在磨坊的南面；请你探到了外边的消息以后，就到那儿告诉我，让我可以决定应当怎样走我的路。\u003c/p>\n","text":"奥菲狄乌斯 我在柏树林里等着，它就在磨坊的南面；请你探到了外边的消息以后，就到那儿告诉我，让我可以决定应当怎样走我的路。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00306","html":"\u003cp class=\"epub-calibre1\">兵士甲 是，将军。\u003cb class=\"epub-calibre3\">（各下。）\u003c/b>\u003c/p>\n","text":"兵士甲 是，将军。（各下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第十场 伏尔斯人营地","headingLevel":4,"sourceAnchor":"a732","actNumber":1,"sceneNumber":10},{"id":"part0031-section-012","label":"第二幕","kind":"act","blocks":[{"id":"part0031-00307","html":"\u003ch3 id=\"epub-part0031-a733\" class=\"epub-calibre11\">第二幕\u003c/h3>\n","text":"第二幕\n","sourceAnchor":"a733","tag":"h3"}],"heading":"第二幕","headingLevel":3,"sourceAnchor":"a733","actNumber":2},{"id":"part0031-section-013","label":"第二幕 · 第一场 罗马。广场","kind":"scene","blocks":[{"id":"part0031-00308","html":"\u003ch4 id=\"epub-part0031-a734\" class=\"epub-calibre12\">第一场 罗马。广场\u003c/h4>\n","text":"第一场 罗马。广场\n","sourceAnchor":"a734","tag":"h4"},{"id":"part0031-00309","html":"\u003cp class=\"epub-block1\">米尼涅斯、西西涅斯及勃鲁托斯上。\u003c/p>\n","text":"米尼涅斯、西西涅斯及勃鲁托斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00310","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 占卜的人告诉我，我们今晚将有消息到来。\u003c/p>\n","text":"米尼涅斯 占卜的人告诉我，我们今晚将有消息到来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00311","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 好消息还是坏消息？\u003c/p>\n","text":"勃鲁托斯 好消息还是坏消息？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00312","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 这消息不是人民所希望听到的，因为他们对马歇斯没有好感。\u003c/p>\n","text":"米尼涅斯 这消息不是人民所希望听到的，因为他们对马歇斯没有好感。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00313","html":"\u003cp class=\"epub-calibre1\">西西涅斯 畜生也知道谁是他们的友人。\u003c/p>\n","text":"西西涅斯 畜生也知道谁是他们的友人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00314","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 请问，狼喜欢什么？\u003c/p>\n","text":"米尼涅斯 请问，狼喜欢什么？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00315","html":"\u003cp class=\"epub-calibre1\">西西涅斯 羔羊。\u003c/p>\n","text":"西西涅斯 羔羊。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00316","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 对了，因为它可以吃它，正像那些饥饿的平民恨不得把尊贵的马歇斯吃下去一般。\u003c/p>\n","text":"米尼涅斯 对了，因为它可以吃它，正像那些饥饿的平民恨不得把尊贵的马歇斯吃下去一般。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00317","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 他真是一头羔羊！吼起来却像一头熊。\u003c/p>\n","text":"勃鲁托斯 他真是一头羔羊！吼起来却像一头熊。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00318","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 他真是一头熊！却过着羔羊一般的生活。你们两位都是老人家了；让我问你们一件事情，请你们告诉我。\u003c/p>\n","text":"米尼涅斯 他真是一头熊！却过着羔羊一般的生活。你们两位都是老人家了；让我问你们一件事情，请你们告诉我。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00319","html":"\u003cp class=\"epub-calibre1\">西西涅斯 勃鲁托斯 好，你说。\u003c/p>\n","text":"西西涅斯 勃鲁托斯 好，你说。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00320","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 马歇斯究竟有些什么重大的缺点，这种缺点是不是也可以从你们两位身上同样找出许多来呢？\u003c/p>\n","text":"米尼涅斯 马歇斯究竟有些什么重大的缺点，这种缺点是不是也可以从你们两位身上同样找出许多来呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00321","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 任何缺点他都不缺少，所有的缺点他都齐备。\u003c/p>\n","text":"勃鲁托斯 任何缺点他都不缺少，所有的缺点他都齐备。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00322","html":"\u003cp class=\"epub-calibre1\">西西涅斯 尤其是骄傲。\u003c/p>\n","text":"西西涅斯 尤其是骄傲。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00323","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 他的自负更可以凌越一切。\u003c/p>\n","text":"勃鲁托斯 他的自负更可以凌越一切。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00324","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 这可奇了。你们两位知道我们这城里的人，我的意思是说，我们在军中有地位的人怎样批评你们吗？\u003c/p>\n","text":"米尼涅斯 这可奇了。你们两位知道我们这城里的人，我的意思是说，我们在军中有地位的人怎样批评你们吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00325","html":"\u003cp class=\"epub-calibre1\">西西涅斯 勃鲁托斯 他们怎样批评我们？\u003c/p>\n","text":"西西涅斯 勃鲁托斯 他们怎样批评我们？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00326","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 因为你们现在说起骄傲——你们不会生气吗？\u003c/p>\n","text":"米尼涅斯 因为你们现在说起骄傲——你们不会生气吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00327","html":"\u003cp class=\"epub-calibre1\">西西涅斯 勃鲁托斯 好，好，你说吧。\u003c/p>\n","text":"西西涅斯 勃鲁托斯 好，好，你说吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00328","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 好，那也没有什么关系；因为本来就是芝麻大的一点小事，也会使你们大发脾气的。把你们的火性耐一耐；要是你们一定要动怒，那也随你们的便。你们怪马歇斯太骄傲吗？\u003c/p>\n","text":"米尼涅斯 好，那也没有什么关系；因为本来就是芝麻大的一点小事，也会使你们大发脾气的。把你们的火性耐一耐；要是你们一定要动怒，那也随你们的便。你们怪马歇斯太骄傲吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00329","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 这不单是我们两人的意见。\u003c/p>\n","text":"勃鲁托斯 这不单是我们两人的意见。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00330","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我知道单单凭着你们两个人，是再也干不出什么大事情来的；你们的助手太多了，否则你们的行动就会变的非常简单；你们的能力太幼稚了，只好因人成事。你们说起骄傲；啊！要是你们能够转过眼睛来看看你们自己的背后，把你们自己反省一下！啊，要是你们能够！\u003c/p>\n","text":"米尼涅斯 我知道单单凭着你们两个人，是再也干不出什么大事情来的；你们的助手太多了，否则你们的行动就会变的非常简单；你们的能力太幼稚了，只好因人成事。你们说起骄傲；啊！要是你们能够转过眼睛来看看你们自己的背后，把你们自己反省一下！啊，要是你们能够！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00331","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 那便怎样呢？\u003c/p>\n","text":"勃鲁托斯 那便怎样呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00332","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 那时候你们就可以看见一双全罗马最骄傲狂妄、无功受禄的官儿，换句话说，全罗马一对最大的傻瓜。\u003c/p>\n","text":"米尼涅斯 那时候你们就可以看见一双全罗马最骄傲狂妄、无功受禄的官儿，换句话说，全罗马一对最大的傻瓜。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00333","html":"\u003cp class=\"epub-calibre1\">西西涅斯 米尼涅斯，谁都知道你是个怎样的人。\u003c/p>\n","text":"西西涅斯 米尼涅斯，谁都知道你是个怎样的人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00334","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 谁都知道我是个喜欢说说笑话的贵族，也喜欢喝杯不掺水的热酒；人家说我有点先入为主，太容易大惊小怪；我喜欢作长夜之宴，不高兴日出而作；想到什么就要说出来，不让一些芥蒂留在心里。碰到像你们这样的两位贵人——恕我不能称你们为圣人——要是你们给我喝的酒不合我的口味，我就会向它扮鬼脸；要是你们所发表的高论，大部分都是些驴子叫，我也不敢恭维你们讲得不错；虽然人家要是说你们是两位尊严可敬的长者，我也只好不去跟他们争论，可是谁说你们长着很好的相貌，就是说了一个大谎。你们要是从我的为人里看出这一点，就算你们了解我了吗？即使算你们了解了我，那么以你们昏聩的眼光，又能从我的这种品性里看出什么缺点来呢？\u003c/p>\n","text":"米尼涅斯 谁都知道我是个喜欢说说笑话的贵族，也喜欢喝杯不掺水的热酒；人家说我有点先入为主，太容易大惊小怪；我喜欢作长夜之宴，不高兴日出而作；想到什么就要说出来，不让一些芥蒂留在心里。碰到像你们这样的两位贵人——恕我不能称你们为圣人——要是你们给我喝的酒不合我的口味，我就会向它扮鬼脸；要是你们所发表的高论，大部分都是些驴子叫，我也不敢恭维你们讲得不错；虽然人家要是说你们是两位尊严可敬的长者，我也只好不去跟他们争论，可是谁说你们长着很好的相貌，就是说了一个大谎。你们要是从我的为人里看出这一点，就算你们了解我了吗？即使算你们了解了我，那么以你们昏聩的眼光，又能从我的这种品性里看出什么缺点来呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00335","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 算了，算了，我们了解你是个怎样的人。\u003c/p>\n","text":"勃鲁托斯 算了，算了，我们了解你是个怎样的人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00336","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 你们既不了解我，也不了解你们自己，你们什么都不了解。只要那些苦人们向你们脱帽屈膝，你们就觉得踌躇满志。你们费去整整的一个大好下午，审判一个卖橘子的女人跟一个卖塞子的男人涉讼的案件，结果还是把这场三便士的官司宣布延期判决。当你们正在听两造辩论的时候，要是突然发起疝气痛来，你们就会现出一脸的怪相，暴跳如雷，一面连声喊拿便壶来，一面斥退两造，好好一件案子，给你们越审越糊涂；纠纷没有解决，两下里只是挨你们骂了几声混蛋。你们真是一对奇怪的宝贝。\u003c/p>\n","text":"米尼涅斯 你们既不了解我，也不了解你们自己，你们什么都不了解。只要那些苦人们向你们脱帽屈膝，你们就觉得踌躇满志。你们费去整整的一个大好下午，审判一个卖橘子的女人跟一个卖塞子的男人涉讼的案件，结果还是把这场三便士的官司宣布延期判决。当你们正在听两造辩论的时候，要是突然发起疝气痛来，你们就会现出一脸的怪相，暴跳如雷，一面连声喊拿便壶来，一面斥退两造，好好一件案子，给你们越审越糊涂；纠纷没有解决，两下里只是挨你们骂了几声混蛋。你们真是一对奇怪的宝贝。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00337","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 算了，算了，大家都知道你在筵席上是一个嬉笑怒骂的好手，在议会里却是一个毫无用处的人物。\u003c/p>\n","text":"勃鲁托斯 算了，算了，大家都知道你在筵席上是一个嬉笑怒骂的好手，在议会里却是一个毫无用处的人物。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00338","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我们的教士们见了你们这种荒唐的家伙，也会忍不住把你们嘲笑。你们讲得最中肯的时候，那些话也不值得你们挥动你们的胡须；讲到你们的胡须，那么还不配塞在一个拙劣的椅垫或是驴子的驮鞍里。可是你们一定要说马歇斯是骄傲的；按照最低的估计，他也抵得过你们所有的老前辈合起来的价值，虽然他们中间有几个最有名的人物也许是世代相传的刽子手。晚安，两位尊驾；你们是那群畜类一般的平民的牧人，我再跟你们谈下去，我的脑子也要沾上污秽了；恕我失礼少陪啦。\u003cb class=\"epub-calibre3\">（勃鲁托斯、西西涅斯退至一旁。）\u003c/b>\u003c/p>\n","text":"米尼涅斯 我们的教士们见了你们这种荒唐的家伙，也会忍不住把你们嘲笑。你们讲得最中肯的时候，那些话也不值得你们挥动你们的胡须；讲到你们的胡须，那么还不配塞在一个拙劣的椅垫或是驴子的驮鞍里。可是你们一定要说马歇斯是骄傲的；按照最低的估计，他也抵得过你们所有的老前辈合起来的价值，虽然他们中间有几个最有名的人物也许是世代相传的刽子手。晚安，两位尊驾；你们是那群畜类一般的平民的牧人，我再跟你们谈下去，我的脑子也要沾上污秽了；恕我失礼少陪啦。（勃鲁托斯、西西涅斯退至一旁。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00339","html":"\u003cp class=\"epub-block1\">伏伦妮娅，维吉利娅及凡勒利娅上。\u003c/p>\n","text":"伏伦妮娅，维吉利娅及凡勒利娅上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00340","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 啊，我的又美丽又高贵的太太们，月亮要是降下尘世；也不会比你们更高贵；请问你们这样热烈地在望着什么？\u003c/p>\n","text":"米尼涅斯 啊，我的又美丽又高贵的太太们，月亮要是降下尘世；也不会比你们更高贵；请问你们这样热烈地在望着什么？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00341","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 正直的米尼涅斯，我的孩子马歇斯来了；为了天后朱诺的爱，让我们去吧。\u003c/p>\n","text":"伏伦妮娅 正直的米尼涅斯，我的孩子马歇斯来了；为了天后朱诺的爱，让我们去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00342","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 哈！马歇斯回来了吗？\u003c/p>\n","text":"米尼涅斯 哈！马歇斯回来了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00343","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 是的，尊贵的米尼涅斯，他载着胜利的荣誉回来了。\u003c/p>\n","text":"伏伦妮娅 是的，尊贵的米尼涅斯，他载着胜利的荣誉回来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00344","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 让我向您脱帽致敬，朱庇特，我谢谢您。呵！马歇斯回来了！\u003c/p>\n","text":"米尼涅斯 让我向您脱帽致敬，朱庇特，我谢谢您。呵！马歇斯回来了！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00345","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 维吉利娅 是的，他真的回来了。\u003c/p>\n","text":"伏伦妮娅 维吉利娅 是的，他真的回来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00346","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 瞧，这儿是他写来的一封信。他还有一封信给政府，还有一封给他的妻子；我想您家里也有一封他写给您的信。\u003c/p>\n","text":"伏伦妮娅 瞧，这儿是他写来的一封信。他还有一封信给政府，还有一封给他的妻子；我想您家里也有一封他写给您的信。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00347","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我今晚要高兴得把我的屋子都掀翻了。有一封信给我！\u003c/p>\n","text":"米尼涅斯 我今晚要高兴得把我的屋子都掀翻了。有一封信给我！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00348","html":"\u003cp class=\"epub-calibre1\">维吉利娅 是的，真的有一封信给您；我看见的。\u003c/p>\n","text":"维吉利娅 是的，真的有一封信给您；我看见的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00349","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 有一封信给我！读了他的信可以使我七年不害病，在这七年里头，我要向医生撇嘴唇；比起这一味延年却病的灵丹来，药经里最神效的药方也只算江湖医生的草头方，只好胡乱给马儿治治病。他没有受伤吗？他每一次回来的时候，总是负着伤的。\u003c/p>\n","text":"米尼涅斯 有一封信给我！读了他的信可以使我七年不害病，在这七年里头，我要向医生撇嘴唇；比起这一味延年却病的灵丹来，药经里最神效的药方也只算江湖医生的草头方，只好胡乱给马儿治治病。他没有受伤吗？他每一次回来的时候，总是负着伤的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00350","html":"\u003cp class=\"epub-calibre1\">维吉利娅 啊，不，不，不。\u003c/p>\n","text":"维吉利娅 啊，不，不，不。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00351","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 啊！他是受伤的，感谢天神！\u003c/p>\n","text":"伏伦妮娅 啊！他是受伤的，感谢天神！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00352","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 只要受伤不厉害，我也要感谢天神。他把胜利放进他的口袋里了吗？受了伤才更可以显出他的英雄。\u003c/p>\n","text":"米尼涅斯 只要受伤不厉害，我也要感谢天神。他把胜利放进他的口袋里了吗？受了伤才更可以显出他的英雄。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00353","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 他把胜利高悬在额角上，米尼涅斯；他已经第三次戴着橡叶冠回来了。\u003c/p>\n","text":"伏伦妮娅 他把胜利高悬在额角上，米尼涅斯；他已经第三次戴着橡叶冠回来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00354","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 他已经把奥菲狄乌斯痛痛快快地教训过了吗？\u003c/p>\n","text":"米尼涅斯 他已经把奥菲狄乌斯痛痛快快地教训过了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00355","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 泰特斯·拉歇斯信上说他们曾经交战过，可是奥菲狄乌斯逃走了。\u003c/p>\n","text":"伏伦妮娅 泰特斯·拉歇斯信上说他们曾经交战过，可是奥菲狄乌斯逃走了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00356","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 的确，他也只好逃走；否则，即使有全科利奥里城里的宝柜和金银，我也根本不会再提起这个奥菲狄乌斯的名字的。元老院有没有知道这一个消息？\u003c/p>\n","text":"米尼涅斯 的确，他也只好逃走；否则，即使有全科利奥里城里的宝柜和金银，我也根本不会再提起这个奥菲狄乌斯的名字的。元老院有没有知道这一个消息？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00357","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 两位好夫人，我们去吧。是的，是的，是的，元老院已经得到元帅的来信，他把这次战争的全部功劳归在我的儿子身上。他这一次的战功的确比他以前各次的战功更要超过一倍。\u003c/p>\n","text":"伏伦妮娅 两位好夫人，我们去吧。是的，是的，是的，元老院已经得到元帅的来信，他把这次战争的全部功劳归在我的儿子身上。他这一次的战功的确比他以前各次的战功更要超过一倍。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00358","html":"\u003cp class=\"epub-calibre1\">凡勒利娅 真的，他们都说起关于他的许多惊人的作为。\u003c/p>\n","text":"凡勒利娅 真的，他们都说起关于他的许多惊人的作为。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00359","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 惊人的作为！嘿，我告诉你吧，这些都是他凭着真本领干下来的呢。\u003c/p>\n","text":"米尼涅斯 惊人的作为！嘿，我告诉你吧，这些都是他凭着真本领干下来的呢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00360","html":"\u003cp class=\"epub-calibre1\">维吉利娅 愿天神默佑那些话都是真的！\u003c/p>\n","text":"维吉利娅 愿天神默佑那些话都是真的！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00361","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 真的！还会是假的不成？\u003c/p>\n","text":"伏伦妮娅 真的！还会是假的不成？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00362","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 真的！我可以发誓那些话都是真的。他什么地方受了伤？\u003cb class=\"epub-calibre3\">（向西西涅斯、勃鲁托斯）\u003c/b>上帝保佑两位尊驾！马歇斯回来了；他有更多可以骄傲的理由啦。\u003cb class=\"epub-calibre3\">（向伏伦妮娅）\u003c/b>他什么地方受了伤？\u003c/p>\n","text":"米尼涅斯 真的！我可以发誓那些话都是真的。他什么地方受了伤？（向西西涅斯、勃鲁托斯）上帝保佑两位尊驾！马歇斯回来了；他有更多可以骄傲的理由啦。（向伏伦妮娅）他什么地方受了伤？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00363","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 肩膀上，左臂上；当他在民众之前站起来的时候，他可以把很大的伤疤公开展示哩。在击退塔昆这一役中间，他身上有七处受伤。\u003c/p>\n","text":"伏伦妮娅 肩膀上，左臂上；当他在民众之前站起来的时候，他可以把很大的伤疤公开展示哩。在击退塔昆这一役中间，他身上有七处受伤。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00364","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 颈上一处，大腿上两处，我知道一共有九处。\u003c/p>\n","text":"米尼涅斯 颈上一处，大腿上两处，我知道一共有九处。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00365","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 在这一次出征以前，他全身一共有二十五处伤痕。\u003c/p>\n","text":"伏伦妮娅 在这一次出征以前，他全身一共有二十五处伤痕。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00366","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 现在是二十七处了；每一个伤口都是一个敌人的坟墓。\u003cb class=\"epub-calibre3\">（内欢呼声，喇叭奏花腔）\u003c/b>听！喇叭的声音！\u003c/p>\n","text":"米尼涅斯 现在是二十七处了；每一个伤口都是一个敌人的坟墓。（内欢呼声，喇叭奏花腔）听！喇叭的声音！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00367","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 这是马歇斯将要到来的预报。凡是他所到之处，总是震响着雷声；他经过以后，只留下一片汪洋的泪海；在他壮健的臂腕里躲藏着幽冥的死神；只要他一挥手，人们就丧失了生命。\u003c/p>\n","text":"伏伦妮娅 这是马歇斯将要到来的预报。凡是他所到之处，总是震响着雷声；他经过以后，只留下一片汪洋的泪海；在他壮健的臂腕里躲藏着幽冥的死神；只要他一挥手，人们就丧失了生命。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00368","html":"\u003cp class=\"epub-block1\">喇叭奏花腔。考密涅斯及泰特斯·拉歇斯拥科利奥兰纳斯戴橡叶冠上，将校、兵士及一传令官随上。\u003c/p>\n","text":"喇叭奏花腔。考密涅斯及泰特斯·拉歇斯拥科利奥兰纳斯戴橡叶冠上，将校、兵士及一传令官随上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00369","html":"\u003cp class=\"epub-calibre1\">传令官 罗马全体人民听着：马歇斯单身独力，在科利奥里城内奋战；他已经在那里赢得了一个光荣的名字，在卡厄斯·马歇斯之后，加上科利奥兰纳斯的荣称。欢迎您到罗马来，著名的科利奥兰纳斯！\u003cb class=\"epub-calibre3\">（喇叭奏花腔。）\u003c/b>\u003c/p>\n","text":"传令官 罗马全体人民听着：马歇斯单身独力，在科利奥里城内奋战；他已经在那里赢得了一个光荣的名字，在卡厄斯·马歇斯之后，加上科利奥兰纳斯的荣称。欢迎您到罗马来，著名的科利奥兰纳斯！（喇叭奏花腔。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00370","html":"\u003cp class=\"epub-calibre1\">众人 欢迎您到罗马来，著名的科利奥兰纳斯！\u003c/p>\n","text":"众人 欢迎您到罗马来，著名的科利奥兰纳斯！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00371","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 快别这样；我不喜欢这一套。请你们免了吧。\u003c/p>\n","text":"科利奥兰纳斯 快别这样；我不喜欢这一套。请你们免了吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00372","html":"\u003cp class=\"epub-calibre1\">考密涅斯 瞧，将军，您的母亲！\u003c/p>\n","text":"考密涅斯 瞧，将军，您的母亲！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00373","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 啊！我知道您为了我的胜利，一定已经祈祷过所有的神明。\u003cb class=\"epub-calibre3\">（跪下。）\u003c/b>\u003c/p>\n","text":"科利奥兰纳斯 啊！我知道您为了我的胜利，一定已经祈祷过所有的神明。（跪下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00374","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 不，我的好军人，起来；我的善良的马歇斯，尊贵的卡厄斯，还有你那个凭着功劳博得的新的荣名——那是怎么叫的？——我必须称呼你科利奥兰纳斯吗？——可是啊！你的妻子！——\u003c/p>\n","text":"伏伦妮娅 不，我的好军人，起来；我的善良的马歇斯，尊贵的卡厄斯，还有你那个凭着功劳博得的新的荣名——那是怎么叫的？——我必须称呼你科利奥兰纳斯吗？——可是啊！你的妻子！——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00375","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我的静默的好人儿，愿你有福！你这样泪流满面地迎接我的凯旋，要是一具棺材装着我的尸骨回来，你倒会含笑吗？啊！我的亲爱的，科利奥里的寡妇和失去儿子的母亲，她们的眼睛也哭得像你一样。\u003c/p>\n","text":"科利奥兰纳斯 我的静默的好人儿，愿你有福！你这样泪流满面地迎接我的凯旋，要是一具棺材装着我的尸骨回来，你倒会含笑吗？啊！我的亲爱的，科利奥里的寡妇和失去儿子的母亲，她们的眼睛也哭得像你一样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00376","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 愿天神替你加上荣冠！\u003c/p>\n","text":"米尼涅斯 愿天神替你加上荣冠！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00377","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你还活着吗？\u003cb class=\"epub-calibre3\">（向凡勒利娅）\u003c/b>啊，我的好夫人，恕我失礼。\u003c/p>\n","text":"科利奥兰纳斯 你还活着吗？（向凡勒利娅）啊，我的好夫人，恕我失礼。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00378","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 我不知道应当转身向什么地方。啊！欢迎你们回来！欢迎，元帅！欢迎，各位将士！\u003c/p>\n","text":"伏伦妮娅 我不知道应当转身向什么地方。啊！欢迎你们回来！欢迎，元帅！欢迎，各位将士！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00379","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 十万个欢迎！我也想哭，也想笑；我的心又轻松又沉重。欢迎！谁要是不高兴看见你，愿咒诅咬啮着他的心！你们是应当被罗马所眷爱的三个人；可是凭着人类的忠心起誓，在我们的城市里却有几棵老山楂树，它们的口味是和你们不同的。可是欢迎，战士们！是荨麻我们就叫它荨麻，傻瓜们的错处一言以蔽之，其名为愚蠢。\u003c/p>\n","text":"米尼涅斯 十万个欢迎！我也想哭，也想笑；我的心又轻松又沉重。欢迎！谁要是不高兴看见你，愿咒诅咬啮着他的心！你们是应当被罗马所眷爱的三个人；可是凭着人类的忠心起誓，在我们的城市里却有几棵老山楂树，它们的口味是和你们不同的。可是欢迎，战士们！是荨麻我们就叫它荨麻，傻瓜们的错处一言以蔽之，其名为愚蠢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00380","html":"\u003cp class=\"epub-calibre1\">考密涅斯 你说得有理。\u003c/p>\n","text":"考密涅斯 你说得有理。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00381","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 米尼涅斯，这是永远的真理。\u003c/p>\n","text":"科利奥兰纳斯 米尼涅斯，这是永远的真理。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00382","html":"\u003cp class=\"epub-calibre1\">传令官 站开，站开！\u003c/p>\n","text":"传令官 站开，站开！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00383","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 \u003cb class=\"epub-calibre3\">（向伏伦妮娅、凡勒利娅）\u003c/b>让我吻您的手，再让我吻您的。在我还没有回到自己家里去以前，我必须先去访问那些贵族们；他们不但给我欢迎，而且还给我新的光荣。\u003c/p>\n","text":"科利奥兰纳斯 （向伏伦妮娅、凡勒利娅）让我吻您的手，再让我吻您的。在我还没有回到自己家里去以前，我必须先去访问那些贵族们；他们不但给我欢迎，而且还给我新的光荣。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00384","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 我已经活到今天，看见我的愿望一一实现，我的幻想构成的美梦成为事实；现在只有一个愿望还没有满足，可是我相信我们的罗马一定会把它加在你的身上的。\u003c/p>\n","text":"伏伦妮娅 我已经活到今天，看见我的愿望一一实现，我的幻想构成的美梦成为事实；现在只有一个愿望还没有满足，可是我相信我们的罗马一定会把它加在你的身上的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00385","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 好妈妈，您要知道，我宁愿照我自己的意思做他们的仆人，不愿擅权弄势，和他们在一起做主人。\u003c/p>\n","text":"科利奥兰纳斯 好妈妈，您要知道，我宁愿照我自己的意思做他们的仆人，不愿擅权弄势，和他们在一起做主人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00386","html":"\u003cp class=\"epub-calibre1\">考密涅斯 前进，到议会去！\u003cb class=\"epub-calibre3\">（喇叭奏花腔；吹号筒。众列队按序下；西西涅斯、勃鲁托斯留场。）\u003c/b>\u003c/p>\n","text":"考密涅斯 前进，到议会去！（喇叭奏花腔；吹号筒。众列队按序下；西西涅斯、勃鲁托斯留场。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00387","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 所有的舌头都在讲他，眼光昏花的老头子也都戴了眼镜出来瞧他；饶舌的乳媪因为讲他讲得出了神，让她的孩子在一旁啼哭；灶下的丫头也把她最好的麻巾裹在她那油腻的颈上，爬上墙头去望他；马棚里、阳台上、窗眼里，全都挤满了，水沟里、田塍上，也都站满着各色各样的人，大家争先恐后地想看一看他的脸；难得露脸的祭司也在人丛里挤来挤去，跟人家占夺一个地位；蒙着面罩的太太奶奶们也让她们用心装扮过的面庞去接受阳光的热吻，吻得一块红、一块白的；真是热闹极了，简直像把他当作了一尊天神的化身似的。\u003c/p>\n","text":"勃鲁托斯 所有的舌头都在讲他，眼光昏花的老头子也都戴了眼镜出来瞧他；饶舌的乳媪因为讲他讲得出了神，让她的孩子在一旁啼哭；灶下的丫头也把她最好的麻巾裹在她那油腻的颈上，爬上墙头去望他；马棚里、阳台上、窗眼里，全都挤满了，水沟里、田塍上，也都站满着各色各样的人，大家争先恐后地想看一看他的脸；难得露脸的祭司也在人丛里挤来挤去，跟人家占夺一个地位；蒙着面罩的太太奶奶们也让她们用心装扮过的面庞去接受阳光的热吻，吻得一块红、一块白的；真是热闹极了，简直像把他当作了一尊天神的化身似的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00388","html":"\u003cp class=\"epub-calibre1\">西西涅斯 我说，他这次一定有做执政的希望。\u003c/p>\n","text":"西西涅斯 我说，他这次一定有做执政的希望。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00389","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 那么当他握权的时候，我们只好无所事事了。\u003c/p>\n","text":"勃鲁托斯 那么当他握权的时候，我们只好无所事事了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00390","html":"\u003cp class=\"epub-calibre1\">西西涅斯 他初握政权，地位还不能巩固，可是他将要失去他已得的光荣。\u003c/p>\n","text":"西西涅斯 他初握政权，地位还不能巩固，可是他将要失去他已得的光荣。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00391","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 那就好了。\u003c/p>\n","text":"勃鲁托斯 那就好了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00392","html":"\u003cp class=\"epub-calibre1\">西西涅斯 你放心吧，我们所代表的平民，本来对他抱着恶感，只要为了些微细故，就会忘记他新得的光荣，凭着他这副骄傲的脾气，我相信他一定会干出一些不慊人意的事来。\u003c/p>\n","text":"西西涅斯 你放心吧，我们所代表的平民，本来对他抱着恶感，只要为了些微细故，就会忘记他新得的光荣，凭着他这副骄傲的脾气，我相信他一定会干出一些不慊人意的事来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00393","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 我听见他发誓说，要是他被推为执政，他决不到市场上去，也不愿穿上表示谦卑的粗衣；他也不愿按照习惯，把他的伤痕袒露给人民看，从他们恶臭的嘴里求得同意。\u003c/p>\n","text":"勃鲁托斯 我听见他发誓说，要是他被推为执政，他决不到市场上去，也不愿穿上表示谦卑的粗衣；他也不愿按照习惯，把他的伤痕袒露给人民看，从他们恶臭的嘴里求得同意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00394","html":"\u003cp class=\"epub-calibre1\">西西涅斯 正是这样。\u003c/p>\n","text":"西西涅斯 正是这样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00395","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 他是这样说的。啊！他宁愿放弃执政的地位，也不愿俯从绅士贵族们的请求去干这样的事。\u003c/p>\n","text":"勃鲁托斯 他是这样说的。啊！他宁愿放弃执政的地位，也不愿俯从绅士贵族们的请求去干这样的事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00396","html":"\u003cp class=\"epub-calibre1\">西西涅斯 我但愿他坚持着这样的意思，把它见之实施。\u003c/p>\n","text":"西西涅斯 我但愿他坚持着这样的意思，把它见之实施。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00397","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 他大概会这么干的。\u003c/p>\n","text":"勃鲁托斯 他大概会这么干的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00398","html":"\u003cp class=\"epub-calibre1\">西西涅斯 要是真的这样，那么正像我们所希望的，他的崩溃一定无可避免了。\u003c/p>\n","text":"西西涅斯 要是真的这样，那么正像我们所希望的，他的崩溃一定无可避免了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00399","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 他要是不倒，我们的权力也要动摇。为了促成他的没落，我们必须让人民知道他一向对于他们怀着怎样的敌意；要是他掌握了大权，他一定要把他们当作骡马一样看待，压制他们的申诉，剥夺他们的自由；认为他们的行动和能力是不适宜于处理世间的事务的，正像战争的时候用不着骆驼一样；豢养他们的目的，只是要他们担负重荷，要是他们在重负之下压得爬不起来，一顿痛打便是给他们的赏赐。\u003c/p>\n","text":"勃鲁托斯 他要是不倒，我们的权力也要动摇。为了促成他的没落，我们必须让人民知道他一向对于他们怀着怎样的敌意；要是他掌握了大权，他一定要把他们当作骡马一样看待，压制他们的申诉，剥夺他们的自由；认为他们的行动和能力是不适宜于处理世间的事务的，正像战争的时候用不着骆驼一样；豢养他们的目的，只是要他们担负重荷，要是他们在重负之下压得爬不起来，一顿痛打便是给他们的赏赐。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00400","html":"\u003cp class=\"epub-calibre1\">西西涅斯 只要给他一点刺激，他的傲慢不逊的脾气，一定会向人民发泄出来，正像嗾使一群狗去咬绵羊一样容易；那时候你这一番话就等于点在干柴上的一把烈火，那火焰可以使他的声名从此化为灰烬。\u003c/p>\n","text":"西西涅斯 只要给他一点刺激，他的傲慢不逊的脾气，一定会向人民发泄出来，正像嗾使一群狗去咬绵羊一样容易；那时候你这一番话就等于点在干柴上的一把烈火，那火焰可以使他的声名从此化为灰烬。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00401","html":"\u003cp class=\"epub-block1\">一使者上。\u003c/p>\n","text":"一使者上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00402","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 有什么事？\u003c/p>\n","text":"勃鲁托斯 有什么事？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00403","html":"\u003cp class=\"epub-calibre1\">使者 请两位大人到议会里去。人家都以为马歇斯将要做执政。我看见聋子围拢来瞧他，瞎子围拢去听他讲话；当他一路经过的时候，中年的妇女向他挥手套，年轻的姑娘向他挥围巾手帕；贵族们见了他，像对着乔武的神像似的鞠躬致敬，平民们见了他，都纷纷掷帽；欢声雷动；我从来没有见过这样的景象。\u003c/p>\n","text":"使者 请两位大人到议会里去。人家都以为马歇斯将要做执政。我看见聋子围拢来瞧他，瞎子围拢去听他讲话；当他一路经过的时候，中年的妇女向他挥手套，年轻的姑娘向他挥围巾手帕；贵族们见了他，像对着乔武的神像似的鞠躬致敬，平民们见了他，都纷纷掷帽；欢声雷动；我从来没有见过这样的景象。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00404","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 我们到议会去吧。让我们一面用耳朵和眼睛留心着眼前的情势，一面用我们的心思想着未来的意图。\u003c/p>\n","text":"勃鲁托斯 我们到议会去吧。让我们一面用耳朵和眼睛留心着眼前的情势，一面用我们的心思想着未来的意图。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00405","html":"\u003cp class=\"epub-calibre1\">西西涅斯 那么请了。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"西西涅斯 那么请了。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第一场 罗马。广场","headingLevel":4,"sourceAnchor":"a734","actNumber":2,"sceneNumber":1},{"id":"part0031-section-014","label":"第二幕 · 第二场 同前。议会","kind":"scene","blocks":[{"id":"part0031-00406","html":"\u003ch4 id=\"epub-part0031-a735\" class=\"epub-calibre12\">第二场 同前。议会\u003c/h4>\n","text":"第二场 同前。议会\n","sourceAnchor":"a735","tag":"h4"},{"id":"part0031-00407","html":"\u003cp class=\"epub-block1\">二吏役上，铺坐垫。\u003c/p>\n","text":"二吏役上，铺坐垫。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00408","html":"\u003cp class=\"epub-calibre1\">吏甲 来，来，他们快要来了。有多少人竞争执政的位置？\u003c/p>\n","text":"吏甲 来，来，他们快要来了。有多少人竞争执政的位置？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00409","html":"\u003cp class=\"epub-calibre1\">吏乙 他们说有三个人；可是谁都以为科利奥兰纳斯一定会当选。\u003c/p>\n","text":"吏乙 他们说有三个人；可是谁都以为科利奥兰纳斯一定会当选。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00410","html":"\u003cp class=\"epub-calibre1\">吏甲 他是个好汉子；可是他太骄傲了，对于平民也没有好感。\u003c/p>\n","text":"吏甲 他是个好汉子；可是他太骄傲了，对于平民也没有好感。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00411","html":"\u003cp class=\"epub-calibre1\">吏乙 老实说一句，有许多大人物尽管口头上拼命讨好平民，心里却一点不喜欢他们；也有许多人喜欢了一个人，却不知道为什么要喜欢他，他们既然会莫名其妙地爱他，也就会莫名其妙地恨他。所以科利奥兰纳斯对于他们的爱憎漠不关心，正可以表示他真正了解他们的性格；他也由他们去看得一清二楚，满不在意。\u003c/p>\n","text":"吏乙 老实说一句，有许多大人物尽管口头上拼命讨好平民，心里却一点不喜欢他们；也有许多人喜欢了一个人，却不知道为什么要喜欢他，他们既然会莫名其妙地爱他，也就会莫名其妙地恨他。所以科利奥兰纳斯对于他们的爱憎漠不关心，正可以表示他真正了解他们的性格；他也由他们去看得一清二楚，满不在意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00412","html":"\u003cp class=\"epub-calibre1\">吏甲 要是他对于他们的爱憎漠不关心，那么他既不会有心讨好他们，也不会故意冒犯他们；可是他对他们寻衅的心理，却比他们对他仇恨的心理更强，凡是可以表明他是他们的敌人的事实，他总是不加讳饰地表现出来。像这样有意装出敌视人民的态度，比起他所唾弃的那种取媚人民以求得他们欢心的手段来，同样是不足为法的。\u003c/p>\n","text":"吏甲 要是他对于他们的爱憎漠不关心，那么他既不会有心讨好他们，也不会故意冒犯他们；可是他对他们寻衅的心理，却比他们对他仇恨的心理更强，凡是可以表明他是他们的敌人的事实，他总是不加讳饰地表现出来。像这样有意装出敌视人民的态度，比起他所唾弃的那种取媚人民以求得他们欢心的手段来，同样是不足为法的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00413","html":"\u003cp class=\"epub-calibre1\">吏乙 他替国家立下了极大的功劳；他的跻登高位，绝不像那些毫无寸尺之功、单凭着向人民曲意逢迎的手段滥邀爵禄的人们那样容易；他的荣誉彪炳在他们的眼前，他的功业铭刻在他们的心底，他们要是不作一声，否认这一切，那就是忘恩负义；要是颠倒是非，混淆黑白，那就是恶意中伤。\u003c/p>\n","text":"吏乙 他替国家立下了极大的功劳；他的跻登高位，绝不像那些毫无寸尺之功、单凭着向人民曲意逢迎的手段滥邀爵禄的人们那样容易；他的荣誉彪炳在他们的眼前，他的功业铭刻在他们的心底，他们要是不作一声，否认这一切，那就是忘恩负义；要是颠倒是非，混淆黑白，那就是恶意中伤。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00414","html":"\u003cp class=\"epub-calibre1\">吏甲 别讲他了；他是一个可尊敬的人。让开，他们来了。\u003c/p>\n","text":"吏甲 别讲他了；他是一个可尊敬的人。让开，他们来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00415","html":"\u003cp class=\"epub-block1\">喇叭奏花腔。侍卫官前导，考密涅斯（执政）、米尼涅斯、科利奥兰纳斯、众元老、西西涅斯、勃鲁托斯同上；元老及护民官依次就座。\u003c/p>\n","text":"喇叭奏花腔。侍卫官前导，考密涅斯（执政）、米尼涅斯、科利奥兰纳斯、众元老、西西涅斯、勃鲁托斯同上；元老及护民官依次就座。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00416","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我们已经决定处置伏尔斯人的办法，并且决定召唤泰特斯·拉歇斯回来，剩下来要在这一次会议里决定的主要的问题，就是怎样酬报我们这一位为国宣劳的英雄。所以，各位尊严的元老们，请你们要求现任执政，也就是领导我们得到这一次胜利的主帅，略为向我们报告一些卡厄斯·马歇斯·科利奥兰纳斯所造成的英勇的伟绩，让我们可以按照他实际的功劳向他表示我们的感谢，并且用适当的尊荣褒奖他。\u003c/p>\n","text":"米尼涅斯 我们已经决定处置伏尔斯人的办法，并且决定召唤泰特斯·拉歇斯回来，剩下来要在这一次会议里决定的主要的问题，就是怎样酬报我们这一位为国宣劳的英雄。所以，各位尊严的元老们，请你们要求现任执政，也就是领导我们得到这一次胜利的主帅，略为向我们报告一些卡厄斯·马歇斯·科利奥兰纳斯所造成的英勇的伟绩，让我们可以按照他实际的功劳向他表示我们的感谢，并且用适当的尊荣褒奖他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00417","html":"\u003cp class=\"epub-calibre1\">元老甲 说吧，好考密涅斯；不要因为怕叙述太长而忽略了什么，宁可让我们觉得国家酬庸有功太菲薄，不要使我们觉得政府的爵禄失之过滥。\u003cb class=\"epub-calibre3\">（向西西涅斯、勃鲁托斯）\u003c/b>两位人民的代表，请你们耐心静听，当我们决定了一个结果以后，还要有劳你们向民众传达我们的意见，征求他们善意的同情。\u003c/p>\n","text":"元老甲 说吧，好考密涅斯；不要因为怕叙述太长而忽略了什么，宁可让我们觉得国家酬庸有功太菲薄，不要使我们觉得政府的爵禄失之过滥。（向西西涅斯、勃鲁托斯）两位人民的代表，请你们耐心静听，当我们决定了一个结果以后，还要有劳你们向民众传达我们的意见，征求他们善意的同情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00418","html":"\u003cp class=\"epub-calibre1\">西西涅斯 我们这次为了通过一个满意的条约而集会，在欣慰之余，我们是很愿意给我们这位英雄不次的荣迁的。\u003c/p>\n","text":"西西涅斯 我们这次为了通过一个满意的条约而集会，在欣慰之余，我们是很愿意给我们这位英雄不次的荣迁的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00419","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 要是他能够把他一向对人民的看法稍微改善一点，那么我们一定可以赞同。\u003c/p>\n","text":"勃鲁托斯 要是他能够把他一向对人民的看法稍微改善一点，那么我们一定可以赞同。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00420","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 不要说到题外去；我希望你还是不要开口的好。你们愿意听考密涅斯说话吗？\u003c/p>\n","text":"米尼涅斯 不要说到题外去；我希望你还是不要开口的好。你们愿意听考密涅斯说话吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00421","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 当然愿意；可是我的劝告却要比您的责备恰当一些哩。\u003c/p>\n","text":"勃鲁托斯 当然愿意；可是我的劝告却要比您的责备恰当一些哩。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00422","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 他喜爱你们的人民；可是不要硬叫他和他们睡在一个床上。尊贵的考密涅斯，说吧。\u003cb class=\"epub-calibre3\">（科利奥兰纳斯起立欲去）\u003c/b>不，您坐下。\u003c/p>\n","text":"米尼涅斯 他喜爱你们的人民；可是不要硬叫他和他们睡在一个床上。尊贵的考密涅斯，说吧。（科利奥兰纳斯起立欲去）不，您坐下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00423","html":"\u003cp class=\"epub-calibre1\">元老甲 坐下，科利奥兰纳斯；不要因为听到你自己所做的光荣的事情而惭愧。\u003c/p>\n","text":"元老甲 坐下，科利奥兰纳斯；不要因为听到你自己所做的光荣的事情而惭愧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00424","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 请诸位原谅，我宁愿让我的伤痕消失了形迹，不愿听人家讲起我得到它们时的情形。\u003c/p>\n","text":"科利奥兰纳斯 请诸位原谅，我宁愿让我的伤痕消失了形迹，不愿听人家讲起我得到它们时的情形。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00425","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 将军，我希望您不是因为听了我的话，所以不安于席的。\u003c/p>\n","text":"勃鲁托斯 将军，我希望您不是因为听了我的话，所以不安于席的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00426","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 不，可是往往打击使我停留，空言却使我逃避。你的话都是不关痛痒的。至于你的人民，我只能按照他们的价值来喜爱他们。\u003c/p>\n","text":"科利奥兰纳斯 不，可是往往打击使我停留，空言却使我逃避。你的话都是不关痛痒的。至于你的人民，我只能按照他们的价值来喜爱他们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00427","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 请坐下来吧。\u003c/p>\n","text":"米尼涅斯 请坐下来吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00428","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我宁愿在赴战的号角吹响的时候，让人家在太阳底下搔我的头颅，不愿呆坐着听人家把我的一些不足道的小事信口夸张。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"科利奥兰纳斯 我宁愿在赴战的号角吹响的时候，让人家在太阳底下搔我的头颅，不愿呆坐着听人家把我的一些不足道的小事信口夸张。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00429","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 两位人民代表，你们现在已经看见他宁愿用他全身的力量去追求荣誉，不愿分出一小部分的精神来听人家的赞美，他怎么能够向你们那些一千个中间难得有一个好人的芸芸众生浪费他的谀辞呢？说吧，考密涅斯。\u003c/p>\n","text":"米尼涅斯 两位人民代表，你们现在已经看见他宁愿用他全身的力量去追求荣誉，不愿分出一小部分的精神来听人家的赞美，他怎么能够向你们那些一千个中间难得有一个好人的芸芸众生浪费他的谀辞呢？说吧，考密涅斯。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00430","html":"\u003cp class=\"epub-calibre1\">考密涅斯 我的声音太微弱了，不够叙述科利奥兰纳斯的功绩。勇敢是世人公认的最大美德，有勇的人是最值得崇敬的；要是我们可以这么说，那么我现在所要说起的这一个人，在全世界简直找不出一个可以和他抗衡的人物。当塔昆举兵向罗马侵犯的时候，他还只有十六岁，就已经在战场上崭露头角，表现他过人的神勇；我们当时的执政亲眼看见那些鬑鬑多须的大汉被白皙韶秀的他追赶得没命奔逃。他跨过了一个被压倒在地上的罗马人的身体，当着执政的面前，手刃了三个敌人；塔昆也和他亲自对垒，被他打了下来。在那一天的战绩里，他本来可以做一个怯懦不前的妇女，但他证明了自己是战场上顶勇敢的男子，为了旌扬他的功勋，他的额上被加上了橡叶的荣冠。这样他从一个新列戎行的孺子，变成一个能征惯战的健儿，他的与日俱增的勇敢，像大海一样充沛，在前后十七次战役之中，战无不胜，攻无不克。讲到最近这一次在科利奥里城前和城中的鏖战，那么我可以说，我的言辞是无法给他适当的赞美的；他阻止了奔逃的败众，用他惊人的榜样，扫去了懦夫心中的恐惧；正像水草当着一艘疾驶的帆船一样，他的剑光挥处，人们不是降服就是死亡，谁要是碰着他的锋刃，再也没有活命的希望；从脸上到脚上，他浑身都染着血，他的每一个行动，都伴随着绝命的哀号；他一个人闯进了密布着死亡的城里用他操纵着死生的铁手染红了城门，然后他又单身脱围而出，带着一队生力军，像一颗彗星似的向科利奥里突击。他已经大获全胜；但战争的喧声又开始刺激他敏锐的感觉，于是他兼人的精力又使他忘却了身体的疲劳，他立刻再上战场，在那里奔走驰突，杀人如麻，好像这是一场永无休止的掠夺一样；直到我们把城郊全部占领以后，他不曾有一刻站定喘息的时间。\u003c/p>\n","text":"考密涅斯 我的声音太微弱了，不够叙述科利奥兰纳斯的功绩。勇敢是世人公认的最大美德，有勇的人是最值得崇敬的；要是我们可以这么说，那么我现在所要说起的这一个人，在全世界简直找不出一个可以和他抗衡的人物。当塔昆举兵向罗马侵犯的时候，他还只有十六岁，就已经在战场上崭露头角，表现他过人的神勇；我们当时的执政亲眼看见那些鬑鬑多须的大汉被白皙韶秀的他追赶得没命奔逃。他跨过了一个被压倒在地上的罗马人的身体，当着执政的面前，手刃了三个敌人；塔昆也和他亲自对垒，被他打了下来。在那一天的战绩里，他本来可以做一个怯懦不前的妇女，但他证明了自己是战场上顶勇敢的男子，为了旌扬他的功勋，他的额上被加上了橡叶的荣冠。这样他从一个新列戎行的孺子，变成一个能征惯战的健儿，他的与日俱增的勇敢，像大海一样充沛，在前后十七次战役之中，战无不胜，攻无不克。讲到最近这一次在科利奥里城前和城中的鏖战，那么我可以说，我的言辞是无法给他适当的赞美的；他阻止了奔逃的败众，用他惊人的榜样，扫去了懦夫心中的恐惧；正像水草当着一艘疾驶的帆船一样，他的剑光挥处，人们不是降服就是死亡，谁要是碰着他的锋刃，再也没有活命的希望；从脸上到脚上，他浑身都染着血，他的每一个行动，都伴随着绝命的哀号；他一个人闯进了密布着死亡的城里用他操纵着死生的铁手染红了城门，然后他又单身脱围而出，带着一队生力军，像一颗彗星似的向科利奥里突击。他已经大获全胜；但战争的喧声又开始刺激他敏锐的感觉，于是他兼人的精力又使他忘却了身体的疲劳，他立刻再上战场，在那里奔走驰突，杀人如麻，好像这是一场永无休止的掠夺一样；直到我们把城郊全部占领以后，他不曾有一刻站定喘息的时间。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00431","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 了不得的英雄！\u003c/p>\n","text":"米尼涅斯 了不得的英雄！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00432","html":"\u003cp class=\"epub-calibre1\">元老甲 我们所准备给他的光荣，他是受之无愧的。\u003c/p>\n","text":"元老甲 我们所准备给他的光荣，他是受之无愧的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00433","html":"\u003cp class=\"epub-calibre1\">考密涅斯 他拒绝我们分给他的战利品，把一切珍贵的宝物视同粪土；他的欲望比吝啬者的度量更小；行为的本身便是他给自己的酬报。\u003c/p>\n","text":"考密涅斯 他拒绝我们分给他的战利品，把一切珍贵的宝物视同粪土；他的欲望比吝啬者的度量更小；行为的本身便是他给自己的酬报。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00434","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 他是个高贵的人物；快去请他来。\u003c/p>\n","text":"米尼涅斯 他是个高贵的人物；快去请他来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00435","html":"\u003cp class=\"epub-calibre1\">元老甲 请科利奥兰纳斯来。\u003c/p>\n","text":"元老甲 请科利奥兰纳斯来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00436","html":"\u003cp class=\"epub-calibre1\">警吏 他来了。\u003c/p>\n","text":"警吏 他来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00437","html":"\u003cp class=\"epub-block1\">科利奥兰纳斯重上。\u003c/p>\n","text":"科利奥兰纳斯重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00438","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 科利奥兰纳斯，元老们很愿意举你做执政。\u003c/p>\n","text":"米尼涅斯 科利奥兰纳斯，元老们很愿意举你做执政。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00439","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我愿意永远为他们尽忠效命。\u003c/p>\n","text":"科利奥兰纳斯 我愿意永远为他们尽忠效命。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00440","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 现在还有一步手续必须履行，您应该向人民说几句话。\u003c/p>\n","text":"米尼涅斯 现在还有一步手续必须履行，您应该向人民说几句话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00441","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 请你们宽免我这一项例行的手续，因为我不能披上粗布的长衣，裸露着身体，请求他们为了我的伤痕的缘故，接受我做他们的执政。请你们不要让我干这种事吧。\u003c/p>\n","text":"科利奥兰纳斯 请你们宽免我这一项例行的手续，因为我不能披上粗布的长衣，裸露着身体，请求他们为了我的伤痕的缘故，接受我做他们的执政。请你们不要让我干这种事吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00442","html":"\u003cp class=\"epub-calibre1\">西西涅斯 将军，人民必须表示他们的意见；他们也决不愿变更规定的仪式。\u003c/p>\n","text":"西西涅斯 将军，人民必须表示他们的意见；他们也决不愿变更规定的仪式。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00443","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 不要激怒他们；您还是遵照着习惯，像前任的那些人一样，用合法的形式取得您的地位吧。\u003c/p>\n","text":"米尼涅斯 不要激怒他们；您还是遵照着习惯，像前任的那些人一样，用合法的形式取得您的地位吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00444","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 要我扮演这一幕把戏，我一定要脸红，我看还是免了吧。\u003c/p>\n","text":"科利奥兰纳斯 要我扮演这一幕把戏，我一定要脸红，我看还是免了吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00445","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 \u003cb class=\"epub-calibre3\">（向西西涅斯旁白）\u003c/b>你听见吗？\u003c/p>\n","text":"勃鲁托斯 （向西西涅斯旁白）你听见吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00446","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 向他们夸口，说我做过这样的事，那样的事，把应当藏匿起来的没有痛楚的伤疤给他们看，好像我受了这些伤，只是为了换得他们的一声赞叹！\u003c/p>\n","text":"科利奥兰纳斯 向他们夸口，说我做过这样的事，那样的事，把应当藏匿起来的没有痛楚的伤疤给他们看，好像我受了这些伤，只是为了换得他们的一声赞叹！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00447","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 不要固执着这一点。两位护民官，请你们向民众传达我们的意志。愿我们尊严的执政享有一切快乐和光荣！\u003c/p>\n","text":"米尼涅斯 不要固执着这一点。两位护民官，请你们向民众传达我们的意志。愿我们尊严的执政享有一切快乐和光荣！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00448","html":"\u003cp class=\"epub-calibre1\">众元老 愿一切快乐和光荣降于科利奥兰纳斯！\u003cb class=\"epub-calibre3\">（喇叭奏花腔；除西西涅斯、勃鲁托斯外均退场。）\u003c/b>\u003c/p>\n","text":"众元老 愿一切快乐和光荣降于科利奥兰纳斯！（喇叭奏花腔；除西西涅斯、勃鲁托斯外均退场。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00449","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 你知道他将怎样对待人民。\u003c/p>\n","text":"勃鲁托斯 你知道他将怎样对待人民。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00450","html":"\u003cp class=\"epub-calibre1\">西西涅斯 但愿他们知道他的用心！他将要用一种鄙夷不屑的态度去请求他们，好像他从他们手里得到恩惠是一件耻辱。\u003c/p>\n","text":"西西涅斯 但愿他们知道他的用心！他将要用一种鄙夷不屑的态度去请求他们，好像他从他们手里得到恩惠是一件耻辱。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00451","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 来，我们去把这儿的一切经过情形通知他们；我知道他们都在市场上等候着我们的消息。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"勃鲁托斯 来，我们去把这儿的一切经过情形通知他们；我知道他们都在市场上等候着我们的消息。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第二场 同前。议会","headingLevel":4,"sourceAnchor":"a735","actNumber":2,"sceneNumber":2},{"id":"part0031-section-015","label":"第二幕 · 第三场 同前。大市场","kind":"scene","blocks":[{"id":"part0031-00452","html":"\u003ch4 id=\"epub-part0031-a736\" class=\"epub-calibre12\">第三场 同前。大市场\u003c/h4>\n","text":"第三场 同前。大市场\n","sourceAnchor":"a736","tag":"h4"},{"id":"part0031-00453","html":"\u003cp class=\"epub-block1\">若干市民上。\u003c/p>\n","text":"若干市民上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00454","html":"\u003cp class=\"epub-calibre1\">市民甲 要是他请求我们的同意，我们可不能拒绝他。\u003c/p>\n","text":"市民甲 要是他请求我们的同意，我们可不能拒绝他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00455","html":"\u003cp class=\"epub-calibre1\">市民乙 要是我们不能同意，我们可以拒绝他。\u003c/p>\n","text":"市民乙 要是我们不能同意，我们可以拒绝他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00456","html":"\u003cp class=\"epub-calibre1\">市民丙 我们有权力拒绝他，可是我们没有权力运用这一种权力；因为要是他把他的伤痕给我们看，把他的功绩告诉我们，我们的舌头就应当替他的伤痕说话，告诉他他的伟大的功绩已经得到我们慷慨的嘉纳。忘恩负义是一种极大的罪恶，忘恩负义的群众是一个可怕的妖魔；我们都是群众中间的一分子，都要变成这妖魔身上的器官肢体了。\u003c/p>\n","text":"市民丙 我们有权力拒绝他，可是我们没有权力运用这一种权力；因为要是他把他的伤痕给我们看，把他的功绩告诉我们，我们的舌头就应当替他的伤痕说话，告诉他他的伟大的功绩已经得到我们慷慨的嘉纳。忘恩负义是一种极大的罪恶，忘恩负义的群众是一个可怕的妖魔；我们都是群众中间的一分子，都要变成这妖魔身上的器官肢体了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00457","html":"\u003cp class=\"epub-calibre1\">市民甲 我可以举出一个小小的例子，证明我们在人家眼里正是这样一个东西：有一次我们为了要求谷物而鼓噪起来的时候，他自己曾经破口骂我们是多头的群众。\u003c/p>\n","text":"市民甲 我可以举出一个小小的例子，证明我们在人家眼里正是这样一个东西：有一次我们为了要求谷物而鼓噪起来的时候，他自己曾经破口骂我们是多头的群众。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00458","html":"\u003cp class=\"epub-calibre1\">市民丙 许多人都这样称呼我们，不是因为我们的头发有的是褐色的，有的是黑色的，有的是赭色的，有的是光秃秃的，而是因为我们的思想是这么分歧不一。我真的在想，要是我们各人所有的思想都从一个脑壳里发表出来，它们一定会有的往东，有的往西，有的往北，有的往南，四下里飞散开去。\u003c/p>\n","text":"市民丙 许多人都这样称呼我们，不是因为我们的头发有的是褐色的，有的是黑色的，有的是赭色的，有的是光秃秃的，而是因为我们的思想是这么分歧不一。我真的在想，要是我们各人所有的思想都从一个脑壳里发表出来，它们一定会有的往东，有的往西，有的往北，有的往南，四下里飞散开去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00459","html":"\u003cp class=\"epub-calibre1\">市民乙 你这样想吗？你看我的思想会向哪一个方向飞？\u003c/p>\n","text":"市民乙 你这样想吗？你看我的思想会向哪一个方向飞？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00460","html":"\u003cp class=\"epub-calibre1\">市民丙 嘿，你的思想可不像别人的思想那样容易出来，因为它是牢牢地封在一个木头的脑壳里的；可是要是它得到了自由，它一定会飞到南方去。\u003c/p>\n","text":"市民丙 嘿，你的思想可不像别人的思想那样容易出来，因为它是牢牢地封在一个木头的脑壳里的；可是要是它得到了自由，它一定会飞到南方去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00461","html":"\u003cp class=\"epub-calibre1\">市民乙 为什么飞到南方去？\u003c/p>\n","text":"市民乙 为什么飞到南方去？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00462","html":"\u003cp class=\"epub-calibre1\">市民丙 到南方去迷失在一阵大雾里，它的四分之三溶解在恶臭的露水里，剩下的四分之一因为良心上过意不去，仍旧转回来，帮助你娶一个妻子。\u003c/p>\n","text":"市民丙 到南方去迷失在一阵大雾里，它的四分之三溶解在恶臭的露水里，剩下的四分之一因为良心上过意不去，仍旧转回来，帮助你娶一个妻子。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00463","html":"\u003cp class=\"epub-calibre1\">市民乙 你老这样开人家的玩笑；开吧，开吧。\u003c/p>\n","text":"市民乙 你老这样开人家的玩笑；开吧，开吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00464","html":"\u003cp class=\"epub-calibre1\">市民丙 你们都决定对他表示同意吗？可是那也没有关系，最后的结果是要取决于大多数的意见的。我说，要是他愿意同情民众，那么从来不曾有过一个比他更胜任的人了。\u003c/p>\n","text":"市民丙 你们都决定对他表示同意吗？可是那也没有关系，最后的结果是要取决于大多数的意见的。我说，要是他愿意同情民众，那么从来不曾有过一个比他更胜任的人了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00465","html":"\u003cp class=\"epub-block1\">科利奥兰纳斯披粗衣与米尼涅斯同上。\u003c/p>\n","text":"科利奥兰纳斯披粗衣与米尼涅斯同上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00466","html":"\u003cp class=\"epub-calibre1\">市民丙 他来了，还披着一件粗布的长衣。留心他的举止。我们不要大家在一起，或者一个人，或者两个人三个人，分别跑到他站立的地方。他必须征求个别的同意；我们每一个人都有他各自的权利，可以用我们自己的嘴向他表示我们各自的同意。所以大家跟我来吧，让我指导你们怎样走过他的身旁。\u003c/p>\n","text":"市民丙 他来了，还披着一件粗布的长衣。留心他的举止。我们不要大家在一起，或者一个人，或者两个人三个人，分别跑到他站立的地方。他必须征求个别的同意；我们每一个人都有他各自的权利，可以用我们自己的嘴向他表示我们各自的同意。所以大家跟我来吧，让我指导你们怎样走过他的身旁。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00467","html":"\u003cp class=\"epub-calibre1\">众人 很好，很好。\u003cb class=\"epub-calibre3\">（市民等同下。）\u003c/b>\u003c/p>\n","text":"众人 很好，很好。（市民等同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00468","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 啊，将军，您错了；您不知道最尊贵的人都做过这样的事吗？\u003c/p>\n","text":"米尼涅斯 啊，将军，您错了；您不知道最尊贵的人都做过这样的事吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00469","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我应该怎么说？“求求你，先生，”——哼！我不能让我的舌头发出这种乞怜的调子。“瞧，先生，我的伤痕！当你们那些同胞们听见了自己军中的鼓声而惊呼逃走的时候，我因为为国尽劳，受了这么多伤。”\u003c/p>\n","text":"科利奥兰纳斯 我应该怎么说？“求求你，先生，”——哼！我不能让我的舌头发出这种乞怜的调子。“瞧，先生，我的伤痕！当你们那些同胞们听见了自己军中的鼓声而惊呼逃走的时候，我因为为国尽劳，受了这么多伤。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00470","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 嗳哟，天哪！您不能那样说；您必须请求他们想起您的功劳。\u003c/p>\n","text":"米尼涅斯 嗳哟，天哪！您不能那样说；您必须请求他们想起您的功劳。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00471","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 想起我的功劳！哼！我宁愿他们把我忘记，正如他们把神父们的忠告也忘记了一样。\u003c/p>\n","text":"科利奥兰纳斯 想起我的功劳！哼！我宁愿他们把我忘记，正如他们把神父们的忠告也忘记了一样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00472","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 您会把事情弄坏的。我走了。请您好好地对他们说话。\u003c/p>\n","text":"米尼涅斯 您会把事情弄坏的。我走了。请您好好地对他们说话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00473","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 叫他们把脸洗一洗，把他们的牙齿刷干净。\u003cb class=\"epub-calibre3\">（米尼涅斯下）\u003c/b>好，有一对来了。\u003c/p>\n","text":"科利奥兰纳斯 叫他们把脸洗一洗，把他们的牙齿刷干净。（米尼涅斯下）好，有一对来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00474","html":"\u003cp class=\"epub-block1\">二市民重上。\u003c/p>\n","text":"二市民重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00475","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 先生，你们知道我为什么站在这儿吗？\u003c/p>\n","text":"科利奥兰纳斯 先生，你们知道我为什么站在这儿吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00476","html":"\u003cp class=\"epub-calibre1\">市民甲 我们知道，将军；告诉我们您到这儿来的缘故。\u003c/p>\n","text":"市民甲 我们知道，将军；告诉我们您到这儿来的缘故。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00477","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 因为我自己的功劳。\u003c/p>\n","text":"科利奥兰纳斯 因为我自己的功劳。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00478","html":"\u003cp class=\"epub-calibre1\">市民乙 您自己的功劳！\u003c/p>\n","text":"市民乙 您自己的功劳！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00479","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 嗯，却不是我自己的意志。\u003c/p>\n","text":"科利奥兰纳斯 嗯，却不是我自己的意志。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00480","html":"\u003cp class=\"epub-calibre1\">市民甲 怎么不是您自己的意志？\u003c/p>\n","text":"市民甲 怎么不是您自己的意志？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00481","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 不，先生，我从来不愿意向穷人求乞。\u003c/p>\n","text":"科利奥兰纳斯 不，先生，我从来不愿意向穷人求乞。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00482","html":"\u003cp class=\"epub-calibre1\">市民甲 您必须明白，要是我们给了您什么东西，我们是希望从您身上得到一点好处的。\u003c/p>\n","text":"市民甲 您必须明白，要是我们给了您什么东西，我们是希望从您身上得到一点好处的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00483","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 好，那么我要请问，向你们讨一个执政做要多少价钱？\u003c/p>\n","text":"科利奥兰纳斯 好，那么我要请问，向你们讨一个执政做要多少价钱？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00484","html":"\u003cp class=\"epub-calibre1\">市民甲 那价钱就是您必须恭恭敬敬地请求。\u003c/p>\n","text":"市民甲 那价钱就是您必须恭恭敬敬地请求。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00485","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 恭恭敬敬！先生，我请求你们，让我做执政吧；你们要是想看我的伤痕，我愿意在隐僻一点的地方给你们看。请你们给我同意吧，先生；你们怎么说？\u003c/p>\n","text":"科利奥兰纳斯 恭恭敬敬！先生，我请求你们，让我做执政吧；你们要是想看我的伤痕，我愿意在隐僻一点的地方给你们看。请你们给我同意吧，先生；你们怎么说？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00486","html":"\u003cp class=\"epub-calibre1\">市民乙 您可以得到我们的同意，尊贵的将军。\u003c/p>\n","text":"市民乙 您可以得到我们的同意，尊贵的将军。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00487","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 一言为定，先生。我已经讨到两个尊贵的同意了。谢谢你们的布施；再见。\u003c/p>\n","text":"科利奥兰纳斯 一言为定，先生。我已经讨到两个尊贵的同意了。谢谢你们的布施；再见。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00488","html":"\u003cp class=\"epub-calibre1\">市民甲 可是这有点儿古怪。\u003c/p>\n","text":"市民甲 可是这有点儿古怪。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00489","html":"\u003cp class=\"epub-calibre1\">市民乙 要是已经出口的话可以收回——可是那也算了。\u003cb class=\"epub-calibre3\">（二市民下。）\u003c/b>\u003c/p>\n","text":"市民乙 要是已经出口的话可以收回——可是那也算了。（二市民下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00490","html":"\u003cp class=\"epub-block1\">其他二市民重上。\u003c/p>\n","text":"其他二市民重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00491","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我请求你们，现在我已经按照习惯，披上这一件衣服了，你们能够允许我做执政吗？\u003c/p>\n","text":"科利奥兰纳斯 我请求你们，现在我已经按照习惯，披上这一件衣服了，你们能够允许我做执政吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00492","html":"\u003cp class=\"epub-calibre1\">市民丙 您虽然有功国家，可是不孚众望。\u003c/p>\n","text":"市民丙 您虽然有功国家，可是不孚众望。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00493","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 请教？\u003c/p>\n","text":"科利奥兰纳斯 请教？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00494","html":"\u003cp class=\"epub-calibre1\">市民丙 您鞭笞罗马的敌人，也鞭笞罗马的友人；您对平民一向没有好感。\u003c/p>\n","text":"市民丙 您鞭笞罗马的敌人，也鞭笞罗马的友人；您对平民一向没有好感。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00495","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 您应该格外敬重我，因为我没有滥卖人情。先生，为了博取人民的欢心，我愿意向我这些誓同生死的同胞们谄媚，这是他们所认为温良恭顺的行为。既然他们所需要的，只是我的脱帽致敬，不是我的竭忠尽瘁，那么我可以学习一套卑躬屈节的本领，尽量向他们装腔作势；那就是说，先生，我要学学那些善于笼络人心的贵人，谁喜欢这一套，我可以大量奉送。所以我请求你们，让我做执政吧。\u003c/p>\n","text":"科利奥兰纳斯 您应该格外敬重我，因为我没有滥卖人情。先生，为了博取人民的欢心，我愿意向我这些誓同生死的同胞们谄媚，这是他们所认为温良恭顺的行为。既然他们所需要的，只是我的脱帽致敬，不是我的竭忠尽瘁，那么我可以学习一套卑躬屈节的本领，尽量向他们装腔作势；那就是说，先生，我要学学那些善于笼络人心的贵人，谁喜欢这一套，我可以大量奉送。所以我请求你们，让我做执政吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00496","html":"\u003cp class=\"epub-calibre1\">市民丁 我们希望您是我们的朋友，所以愿意给您诚心的赞助。\u003c/p>\n","text":"市民丁 我们希望您是我们的朋友，所以愿意给您诚心的赞助。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00497","html":"\u003cp class=\"epub-calibre1\">市民丙 您曾经为国家受了许多伤。\u003c/p>\n","text":"市民丙 您曾经为国家受了许多伤。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00498","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你们既然已经知道，那我也用不着袒露我的身体向你们证明。我一定非常珍重你们的盛意，不再来麻烦你们了。\u003c/p>\n","text":"科利奥兰纳斯 你们既然已经知道，那我也用不着袒露我的身体向你们证明。我一定非常珍重你们的盛意，不再来麻烦你们了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00499","html":"\u003cp class=\"epub-calibre1\">市民丙 市民丁 愿天神给您快乐，将军！\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"市民丙 市民丁 愿天神给您快乐，将军！（同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00500","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 最珍贵的同意！宁可死，宁可挨饿，也不要向别人求讨我们分所应得的酬报。为什么我要穿起这身毡布的外衣站在这儿，向每一个路过的人乞讨不必要的同意？习惯逼着我这样做；习惯怎样命令我们，我们就该怎样做，陈年累世的灰尘让它堆在那儿不加扫拭，高积如山的错误把公道正义完全障蔽。与其扮演这样的把戏，还不如索性把国家尊贵的名位赏给愿意干这种事的人。我已经演了半本，待我憋着这口气，演完那下半本吧。又有几个同意来了。\u003c/p>\n","text":"科利奥兰纳斯 最珍贵的同意！宁可死，宁可挨饿，也不要向别人求讨我们分所应得的酬报。为什么我要穿起这身毡布的外衣站在这儿，向每一个路过的人乞讨不必要的同意？习惯逼着我这样做；习惯怎样命令我们，我们就该怎样做，陈年累世的灰尘让它堆在那儿不加扫拭，高积如山的错误把公道正义完全障蔽。与其扮演这样的把戏，还不如索性把国家尊贵的名位赏给愿意干这种事的人。我已经演了半本，待我憋着这口气，演完那下半本吧。又有几个同意来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00501","html":"\u003cp class=\"epub-block1\">其他三市民重上。\u003c/p>\n","text":"其他三市民重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00502","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你们的同意！为了你们的同意，我和敌人作战；为了你们的同意，我经历十八次战争，受到二十多处创伤；为了你们的同意，我干下许多大大小小的事情。我要做执政；请你们给我同意吧。\u003c/p>\n","text":"科利奥兰纳斯 你们的同意！为了你们的同意，我和敌人作战；为了你们的同意，我经历十八次战争，受到二十多处创伤；为了你们的同意，我干下许多大大小小的事情。我要做执政；请你们给我同意吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00503","html":"\u003cp class=\"epub-calibre1\">市民戊 他曾经立过大功，必须让他得到每一个正直人的同意。\u003c/p>\n","text":"市民戊 他曾经立过大功，必须让他得到每一个正直人的同意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00504","html":"\u003cp class=\"epub-calibre1\">市民己 那么让他做执政吧。愿天神给他快乐，使他成为人民的好友！\u003c/p>\n","text":"市民己 那么让他做执政吧。愿天神给他快乐，使他成为人民的好友！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00505","html":"\u003cp class=\"epub-calibre1\">众人 阿门，阿门。上帝保佑你，尊贵的执政！\u003cb class=\"epub-calibre3\">（市民等下。）\u003c/b>\u003c/p>\n","text":"众人 阿门，阿门。上帝保佑你，尊贵的执政！（市民等下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00506","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 尊贵的同意！\u003c/p>\n","text":"科利奥兰纳斯 尊贵的同意！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00507","html":"\u003cp class=\"epub-block1\">米尼涅斯偕勃鲁托斯、西西涅斯重上。\u003c/p>\n","text":"米尼涅斯偕勃鲁托斯、西西涅斯重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00508","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 您已经忍受种种麻烦，这两位护民官将会向您宣布您已经得到人民的同意，现在您必须立刻到元老院去，接受正式的任命。\u003c/p>\n","text":"米尼涅斯 您已经忍受种种麻烦，这两位护民官将会向您宣布您已经得到人民的同意，现在您必须立刻到元老院去，接受正式的任命。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00509","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 事情完了吗？\u003c/p>\n","text":"科利奥兰纳斯 事情完了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00510","html":"\u003cp class=\"epub-calibre1\">西西涅斯 您已经按照惯例履行了请求同意的手续；人民已经接受了您，他们就要再召集一次会议，通过您的任命。\u003c/p>\n","text":"西西涅斯 您已经按照惯例履行了请求同意的手续；人民已经接受了您，他们就要再召集一次会议，通过您的任命。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00511","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 什么地方？就在元老院吗？\u003c/p>\n","text":"科利奥兰纳斯 什么地方？就在元老院吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00512","html":"\u003cp class=\"epub-calibre1\">西西涅斯 就在那儿，科利奥兰纳斯。\u003c/p>\n","text":"西西涅斯 就在那儿，科利奥兰纳斯。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00513","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我可以把这些衣服换下来了吗？\u003c/p>\n","text":"科利奥兰纳斯 我可以把这些衣服换下来了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00514","html":"\u003cp class=\"epub-calibre1\">西西涅斯 您可以，将军。\u003c/p>\n","text":"西西涅斯 您可以，将军。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00515","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我就去换衣服；让我认识了我自己的本来面目以后，再到元老院来。\u003c/p>\n","text":"科利奥兰纳斯 我就去换衣服；让我认识了我自己的本来面目以后，再到元老院来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00516","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我陪您去。你们两位也跟我们一起走吗？\u003c/p>\n","text":"米尼涅斯 我陪您去。你们两位也跟我们一起走吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00517","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 我们还要在这儿等候民众。\u003c/p>\n","text":"勃鲁托斯 我们还要在这儿等候民众。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00518","html":"\u003cp class=\"epub-calibre1\">西西涅斯 再见。\u003cb class=\"epub-calibre3\">（科利奥兰纳斯，米尼涅斯下）\u003c/b>他现在已经拿稳了；从他的脸色看来，他心里好像在火一样烧着呢。\u003c/p>\n","text":"西西涅斯 再见。（科利奥兰纳斯，米尼涅斯下）他现在已经拿稳了；从他的脸色看来，他心里好像在火一样烧着呢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00519","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 他用一颗骄傲的心穿着他的卑贱的衣服。请你打发这些民众吧。\u003c/p>\n","text":"勃鲁托斯 他用一颗骄傲的心穿着他的卑贱的衣服。请你打发这些民众吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00520","html":"\u003cp class=\"epub-block1\">众市民重上。\u003c/p>\n","text":"众市民重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00521","html":"\u003cp class=\"epub-calibre1\">西西涅斯 啊，各位朋友！你们已经选中这个人了吗？\u003c/p>\n","text":"西西涅斯 啊，各位朋友！你们已经选中这个人了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00522","html":"\u003cp class=\"epub-calibre1\">市民甲 他已经得到我们的同意。\u003c/p>\n","text":"市民甲 他已经得到我们的同意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00523","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 我们祈祷神明，但愿他不要辜负你们的好意。\u003c/p>\n","text":"勃鲁托斯 我们祈祷神明，但愿他不要辜负你们的好意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00524","html":"\u003cp class=\"epub-calibre1\">市民乙 阿门。照我的愚见观察，他在请求我们同意的时候，仿佛在讥笑我们。\u003c/p>\n","text":"市民乙 阿门。照我的愚见观察，他在请求我们同意的时候，仿佛在讥笑我们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00525","html":"\u003cp class=\"epub-calibre1\">市民丙 不错，他简直在辱骂我们。\u003c/p>\n","text":"市民丙 不错，他简直在辱骂我们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00526","html":"\u003cp class=\"epub-calibre1\">市民甲 不，他说起话来总是这样的；他没有讥笑我们。\u003c/p>\n","text":"市民甲 不，他说起话来总是这样的；他没有讥笑我们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00527","html":"\u003cp class=\"epub-calibre1\">市民乙 除了你一个人之外，我们中间每一个人都说他用侮蔑的态度对待我们。他应该把他的功劳的印记，他为国家留下的伤痕给我们看。\u003c/p>\n","text":"市民乙 除了你一个人之外，我们中间每一个人都说他用侮蔑的态度对待我们。他应该把他的功劳的印记，他为国家留下的伤痕给我们看。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00528","html":"\u003cp class=\"epub-calibre1\">西西涅斯 啊，那我相信他一定会给你们看的。\u003c/p>\n","text":"西西涅斯 啊，那我相信他一定会给你们看的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00529","html":"\u003cp class=\"epub-calibre1\">众人 不，不，谁也没有瞧见。\u003c/p>\n","text":"众人 不，不，谁也没有瞧见。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00530","html":"\u003cp class=\"epub-calibre1\">市民丙 他说他有许多伤痕，可以在隐僻一点的地方给我们看。他这样带着轻蔑的神气挥舞着他的帽子，“我要做执政，”他说，“除非得到你们的同意，传统的习惯不会容许我；所以我要请求你们同意。”当我们答应了他以后，他就说，“谢谢你们的同意，谢谢你们最珍贵的同意；现在你们已经给我同意，我也用不着你们了。”这不是讥笑是什么？\u003c/p>\n","text":"市民丙 他说他有许多伤痕，可以在隐僻一点的地方给我们看。他这样带着轻蔑的神气挥舞着他的帽子，“我要做执政，”他说，“除非得到你们的同意，传统的习惯不会容许我；所以我要请求你们同意。”当我们答应了他以后，他就说，“谢谢你们的同意，谢谢你们最珍贵的同意；现在你们已经给我同意，我也用不着你们了。”这不是讥笑是什么？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00531","html":"\u003cp class=\"epub-calibre1\">西西涅斯 啊，到底是你们没有看见呢，还是你们已经看见了，却一味表示孩子气的好感，随便给了他同意？\u003c/p>\n","text":"西西涅斯 啊，到底是你们没有看见呢，还是你们已经看见了，却一味表示孩子气的好感，随便给了他同意？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00532","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 你们难道不会凭着你们所受的教训，对他说当他还没有掌握权力、不过是政府里一个地位卑微的仆人的时候，他就是你们的敌人，老是反对着你们的自由和你们在这共和国里所享有的特权吗？你们难道不会对他说，现在他登上了秉持国家大权的地位，要是他仍旧怀着恶意，继续做平民的死敌，那么你们现在所表示的同意，不将要成为你们自己的咒诅吗？你们应当对他说，他的伟大的功业，既然可以使他享有他所要求的地位而无愧色，但愿他的仁厚的天性，也能够想到你们现在所给他的同情的赞助，而把他对你们的敌意变成友谊，永远做你们慈爱的执政。\u003c/p>\n","text":"勃鲁托斯 你们难道不会凭着你们所受的教训，对他说当他还没有掌握权力、不过是政府里一个地位卑微的仆人的时候，他就是你们的敌人，老是反对着你们的自由和你们在这共和国里所享有的特权吗？你们难道不会对他说，现在他登上了秉持国家大权的地位，要是他仍旧怀着恶意，继续做平民的死敌，那么你们现在所表示的同意，不将要成为你们自己的咒诅吗？你们应当对他说，他的伟大的功业，既然可以使他享有他所要求的地位而无愧色，但愿他的仁厚的天性，也能够想到你们现在所给他的同情的赞助，而把他对你们的敌意变成友谊，永远做你们慈爱的执政。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00533","html":"\u003cp class=\"epub-calibre1\">西西涅斯 你们照这样对他说了以后，就可以触动他的心性，试探他的真正的意向；也许他会给你们善意的允诺，那么将来倘有需要的时候，你们就可以责令他履行旧约；也许那会激怒他的暴戾的天性，因为他是不能容忍任何拘束的，这样引动了他的恼怒，你们就可以借着他的恶劣的脾气做理由，拒绝他当执政。\u003c/p>\n","text":"西西涅斯 你们照这样对他说了以后，就可以触动他的心性，试探他的真正的意向；也许他会给你们善意的允诺，那么将来倘有需要的时候，你们就可以责令他履行旧约；也许那会激怒他的暴戾的天性，因为他是不能容忍任何拘束的，这样引动了他的恼怒，你们就可以借着他的恶劣的脾气做理由，拒绝他当执政。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00534","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 你们看他在需要你们好感的时候，会用这样公然侮蔑的态度向你们请求，难道你们没有想到当他有权力压迫你们的时候，他这种侮蔑的态度不会变成公然的伤害吗？怎么，你们胸膛里难道都是没有心的吗？或者你们的舌头会反抗理智的判断吗？\u003c/p>\n","text":"勃鲁托斯 你们看他在需要你们好感的时候，会用这样公然侮蔑的态度向你们请求，难道你们没有想到当他有权力压迫你们的时候，他这种侮蔑的态度不会变成公然的伤害吗？怎么，你们胸膛里难道都是没有心的吗？或者你们的舌头会反抗理智的判断吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00535","html":"\u003cp class=\"epub-calibre1\">西西涅斯 你们以前不是曾经拒绝过向你们请求的人吗？现在他并没有请求你们，不过把你们讥笑了一顿，你们却会毫不迟疑地给他同意吗？\u003c/p>\n","text":"西西涅斯 你们以前不是曾经拒绝过向你们请求的人吗？现在他并没有请求你们，不过把你们讥笑了一顿，你们却会毫不迟疑地给他同意吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00536","html":"\u003cp class=\"epub-calibre1\">市民丙 他还没有经过正式的确认，我们还可以拒绝他。\u003c/p>\n","text":"市民丙 他还没有经过正式的确认，我们还可以拒绝他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00537","html":"\u003cp class=\"epub-calibre1\">市民乙 我们一定要拒绝他；我可以号召五百个人反对他就任。\u003c/p>\n","text":"市民乙 我们一定要拒绝他；我可以号召五百个人反对他就任。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00538","html":"\u003cp class=\"epub-calibre1\">市民甲 好，就是一千个人也不难，还可以叫他们各人拉些朋友来充数。\u003c/p>\n","text":"市民甲 好，就是一千个人也不难，还可以叫他们各人拉些朋友来充数。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00539","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 你们立刻就去，告诉你们那些朋友，说他们已经选了一个执政，他将会剥夺他们的自由，限制他们发言的权利，把他们当作狗一样看待，虽然为了要它们吠叫而豢养，可是往往因为它们吠叫而把它们痛打。\u003c/p>\n","text":"勃鲁托斯 你们立刻就去，告诉你们那些朋友，说他们已经选了一个执政，他将会剥夺他们的自由，限制他们发言的权利，把他们当作狗一样看待，虽然为了要它们吠叫而豢养，可是往往因为它们吠叫而把它们痛打。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00540","html":"\u003cp class=\"epub-calibre1\">西西涅斯 让他们集合起来，重新作一次郑重的考虑，一致撤回你们愚昧的选举。竭力向他们提出他的骄傲和他从前对你们的憎恨；也不要忘记他是用怎样轻蔑的态度穿着那件谦卑的衣服，当他向你们请求的时候，他是怎样讥笑着你们；可是你们因为存心忠厚，只想到他的功劳，所以像这样从牢不可拔的憎恨里表现出来的放肆无礼的举止，也就被你们忽略过去了。\u003c/p>\n","text":"西西涅斯 让他们集合起来，重新作一次郑重的考虑，一致撤回你们愚昧的选举。竭力向他们提出他的骄傲和他从前对你们的憎恨；也不要忘记他是用怎样轻蔑的态度穿着那件谦卑的衣服，当他向你们请求的时候，他是怎样讥笑着你们；可是你们因为存心忠厚，只想到他的功劳，所以像这样从牢不可拔的憎恨里表现出来的放肆无礼的举止，也就被你们忽略过去了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00541","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 可以把过失推在我们两人——你们的护民官身上，说都是我们一定要你们选举他。\u003c/p>\n","text":"勃鲁托斯 可以把过失推在我们两人——你们的护民官身上，说都是我们一定要你们选举他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00542","html":"\u003cp class=\"epub-calibre1\">西西涅斯 你们可以说，你们是在我们的命令之下选举他的，不是出于你们自己的真意；你们的心里因为存着不得不然的见解，而不是因为觉得应该这样做，所以才会违背着本心，而赞同他做执政。把一切过失推在我们身上好了。\u003c/p>\n","text":"西西涅斯 你们可以说，你们是在我们的命令之下选举他的，不是出于你们自己的真意；你们的心里因为存着不得不然的见解，而不是因为觉得应该这样做，所以才会违背着本心，而赞同他做执政。把一切过失推在我们身上好了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00543","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 对了，不要宽恕我们。说我们向你们反复讲说，他在多么年轻的时候就已经开始为国家出力；他已经服务了多么长久；他的家世是多么高贵；纽玛的外孙，继伟大的霍斯提力斯君临罗马的安格斯·马歇斯，就是从他们家里出来的；替我们开渠通水的坡勃律斯和昆塔斯也是那一族里的人；做过两任监察官的森索利纳斯是他的先祖。\u003c/p>\n","text":"勃鲁托斯 对了，不要宽恕我们。说我们向你们反复讲说，他在多么年轻的时候就已经开始为国家出力；他已经服务了多么长久；他的家世是多么高贵；纽玛的外孙，继伟大的霍斯提力斯君临罗马的安格斯·马歇斯，就是从他们家里出来的；替我们开渠通水的坡勃律斯和昆塔斯也是那一族里的人；做过两任监察官的森索利纳斯是他的先祖。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00544","html":"\u003cp class=\"epub-calibre1\">西西涅斯 因为他出身这样高贵，他自己又立下这许多功劳，应该可以使他得到一个很高的位置，所以我们才把他向你们举荐；可是你们在把他过去的行为和现在的态度互相观照之下，认为他始终是你们的敌人，所以决定撤回你们一时疏忽的同意。\u003c/p>\n","text":"西西涅斯 因为他出身这样高贵，他自己又立下这许多功劳，应该可以使他得到一个很高的位置，所以我们才把他向你们举荐；可是你们在把他过去的行为和现在的态度互相观照之下，认为他始终是你们的敌人，所以决定撤回你们一时疏忽的同意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00545","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 你们坚持着说，你们的同意只是因为受到我们的怂恿；把民众召集起来以后，你们立刻就到议会里来。\u003c/p>\n","text":"勃鲁托斯 你们坚持着说，你们的同意只是因为受到我们的怂恿；把民众召集起来以后，你们立刻就到议会里来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00546","html":"\u003cp class=\"epub-calibre1\">众人 我们一定这样做；我们大家都懊悔选他。\u003cb class=\"epub-calibre3\">（众市民下。）\u003c/b>\u003c/p>\n","text":"众人 我们一定这样做；我们大家都懊悔选他。（众市民下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00547","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 让他们去闹；与其隐忍着更大的危机，不如冒险鼓动起这一场叛变。要是他照着以往的脾气，果然因为他们的拒绝而发起怒来，那么我们正可以好好利用这一个机会。\u003c/p>\n","text":"勃鲁托斯 让他们去闹；与其隐忍着更大的危机，不如冒险鼓动起这一场叛变。要是他照着以往的脾气，果然因为他们的拒绝而发起怒来，那么我们正可以好好利用这一个机会。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00548","html":"\u003cp class=\"epub-calibre1\">西西涅斯 到议会去。来，我们必须趁着大批的民众还没有赶到以前先到那儿，免得被人家看出他们是受我们的煽动。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"西西涅斯 到议会去。来，我们必须趁着大批的民众还没有赶到以前先到那儿，免得被人家看出他们是受我们的煽动。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第三场 同前。大市场","headingLevel":4,"sourceAnchor":"a736","actNumber":2,"sceneNumber":3},{"id":"part0031-section-016","label":"第三幕","kind":"act","blocks":[{"id":"part0031-00549","html":"\u003ch3 id=\"epub-part0031-a737\" class=\"epub-calibre11\">第三幕\u003c/h3>\n","text":"第三幕\n","sourceAnchor":"a737","tag":"h3"}],"heading":"第三幕","headingLevel":3,"sourceAnchor":"a737","actNumber":3},{"id":"part0031-section-017","label":"第三幕 · 第一场 罗马。街道","kind":"scene","blocks":[{"id":"part0031-00550","html":"\u003ch4 id=\"epub-part0031-a738\" class=\"epub-calibre12\">第一场 罗马。街道\u003c/h4>\n","text":"第一场 罗马。街道\n","sourceAnchor":"a738","tag":"h4"},{"id":"part0031-00551","html":"\u003cp class=\"epub-block1\">吹号筒；科利奥兰纳斯、米尼涅斯、考密涅斯、泰特斯·拉歇斯、众元老、贵族等同上。\u003c/p>\n","text":"吹号筒；科利奥兰纳斯、米尼涅斯、考密涅斯、泰特斯·拉歇斯、众元老、贵族等同上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00552","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 那么塔勒斯·奥菲狄乌斯又发兵来了吗？\u003c/p>\n","text":"科利奥兰纳斯 那么塔勒斯·奥菲狄乌斯又发兵来了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00553","html":"\u003cp class=\"epub-calibre1\">拉歇斯 是的，阁下；所以我们应当格外迅速地部署起来。\u003c/p>\n","text":"拉歇斯 是的，阁下；所以我们应当格外迅速地部署起来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00554","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 这么说，伏尔斯人还是没有屈服，随时准备着向我们乘机进攻。\u003c/p>\n","text":"科利奥兰纳斯 这么说，伏尔斯人还是没有屈服，随时准备着向我们乘机进攻。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00555","html":"\u003cp class=\"epub-calibre1\">考密涅斯 执政阁下，他们已经精疲力尽，我们这一辈子大概不会再看见他们的旗帜飘扬了。\u003c/p>\n","text":"考密涅斯 执政阁下，他们已经精疲力尽，我们这一辈子大概不会再看见他们的旗帜飘扬了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00556","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你看见奥菲狄乌斯吗？\u003c/p>\n","text":"科利奥兰纳斯 你看见奥菲狄乌斯吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00557","html":"\u003cp class=\"epub-calibre1\">拉歇斯 在我们的保卫之下他曾经来看过我；他咒骂伏尔斯人，因为他们这样卑怯地举城纳降。现在他退到安息地方去了。\u003c/p>\n","text":"拉歇斯 在我们的保卫之下他曾经来看过我；他咒骂伏尔斯人，因为他们这样卑怯地举城纳降。现在他退到安息地方去了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00558","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 他说起我吗？\u003c/p>\n","text":"科利奥兰纳斯 他说起我吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00559","html":"\u003cp class=\"epub-calibre1\">拉歇斯 说起的，阁下。\u003c/p>\n","text":"拉歇斯 说起的，阁下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00560","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 怎么说？说些什么？\u003c/p>\n","text":"科利奥兰纳斯 怎么说？说些什么？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00561","html":"\u003cp class=\"epub-calibre1\">拉歇斯 他说他跟您剑对剑地会过多少次；在这世上，您是他最切齿痛恨的一个人，他说只要能够找到一个机会把您打败，他不惜荡尽他的财产。\u003c/p>\n","text":"拉歇斯 他说他跟您剑对剑地会过多少次；在这世上，您是他最切齿痛恨的一个人，他说只要能够找到一个机会把您打败，他不惜荡尽他的财产。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00562","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 他住在安息地方吗？\u003c/p>\n","text":"科利奥兰纳斯 他住在安息地方吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00563","html":"\u003cp class=\"epub-calibre1\">拉歇斯 是的。\u003c/p>\n","text":"拉歇斯 是的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00564","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我希望有机会到那边去找他，让我们把彼此的仇恨发泄一个痛快。欢迎你回来！\u003c/p>\n","text":"科利奥兰纳斯 我希望有机会到那边去找他，让我们把彼此的仇恨发泄一个痛快。欢迎你回来！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00565","html":"\u003cp class=\"epub-block1\">西西涅斯及勃鲁托斯上。\u003c/p>\n","text":"西西涅斯及勃鲁托斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00566","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 瞧！这两个是护民官，平民大众的喉舌；我瞧不起他们，因为他们擅作威福，简直到了叫人忍无可忍的地步。\u003c/p>\n","text":"科利奥兰纳斯 瞧！这两个是护民官，平民大众的喉舌；我瞧不起他们，因为他们擅作威福，简直到了叫人忍无可忍的地步。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00567","html":"\u003cp class=\"epub-calibre1\">西西涅斯 不要走过去。\u003c/p>\n","text":"西西涅斯 不要走过去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00568","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 嘿！那是什么意思？\u003c/p>\n","text":"科利奥兰纳斯 嘿！那是什么意思？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00569","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 前面有危险，不要过去。\u003c/p>\n","text":"勃鲁托斯 前面有危险，不要过去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00570","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 为什么有这样的变化？\u003c/p>\n","text":"科利奥兰纳斯 为什么有这样的变化？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00571","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 怎么一回事？\u003c/p>\n","text":"米尼涅斯 怎么一回事？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00572","html":"\u003cp class=\"epub-calibre1\">考密涅斯 他不是已经由贵族平民双方通过了吗？\u003c/p>\n","text":"考密涅斯 他不是已经由贵族平民双方通过了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00573","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 考密涅斯，他没有。\u003c/p>\n","text":"勃鲁托斯 考密涅斯，他没有。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00574","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我不是已经得到孩子们的同意了吗？\u003c/p>\n","text":"科利奥兰纳斯 我不是已经得到孩子们的同意了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00575","html":"\u003cp class=\"epub-calibre1\">元老甲 两位护民官，让开；他必须到市场上去。\u003c/p>\n","text":"元老甲 两位护民官，让开；他必须到市场上去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00576","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 人民对他非常愤怒。\u003c/p>\n","text":"勃鲁托斯 人民对他非常愤怒。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00577","html":"\u003cp class=\"epub-calibre1\">西西涅斯 站住，否则大家都要卷进一场骚动里了。\u003c/p>\n","text":"西西涅斯 站住，否则大家都要卷进一场骚动里了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00578","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你们不是他们的牧人吗？他们会把刚才出口的话当场否认，这样的人也可以让他们有发言的权利吗？你们管些什么事情？你们既然是他们的嘴巴，为什么不把他们的牙齿管住？你们没有指使他们吗？\u003c/p>\n","text":"科利奥兰纳斯 你们不是他们的牧人吗？他们会把刚才出口的话当场否认，这样的人也可以让他们有发言的权利吗？你们管些什么事情？你们既然是他们的嘴巴，为什么不把他们的牙齿管住？你们没有指使他们吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00579","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 安静点儿，安静点儿。\u003c/p>\n","text":"米尼涅斯 安静点儿，安静点儿。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00580","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 这是一场有意的行动，全然是阴谋的结果，它的目的是要拘束贵族的意志。要是我们容忍这一种行为，我们就只好和那些既没有能力统治、又不愿被人统治的人们生活在一起了。\u003c/p>\n","text":"科利奥兰纳斯 这是一场有意的行动，全然是阴谋的结果，它的目的是要拘束贵族的意志。要是我们容忍这一种行为，我们就只好和那些既没有能力统治、又不愿被人统治的人们生活在一起了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00581","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 不要说这是一个阴谋。人民高呼着说您讥笑了他们，说您在不久以前施放谷物的时候，曾经口出怨言，辱骂那些为人民请命的人，说他们是时势的趋附者，谄媚之徒，卑鄙的小人。\u003c/p>\n","text":"勃鲁托斯 不要说这是一个阴谋。人民高呼着说您讥笑了他们，说您在不久以前施放谷物的时候，曾经口出怨言，辱骂那些为人民请命的人，说他们是时势的趋附者，谄媚之徒，卑鄙的小人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00582","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 这是大家早就知道的。\u003c/p>\n","text":"科利奥兰纳斯 这是大家早就知道的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00583","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 他们有的人还不知道。\u003c/p>\n","text":"勃鲁托斯 他们有的人还不知道。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00584","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 那么是你后来告诉他们的吗？\u003c/p>\n","text":"科利奥兰纳斯 那么是你后来告诉他们的吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00585","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 怎么！我告诉他们！\u003c/p>\n","text":"勃鲁托斯 怎么！我告诉他们！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00586","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你很可以干这种事的。\u003c/p>\n","text":"科利奥兰纳斯 你很可以干这种事的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00587","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 像您干的这种事，我想我可以比您干得好一点。\u003c/p>\n","text":"勃鲁托斯 像您干的这种事，我想我可以比您干得好一点。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00588","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 那么我为什么要做执政呢？凭着那边天上的云起誓，让我也像你们一样没有寸尺之功，跟你们一起做个护民官吧！\u003c/p>\n","text":"科利奥兰纳斯 那么我为什么要做执政呢？凭着那边天上的云起誓，让我也像你们一样没有寸尺之功，跟你们一起做个护民官吧！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00589","html":"\u003cp class=\"epub-calibre1\">西西涅斯 您把悻悻之情表现得太露骨了，人民正是为了这个缘故才激动起来的。您现在已经迷失了道路，要是您想达到您的目的地，您必须用温和一点的态度向人家问路，否则您不但永远做不到一个尊荣的执政，就是要跟他并肩做一个护民官，也是一样办不到的。\u003c/p>\n","text":"西西涅斯 您把悻悻之情表现得太露骨了，人民正是为了这个缘故才激动起来的。您现在已经迷失了道路，要是您想达到您的目的地，您必须用温和一点的态度向人家问路，否则您不但永远做不到一个尊荣的执政，就是要跟他并肩做一个护民官，也是一样办不到的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00590","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 让我们安静一点。\u003c/p>\n","text":"米尼涅斯 让我们安静一点。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00591","html":"\u003cp class=\"epub-calibre1\">考密涅斯 人民一定被人利用、受人指使了。这一种纷争不应该在罗马发生；科利奥兰纳斯因功受禄，也不该在他坦荡的大路上遭遇这种用卑鄙手段安放上去的当途的障碍。\u003c/p>\n","text":"考密涅斯 人民一定被人利用、受人指使了。这一种纷争不应该在罗马发生；科利奥兰纳斯因功受禄，也不该在他坦荡的大路上遭遇这种用卑鄙手段安放上去的当途的障碍。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00592","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 向我提起谷物的事情！那个时候我是这样说的，我可以把它重说一遍——\u003c/p>\n","text":"科利奥兰纳斯 向我提起谷物的事情！那个时候我是这样说的，我可以把它重说一遍——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00593","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 现在不用说了。\u003c/p>\n","text":"米尼涅斯 现在不用说了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00594","html":"\u003cp class=\"epub-calibre1\">元老甲 在这样意气相争的时候，还是不用说了吧。\u003c/p>\n","text":"元老甲 在这样意气相争的时候，还是不用说了吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00595","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我一定要说。我的高贵的朋友们，请你们原谅。这种反复无常、腥臊恶臭的群众，我不愿恭维他们，让他们认清楚自己的面目吧。我要再说一遍，我们因为屈尊纡贵，与他们降身相伍，已经亲手播下了叛乱、放肆和骚扰的祸根，要是再对他们姑息纵容，那么这种莠草更将滋蔓横行，危害我们元老院的权力；我们不是没有道德，更不是没有力量，可是我们的力量已经送给一群乞丐了。\u003c/p>\n","text":"科利奥兰纳斯 我一定要说。我的高贵的朋友们，请你们原谅。这种反复无常、腥臊恶臭的群众，我不愿恭维他们，让他们认清楚自己的面目吧。我要再说一遍，我们因为屈尊纡贵，与他们降身相伍，已经亲手播下了叛乱、放肆和骚扰的祸根，要是再对他们姑息纵容，那么这种莠草更将滋蔓横行，危害我们元老院的权力；我们不是没有道德，更不是没有力量，可是我们的力量已经送给一群乞丐了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00596","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 好，别说下去了。\u003c/p>\n","text":"米尼涅斯 好，别说下去了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00597","html":"\u003cp class=\"epub-calibre1\">元老甲 请您不要再说下去了。\u003c/p>\n","text":"元老甲 请您不要再说下去了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00598","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 怎么！不再说下去！我曾经不怕外力的凭陵，为国家流过血，现在我更要大声疾呼，直到嘶破我的肺部为止，警告你们留意那些你们所厌恶、畏惧、惟恐沾染然而却又正在竭力招引上身的麻疹。\u003c/p>\n","text":"科利奥兰纳斯 怎么！不再说下去！我曾经不怕外力的凭陵，为国家流过血，现在我更要大声疾呼，直到嘶破我的肺部为止，警告你们留意那些你们所厌恶、畏惧、惟恐沾染然而却又正在竭力招引上身的麻疹。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00599","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 您讲起人民的时候，好像您是一位膺惩罪恶的天神，忘记了您也是跟他们具有同样弱点的凡人。\u003c/p>\n","text":"勃鲁托斯 您讲起人民的时候，好像您是一位膺惩罪恶的天神，忘记了您也是跟他们具有同样弱点的凡人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00600","html":"\u003cp class=\"epub-calibre1\">西西涅斯 我们应当让人民知道他这种话。\u003c/p>\n","text":"西西涅斯 我们应当让人民知道他这种话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00601","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 怎么，怎么？他的一时气愤的话吗？\u003c/p>\n","text":"米尼涅斯 怎么，怎么？他的一时气愤的话吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00602","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 一时气愤！即使我像午夜的睡眠一样善于忍耐，凭着乔武起誓，我也不会改变我这一种意思！\u003c/p>\n","text":"科利奥兰纳斯 一时气愤！即使我像午夜的睡眠一样善于忍耐，凭着乔武起誓，我也不会改变我这一种意思！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00603","html":"\u003cp class=\"epub-calibre1\">西西涅斯 您这一种意思必须让它留着毒害自己，不能让它毒害别人。\u003c/p>\n","text":"西西涅斯 您这一种意思必须让它留着毒害自己，不能让它毒害别人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00604","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 必须让它留着！你们听见这个侏儒群中的高个子的话吗？你们注意到他那斩钉截铁的“必须”两个字吗？\u003c/p>\n","text":"科利奥兰纳斯 必须让它留着！你们听见这个侏儒群中的高个子的话吗？你们注意到他那斩钉截铁的“必须”两个字吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00605","html":"\u003cp class=\"epub-calibre1\">考密涅斯 好像他的话就是神圣的律法似的。\u003c/p>\n","text":"考密涅斯 好像他的话就是神圣的律法似的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00606","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 “必须”！啊，善良而不智的贵族！你们这些庄重而卤莽的元老们，为什么你们会允许这多头的水蛇选举一个官吏，让他代替怪物发言，凭着他的专横的“必须”两字，他会大胆宣布要把你们的水流向沟渠决注，把你们的河道侵为己有？放下你们的愚昧，从你们危险的宽容中间觉醒过来吧！你们是博学的人，不要像一般愚人一样，甘心替他们掇椅铺垫。要是他们做了元老，你们便要变成平民；当他们的声音和你们的声音混合在一起的时候，因为他们人数众多，你们将要完全为他们所掩盖，被他们所支配。他们可以选择他们自己的官长，就像这家伙一样，凭着他的“必须”、他的迎合民心的“必须”两字，就可以和最尊严的元老们对抗。凭着乔武本身起誓，执政们将会因此失去他们的身份；当两种权力彼此对峙的时候，混乱就会乘机而起，我一想到这种危机，心里就感到极大的痛苦。\u003c/p>\n","text":"科利奥兰纳斯 “必须”！啊，善良而不智的贵族！你们这些庄重而卤莽的元老们，为什么你们会允许这多头的水蛇选举一个官吏，让他代替怪物发言，凭着他的专横的“必须”两字，他会大胆宣布要把你们的水流向沟渠决注，把你们的河道侵为己有？放下你们的愚昧，从你们危险的宽容中间觉醒过来吧！你们是博学的人，不要像一般愚人一样，甘心替他们掇椅铺垫。要是他们做了元老，你们便要变成平民；当他们的声音和你们的声音混合在一起的时候，因为他们人数众多，你们将要完全为他们所掩盖，被他们所支配。他们可以选择他们自己的官长，就像这家伙一样，凭着他的“必须”、他的迎合民心的“必须”两字，就可以和最尊严的元老们对抗。凭着乔武本身起誓，执政们将会因此失去他们的身份；当两种权力彼此对峙的时候，混乱就会乘机而起，我一想到这种危机，心里就感到极大的痛苦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00607","html":"\u003cp class=\"epub-calibre1\">考密涅斯 好，到市场上去吧。\u003c/p>\n","text":"考密涅斯 好，到市场上去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00608","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 谁授权执政，使他散放仓库中的存谷，像从前希腊的情形——\u003c/p>\n","text":"科利奥兰纳斯 谁授权执政，使他散放仓库中的存谷，像从前希腊的情形——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00609","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 得啦，得啦，别提起那句话啦。\u003c/p>\n","text":"米尼涅斯 得啦，得啦，别提起那句话啦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00610","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 虽然希腊人民有更大的权力，可是我说，他们这一种举动，无异养成反叛的风气，酿成了国家的瓦解。\u003c/p>\n","text":"科利奥兰纳斯 虽然希腊人民有更大的权力，可是我说，他们这一种举动，无异养成反叛的风气，酿成了国家的瓦解。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00611","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 嘿，人民可以同意说这种话的人当执政吗？\u003c/p>\n","text":"勃鲁托斯 嘿，人民可以同意说这种话的人当执政吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00612","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我可以说出比他们的同意更好的理由来。他们知道这些谷不是我们名分中的酬报，自以为谁也不会把它从他们的嘴边夺下来，所以也从来不曾为它出过一丝劳力。当国家危急存亡的关头要他们出征的时候，他们懒得连城门也不肯走出；一到了战场，他们只有在叛变内讧这一类行动上表现了最大的勇气；像这样的功绩，是不该把谷物白白分给他们的。他们常常用莫须有的罪名指斥元老院，难道我们因为受到了他们那样的指斥，才会作这样慷慨的施舍吗？好，给了他们又怎样呢？这些盲目的群众会感激元老院的好意吗？他们的行动就可以代替他们的言语：“我们提出要求；我们是大多数，他们畏惧我们，所以答应了我们的要求。”这样我们贬抑了我们自己的地位，让那些乌合之众把我们的谨慎称为恐惧；他们的胆子愈来愈大，总有一天会打开元老院的锁，让一群乌鸦飞进来向鹰隼乱啄。\u003c/p>\n","text":"科利奥兰纳斯 我可以说出比他们的同意更好的理由来。他们知道这些谷不是我们名分中的酬报，自以为谁也不会把它从他们的嘴边夺下来，所以也从来不曾为它出过一丝劳力。当国家危急存亡的关头要他们出征的时候，他们懒得连城门也不肯走出；一到了战场，他们只有在叛变内讧这一类行动上表现了最大的勇气；像这样的功绩，是不该把谷物白白分给他们的。他们常常用莫须有的罪名指斥元老院，难道我们因为受到了他们那样的指斥，才会作这样慷慨的施舍吗？好，给了他们又怎样呢？这些盲目的群众会感激元老院的好意吗？他们的行动就可以代替他们的言语：“我们提出要求；我们是大多数，他们畏惧我们，所以答应了我们的要求。”这样我们贬抑了我们自己的地位，让那些乌合之众把我们的谨慎称为恐惧；他们的胆子愈来愈大，总有一天会打开元老院的锁，让一群乌鸦飞进来向鹰隼乱啄。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00613","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 够了，够了。\u003c/p>\n","text":"米尼涅斯 够了，够了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00614","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 够了，已经说得太多了。\u003c/p>\n","text":"勃鲁托斯 够了，已经说得太多了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00615","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 不，再听我说下去。无论天上人间，一切可以凭着发誓的东西，愿它们为我的结论作证！元老贵族与平民两方面的权柄，一部分因为确有原因而轻视着另一部分，那一部分却毫无理由地侮辱着这一部分；身份、名位和智慧不能决定可否，却必须取决于无知的大众的一句是非，这样的结果必致于忽略了实际的需要，让轻率的狂妄操纵着一切；正当的目的受到阻碍，一切事情都是无目的地胡作非为。所以，我请求你们，要是你们的谨慎过于你们的恐惧，你们爱护国家的基础甚于怀疑它的变化，你们喜欢光荣甚于长生，愿意用危险的药饵向一个别无生望的病体作冒险的一试，那么赶快拔去群众的舌头吧；让他们不要去舐那将要毒害他们的蜜糖。你们要是受到耻辱，是非的公论也要从此不明，政府将要失去它所应有的健全，因为它被恶势力所统治，一切善政都将无法推行。\u003c/p>\n","text":"科利奥兰纳斯 不，再听我说下去。无论天上人间，一切可以凭着发誓的东西，愿它们为我的结论作证！元老贵族与平民两方面的权柄，一部分因为确有原因而轻视着另一部分，那一部分却毫无理由地侮辱着这一部分；身份、名位和智慧不能决定可否，却必须取决于无知的大众的一句是非，这样的结果必致于忽略了实际的需要，让轻率的狂妄操纵着一切；正当的目的受到阻碍，一切事情都是无目的地胡作非为。所以，我请求你们，要是你们的谨慎过于你们的恐惧，你们爱护国家的基础甚于怀疑它的变化，你们喜欢光荣甚于长生，愿意用危险的药饵向一个别无生望的病体作冒险的一试，那么赶快拔去群众的舌头吧；让他们不要去舐那将要毒害他们的蜜糖。你们要是受到耻辱，是非的公论也要从此不明，政府将要失去它所应有的健全，因为它被恶势力所统治，一切善政都将无法推行。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00616","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 他已经说得很够了。\u003c/p>\n","text":"勃鲁托斯 他已经说得很够了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00617","html":"\u003cp class=\"epub-calibre1\">西西涅斯 他说的全然是叛徒的话；他必须受叛徒的处分。\u003c/p>\n","text":"西西涅斯 他说的全然是叛徒的话；他必须受叛徒的处分。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00618","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你这卑鄙的家伙！让你受众人的唾弃！人民要这种秃头的护民官干吗呢？因为信任了他们，所以人民才会不再服从比他们地位高的人。在叛乱的时候，一切不合理的事实都可以武断地成为法律，那时候他们才是应该受人拥戴的人物；可是在正常的时期，那么让一切按照着正理而行，把他们的权力推下尘土里去吧。\u003c/p>\n","text":"科利奥兰纳斯 你这卑鄙的家伙！让你受众人的唾弃！人民要这种秃头的护民官干吗呢？因为信任了他们，所以人民才会不再服从比他们地位高的人。在叛乱的时候，一切不合理的事实都可以武断地成为法律，那时候他们才是应该受人拥戴的人物；可是在正常的时期，那么让一切按照着正理而行，把他们的权力推下尘土里去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00619","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 公然的叛逆！\u003c/p>\n","text":"勃鲁托斯 公然的叛逆！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00620","html":"\u003cp class=\"epub-calibre1\">西西涅斯 这还是个执政吗？不。\u003c/p>\n","text":"西西涅斯 这还是个执政吗？不。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00621","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 喂！警官呢？把他逮捕起来。\u003c/p>\n","text":"勃鲁托斯 喂！警官呢？把他逮捕起来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00622","html":"\u003cp class=\"epub-block1\">一警吏上。\u003c/p>\n","text":"一警吏上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00623","html":"\u003cp class=\"epub-calibre1\">西西涅斯 去，叫民众来；\u003cb class=\"epub-calibre3\">（警吏下）\u003c/b>我用人民的名义亲自逮捕你，宣布你是一个企图政变的叛徒，公众幸福的敌人；我命令你不得反抗，跟我去听候处分。\u003c/p>\n","text":"西西涅斯 去，叫民众来；（警吏下）我用人民的名义亲自逮捕你，宣布你是一个企图政变的叛徒，公众幸福的敌人；我命令你不得反抗，跟我去听候处分。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00624","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 滚开，老山羊！\u003c/p>\n","text":"科利奥兰纳斯 滚开，老山羊！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00625","html":"\u003cp class=\"epub-calibre1\">众元老 我们可以替他担保。\u003c/p>\n","text":"众元老 我们可以替他担保。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00626","html":"\u003cp class=\"epub-calibre1\">考密涅斯 老人家，放开手。\u003c/p>\n","text":"考密涅斯 老人家，放开手。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00627","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 滚开，坏东西！否则我要把你的骨头一根根摇下来。\u003c/p>\n","text":"科利奥兰纳斯 滚开，坏东西！否则我要把你的骨头一根根摇下来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00628","html":"\u003cp class=\"epub-calibre1\">西西涅斯 诸位市民，救命啊！\u003c/p>\n","text":"西西涅斯 诸位市民，救命啊！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00629","html":"\u003cp class=\"epub-block1\">若干警吏率侍从及一群市民同上。\u003c/p>\n","text":"若干警吏率侍从及一群市民同上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00630","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 两方面彼此客气一点。\u003c/p>\n","text":"米尼涅斯 两方面彼此客气一点。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00631","html":"\u003cp class=\"epub-calibre1\">西西涅斯 这个人要夺去你们一切的权力。\u003c/p>\n","text":"西西涅斯 这个人要夺去你们一切的权力。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00632","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 抓住他，警官们！\u003c/p>\n","text":"勃鲁托斯 抓住他，警官们！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00633","html":"\u003cp class=\"epub-calibre1\">众市民 打倒他！打倒他！——\u003c/p>\n","text":"众市民 打倒他！打倒他！——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00634","html":"\u003cp class=\"epub-calibre1\">众元老 \u003cb class=\"epub-calibre3\">（围绕科利奥兰纳斯忙作一团，狂呼）\u003c/b>武器！——武器！——武器！——护民官！——贵族们！——市民们！——喂！——西西涅斯！——勃鲁托斯！——科利奥兰纳斯！——市民们！——静！——静！——静！——且慢！——住手！——静！\u003c/p>\n","text":"众元老 （围绕科利奥兰纳斯忙作一团，狂呼）武器！——武器！——武器！——护民官！——贵族们！——市民们！——喂！——西西涅斯！——勃鲁托斯！——科利奥兰纳斯！——市民们！——静！——静！——静！——且慢！——住手！——静！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00635","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 事情将要闹得怎样呢？——我气都喘不过来啦。这一场乱子可不小。我话都说不出来啦。你们这两位护民官！科利奥兰纳斯，忍耐些！好西西涅斯，说句话吧。\u003c/p>\n","text":"米尼涅斯 事情将要闹得怎样呢？——我气都喘不过来啦。这一场乱子可不小。我话都说不出来啦。你们这两位护民官！科利奥兰纳斯，忍耐些！好西西涅斯，说句话吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00636","html":"\u003cp class=\"epub-calibre1\">西西涅斯 听我说，诸位民众；静下来！\u003c/p>\n","text":"西西涅斯 听我说，诸位民众；静下来！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00637","html":"\u003cp class=\"epub-calibre1\">众市民 让我们听我们的护民官说话；静下来！说，说，说。\u003c/p>\n","text":"众市民 让我们听我们的护民官说话；静下来！说，说，说。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00638","html":"\u003cp class=\"epub-calibre1\">西西涅斯 你们快要失去你们的自由了，马歇斯将要夺去你们的一切；马歇斯，就是刚才你们选举他做执政的。\u003c/p>\n","text":"西西涅斯 你们快要失去你们的自由了，马歇斯将要夺去你们的一切；马歇斯，就是刚才你们选举他做执政的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00639","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 哎哟，哎哟，哎哟！这不是去灭火，明明是火上加油。\u003c/p>\n","text":"米尼涅斯 哎哟，哎哟，哎哟！这不是去灭火，明明是火上加油。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00640","html":"\u003cp class=\"epub-calibre1\">元老甲 他要把我们这城市拆为平地。\u003c/p>\n","text":"元老甲 他要把我们这城市拆为平地。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00641","html":"\u003cp class=\"epub-calibre1\">西西涅斯 没有人民，还有什么城市？\u003c/p>\n","text":"西西涅斯 没有人民，还有什么城市？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00642","html":"\u003cp class=\"epub-calibre1\">众市民 对了，有人民才有城市。\u003c/p>\n","text":"众市民 对了，有人民才有城市。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00643","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 我们得到全体的同意，就任人民的长官。\u003c/p>\n","text":"勃鲁托斯 我们得到全体的同意，就任人民的长官。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00644","html":"\u003cp class=\"epub-calibre1\">众市民 你们继续是我们的长官。\u003c/p>\n","text":"众市民 你们继续是我们的长官。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00645","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 他们也未必会放弃这一个地位。\u003c/p>\n","text":"米尼涅斯 他们也未必会放弃这一个地位。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00646","html":"\u003cp class=\"epub-calibre1\">考密涅斯 他们要把城市拆毁，把屋宇摧为平地，把整整齐齐的市面埋葬在一堆瓦砾的中间。\u003c/p>\n","text":"考密涅斯 他们要把城市拆毁，把屋宇摧为平地，把整整齐齐的市面埋葬在一堆瓦砾的中间。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00647","html":"\u003cp class=\"epub-calibre1\">西西涅斯 这一种罪名应该判处死刑。\u003c/p>\n","text":"西西涅斯 这一种罪名应该判处死刑。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00648","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 让我们执行我们的权力，否则让我们失去我们的权力。我们现在奉人民的意旨，宣布马歇斯应该立刻受死刑的处分。\u003c/p>\n","text":"勃鲁托斯 让我们执行我们的权力，否则让我们失去我们的权力。我们现在奉人民的意旨，宣布马歇斯应该立刻受死刑的处分。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00649","html":"\u003cp class=\"epub-calibre1\">西西涅斯 抓住他，把他押送到大帕岩\u003ca id=\"epub-part0031-w003\">\u003c/a>\u003ca href=\"#epub-part0031-m003\" data-source-anchor=\"m003\">\u003csup class=\"epub-calibre13\">[3]\u003c/sup>\u003c/a>上，推下山谷里去。\u003c/p>\n","text":"西西涅斯 抓住他，把他押送到大帕岩[3]上，推下山谷里去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00650","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 警官们，抓住他！\u003c/p>\n","text":"勃鲁托斯 警官们，抓住他！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00651","html":"\u003cp class=\"epub-calibre1\">众市民 马歇斯，赶快束手就缚！\u003c/p>\n","text":"众市民 马歇斯，赶快束手就缚！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00652","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 听我说一句话；两位护民官，请你们听我说一句话。\u003c/p>\n","text":"米尼涅斯 听我说一句话；两位护民官，请你们听我说一句话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00653","html":"\u003cp class=\"epub-calibre1\">警吏 静，静！\u003c/p>\n","text":"警吏 静，静！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00654","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 请你们做祖国的真正的友人，像你们表面上所装的一样；什么事情都可以用温和一点的手段解决，何必这样操切从事？\u003c/p>\n","text":"米尼涅斯 请你们做祖国的真正的友人，像你们表面上所装的一样；什么事情都可以用温和一点的手段解决，何必这样操切从事？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00655","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 要是病症凶险，只有投下猛药才可见效，谨慎反会误了大事。抓住他，把他押到山岩上去。\u003c/p>\n","text":"勃鲁托斯 要是病症凶险，只有投下猛药才可见效，谨慎反会误了大事。抓住他，把他押到山岩上去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00656","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 不，我宁愿死在这里。\u003cb class=\"epub-calibre3\">（拔剑）\u003c/b>你们中间有的人曾经瞧见我怎样跟敌人争战；来，你们自己现在也来试一试看。\u003c/p>\n","text":"科利奥兰纳斯 不，我宁愿死在这里。（拔剑）你们中间有的人曾经瞧见我怎样跟敌人争战；来，你们自己现在也来试一试看。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00657","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 放下那柄剑！两位护民官，你们暂时退下去吧。\u003c/p>\n","text":"米尼涅斯 放下那柄剑！两位护民官，你们暂时退下去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00658","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 抓住他！\u003c/p>\n","text":"勃鲁托斯 抓住他！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00659","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 帮助马歇斯，帮助他，你们这些有义气的人；帮助他，年轻的和年老的！\u003c/p>\n","text":"米尼涅斯 帮助马歇斯，帮助他，你们这些有义气的人；帮助他，年轻的和年老的！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00660","html":"\u003cp class=\"epub-calibre1\">众市民 打倒他！——打倒他！\u003cb class=\"epub-calibre3\">（在纷乱中护民官、警吏及民众均被打退。）\u003c/b>\u003c/p>\n","text":"众市民 打倒他！——打倒他！（在纷乱中护民官、警吏及民众均被打退。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00661","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 去，回到你家里去；快去！否则大家都要活不成啦。\u003c/p>\n","text":"米尼涅斯 去，回到你家里去；快去！否则大家都要活不成啦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00662","html":"\u003cp class=\"epub-calibre1\">元老乙 您快去吧。\u003c/p>\n","text":"元老乙 您快去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00663","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 站住；我们的朋友跟我们的敌人一样多。\u003c/p>\n","text":"科利奥兰纳斯 站住；我们的朋友跟我们的敌人一样多。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00664","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 难道我们一定要跟他们打起来吗？\u003c/p>\n","text":"米尼涅斯 难道我们一定要跟他们打起来吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00665","html":"\u003cp class=\"epub-calibre1\">元老甲 天神保佑我们不要有这样的事！尊贵的朋友，请你回家去，让我们设法挽回局势吧。\u003c/p>\n","text":"元老甲 天神保佑我们不要有这样的事！尊贵的朋友，请你回家去，让我们设法挽回局势吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00666","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 这是我们身上的一个痛疮，你不能替你自己医治；请你快去吧。\u003c/p>\n","text":"米尼涅斯 这是我们身上的一个痛疮，你不能替你自己医治；请你快去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00667","html":"\u003cp class=\"epub-calibre1\">考密涅斯 来，跟我们一块儿去。\u003c/p>\n","text":"考密涅斯 来，跟我们一块儿去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00668","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我希望他们是一群野蛮人，不是罗马人；虽然这些畜类生在罗马，长大在朱庇特神庙的宇下，可是他们却跟野蛮人没有分别——\u003c/p>\n","text":"科利奥兰纳斯 我希望他们是一群野蛮人，不是罗马人；虽然这些畜类生在罗马，长大在朱庇特神庙的宇下，可是他们却跟野蛮人没有分别——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00669","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 去吧；不要把你的满脸义愤放在你的唇舌上。\u003c/p>\n","text":"米尼涅斯 去吧；不要把你的满脸义愤放在你的唇舌上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00670","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 要是堂堂正正地交锋起来，我一个人可以打败他们四十个人。\u003c/p>\n","text":"科利奥兰纳斯 要是堂堂正正地交锋起来，我一个人可以打败他们四十个人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00671","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我自己也可以抵挡他们中间的一对头儿脑儿，那两个护民官。\u003c/p>\n","text":"米尼涅斯 我自己也可以抵挡他们中间的一对头儿脑儿，那两个护民官。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00672","html":"\u003cp class=\"epub-calibre1\">考密涅斯 可是现在众寡悬殊；当一幢房屋坍下的时候而不知道趋避，这一种勇气是被称为愚笨的。您还是趁着那群乱民没有回来以前赶快走开吧；他们的愤怒就像受到阻力的流水一样，一朝横决，就会把他们所负载的一切完全冲掉。\u003c/p>\n","text":"考密涅斯 可是现在众寡悬殊；当一幢房屋坍下的时候而不知道趋避，这一种勇气是被称为愚笨的。您还是趁着那群乱民没有回来以前赶快走开吧；他们的愤怒就像受到阻力的流水一样，一朝横决，就会把他们所负载的一切完全冲掉。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00673","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 请您快去吧。我要试一试我这老年人的智慧对于那些没有头脑的东西是不是有点需要；无论如何，这事情总要想法子弥缝过去。\u003c/p>\n","text":"米尼涅斯 请您快去吧。我要试一试我这老年人的智慧对于那些没有头脑的东西是不是有点需要；无论如何，这事情总要想法子弥缝过去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00674","html":"\u003cp class=\"epub-calibre1\">考密涅斯 去吧，去吧。\u003cb class=\"epub-calibre3\">（科利奥兰纳斯、考密涅斯及余人等同下。）\u003c/b>\u003c/p>\n","text":"考密涅斯 去吧，去吧。（科利奥兰纳斯、考密涅斯及余人等同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00675","html":"\u003cp class=\"epub-calibre1\">贵族甲 这个人把他自己的前途葬送了。\u003c/p>\n","text":"贵族甲 这个人把他自己的前途葬送了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00676","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 他的天性太高贵了，不适宜于这一个世界。他不肯恭维涅普图努斯的三叉戟的雄威，或是乔武的雷霆的神力。他的心就在他的口头，想到什么一定要说出来。他一动了怒，就会忘记世上有一个死字。\u003cb class=\"epub-calibre3\">（内喧声）\u003c/b>听他们闹得多厉害！\u003c/p>\n","text":"米尼涅斯 他的天性太高贵了，不适宜于这一个世界。他不肯恭维涅普图努斯的三叉戟的雄威，或是乔武的雷霆的神力。他的心就在他的口头，想到什么一定要说出来。他一动了怒，就会忘记世上有一个死字。（内喧声）听他们闹得多厉害！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00677","html":"\u003cp class=\"epub-calibre1\">贵族乙 我希望他们都去睡觉！\u003c/p>\n","text":"贵族乙 我希望他们都去睡觉！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00678","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我希望他们都给我跳下台伯河里！好厉害！他就不能对他们说句好话吗？\u003c/p>\n","text":"米尼涅斯 我希望他们都给我跳下台伯河里！好厉害！他就不能对他们说句好话吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00679","html":"\u003cp class=\"epub-block1\">勃鲁托斯及西西涅斯率乱民上。\u003c/p>\n","text":"勃鲁托斯及西西涅斯率乱民上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00680","html":"\u003cp class=\"epub-calibre1\">西西涅斯 要把全城的人吃掉、让他一个人称霸的那条毒蛇呢？\u003c/p>\n","text":"西西涅斯 要把全城的人吃掉、让他一个人称霸的那条毒蛇呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00681","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 两位尊贵的护民官——\u003c/p>\n","text":"米尼涅斯 两位尊贵的护民官——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00682","html":"\u003cp class=\"epub-calibre1\">西西涅斯 我们必须用无情的铁手，把他推下大帕岩去；他已经公然反抗法律，所以法律也无须再向他执行什么审判的手续，他既然藐视群众，就叫他认识认识群众的力量。\u003c/p>\n","text":"西西涅斯 我们必须用无情的铁手，把他推下大帕岩去；他已经公然反抗法律，所以法律也无须再向他执行什么审判的手续，他既然藐视群众，就叫他认识认识群众的力量。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00683","html":"\u003cp class=\"epub-calibre1\">市民甲 我们要让他明白，尊贵的护民官是人民的喉舌，我们是他们的胳臂。\u003c/p>\n","text":"市民甲 我们要让他明白，尊贵的护民官是人民的喉舌，我们是他们的胳臂。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00684","html":"\u003cp class=\"epub-calibre1\">众市民 我们一定要让他明白。\u003c/p>\n","text":"众市民 我们一定要让他明白。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00685","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 诸位，诸位——\u003c/p>\n","text":"米尼涅斯 诸位，诸位——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00686","html":"\u003cp class=\"epub-calibre1\">西西涅斯 静些！\u003c/p>\n","text":"西西涅斯 静些！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00687","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 有话可以商量，何必吵成这个样子？\u003c/p>\n","text":"米尼涅斯 有话可以商量，何必吵成这个样子？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00688","html":"\u003cp class=\"epub-calibre1\">西西涅斯 先生，你怎么也会帮助他逃走了？\u003c/p>\n","text":"西西涅斯 先生，你怎么也会帮助他逃走了？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00689","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 听我说；我知道这位执政的长处，我也可以举出他的短处。\u003c/p>\n","text":"米尼涅斯 听我说；我知道这位执政的长处，我也可以举出他的短处。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00690","html":"\u003cp class=\"epub-calibre1\">西西涅斯 执政！什么执政？\u003c/p>\n","text":"西西涅斯 执政！什么执政？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00691","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 科利奥兰纳斯执政。\u003c/p>\n","text":"米尼涅斯 科利奥兰纳斯执政。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00692","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 他！执政！\u003c/p>\n","text":"勃鲁托斯 他！执政！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00693","html":"\u003cp class=\"epub-calibre1\">众市民 不，不，不，不，不。\u003c/p>\n","text":"众市民 不，不，不，不，不。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00694","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 要是两位护民官和你们这些善良的民众允许我，我要请求说一两句话，你们听了以后，就会平心静气，自悔多事了。\u003c/p>\n","text":"米尼涅斯 要是两位护民官和你们这些善良的民众允许我，我要请求说一两句话，你们听了以后，就会平心静气，自悔多事了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00695","html":"\u003cp class=\"epub-calibre1\">西西涅斯 那么简简单单地说吧；因为我们已经决定除去这个恶毒的叛徒。把他驱逐出境会引起未来的祸患；留在国内，我们都要死在他的手里；所以我们决定就在今晚把他处死。\u003c/p>\n","text":"西西涅斯 那么简简单单地说吧；因为我们已经决定除去这个恶毒的叛徒。把他驱逐出境会引起未来的祸患；留在国内，我们都要死在他的手里；所以我们决定就在今晚把他处死。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00696","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我们的罗马是以赏罚严明著名于全世界的，她对于有功的儿女的爱护，是记录在天神的册籍里的，要是现在她像一头灭绝天性的母兽一样，吞食了她自己的子女，善良的神明一定不能容许！\u003c/p>\n","text":"米尼涅斯 我们的罗马是以赏罚严明著名于全世界的，她对于有功的儿女的爱护，是记录在天神的册籍里的，要是现在她像一头灭绝天性的母兽一样，吞食了她自己的子女，善良的神明一定不能容许！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00697","html":"\u003cp class=\"epub-calibre1\">西西涅斯 他是一颗必须割去的疮疖。\u003c/p>\n","text":"西西涅斯 他是一颗必须割去的疮疖。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00698","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 啊！他是一段生着疮疖的肢体，割去了会致人死命，治愈它却很容易。他对罗马做了些什么事，你们要把他处死呢？他杀死我们的敌人，为他的祖国流过血，我敢说一句，他所失去的血，比他身上所有的血更多；他剩下的血，要是现在再被他的国人取去，那么无论下这样毒手的人，或是容忍这种事情发生的人，都要永远在后世留下一个可耻的烙印了。\u003c/p>\n","text":"米尼涅斯 啊！他是一段生着疮疖的肢体，割去了会致人死命，治愈它却很容易。他对罗马做了些什么事，你们要把他处死呢？他杀死我们的敌人，为他的祖国流过血，我敢说一句，他所失去的血，比他身上所有的血更多；他剩下的血，要是现在再被他的国人取去，那么无论下这样毒手的人，或是容忍这种事情发生的人，都要永远在后世留下一个可耻的烙印了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00699","html":"\u003cp class=\"epub-calibre1\">西西涅斯 这些全然是胡说八道。\u003c/p>\n","text":"西西涅斯 这些全然是胡说八道。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00700","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 一派歪论；当他爱他的国家的时候，他的国家也尊重他。\u003c/p>\n","text":"勃鲁托斯 一派歪论；当他爱他的国家的时候，他的国家也尊重他。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00701","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 他的战功如果腐朽了，人家也就对他失去敬意了。\u003c/p>\n","text":"米尼涅斯 他的战功如果腐朽了，人家也就对他失去敬意了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00702","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 我们不想再听你说下去了。追到他家里去，把他拖出来；他是一种能够传染的恶病，不要让他的流毒沾到别人身上。\u003c/p>\n","text":"勃鲁托斯 我们不想再听你说下去了。追到他家里去，把他拖出来；他是一种能够传染的恶病，不要让他的流毒沾到别人身上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00703","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 再听我说一句话，只有一句话。你们现在的行动，都是出于一时的气愤，就像纵虎出柙一样，当你们自悔孟浪的时候，再要把笨重的铅块系在虎脚上就来不及了。与其卤莽偾事，不如循序渐进；否则他也不是没有人拥护的，要是因此而引起内争，那么伟大的罗马要在罗马人自己手里毁掉了。\u003c/p>\n","text":"米尼涅斯 再听我说一句话，只有一句话。你们现在的行动，都是出于一时的气愤，就像纵虎出柙一样，当你们自悔孟浪的时候，再要把笨重的铅块系在虎脚上就来不及了。与其卤莽偾事，不如循序渐进；否则他也不是没有人拥护的，要是因此而引起内争，那么伟大的罗马要在罗马人自己手里毁掉了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00704","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 要是这样的话——\u003c/p>\n","text":"勃鲁托斯 要是这样的话——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00705","html":"\u003cp class=\"epub-calibre1\">西西涅斯 你还说什么？我们不是已经领略到他是怎样地服从命令的吗？我们的警察官不是已经遭他痛打了吗？我们自己不是也遭他反抗过了吗？来！\u003c/p>\n","text":"西西涅斯 你还说什么？我们不是已经领略到他是怎样地服从命令的吗？我们的警察官不是已经遭他痛打了吗？我们自己不是也遭他反抗过了吗？来！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00706","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 请你们想到这一点：他自从两手能够拔剑的时候起，就一直在战阵中长大，不曾在温文尔雅的语言方面受过训练；他说起话来，总是把美谷和糠麸不加分别地同时倾吐。你们要是允许我，我可以到他家里去，向他陈说利害，叫他接受用和平的手段，合法的方式进行的裁判。\u003c/p>\n","text":"米尼涅斯 请你们想到这一点：他自从两手能够拔剑的时候起，就一直在战阵中长大，不曾在温文尔雅的语言方面受过训练；他说起话来，总是把美谷和糠麸不加分别地同时倾吐。你们要是允许我，我可以到他家里去，向他陈说利害，叫他接受用和平的手段，合法的方式进行的裁判。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00707","html":"\u003cp class=\"epub-calibre1\">元老甲 两位尊贵的护民官，这是最人道的办法；你们原来的方式太残酷了，而且也不知道将会引起怎样的结果。\u003c/p>\n","text":"元老甲 两位尊贵的护民官，这是最人道的办法；你们原来的方式太残酷了，而且也不知道将会引起怎样的结果。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00708","html":"\u003cp class=\"epub-calibre1\">西西涅斯 尊贵的米尼涅斯，那么请您接受人民的委托，去把他传来。各位朋友，放下你们的武器。\u003c/p>\n","text":"西西涅斯 尊贵的米尼涅斯，那么请您接受人民的委托，去把他传来。各位朋友，放下你们的武器。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00709","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 不要回去。\u003c/p>\n","text":"勃鲁托斯 不要回去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00710","html":"\u003cp class=\"epub-calibre1\">西西涅斯 在市场上集合。我们在那边等着你们。要是您不能把马歇斯带来，我们就实行原来的办法。\u003c/p>\n","text":"西西涅斯 在市场上集合。我们在那边等着你们。要是您不能把马歇斯带来，我们就实行原来的办法。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00711","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我一定会叫他来的。\u003cb class=\"epub-calibre3\">（向众元老）\u003c/b>请你们陪我去一趟。他一定要来，否则事情会愈弄愈糟的。\u003c/p>\n","text":"米尼涅斯 我一定会叫他来的。（向众元老）请你们陪我去一趟。他一定要来，否则事情会愈弄愈糟的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00712","html":"\u003cp class=\"epub-calibre1\">元老甲 我们去找他吧。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"元老甲 我们去找他吧。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第一场 罗马。街道","headingLevel":4,"sourceAnchor":"a738","actNumber":3,"sceneNumber":1},{"id":"part0031-section-018","label":"第三幕 · 第二场 同前。科利奥兰纳斯家中一室","kind":"scene","blocks":[{"id":"part0031-00713","html":"\u003ch4 id=\"epub-part0031-a739\" class=\"epub-calibre12\">第二场 同前。科利奥兰纳斯家中一室\u003c/h4>\n","text":"第二场 同前。科利奥兰纳斯家中一室\n","sourceAnchor":"a739","tag":"h4"},{"id":"part0031-00714","html":"\u003cp class=\"epub-block1\">科利奥兰纳斯及贵族等上。\u003c/p>\n","text":"科利奥兰纳斯及贵族等上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00715","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 让他们大家来扯我的耳朵；让他们把我用车轮辗死、马蹄踏死，或是堆十座山在大帕岩上，把我推下看不见底的深谷；我还是用这样一副态度对待他们。\u003c/p>\n","text":"科利奥兰纳斯 让他们大家来扯我的耳朵；让他们把我用车轮辗死、马蹄踏死，或是堆十座山在大帕岩上，把我推下看不见底的深谷；我还是用这样一副态度对待他们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00716","html":"\u003cp class=\"epub-calibre1\">贵族甲 这正是您的过人之处。\u003c/p>\n","text":"贵族甲 这正是您的过人之处。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00717","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我的母亲常常说他们只是一批萎靡软弱的货色，几毛钱就可以把他们买来卖去，在集会的时候秃露着头顶，听到像我这样地位的人谈到战争或和平的问题，就会打呵欠，莫名其妙地不作一声；我想她现在也不大赞成我。\u003c/p>\n","text":"科利奥兰纳斯 我的母亲常常说他们只是一批萎靡软弱的货色，几毛钱就可以把他们买来卖去，在集会的时候秃露着头顶，听到像我这样地位的人谈到战争或和平的问题，就会打呵欠，莫名其妙地不作一声；我想她现在也不大赞成我。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00718","html":"\u003cp class=\"epub-block1\">伏伦妮娅上。\u003c/p>\n","text":"伏伦妮娅上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00719","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我正在说起您。您为什么要我温和一点？难道您要我违反我的本性吗？您应该说，我现在的所作所为，正可以表现我的真正的骨气。\u003c/p>\n","text":"科利奥兰纳斯 我正在说起您。您为什么要我温和一点？难道您要我违反我的本性吗？您应该说，我现在的所作所为，正可以表现我的真正的骨气。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00720","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 啊！儿啊，儿啊，儿啊，我希望你不要在基础未固以前，就丢失了你手中的权力。\u003c/p>\n","text":"伏伦妮娅 啊！儿啊，儿啊，儿啊，我希望你不要在基础未固以前，就丢失了你手中的权力。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00721","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 别管我。\u003c/p>\n","text":"科利奥兰纳斯 别管我。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00722","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 你要不是这样有意显露你的锋芒，已经不失为一个豪杰之士；在他们还有力量阻挠你的时候，你要是少向他们矜夸一些意气，也可以少碰到一些逆意的事情。\u003c/p>\n","text":"伏伦妮娅 你要不是这样有意显露你的锋芒，已经不失为一个豪杰之士；在他们还有力量阻挠你的时候，你要是少向他们矜夸一些意气，也可以少碰到一些逆意的事情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00723","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 让他们上吊去吧！\u003c/p>\n","text":"科利奥兰纳斯 让他们上吊去吧！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00724","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 是的，我还希望他们在火里烧死。\u003c/p>\n","text":"伏伦妮娅 是的，我还希望他们在火里烧死。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00725","html":"\u003cp class=\"epub-block1\">米尼涅斯及元老等上。\u003c/p>\n","text":"米尼涅斯及元老等上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00726","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 来，来；您太粗暴了，有点太粗暴了；您非得回去把局势弥缝弥缝不可。\u003c/p>\n","text":"米尼涅斯 来，来；您太粗暴了，有点太粗暴了；您非得回去把局势弥缝弥缝不可。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00727","html":"\u003cp class=\"epub-calibre1\">元老甲 此外没有办法了；您要是不愿意这样做，我们的城市就要分裂而灭亡了。\u003c/p>\n","text":"元老甲 此外没有办法了；您要是不愿意这样做，我们的城市就要分裂而灭亡了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00728","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 请你接受劝告吧。我有一颗跟你同样刚强的心，可是我还有一个头脑，教我把我的愤怒用在更适当的地方。\u003c/p>\n","text":"伏伦妮娅 请你接受劝告吧。我有一颗跟你同样刚强的心，可是我还有一个头脑，教我把我的愤怒用在更适当的地方。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00729","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 说得好，尊贵的夫人！倘不是因为遭到这样非常的变化，为了挽回大局起见，不得不出此下策，那么我也要擐甲持枪，决不忍受这样的耻辱，让他去向群众屈身的。\u003c/p>\n","text":"米尼涅斯 说得好，尊贵的夫人！倘不是因为遭到这样非常的变化，为了挽回大局起见，不得不出此下策，那么我也要擐甲持枪，决不忍受这样的耻辱，让他去向群众屈身的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00730","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我必须怎么办？\u003c/p>\n","text":"科利奥兰纳斯 我必须怎么办？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00731","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 回去见那两个护民官。\u003c/p>\n","text":"米尼涅斯 回去见那两个护民官。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00732","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 好，还有呢？还有呢？\u003c/p>\n","text":"科利奥兰纳斯 好，还有呢？还有呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00733","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 为了您的失言道歉。\u003c/p>\n","text":"米尼涅斯 为了您的失言道歉。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00734","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 向他们道歉！我不能向神明道歉；难道我必须向他们道歉吗？\u003c/p>\n","text":"科利奥兰纳斯 向他们道歉！我不能向神明道歉；难道我必须向他们道歉吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00735","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 你太固执了；在危急的时候，一个人是应当通权达变的。我听你说过，在战争中间，荣誉和权谋就像亲密的朋友一样不可分离；假定这句话是真的，那么请你告诉我，在和平的时候，它们倘然不能交相为用，是不是能够独立存在？\u003c/p>\n","text":"伏伦妮娅 你太固执了；在危急的时候，一个人是应当通权达变的。我听你说过，在战争中间，荣誉和权谋就像亲密的朋友一样不可分离；假定这句话是真的，那么请你告诉我，在和平的时候，它们倘然不能交相为用，是不是能够独立存在？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00736","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 嘿！嘿！\u003c/p>\n","text":"科利奥兰纳斯 嘿！嘿！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00737","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 问得好。\u003c/p>\n","text":"米尼涅斯 问得好。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00738","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 要是你们在战争中间，为了达到你们的目的起见，不妨采用权谋，示人以诈，而这样的行为对于荣誉并无损害，那么在和平的时候，万一也像战时一样需要权谋，为什么它就不能和荣誉并行不悖呢？\u003c/p>\n","text":"伏伦妮娅 要是你们在战争中间，为了达到你们的目的起见，不妨采用权谋，示人以诈，而这样的行为对于荣誉并无损害，那么在和平的时候，万一也像战时一样需要权谋，为什么它就不能和荣誉并行不悖呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00739","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 为什么您要强迫我接受这种理由？\u003c/p>\n","text":"科利奥兰纳斯 为什么您要强迫我接受这种理由？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00740","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 因为你现在必须去向人民说话；不是照着你自己的意思说话，却要去向他们说一些完全违背你的本心的话。为了避免把自己的命运作孤注，为了避免流许多的血，你可以用温和的词句招抚一个城市，那么向人民说这样的话，对于你的荣誉又有什么损害呢？要是我的财产和我的亲友处于生死存亡的关头，需要我用欺诈的手段保全他们，我就会毅然去干那样的事，并不以为有什么可耻；我是代表你的妻子、你的儿子、这些元老和贵族们向你进这番忠告的；可是你却宁愿向这些无知的群众们怒目横眉，不愿向他们稍假辞色，去博取他们的欢心和爱戴，这是维持你的荣誉和地位所必需的保障。\u003c/p>\n","text":"伏伦妮娅 因为你现在必须去向人民说话；不是照着你自己的意思说话，却要去向他们说一些完全违背你的本心的话。为了避免把自己的命运作孤注，为了避免流许多的血，你可以用温和的词句招抚一个城市，那么向人民说这样的话，对于你的荣誉又有什么损害呢？要是我的财产和我的亲友处于生死存亡的关头，需要我用欺诈的手段保全他们，我就会毅然去干那样的事，并不以为有什么可耻；我是代表你的妻子、你的儿子、这些元老和贵族们向你进这番忠告的；可是你却宁愿向这些无知的群众们怒目横眉，不愿向他们稍假辞色，去博取他们的欢心和爱戴，这是维持你的荣誉和地位所必需的保障。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00741","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 尊贵的夫人！走吧，跟我们走吧；说两句好话；也许你不但可以缓和当前的危险，并且可以弥补过去的错误。\u003c/p>\n","text":"米尼涅斯 尊贵的夫人！走吧，跟我们走吧；说两句好话；也许你不但可以缓和当前的危险，并且可以弥补过去的错误。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00742","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 我的孩子，请你现在就去见他们，把这帽子拿在手里，你的膝盖吻着地上的砖石，摇摆着你的头，克制你的坚强的心，让它变得像摇摇欲坠的烂熟的桑子一样谦卑；在这种事情上，行为往往胜于雄辩，愚人的眼睛是比他们的耳朵聪明得多的。你可以对他们说，你是他们的战士，因为生长在干戈扰攘之中，不懂得博取他们好感所应有的礼节；可是从此以后，当你握权在位的日子，你一定会为他们鞠躬尽瘁。\u003c/p>\n","text":"伏伦妮娅 我的孩子，请你现在就去见他们，把这帽子拿在手里，你的膝盖吻着地上的砖石，摇摆着你的头，克制你的坚强的心，让它变得像摇摇欲坠的烂熟的桑子一样谦卑；在这种事情上，行为往往胜于雄辩，愚人的眼睛是比他们的耳朵聪明得多的。你可以对他们说，你是他们的战士，因为生长在干戈扰攘之中，不懂得博取他们好感所应有的礼节；可是从此以后，当你握权在位的日子，你一定会为他们鞠躬尽瘁。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00743","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 您只要照她这两句话说过以后，他们的心就是您的了；因为他们的原谅是有求必应的，正像他们爱说废话一样不费事。\u003c/p>\n","text":"米尼涅斯 您只要照她这两句话说过以后，他们的心就是您的了；因为他们的原谅是有求必应的，正像他们爱说废话一样不费事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00744","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 请你听从我们的劝告，去吧；虽然我知道你宁愿在火焰的深谷里追逐你的敌人，不愿在卧室之中向他献媚。考密涅斯来了。\u003c/p>\n","text":"伏伦妮娅 请你听从我们的劝告，去吧；虽然我知道你宁愿在火焰的深谷里追逐你的敌人，不愿在卧室之中向他献媚。考密涅斯来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00745","html":"\u003cp class=\"epub-block1\">考密涅斯上。\u003c/p>\n","text":"考密涅斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00746","html":"\u003cp class=\"epub-calibre1\">考密涅斯 我已经到市场上去过。您现在必须结合强力的援助，否则就得用温和的态度保全您自己，或者暂时出走，躲避他们的锋芒。所有的民众都激怒了。\u003c/p>\n","text":"考密涅斯 我已经到市场上去过。您现在必须结合强力的援助，否则就得用温和的态度保全您自己，或者暂时出走，躲避他们的锋芒。所有的民众都激怒了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00747","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 只有谦恭的言语才可以挽回形势。\u003c/p>\n","text":"米尼涅斯 只有谦恭的言语才可以挽回形势。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00748","html":"\u003cp class=\"epub-calibre1\">考密涅斯 要是他能够勉力抑制他的性子，我想这也是个办法。\u003c/p>\n","text":"考密涅斯 要是他能够勉力抑制他的性子，我想这也是个办法。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00749","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 他必须这样做，非这样做不可。请你说你愿意这样做，立刻就去吧。\u003c/p>\n","text":"伏伦妮娅 他必须这样做，非这样做不可。请你说你愿意这样做，立刻就去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00750","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我必须去向他们露我的秃脑袋吗？我必须用我的无耻的舌头，把一句谎话加在我的高贵的心上吗？好，我愿意。可是这一个计策倘然失败，他们就要把这个马歇斯的体肤磨成齑粉，迎风抛散了。到市场上去！你们现在逼着我去做一件事情，它的耻辱是我终身不能洗刷的。\u003c/p>\n","text":"科利奥兰纳斯 我必须去向他们露我的秃脑袋吗？我必须用我的无耻的舌头，把一句谎话加在我的高贵的心上吗？好，我愿意。可是这一个计策倘然失败，他们就要把这个马歇斯的体肤磨成齑粉，迎风抛散了。到市场上去！你们现在逼着我去做一件事情，它的耻辱是我终身不能洗刷的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00751","html":"\u003cp class=\"epub-calibre1\">考密涅斯 来，来，我们愿意帮您的忙。\u003c/p>\n","text":"考密涅斯 来，来，我们愿意帮您的忙。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00752","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 好儿子，你曾经说过，当初你因为受到我的奖励，所以才会成为一个军人；现在请你再接受我的奖励，做一件你从来没有做过的事吧。\u003c/p>\n","text":"伏伦妮娅 好儿子，你曾经说过，当初你因为受到我的奖励，所以才会成为一个军人；现在请你再接受我的奖励，做一件你从来没有做过的事吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00753","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 好，那么我就去。滚开，我的高傲的脾气，让一个娼妓的灵魂占据住我的身体！让我那和战鼓竞响的巨嗓变成像阉人一样地尖细、像催婴儿入睡的处女的歌声一样轻柔的声音！让我的颊上挂起奸徒的巧笑，让学童的眼泪蒙蔽我的目光！让乞儿的舌头在我的嘴唇之间转动，我那跨惯征鞍的罩甲的膝盖，像接受布施一样向人弯曲！不，我不愿意；我怕我会失去对我自己的尊敬，我的身体干了这样的事，也许会使我的精神沾上一重无法摆脱的卑鄙。\u003c/p>\n","text":"科利奥兰纳斯 好，那么我就去。滚开，我的高傲的脾气，让一个娼妓的灵魂占据住我的身体！让我那和战鼓竞响的巨嗓变成像阉人一样地尖细、像催婴儿入睡的处女的歌声一样轻柔的声音！让我的颊上挂起奸徒的巧笑，让学童的眼泪蒙蔽我的目光！让乞儿的舌头在我的嘴唇之间转动，我那跨惯征鞍的罩甲的膝盖，像接受布施一样向人弯曲！不，我不愿意；我怕我会失去对我自己的尊敬，我的身体干了这样的事，也许会使我的精神沾上一重无法摆脱的卑鄙。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00754","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 那么随你的便。我向你请求，比之你向他们请求，对于我是一个更大的耻辱。一切都归于毁灭吧；宁可让你的母亲感觉到你的骄傲，不要让她因为你的危险的顽强而担忧，因为我用像你一样豪壮的心讪笑着死亡。你愿意怎么办就怎么办；你的勇敢是从我身上得来的，你的骄傲却是你自己的。\u003c/p>\n","text":"伏伦妮娅 那么随你的便。我向你请求，比之你向他们请求，对于我是一个更大的耻辱。一切都归于毁灭吧；宁可让你的母亲感觉到你的骄傲，不要让她因为你的危险的顽强而担忧，因为我用像你一样豪壮的心讪笑着死亡。你愿意怎么办就怎么办；你的勇敢是从我身上得来的，你的骄傲却是你自己的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00755","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 请您宽心吧，母亲，我就到市场上去；不要责备我了。我要骗取他们的欢心，当我回来的时候，我将被罗马的一切手艺人所喜爱。瞧，我去了。替我向我的妻子致意。我一定要做一个执政回来，否则你们再不要相信我的舌头也会向人谄媚。\u003c/p>\n","text":"科利奥兰纳斯 请您宽心吧，母亲，我就到市场上去；不要责备我了。我要骗取他们的欢心，当我回来的时候，我将被罗马的一切手艺人所喜爱。瞧，我去了。替我向我的妻子致意。我一定要做一个执政回来，否则你们再不要相信我的舌头也会向人谄媚。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00756","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 照你的意思做吧。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"伏伦妮娅 照你的意思做吧。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00757","html":"\u003cp class=\"epub-calibre1\">考密涅斯 去！护民官在等着您。准备好一些温和的回答；因为我听说他们将要向您提出一些比现在他们加在您身上的更严重的罪状。\u003c/p>\n","text":"考密涅斯 去！护民官在等着您。准备好一些温和的回答；因为我听说他们将要向您提出一些比现在他们加在您身上的更严重的罪状。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00758","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 记好“温和”两个字。\u003c/p>\n","text":"米尼涅斯 记好“温和”两个字。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00759","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 让我们去吧；尽他们捏造我什么罪状，我都可以用我的荣誉答复他们。\u003c/p>\n","text":"科利奥兰纳斯 让我们去吧；尽他们捏造我什么罪状，我都可以用我的荣誉答复他们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00760","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 是的，可是要温和点儿。\u003c/p>\n","text":"米尼涅斯 是的，可是要温和点儿。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00761","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 好，那么就温和点儿。温和！\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"科利奥兰纳斯 好，那么就温和点儿。温和！（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第二场 同前。科利奥兰纳斯家中一室","headingLevel":4,"sourceAnchor":"a739","actNumber":3,"sceneNumber":2},{"id":"part0031-section-019","label":"第三幕 · 第三场 同前。大市场","kind":"scene","blocks":[{"id":"part0031-00762","html":"\u003ch4 id=\"epub-part0031-a740\" class=\"epub-calibre12\">第三场 同前。大市场\u003c/h4>\n","text":"第三场 同前。大市场\n","sourceAnchor":"a740","tag":"h4"},{"id":"part0031-00763","html":"\u003cp class=\"epub-block1\">西西涅斯及勃鲁托斯上。\u003c/p>\n","text":"西西涅斯及勃鲁托斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00764","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 我们说他企图独裁专政，用这一点作为他的最大的罪名；要是他在这一点上能够饰辞自辩，我们就说他敌视人民，并且说他把从安息人那里得到的战利品都中饱了自己的私囊。\u003c/p>\n","text":"勃鲁托斯 我们说他企图独裁专政，用这一点作为他的最大的罪名；要是他在这一点上能够饰辞自辩，我们就说他敌视人民，并且说他把从安息人那里得到的战利品都中饱了自己的私囊。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00765","html":"\u003cp class=\"epub-block1\">一警吏上。\u003c/p>\n","text":"一警吏上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00766","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 啊，他来不来？\u003c/p>\n","text":"勃鲁托斯 啊，他来不来？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00767","html":"\u003cp class=\"epub-calibre1\">警吏 他就来了。\u003c/p>\n","text":"警吏 他就来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00768","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 什么人陪着他？\u003c/p>\n","text":"勃鲁托斯 什么人陪着他？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00769","html":"\u003cp class=\"epub-calibre1\">警吏 年老的米尼涅斯和那些一向袒护他的元老们。\u003c/p>\n","text":"警吏 年老的米尼涅斯和那些一向袒护他的元老们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00770","html":"\u003cp class=\"epub-calibre1\">西西涅斯 你有没有把我们得到的票数记录下来？\u003c/p>\n","text":"西西涅斯 你有没有把我们得到的票数记录下来？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00771","html":"\u003cp class=\"epub-calibre1\">警吏 我已经记下在这儿了。\u003c/p>\n","text":"警吏 我已经记下在这儿了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00772","html":"\u003cp class=\"epub-calibre1\">西西涅斯 你有没有按着部族征询他们的意见？\u003c/p>\n","text":"西西涅斯 你有没有按着部族征询他们的意见？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00773","html":"\u003cp class=\"epub-calibre1\">警吏 我已经分别征询过了。\u003c/p>\n","text":"警吏 我已经分别征询过了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00774","html":"\u003cp class=\"epub-calibre1\">西西涅斯 快把民众立刻召集到这儿来；当他们听见我说，“凭着民众的权利和力量，必须如此如此”的时候，不论是死刑、罚款或是放逐，我要是说“罚款”，就让他们跟着我喊“罚款”；我要是说“死刑”，就让他们跟着我喊“死刑”。\u003c/p>\n","text":"西西涅斯 快把民众立刻召集到这儿来；当他们听见我说，“凭着民众的权利和力量，必须如此如此”的时候，不论是死刑、罚款或是放逐，我要是说“罚款”，就让他们跟着我喊“罚款”；我要是说“死刑”，就让他们跟着我喊“死刑”。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00775","html":"\u003cp class=\"epub-calibre1\">警吏 我一定这样吩咐他们。\u003c/p>\n","text":"警吏 我一定这样吩咐他们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00776","html":"\u003cp class=\"epub-calibre1\">西西涅斯 当他们开始呼喊的时候，叫他们不停地喊下去，大家乱哄哄地高声鼓噪，要求把我们的判决立刻实行。\u003c/p>\n","text":"西西涅斯 当他们开始呼喊的时候，叫他们不停地喊下去，大家乱哄哄地高声鼓噪，要求把我们的判决立刻实行。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00777","html":"\u003cp class=\"epub-calibre1\">警吏 很好。\u003c/p>\n","text":"警吏 很好。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00778","html":"\u003cp class=\"epub-calibre1\">西西涅斯 叫他们留心我们的说话行事，不要退缩让步。\u003c/p>\n","text":"西西涅斯 叫他们留心我们的说话行事，不要退缩让步。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00779","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 去干你的事吧。\u003cb class=\"epub-calibre3\">（警吏下）\u003c/b>一下子就激动他的怒气。他一向惯于征服别人，爱闹别扭；一受了拂逆，就不能控制自己的性子，那时候他心里想到什么便要说出口来，我们就可以看准他这个弱点致他死命。\u003c/p>\n","text":"勃鲁托斯 去干你的事吧。（警吏下）一下子就激动他的怒气。他一向惯于征服别人，爱闹别扭；一受了拂逆，就不能控制自己的性子，那时候他心里想到什么便要说出口来，我们就可以看准他这个弱点致他死命。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00780","html":"\u003cp class=\"epub-calibre1\">西西涅斯 好，他来了。\u003c/p>\n","text":"西西涅斯 好，他来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00781","html":"\u003cp class=\"epub-block1\">科利奥兰纳斯、米尼涅斯、考密涅斯及元老贵族等上。\u003c/p>\n","text":"科利奥兰纳斯、米尼涅斯、考密涅斯及元老贵族等上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00782","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 请您温和点儿。\u003c/p>\n","text":"米尼涅斯 请您温和点儿。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00783","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 好，就像一个马夫似的，为了一点点的赏钱，愿意替无论哪个恶徒奔走。但愿尊荣的天神们护佑罗马的安全，让贤德的君子做我们的执法者！播散爱的种子在我们的中间，使我们宏大的神庙里充满和平的气象，不要使我们的街道为战争所扰乱！\u003c/p>\n","text":"科利奥兰纳斯 好，就像一个马夫似的，为了一点点的赏钱，愿意替无论哪个恶徒奔走。但愿尊荣的天神们护佑罗马的安全，让贤德的君子做我们的执法者！播散爱的种子在我们的中间，使我们宏大的神庙里充满和平的气象，不要使我们的街道为战争所扰乱！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00784","html":"\u003cp class=\"epub-calibre1\">元老甲 阿门，阿门。\u003c/p>\n","text":"元老甲 阿门，阿门。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00785","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 好一个高尚的愿望！\u003c/p>\n","text":"米尼涅斯 好一个高尚的愿望！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00786","html":"\u003cp class=\"epub-block1\">警吏率市民等重上。\u003c/p>\n","text":"警吏率市民等重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00787","html":"\u003cp class=\"epub-calibre1\">西西涅斯 过来，民众。\u003c/p>\n","text":"西西涅斯 过来，民众。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00788","html":"\u003cp class=\"epub-calibre1\">警吏 听你们的护民官说话；肃静！\u003c/p>\n","text":"警吏 听你们的护民官说话；肃静！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00789","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 先听我说几句话。\u003c/p>\n","text":"科利奥兰纳斯 先听我说几句话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00790","html":"\u003cp class=\"epub-calibre1\">西西涅斯 勃鲁托斯 好，说吧。喂，静下来！\u003c/p>\n","text":"西西涅斯 勃鲁托斯 好，说吧。喂，静下来！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00791","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你们就在此刻宣布我的罪状吗？一切必须在这儿决定吗？\u003c/p>\n","text":"科利奥兰纳斯 你们就在此刻宣布我的罪状吗？一切必须在这儿决定吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00792","html":"\u003cp class=\"epub-calibre1\">西西涅斯 我要请你答复，你是不是愿意服从人民的公意，承认他们的官吏的权力，当你的罪案成立以后，甘心接受合法的制裁？\u003c/p>\n","text":"西西涅斯 我要请你答复，你是不是愿意服从人民的公意，承认他们的官吏的权力，当你的罪案成立以后，甘心接受合法的制裁？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00793","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我愿意。\u003c/p>\n","text":"科利奥兰纳斯 我愿意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00794","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 听着！各位市民，他说他愿意。想一想，他立过多少战功；想一想他身上的伤痕，就像墓地上的坟茔一样多。\u003c/p>\n","text":"米尼涅斯 听着！各位市民，他说他愿意。想一想，他立过多少战功；想一想他身上的伤痕，就像墓地上的坟茔一样多。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00795","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 那些不过是荆棘抓破的伤痕，这点点的创痏，也不过供人一笑罢了。\u003c/p>\n","text":"科利奥兰纳斯 那些不过是荆棘抓破的伤痕，这点点的创痏，也不过供人一笑罢了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00796","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 再想一想，他说的话虽然不合一个市民的身份，可是却不失为军人的谈吐；不要把他粗暴的口气认为恶意的言辞，那正是他的军人本色，不是对你们的敌视。\u003c/p>\n","text":"米尼涅斯 再想一想，他说的话虽然不合一个市民的身份，可是却不失为军人的谈吐；不要把他粗暴的口气认为恶意的言辞，那正是他的军人本色，不是对你们的敌视。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00797","html":"\u003cp class=\"epub-calibre1\">考密涅斯 好，好，别说了。\u003c/p>\n","text":"考密涅斯 好，好，别说了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00798","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 为了什么原因，我已经得到全体同意当选执政以后，你们又立刻撤销原议，给我这样的羞辱？\u003c/p>\n","text":"科利奥兰纳斯 为了什么原因，我已经得到全体同意当选执政以后，你们又立刻撤销原议，给我这样的羞辱？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00799","html":"\u003cp class=\"epub-calibre1\">西西涅斯 回答我们。\u003c/p>\n","text":"西西涅斯 回答我们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00800","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 好，说吧；我是应该回答你们的。\u003c/p>\n","text":"科利奥兰纳斯 好，说吧；我是应该回答你们的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00801","html":"\u003cp class=\"epub-calibre1\">西西涅斯 你企图推翻一切罗马相传已久的政制，造成个人专权独裁的地位，所以我们宣布你是人民的叛徒。\u003c/p>\n","text":"西西涅斯 你企图推翻一切罗马相传已久的政制，造成个人专权独裁的地位，所以我们宣布你是人民的叛徒。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00802","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 怎么！叛徒！\u003c/p>\n","text":"科利奥兰纳斯 怎么！叛徒！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00803","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 不，温和点儿，你答应过的。\u003c/p>\n","text":"米尼涅斯 不，温和点儿，你答应过的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00804","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 地狱底层的烈火把这些人民吞了去！说我是他们的叛徒！你这害人的护民官！在你的眼睛里藏着两万个死亡，在你的两手中握着两千万种杀人的毒计，在你说谎的舌头上含着无数杀人的阴谋，我要用向神明祈祷一样坦白的声音，向你说，“你说谎！”\u003c/p>\n","text":"科利奥兰纳斯 地狱底层的烈火把这些人民吞了去！说我是他们的叛徒！你这害人的护民官！在你的眼睛里藏着两万个死亡，在你的两手中握着两千万种杀人的毒计，在你说谎的舌头上含着无数杀人的阴谋，我要用向神明祈祷一样坦白的声音，向你说，“你说谎！”\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00805","html":"\u003cp class=\"epub-calibre1\">西西涅斯 民众，你们听见他的话吗？\u003c/p>\n","text":"西西涅斯 民众，你们听见他的话吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00806","html":"\u003cp class=\"epub-calibre1\">众市民 把他送到山岩上去！把他送到山岩上去！\u003c/p>\n","text":"众市民 把他送到山岩上去！把他送到山岩上去！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00807","html":"\u003cp class=\"epub-calibre1\">西西涅斯 静！我们不必再把新的罪名加在他的身上；你们亲眼看见他所做的事，亲耳听见他所说的话：殴打你们的官吏，辱骂你们自己，用暴力抗拒法律，现在他又公然藐视那些凭着他们的权力审判他的人，像这样罪大恶极的行为，已经应处最严重的死刑了。\u003c/p>\n","text":"西西涅斯 静！我们不必再把新的罪名加在他的身上；你们亲眼看见他所做的事，亲耳听见他所说的话：殴打你们的官吏，辱骂你们自己，用暴力抗拒法律，现在他又公然藐视那些凭着他们的权力审判他的人，像这样罪大恶极的行为，已经应处最严重的死刑了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00808","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 可是他既然为罗马立过功劳——\u003c/p>\n","text":"勃鲁托斯 可是他既然为罗马立过功劳——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00809","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你们还要讲什么功劳？\u003c/p>\n","text":"科利奥兰纳斯 你们还要讲什么功劳？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00810","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 我提起这一点，因为我知道你的功劳。\u003c/p>\n","text":"勃鲁托斯 我提起这一点，因为我知道你的功劳。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00811","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你！\u003c/p>\n","text":"科利奥兰纳斯 你！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00812","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 你怎样答应你的母亲的？\u003c/p>\n","text":"米尼涅斯 你怎样答应你的母亲的？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00813","html":"\u003cp class=\"epub-calibre1\">考密涅斯 你要知道——\u003c/p>\n","text":"考密涅斯 你要知道——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00814","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我不要知道什么。让他们宣判把我投身在高峻的大帕岩下，放逐，鞭打，每天给我吃一粒谷监禁起来，我也不愿用一句好话的代价购买他们的慈悲，更不愿为了乞讨他们的布施而抑制我的雄心，向他们道一声早安。\u003c/p>\n","text":"科利奥兰纳斯 我不要知道什么。让他们宣判把我投身在高峻的大帕岩下，放逐，鞭打，每天给我吃一粒谷监禁起来，我也不愿用一句好话的代价购买他们的慈悲，更不愿为了乞讨他们的布施而抑制我的雄心，向他们道一声早安。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00815","html":"\u003cp class=\"epub-calibre1\">西西涅斯 因为他不但在思想上，而且在行动上不断敌对人民，企图剥夺他们的权力，到现在他居然擅敢在尊严的法律和执法的官吏之前，行使暴力反抗的手段，所以我们用人民的名义，秉着我们护民官的职权，宣布从即时起，把他放逐出我们的城市，要是以后他再进入罗马境内，就要把他投身在大帕岩下。用人民的名义，我说，这判决必须实行。\u003c/p>\n","text":"西西涅斯 因为他不但在思想上，而且在行动上不断敌对人民，企图剥夺他们的权力，到现在他居然擅敢在尊严的法律和执法的官吏之前，行使暴力反抗的手段，所以我们用人民的名义，秉着我们护民官的职权，宣布从即时起，把他放逐出我们的城市，要是以后他再进入罗马境内，就要把他投身在大帕岩下。用人民的名义，我说，这判决必须实行。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00816","html":"\u003cp class=\"epub-calibre1\">众市民 这判决必须实行——这判决必须实行——把他赶出去！——把他放逐出境！\u003c/p>\n","text":"众市民 这判决必须实行——这判决必须实行——把他赶出去！——把他放逐出境！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00817","html":"\u003cp class=\"epub-calibre1\">考密涅斯 听我说，各位人民大众——\u003c/p>\n","text":"考密涅斯 听我说，各位人民大众——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00818","html":"\u003cp class=\"epub-calibre1\">西西涅斯 他已经受到判决；没有什么说的了。\u003c/p>\n","text":"西西涅斯 他已经受到判决；没有什么说的了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00819","html":"\u003cp class=\"epub-calibre1\">考密涅斯 让我说句话。我自己也曾当过执政；我可以向罗马公开展示她的敌人加在我身上的伤痕；我重视祖国的利益，甚于自己的生命和我所珍爱的儿女；要是我说——\u003c/p>\n","text":"考密涅斯 让我说句话。我自己也曾当过执政；我可以向罗马公开展示她的敌人加在我身上的伤痕；我重视祖国的利益，甚于自己的生命和我所珍爱的儿女；要是我说——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00820","html":"\u003cp class=\"epub-calibre1\">西西涅斯 我们知道你的意思；说什么？\u003c/p>\n","text":"西西涅斯 我们知道你的意思；说什么？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00821","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 不必多说，他已经被当作人民和祖国的敌人而放逐了；这判决必须实行。\u003c/p>\n","text":"勃鲁托斯 不必多说，他已经被当作人民和祖国的敌人而放逐了；这判决必须实行。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00822","html":"\u003cp class=\"epub-calibre1\">众市民 这判决必须实行——这判决必须实行。\u003c/p>\n","text":"众市民 这判决必须实行——这判决必须实行。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00823","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你们这些狂吠的贱狗！我痛恨你们的气息，就像痛恨恶臭的沼泽的臭味一样；我轻视你们的好感，就像厌恶腐烂的露骨的尸骸一样。我驱逐了你们；让你们和你们那游移无定的性格永远留在这里吧！让每一句轻微的谣言震动你们的心，你们敌人帽上羽毛的摇闪，就会把你们搧进绝望的深渊！永远保留着把你们的保卫者放逐出境的权力吧，直到最后让你们自己的愚昧觉得人家已经不费一刀一枪，使你们成为最微贱的俘虏！对于你们，对于这一个城市，我只有蔑视；我这样离开你们，这世界上什么地方没有我的安身之处。\u003cb class=\"epub-calibre3\">（科利奥兰纳斯、考密涅斯、米尼涅斯、元老、贵族等同下。）\u003c/b>\u003c/p>\n","text":"科利奥兰纳斯 你们这些狂吠的贱狗！我痛恨你们的气息，就像痛恨恶臭的沼泽的臭味一样；我轻视你们的好感，就像厌恶腐烂的露骨的尸骸一样。我驱逐了你们；让你们和你们那游移无定的性格永远留在这里吧！让每一句轻微的谣言震动你们的心，你们敌人帽上羽毛的摇闪，就会把你们搧进绝望的深渊！永远保留着把你们的保卫者放逐出境的权力吧，直到最后让你们自己的愚昧觉得人家已经不费一刀一枪，使你们成为最微贱的俘虏！对于你们，对于这一个城市，我只有蔑视；我这样离开你们，这世界上什么地方没有我的安身之处。（科利奥兰纳斯、考密涅斯、米尼涅斯、元老、贵族等同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00824","html":"\u003cp class=\"epub-calibre1\">警吏 人民的仇敌已经去了，已经去了！\u003c/p>\n","text":"警吏 人民的仇敌已经去了，已经去了！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00825","html":"\u003cp class=\"epub-calibre1\">众市民 我们的敌人已经被放逐了！——他去了！——呵！呵！\u003cb class=\"epub-calibre3\">（众欢呼，掷帽。）\u003c/b>\u003c/p>\n","text":"众市民 我们的敌人已经被放逐了！——他去了！——呵！呵！（众欢呼，掷帽。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00826","html":"\u003cp class=\"epub-calibre1\">西西涅斯 去，把他赶出城门，像他从前驱逐你们一样驱逐他，尽量发泄你们的愤怒，让他也难堪难堪。让一队卫士卫护我们通过全城。\u003c/p>\n","text":"西西涅斯 去，把他赶出城门，像他从前驱逐你们一样驱逐他，尽量发泄你们的愤怒，让他也难堪难堪。让一队卫士卫护我们通过全城。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00827","html":"\u003cp class=\"epub-calibre1\">众市民 来，来——让我们把他赶出城门！来！神明保佑我们尊贵的护民官！来！\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"众市民 来，来——让我们把他赶出城门！来！神明保佑我们尊贵的护民官！来！（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第三场 同前。大市场","headingLevel":4,"sourceAnchor":"a740","actNumber":3,"sceneNumber":3},{"id":"part0031-section-020","label":"第四幕","kind":"act","blocks":[{"id":"part0031-00828","html":"\u003ch3 id=\"epub-part0031-a741\" class=\"epub-calibre11\">第四幕\u003c/h3>\n","text":"第四幕\n","sourceAnchor":"a741","tag":"h3"}],"heading":"第四幕","headingLevel":3,"sourceAnchor":"a741","actNumber":4},{"id":"part0031-section-021","label":"第四幕 · 第一场 罗马。城门前","kind":"scene","blocks":[{"id":"part0031-00829","html":"\u003ch4 id=\"epub-part0031-a742\" class=\"epub-calibre12\">第一场 罗马。城门前\u003c/h4>\n","text":"第一场 罗马。城门前\n","sourceAnchor":"a742","tag":"h4"},{"id":"part0031-00830","html":"\u003cp class=\"epub-block1\">科利奥兰纳斯、伏伦妮娅、维吉利娅、米尼涅斯、考密涅斯及若干青年贵族上。\u003c/p>\n","text":"科利奥兰纳斯、伏伦妮娅、维吉利娅、米尼涅斯、考密涅斯及若干青年贵族上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00831","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 算了，别哭了，就这样分手吧；那多头的畜生把我撞走了。哎，母亲，您从前的勇气呢？您常常说，患难可以试验一个人的品格；非常的境遇方才可以显出非常的气节；风平浪静的海面，所有的船只都可以并驱竞胜；命运的铁拳击中要害的时候，只有大勇大智的人才能够处之泰然：您常常用那些格言教训我，锻炼我的坚强不屈的志气。\u003c/p>\n","text":"科利奥兰纳斯 算了，别哭了，就这样分手吧；那多头的畜生把我撞走了。哎，母亲，您从前的勇气呢？您常常说，患难可以试验一个人的品格；非常的境遇方才可以显出非常的气节；风平浪静的海面，所有的船只都可以并驱竞胜；命运的铁拳击中要害的时候，只有大勇大智的人才能够处之泰然：您常常用那些格言教训我，锻炼我的坚强不屈的志气。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00832","html":"\u003cp class=\"epub-calibre1\">维吉利娅 天啊！天啊！\u003c/p>\n","text":"维吉利娅 天啊！天啊！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00833","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 不，妇人，请你——\u003c/p>\n","text":"科利奥兰纳斯 不，妇人，请你——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00834","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 愿赤色的瘟疫降临在罗马各色人民的身上，使百工商贾同归于尽！\u003c/p>\n","text":"伏伦妮娅 愿赤色的瘟疫降临在罗马各色人民的身上，使百工商贾同归于尽！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00835","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 怎么，怎么，怎么！当我离开他们以后，他们将会追念我的好处。不，母亲，您从前不是常常说，要是您做了赫剌克勒斯的妻子，您一定会替他完成六件艰巨的工作，减轻他一半的劳力吗？请您仍旧保持这一种精神吧。考密涅斯，不要懊丧；再会！再会，我的妻子！我的母亲！我一定还要干一番事业。你年老而忠心的米尼涅斯，你的眼泪比年轻人的眼泪更辛酸，它会伤害你的眼睛的。我的旧日的主帅，我曾经瞻仰过您那刚强坚毅的气概，您也看见过不少可以使人心肠变硬的景象，请您告诉这两个伤心的妇人，为了不可避免的打击而悲痛，是一件多么痴愚的事情。我的母亲，您知道您一向把我的冒险作为您的安慰，请您相信我，虽然我像一条孤独的龙一样离此而去，可是我将要使人们在谈起我的沼泽的时候，就会瞿然变色；您的儿子除非误中奸谋，一定会有吐气扬眉的一天。\u003c/p>\n","text":"科利奥兰纳斯 怎么，怎么，怎么！当我离开他们以后，他们将会追念我的好处。不，母亲，您从前不是常常说，要是您做了赫剌克勒斯的妻子，您一定会替他完成六件艰巨的工作，减轻他一半的劳力吗？请您仍旧保持这一种精神吧。考密涅斯，不要懊丧；再会！再会，我的妻子！我的母亲！我一定还要干一番事业。你年老而忠心的米尼涅斯，你的眼泪比年轻人的眼泪更辛酸，它会伤害你的眼睛的。我的旧日的主帅，我曾经瞻仰过您那刚强坚毅的气概，您也看见过不少可以使人心肠变硬的景象，请您告诉这两个伤心的妇人，为了不可避免的打击而悲痛，是一件多么痴愚的事情。我的母亲，您知道您一向把我的冒险作为您的安慰，请您相信我，虽然我像一条孤独的龙一样离此而去，可是我将要使人们在谈起我的沼泽的时候，就会瞿然变色；您的儿子除非误中奸谋，一定会有吐气扬眉的一天。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00836","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 我的长子，你要到哪儿去呢？让考密涅斯陪你走一程吧；跟他商量一个妥当的方策，不要盲冲瞎撞，去试探前途的危险。\u003c/p>\n","text":"伏伦妮娅 我的长子，你要到哪儿去呢？让考密涅斯陪你走一程吧；跟他商量一个妥当的方策，不要盲冲瞎撞，去试探前途的危险。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00837","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 天神啊！\u003c/p>\n","text":"科利奥兰纳斯 天神啊！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00838","html":"\u003cp class=\"epub-calibre1\">考密涅斯 我愿意陪着你走一个月，跟你决定一个安身的地方，好让我们彼此互通声息；要是有机会可以设法召你回来的话，我们也可以不致于在茫茫的世界上到处找寻一个莫明踪迹的人，万一事过境迁，大好的机会又要蹉跎过去了。\u003c/p>\n","text":"考密涅斯 我愿意陪着你走一个月，跟你决定一个安身的地方，好让我们彼此互通声息；要是有机会可以设法召你回来的话，我们也可以不致于在茫茫的世界上到处找寻一个莫明踪迹的人，万一事过境迁，大好的机会又要蹉跎过去了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00839","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 再会吧；你已经有一把的年纪，饱受战争的辛苦，不要再跟一个筋骨壮健的人去跋涉风霜了。我只要请你送我出城门。来，我亲爱的妻子，我最亲爱的母亲，我的情深义厚的朋友们，当我出去的时候，请你们用微笑向我道别。请你们来吧。只要我尚在人世，你们一定会听到我的消息；而且你们所听到的，一定还是跟我原来的为人一样。\u003c/p>\n","text":"科利奥兰纳斯 再会吧；你已经有一把的年纪，饱受战争的辛苦，不要再跟一个筋骨壮健的人去跋涉风霜了。我只要请你送我出城门。来，我亲爱的妻子，我最亲爱的母亲，我的情深义厚的朋友们，当我出去的时候，请你们用微笑向我道别。请你们来吧。只要我尚在人世，你们一定会听到我的消息；而且你们所听到的，一定还是跟我原来的为人一样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00840","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 那正是每一个人所乐意听见的。来，我们不用哭泣。要是我能够从我衰老的臂腿上减去七岁年纪，凭着善良的神明发誓，我一定要寸步不离地跟着你。\u003c/p>\n","text":"米尼涅斯 那正是每一个人所乐意听见的。来，我们不用哭泣。要是我能够从我衰老的臂腿上减去七岁年纪，凭着善良的神明发誓，我一定要寸步不离地跟着你。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00841","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 把你的手给我。来。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"科利奥兰纳斯 把你的手给我。来。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第一场 罗马。城门前","headingLevel":4,"sourceAnchor":"a742","actNumber":4,"sceneNumber":1},{"id":"part0031-section-022","label":"第四幕 · 第二场 同前。城门附近的街道","kind":"scene","blocks":[{"id":"part0031-00842","html":"\u003ch4 id=\"epub-part0031-a743\" class=\"epub-calibre12\">第二场 同前。城门附近的街道\u003c/h4>\n","text":"第二场 同前。城门附近的街道\n","sourceAnchor":"a743","tag":"h4"},{"id":"part0031-00843","html":"\u003cp class=\"epub-block1\">西西涅斯、勃鲁托斯及一警吏上。\u003c/p>\n","text":"西西涅斯、勃鲁托斯及一警吏上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00844","html":"\u003cp class=\"epub-calibre1\">西西涅斯 叫他们大家回家去；他已经去了，我们也不必追他。贵族们很不高兴，他们都是袒护他的。\u003c/p>\n","text":"西西涅斯 叫他们大家回家去；他已经去了，我们也不必追他。贵族们很不高兴，他们都是袒护他的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00845","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 现在我们已经表现出我们的力量，事情既已了结，我们不妨在言辞之间装得谦恭一点。\u003c/p>\n","text":"勃鲁托斯 现在我们已经表现出我们的力量，事情既已了结，我们不妨在言辞之间装得谦恭一点。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00846","html":"\u003cp class=\"epub-calibre1\">西西涅斯 叫他们回家去；说他们重要的敌人已经去了，他们已经恢复了往日的力量。\u003c/p>\n","text":"西西涅斯 叫他们回家去；说他们重要的敌人已经去了，他们已经恢复了往日的力量。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00847","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 打发他们各人回家。\u003cb class=\"epub-calibre3\">（警吏下。）\u003c/b>\u003c/p>\n","text":"勃鲁托斯 打发他们各人回家。（警吏下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00848","html":"\u003cp class=\"epub-block1\">伏伦妮娅、维吉利娅及米尼涅斯上。\u003c/p>\n","text":"伏伦妮娅、维吉利娅及米尼涅斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00849","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 他的母亲来了。\u003c/p>\n","text":"勃鲁托斯 他的母亲来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00850","html":"\u003cp class=\"epub-calibre1\">西西涅斯 让我们避开她。\u003c/p>\n","text":"西西涅斯 让我们避开她。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00851","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 为什么？\u003c/p>\n","text":"勃鲁托斯 为什么？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00852","html":"\u003cp class=\"epub-calibre1\">西西涅斯 他们说她发了疯了。\u003c/p>\n","text":"西西涅斯 他们说她发了疯了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00853","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 她们已经看见我们；您尽管走吧。\u003c/p>\n","text":"勃鲁托斯 她们已经看见我们；您尽管走吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00854","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 啊！你们来得正好。愿神明把所有的灾祸降在你们身上，报答你们的好意！\u003c/p>\n","text":"伏伦妮娅 啊！你们来得正好。愿神明把所有的灾祸降在你们身上，报答你们的好意！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00855","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 静些，静些！不要这样高声嚷叫。\u003c/p>\n","text":"米尼涅斯 静些，静些！不要这样高声嚷叫。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00856","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 我倘不是哭不成声，一定要让你们听听——不，我要嚷给你们听听。\u003cb class=\"epub-calibre3\">（向勃鲁托斯）\u003c/b>你想逃走吗？\u003c/p>\n","text":"伏伦妮娅 我倘不是哭不成声，一定要让你们听听——不，我要嚷给你们听听。（向勃鲁托斯）你想逃走吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00857","html":"\u003cp class=\"epub-calibre1\">维吉利娅 \u003cb class=\"epub-calibre3\">（向西西涅斯）\u003c/b>你也别走。我希望我能够向我的丈夫说这样的话。\u003c/p>\n","text":"维吉利娅 （向西西涅斯）你也别走。我希望我能够向我的丈夫说这样的话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00858","html":"\u003cp class=\"epub-calibre1\">西西涅斯 你们是男人吗？\u003c/p>\n","text":"西西涅斯 你们是男人吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00859","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 是的，傻瓜；那是丢脸的事吗？听这傻瓜说的话。我的父亲不是一个男人吗？你果然有这样狐狸般的狡狯，会把一个替罗马立过多少汗马功劳的人放逐出去吗？\u003c/p>\n","text":"伏伦妮娅 是的，傻瓜；那是丢脸的事吗？听这傻瓜说的话。我的父亲不是一个男人吗？你果然有这样狐狸般的狡狯，会把一个替罗马立过多少汗马功劳的人放逐出去吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00860","html":"\u003cp class=\"epub-calibre1\">西西涅斯 哎哟，苍天在上！\u003c/p>\n","text":"西西涅斯 哎哟，苍天在上！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00861","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 为了罗马的利益，他挥舞他的英勇的剑锋，那次数比你说过的聪明话还要多。让我告诉你；可是你去吧；不，你给我站住：我但愿我的儿子在阿拉伯，你和你那一族里的人都跪在他的面前，他手里举起宝剑——\u003c/p>\n","text":"伏伦妮娅 为了罗马的利益，他挥舞他的英勇的剑锋，那次数比你说过的聪明话还要多。让我告诉你；可是你去吧；不，你给我站住：我但愿我的儿子在阿拉伯，你和你那一族里的人都跪在他的面前，他手里举起宝剑——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00862","html":"\u003cp class=\"epub-calibre1\">西西涅斯 那又怎么样呢？\u003c/p>\n","text":"西西涅斯 那又怎么样呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00863","html":"\u003cp class=\"epub-calibre1\">维吉利娅 那又怎么样！他要斩草除根，不留下一个孽种在世上。\u003c/p>\n","text":"维吉利娅 那又怎么样！他要斩草除根，不留下一个孽种在世上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00864","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 全都是些杂种私生子！好人，他为了罗马受过多少伤！\u003c/p>\n","text":"伏伦妮娅 全都是些杂种私生子！好人，他为了罗马受过多少伤！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00865","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 来，来，别闹了。\u003c/p>\n","text":"米尼涅斯 来，来，别闹了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00866","html":"\u003cp class=\"epub-calibre1\">西西涅斯 要是他能够贯彻为国献身的初衷，不把自己辛苦换来的光荣亲手撕毁，那就好了！\u003c/p>\n","text":"西西涅斯 要是他能够贯彻为国献身的初衷，不把自己辛苦换来的光荣亲手撕毁，那就好了！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00867","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 我也希望他这样。\u003c/p>\n","text":"勃鲁托斯 我也希望他这样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00868","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 “我也希望他这样”！都是你们煽动这些乱民，猫狗般的畜生，他们不能认识他的价值，正像我不能了解上天不让世间知道的神秘一样。\u003c/p>\n","text":"伏伦妮娅 “我也希望他这样”！都是你们煽动这些乱民，猫狗般的畜生，他们不能认识他的价值，正像我不能了解上天不让世间知道的神秘一样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00869","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 请你让我们走吧。\u003c/p>\n","text":"勃鲁托斯 请你让我们走吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00870","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 现在，先生，请你给我滚吧。你们已经干了一件了不得的好事。在你们未走之前，再听我说一句话：正像朱庇特的神庙不能和罗马最卑陋的一间屋子相比一样，被你们放逐出去的我的儿子——这位夫人的丈夫，就是他，你们明白了没有？——比起你们这些东西来，真是天壤之别。\u003c/p>\n","text":"伏伦妮娅 现在，先生，请你给我滚吧。你们已经干了一件了不得的好事。在你们未走之前，再听我说一句话：正像朱庇特的神庙不能和罗马最卑陋的一间屋子相比一样，被你们放逐出去的我的儿子——这位夫人的丈夫，就是他，你们明白了没有？——比起你们这些东西来，真是天壤之别。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00871","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 好，好，我们少陪啦。\u003c/p>\n","text":"勃鲁托斯 好，好，我们少陪啦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00872","html":"\u003cp class=\"epub-calibre1\">西西涅斯 为什么我们要呆在这儿，给一个疯婆子缠个不休？\u003c/p>\n","text":"西西涅斯 为什么我们要呆在这儿，给一个疯婆子缠个不休？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00873","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 把我的祈祷带了去吧。\u003cb class=\"epub-calibre3\">（二护民官下）\u003c/b>我但愿天神们什么事也不做，只替我实现我的咒诅！要是我能够每天遇见他们一次，那么我心头的悲哀也许可以倾吐一空。\u003c/p>\n","text":"伏伦妮娅 把我的祈祷带了去吧。（二护民官下）我但愿天神们什么事也不做，只替我实现我的咒诅！要是我能够每天遇见他们一次，那么我心头的悲哀也许可以倾吐一空。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00874","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 您已经骂得他们很痛快；凭良心说，您没有冤屈他们。你们愿意赏光到舍间吃晚饭吗？\u003c/p>\n","text":"米尼涅斯 您已经骂得他们很痛快；凭良心说，您没有冤屈他们。你们愿意赏光到舍间吃晚饭吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00875","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 愤怒是我的食物；我一肚子都是气恼，吃不下东西了。来，我们走吧。不要这样呜呜咽咽地哭个不停，瞧着我的样子，我们在愤怒的时候，应当保持天后般的尊严。来，来，来。\u003c/p>\n","text":"伏伦妮娅 愤怒是我的食物；我一肚子都是气恼，吃不下东西了。来，我们走吧。不要这样呜呜咽咽地哭个不停，瞧着我的样子，我们在愤怒的时候，应当保持天后般的尊严。来，来，来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00876","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 唉，唉，唉！\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"米尼涅斯 唉，唉，唉！（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第二场 同前。城门附近的街道","headingLevel":4,"sourceAnchor":"a743","actNumber":4,"sceneNumber":2},{"id":"part0031-section-023","label":"第四幕 · 第三场 罗马安息间的大路","kind":"scene","blocks":[{"id":"part0031-00877","html":"\u003ch4 id=\"epub-part0031-a744\" class=\"epub-calibre12\">第三场 罗马安息间的大路\u003c/h4>\n","text":"第三场 罗马安息间的大路\n","sourceAnchor":"a744","tag":"h4"},{"id":"part0031-00878","html":"\u003cp class=\"epub-block1\">一罗马人及一伏尔斯人上，相遇。\u003c/p>\n","text":"一罗马人及一伏尔斯人上，相遇。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00879","html":"\u003cp class=\"epub-calibre1\">罗马人 先生，我认识您，您也认识我；您的大名我想是阿德里安。\u003c/p>\n","text":"罗马人 先生，我认识您，您也认识我；您的大名我想是阿德里安。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00880","html":"\u003cp class=\"epub-calibre1\">伏尔斯人 正是，先生。不瞒您说，我可忘记您了。\u003c/p>\n","text":"伏尔斯人 正是，先生。不瞒您说，我可忘记您了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00881","html":"\u003cp class=\"epub-calibre1\">罗马人 我是个罗马人；可是我所干的事，却跟您一样，是跟罗马人作对的。您现在认识我了吗？\u003c/p>\n","text":"罗马人 我是个罗马人；可是我所干的事，却跟您一样，是跟罗马人作对的。您现在认识我了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00882","html":"\u003cp class=\"epub-calibre1\">伏尔斯人 尼凯诺吗？不是。\u003c/p>\n","text":"伏尔斯人 尼凯诺吗？不是。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00883","html":"\u003cp class=\"epub-calibre1\">罗马人 正是，先生。\u003c/p>\n","text":"罗马人 正是，先生。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00884","html":"\u003cp class=\"epub-calibre1\">伏尔斯人 我上次看见您的时候，您的胡子比现在多一点；可是您的声音可以证明您的确是他。罗马有什么消息？我得到了伏尔斯政府的命令，叫我到罗马去找您；您现在省了我一天的路程了。\u003c/p>\n","text":"伏尔斯人 我上次看见您的时候，您的胡子比现在多一点；可是您的声音可以证明您的确是他。罗马有什么消息？我得到了伏尔斯政府的命令，叫我到罗马去找您；您现在省了我一天的路程了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00885","html":"\u003cp class=\"epub-calibre1\">罗马人 罗马曾经发生惊人的叛变；人民跟元老贵族们作对。\u003c/p>\n","text":"罗马人 罗马曾经发生惊人的叛变；人民跟元老贵族们作对。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00886","html":"\u003cp class=\"epub-calibre1\">伏尔斯人 曾经发生！那么现在已经解决了吗？我们的政府却不这样想；他们正在积极准备用兵，想要趁他们争执得十分激烈的时候向他们突袭。\u003c/p>\n","text":"伏尔斯人 曾经发生！那么现在已经解决了吗？我们的政府却不这样想；他们正在积极准备用兵，想要趁他们争执得十分激烈的时候向他们突袭。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00887","html":"\u003cp class=\"epub-calibre1\">罗马人 火焰大体已经熄灭，可是一件微细的琐事就可以使它重新燃烧起来。因为那些贵族们对于放逐科利奥兰纳斯这件事感到非常痛心，一有机会，就准备剥夺人民的一切权力，把那些护民官永远罢免。我可以告诉你，未灭的余烬正在那儿吐出熊熊的火焰，猛烈爆发的时期已经不远了。\u003c/p>\n","text":"罗马人 火焰大体已经熄灭，可是一件微细的琐事就可以使它重新燃烧起来。因为那些贵族们对于放逐科利奥兰纳斯这件事感到非常痛心，一有机会，就准备剥夺人民的一切权力，把那些护民官永远罢免。我可以告诉你，未灭的余烬正在那儿吐出熊熊的火焰，猛烈爆发的时期已经不远了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00888","html":"\u003cp class=\"epub-calibre1\">伏尔斯人 科利奥兰纳斯被放逐了！\u003c/p>\n","text":"伏尔斯人 科利奥兰纳斯被放逐了！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00889","html":"\u003cp class=\"epub-calibre1\">罗马人 被放逐了，先生。\u003c/p>\n","text":"罗马人 被放逐了，先生。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00890","html":"\u003cp class=\"epub-calibre1\">伏尔斯人 尼凯诺，您带了这一个消息去，他们一定十分欢迎。\u003c/p>\n","text":"伏尔斯人 尼凯诺，您带了这一个消息去，他们一定十分欢迎。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00891","html":"\u003cp class=\"epub-calibre1\">罗马人 他们现在的机会很好。人家说，诱奸有夫之妇，最好趁她和丈夫反目的时候下手。你们那位英勇的塔勒斯·奥菲狄乌斯这一下可以大逞威风了，因为他的最大的敌手科利奥兰纳斯已经被他的祖国摈斥了。\u003c/p>\n","text":"罗马人 他们现在的机会很好。人家说，诱奸有夫之妇，最好趁她和丈夫反目的时候下手。你们那位英勇的塔勒斯·奥菲狄乌斯这一下可以大逞威风了，因为他的最大的敌手科利奥兰纳斯已经被他的祖国摈斥了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00892","html":"\u003cp class=\"epub-calibre1\">伏尔斯人 这是不用说的。我很幸运今天凑巧碰见了您；现在我的任务已了，让我陪着您高高兴兴地回去吧。\u003c/p>\n","text":"伏尔斯人 这是不用说的。我很幸运今天凑巧碰见了您；现在我的任务已了，让我陪着您高高兴兴地回去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00893","html":"\u003cp class=\"epub-calibre1\">罗马人 我现在就可以开始把许多罗马的怪事讲给您听，一直讲到晚餐的时候为止；这些事情，都是对于他们的敌人有利的。您说你们已经有一支军队准备出发了吗？\u003c/p>\n","text":"罗马人 我现在就可以开始把许多罗马的怪事讲给您听，一直讲到晚餐的时候为止；这些事情，都是对于他们的敌人有利的。您说你们已经有一支军队准备出发了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00894","html":"\u003cp class=\"epub-calibre1\">伏尔斯人 一支很雄壮的军队；所有人马都已经征齐入伍，分派营舍，命令发出以后，一小时之内就可以出发。\u003c/p>\n","text":"伏尔斯人 一支很雄壮的军队；所有人马都已经征齐入伍，分派营舍，命令发出以后，一小时之内就可以出发。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00895","html":"\u003cp class=\"epub-calibre1\">罗马人 我很高兴听见他们已经准备好了；我想我去见了他们以后，就可以催促他们立刻举事。好，先生，今天能够碰见您，真是一件幸事，我很愿意做您的同行的伴侣。\u003c/p>\n","text":"罗马人 我很高兴听见他们已经准备好了；我想我去见了他们以后，就可以催促他们立刻举事。好，先生，今天能够碰见您，真是一件幸事，我很愿意做您的同行的伴侣。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00896","html":"\u003cp class=\"epub-calibre1\">伏尔斯人 您省了我一趟跋涉，先生；能够跟您一路同行，真是我的莫大的荣幸。\u003c/p>\n","text":"伏尔斯人 您省了我一趟跋涉，先生；能够跟您一路同行，真是我的莫大的荣幸。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00897","html":"\u003cp class=\"epub-calibre1\">罗马人 好，我们一块儿走吧。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"罗马人 好，我们一块儿走吧。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第三场 罗马安息间的大路","headingLevel":4,"sourceAnchor":"a744","actNumber":4,"sceneNumber":3},{"id":"part0031-section-024","label":"第四幕 · 第四场 安息。奥菲狄乌斯家门前","kind":"scene","blocks":[{"id":"part0031-00898","html":"\u003ch4 id=\"epub-part0031-a745\" class=\"epub-calibre12\">第四场 安息。奥菲狄乌斯家门前\u003c/h4>\n","text":"第四场 安息。奥菲狄乌斯家门前\n","sourceAnchor":"a745","tag":"h4"},{"id":"part0031-00899","html":"\u003cp class=\"epub-block1\">科利奥兰纳斯微服化装蒙面上。\u003c/p>\n","text":"科利奥兰纳斯微服化装蒙面上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00900","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 这安息倒是一个很好的城市。城啊，是我使你的妇女们成为寡妇；这些富丽大厦的后嗣，有许多人我曾经听见他们在我的战阵中间呻吟倒地。所以不要认识我，免得你的妇人们用唾涎唾我，你的小儿们投石子打我，使我在琐小的战争中间死去。\u003c/p>\n","text":"科利奥兰纳斯 这安息倒是一个很好的城市。城啊，是我使你的妇女们成为寡妇；这些富丽大厦的后嗣，有许多人我曾经听见他们在我的战阵中间呻吟倒地。所以不要认识我，免得你的妇人们用唾涎唾我，你的小儿们投石子打我，使我在琐小的战争中间死去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00901","html":"\u003cp class=\"epub-block1\">一市民上。\u003c/p>\n","text":"一市民上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00902","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 请了，先生。\u003c/p>\n","text":"科利奥兰纳斯 请了，先生。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00903","html":"\u003cp class=\"epub-calibre1\">市民 请了。\u003c/p>\n","text":"市民 请了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00904","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 请您指点我伟大的奥菲狄乌斯住在什么地方。他是在安息吗？\u003c/p>\n","text":"科利奥兰纳斯 请您指点我伟大的奥菲狄乌斯住在什么地方。他是在安息吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00905","html":"\u003cp class=\"epub-calibre1\">市民 是的，今天晚上他在家里宴请政府中的贵人。\u003c/p>\n","text":"市民 是的，今天晚上他在家里宴请政府中的贵人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00906","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 请问他的家在哪儿？\u003c/p>\n","text":"科利奥兰纳斯 请问他的家在哪儿？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00907","html":"\u003cp class=\"epub-calibre1\">市民 就是在您面前的这一所屋子。\u003c/p>\n","text":"市民 就是在您面前的这一所屋子。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00908","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 谢谢您，先生。再见。\u003cb class=\"epub-calibre3\">（市民下）\u003c/b>啊，变化无常的世事！刚才还是誓同生死的朋友。两个人的胸膛里好像只有一颗心，睡眠、饮食、工作、游戏，都是彼此相共，亲爱得分不开来，一转瞬之间，为了些微的争执，就会变成不共戴天的仇人。同样，切齿痛恨的仇敌，他们在梦寐之中也念念不忘地勾心斗角，互谋倾陷，为了一个偶然的机会，一些不足道的琐事，也会变成亲密的友人，彼此携手合作。我现在也正是这样：我痛恨我自己生长的地方，我的爱心已经移向了这个仇敌的城市。我要进去；要是他把我杀死，那也并不是有悖公道的行为；要是他对我曲意优容，那么我愿意为他的国家尽力。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"科利奥兰纳斯 谢谢您，先生。再见。（市民下）啊，变化无常的世事！刚才还是誓同生死的朋友。两个人的胸膛里好像只有一颗心，睡眠、饮食、工作、游戏，都是彼此相共，亲爱得分不开来，一转瞬之间，为了些微的争执，就会变成不共戴天的仇人。同样，切齿痛恨的仇敌，他们在梦寐之中也念念不忘地勾心斗角，互谋倾陷，为了一个偶然的机会，一些不足道的琐事，也会变成亲密的友人，彼此携手合作。我现在也正是这样：我痛恨我自己生长的地方，我的爱心已经移向了这个仇敌的城市。我要进去；要是他把我杀死，那也并不是有悖公道的行为；要是他对我曲意优容，那么我愿意为他的国家尽力。（下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第四场 安息。奥菲狄乌斯家门前","headingLevel":4,"sourceAnchor":"a745","actNumber":4,"sceneNumber":4},{"id":"part0031-section-025","label":"第四幕 · 第五场 同前。奥菲狄乌斯家中厅堂","kind":"scene","blocks":[{"id":"part0031-00909","html":"\u003ch4 id=\"epub-part0031-a746\" class=\"epub-calibre12\">第五场 同前。奥菲狄乌斯家中厅堂\u003c/h4>\n","text":"第五场 同前。奥菲狄乌斯家中厅堂\n","sourceAnchor":"a746","tag":"h4"},{"id":"part0031-00910","html":"\u003cp class=\"epub-block1\">内乐声；仆甲上。\u003c/p>\n","text":"内乐声；仆甲上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00911","html":"\u003cp class=\"epub-calibre1\">仆甲 酒，酒，酒！他们都在干些什么事！我想我们那些伙计们都睡着了。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"仆甲 酒，酒，酒！他们都在干些什么事！我想我们那些伙计们都睡着了。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00912","html":"\u003cp class=\"epub-block1\">仆乙上。\u003c/p>\n","text":"仆乙上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00913","html":"\u003cp class=\"epub-calibre1\">仆乙 戈得斯呢？主人在叫他。戈得斯！\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"仆乙 戈得斯呢？主人在叫他。戈得斯！（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00914","html":"\u003cp class=\"epub-block1\">科利奥兰纳斯上。\u003c/p>\n","text":"科利奥兰纳斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00915","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 好一间屋子；好香的酒肉味道！可是我却不像一个客人。\u003c/p>\n","text":"科利奥兰纳斯 好一间屋子；好香的酒肉味道！可是我却不像一个客人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00916","html":"\u003cp class=\"epub-block1\">仆甲重上。\u003c/p>\n","text":"仆甲重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00917","html":"\u003cp class=\"epub-calibre1\">仆甲 朋友，你要什么？你是哪儿来的？这儿没有你的地方；出去。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"仆甲 朋友，你要什么？你是哪儿来的？这儿没有你的地方；出去。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00918","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 因为我是科利奥兰纳斯，他们这样款待我是理所当然的。\u003c/p>\n","text":"科利奥兰纳斯 因为我是科利奥兰纳斯，他们这样款待我是理所当然的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00919","html":"\u003cp class=\"epub-block1\">仆乙重上。\u003c/p>\n","text":"仆乙重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00920","html":"\u003cp class=\"epub-calibre1\">仆乙 朋友，你是从什么地方来的？管门的难道不生眼睛，会放这种家伙进来吗？出去出去！\u003c/p>\n","text":"仆乙 朋友，你是从什么地方来的？管门的难道不生眼睛，会放这种家伙进来吗？出去出去！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00921","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 走开！\u003c/p>\n","text":"科利奥兰纳斯 走开！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00922","html":"\u003cp class=\"epub-calibre1\">仆乙 走开！你自己走开！\u003c/p>\n","text":"仆乙 走开！你自己走开！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00923","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你真讨厌。\u003c/p>\n","text":"科利奥兰纳斯 你真讨厌。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00924","html":"\u003cp class=\"epub-calibre1\">仆乙 你这样放肆吗？我就去叫人来跟你说话。\u003c/p>\n","text":"仆乙 你这样放肆吗？我就去叫人来跟你说话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00925","html":"\u003cp class=\"epub-block1\">仆丙上；仆甲重上。\u003c/p>\n","text":"仆丙上；仆甲重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00926","html":"\u003cp class=\"epub-calibre1\">仆丙 这家伙是什么人？\u003c/p>\n","text":"仆丙 这家伙是什么人？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00927","html":"\u003cp class=\"epub-calibre1\">仆甲 我从来没有见过这样古怪的家伙，我没有法子叫他出去。请你去叫主人出来。\u003c/p>\n","text":"仆甲 我从来没有见过这样古怪的家伙，我没有法子叫他出去。请你去叫主人出来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00928","html":"\u003cp class=\"epub-calibre1\">仆丙 朋友，你到这儿来干吗？谢谢你，快出去吧。\u003c/p>\n","text":"仆丙 朋友，你到这儿来干吗？谢谢你，快出去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00929","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 只要让我站在这儿；我不会弄坏你们的炉灶的。\u003c/p>\n","text":"科利奥兰纳斯 只要让我站在这儿；我不会弄坏你们的炉灶的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00930","html":"\u003cp class=\"epub-calibre1\">仆丙 你是什么人？\u003c/p>\n","text":"仆丙 你是什么人？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00931","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 一个绅士。\u003c/p>\n","text":"科利奥兰纳斯 一个绅士。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00932","html":"\u003cp class=\"epub-calibre1\">仆丙 一个穷得出奇的绅士。\u003c/p>\n","text":"仆丙 一个穷得出奇的绅士。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00933","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 正是，你说得不错。\u003c/p>\n","text":"科利奥兰纳斯 正是，你说得不错。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00934","html":"\u003cp class=\"epub-calibre1\">仆丙 谢谢你，穷绅士，到别处去吧；这儿没有你的地方。喂，滚出去。\u003c/p>\n","text":"仆丙 谢谢你，穷绅士，到别处去吧；这儿没有你的地方。喂，滚出去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00935","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你管你自己的事；去，吃你的残羹冷菜去。\u003cb class=\"epub-calibre3\">（将仆丙推开。）\u003c/b>\u003c/p>\n","text":"科利奥兰纳斯 你管你自己的事；去，吃你的残羹冷菜去。（将仆丙推开。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00936","html":"\u003cp class=\"epub-calibre1\">仆丙 怎么，你不肯去吗？请你去告诉主人，他有一个奇怪的客人在这儿。\u003c/p>\n","text":"仆丙 怎么，你不肯去吗？请你去告诉主人，他有一个奇怪的客人在这儿。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00937","html":"\u003cp class=\"epub-calibre1\">仆乙 好，我就去告诉他。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"仆乙 好，我就去告诉他。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00938","html":"\u003cp class=\"epub-calibre1\">仆丙 你住在什么地方？\u003c/p>\n","text":"仆丙 你住在什么地方？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00939","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 在苍天之下。\u003c/p>\n","text":"科利奥兰纳斯 在苍天之下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00940","html":"\u003cp class=\"epub-calibre1\">仆丙 在苍天之下！\u003c/p>\n","text":"仆丙 在苍天之下！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00941","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 是的。\u003c/p>\n","text":"科利奥兰纳斯 是的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00942","html":"\u003cp class=\"epub-calibre1\">仆丙 那是在什么地方？\u003c/p>\n","text":"仆丙 那是在什么地方？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00943","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 在鹞子和乌鸦的城里。\u003c/p>\n","text":"科利奥兰纳斯 在鹞子和乌鸦的城里。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00944","html":"\u003cp class=\"epub-calibre1\">仆丙 在鹞子和乌鸦的城里！这个蠢驴！那么你是和乌鸦住在一起的吗？\u003c/p>\n","text":"仆丙 在鹞子和乌鸦的城里！这个蠢驴！那么你是和乌鸦住在一起的吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00945","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 不；我并不侍候你的主人。\u003c/p>\n","text":"科利奥兰纳斯 不；我并不侍候你的主人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00946","html":"\u003cp class=\"epub-calibre1\">仆丙 怎么，你是来和我们老爷打交道的吗？\u003c/p>\n","text":"仆丙 怎么，你是来和我们老爷打交道的吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00947","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 嗯，反正不是跟你们太太打交道就是好事。别尽说废话了，到酒席上侍候去吧。\u003cb class=\"epub-calibre3\">（将仆丙打走。）\u003c/b>\u003c/p>\n","text":"科利奥兰纳斯 嗯，反正不是跟你们太太打交道就是好事。别尽说废话了，到酒席上侍候去吧。（将仆丙打走。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00948","html":"\u003cp class=\"epub-block1\">奥菲狄乌斯及仆乙上。\u003c/p>\n","text":"奥菲狄乌斯及仆乙上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00949","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 这家伙在什么地方？\u003c/p>\n","text":"奥菲狄乌斯 这家伙在什么地方？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00950","html":"\u003cp class=\"epub-calibre1\">仆乙 这儿，老爷。倘不是恐怕惊吵了里面的各位老爷，我早就把他当狗一样打得半死了。\u003c/p>\n","text":"仆乙 这儿，老爷。倘不是恐怕惊吵了里面的各位老爷，我早就把他当狗一样打得半死了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00951","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 你是从哪儿来的？你要什么？你叫什么名字？为什么不说话？说吧，朋友，你叫什么名字？\u003c/p>\n","text":"奥菲狄乌斯 你是从哪儿来的？你要什么？你叫什么名字？为什么不说话？说吧，朋友，你叫什么名字？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00952","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 \u003cb class=\"epub-calibre3\">（取下面巾）\u003c/b>塔勒斯，要是你还不认识我，看见了我的面，也想不到我是什么人，那么我必须自报姓名了。\u003c/p>\n","text":"科利奥兰纳斯 （取下面巾）塔勒斯，要是你还不认识我，看见了我的面，也想不到我是什么人，那么我必须自报姓名了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00953","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 你叫什么名字？\u003cb class=\"epub-calibre3\">（众仆退后。）\u003c/b>\u003c/p>\n","text":"奥菲狄乌斯 你叫什么名字？（众仆退后。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00954","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我的名字在伏尔斯人的耳中是不好听的，你听见了会觉得刺耳。\u003c/p>\n","text":"科利奥兰纳斯 我的名字在伏尔斯人的耳中是不好听的，你听见了会觉得刺耳。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00955","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 说，你叫什么名字？你有一副凌然不可侵犯的容貌，你的脸上有一种威严；虽然你的装束这样破旧，却不像是一个庸庸碌碌的人。你叫什么名字？\u003c/p>\n","text":"奥菲狄乌斯 说，你叫什么名字？你有一副凌然不可侵犯的容貌，你的脸上有一种威严；虽然你的装束这样破旧，却不像是一个庸庸碌碌的人。你叫什么名字？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00956","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 准备皱起你的眉头来吧。你还不认识我吗？\u003c/p>\n","text":"科利奥兰纳斯 准备皱起你的眉头来吧。你还不认识我吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00957","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 我不认识你。你的名字呢？\u003c/p>\n","text":"奥菲狄乌斯 我不认识你。你的名字呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00958","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我的名字是卡厄斯·马歇斯，我曾经把极大的伤害和灾祸加在你和一切伏尔斯人的身上；我的姓氏科利奥兰纳斯就是最好的证明。辛苦的战役、重大的危险、替我这负恩的国家所流过的血，结果只是换到了这一个空洞的姓氏，为你对我所怀的怨恨留下一个创巨痛深的记忆。只有这名字剩留着；残酷猜嫉的人民，得到了我们那些懦怯的贵族的默许，已经一致遗弃了我，抹煞了我一切的功绩，让那些奴才们把我轰出了罗马。这一种不幸的遭遇，使我今天来到你的家里；不要误会我，以为我想来向你求恩乞命，因为要是我怕死的话，我就应该远远地躲开你；我只是因为出于气愤，渴想报复那些放逐我的人，所以才到这儿来站在你的面前。要是你也有一颗复仇的心，想要替你自己和你的国家洗雪耻辱，现在就是你的机会到了，你正可以利用我的不幸，达到你自己的目的，因为我将要用地狱中一切饿鬼的怨毒，来向我的腐败的祖国作战。可是你要是没有这样的胆量，也不想追求远大的前程，那么一句话，我也已经厌倦人世，愿意伸直我的颈项，听任你的宰割，让你一泄这许多年来郁积在心头的怨恨；你要是不杀我，你就是个傻瓜，因为我一向是你的死敌，曾经从你祖国的胸前溅下了无数吨的血；要是让我活在世上，对于你永远是一个耻辱，除非你能够跟我合作。\u003c/p>\n","text":"科利奥兰纳斯 我的名字是卡厄斯·马歇斯，我曾经把极大的伤害和灾祸加在你和一切伏尔斯人的身上；我的姓氏科利奥兰纳斯就是最好的证明。辛苦的战役、重大的危险、替我这负恩的国家所流过的血，结果只是换到了这一个空洞的姓氏，为你对我所怀的怨恨留下一个创巨痛深的记忆。只有这名字剩留着；残酷猜嫉的人民，得到了我们那些懦怯的贵族的默许，已经一致遗弃了我，抹煞了我一切的功绩，让那些奴才们把我轰出了罗马。这一种不幸的遭遇，使我今天来到你的家里；不要误会我，以为我想来向你求恩乞命，因为要是我怕死的话，我就应该远远地躲开你；我只是因为出于气愤，渴想报复那些放逐我的人，所以才到这儿来站在你的面前。要是你也有一颗复仇的心，想要替你自己和你的国家洗雪耻辱，现在就是你的机会到了，你正可以利用我的不幸，达到你自己的目的，因为我将要用地狱中一切饿鬼的怨毒，来向我的腐败的祖国作战。可是你要是没有这样的胆量，也不想追求远大的前程，那么一句话，我也已经厌倦人世，愿意伸直我的颈项，听任你的宰割，让你一泄这许多年来郁积在心头的怨恨；你要是不杀我，你就是个傻瓜，因为我一向是你的死敌，曾经从你祖国的胸前溅下了无数吨的血；要是让我活在世上，对于你永远是一个耻辱，除非你能够跟我合作。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00959","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 啊，马歇斯，马歇斯！你所说的每一个字，已经从我心里薙除了旧日的怨恨，不再存留一些芥蒂。要是朱庇特从那边的云中宣示神圣的诏语，说，“这是真的，”我也不会相信他甚于相信你，高贵无比的马歇斯。让我用我的胳臂围住你的身体；我这样拥抱着我的剑砧，热烈而真诚地用我的友谊和你比赛，正像我过去雄心勃勃地和你比赛着勇力一样。我告诉你，我曾经热恋着我的妻子，为她发过无数挚情的叹息；可是我现在看见了你，你高贵的英雄！我的狂喜的心，比我第一次看见我的恋人成为我的新妇，跨进我的门槛的时候还要跳跃得厉害。嗨，战神，我对你说，我们已经有一支军队准备行动；我已经再度下了决心，一定要从你的胸前割下一块肉来，即使牺牲自己的一只胳臂，也是甘心的。你曾经打败我十二次，每天晚上我都做着和你交战的梦；在我的睡梦之中，我们常常一起倒在地上，争着解开彼此盔上的扣子，拳击着彼此的咽喉，等到梦醒以后，已经无缘无故地累得半死了。尊贵的马歇斯，即使我们和罗马毫无仇恨，只是因为你被他们放逐了出来，我们也会动员一切十二岁以上七十岁以下的男子，把战争的汹涌的洪流倾倒在罗马忘恩的心脏里。来啊！进去和我们那些善意的元老们握握手，他们现在正要向我告别；他们虽然还没有想到要把罗马吞并，可是已经准备向你们的领土进攻了。\u003c/p>\n","text":"奥菲狄乌斯 啊，马歇斯，马歇斯！你所说的每一个字，已经从我心里薙除了旧日的怨恨，不再存留一些芥蒂。要是朱庇特从那边的云中宣示神圣的诏语，说，“这是真的，”我也不会相信他甚于相信你，高贵无比的马歇斯。让我用我的胳臂围住你的身体；我这样拥抱着我的剑砧，热烈而真诚地用我的友谊和你比赛，正像我过去雄心勃勃地和你比赛着勇力一样。我告诉你，我曾经热恋着我的妻子，为她发过无数挚情的叹息；可是我现在看见了你，你高贵的英雄！我的狂喜的心，比我第一次看见我的恋人成为我的新妇，跨进我的门槛的时候还要跳跃得厉害。嗨，战神，我对你说，我们已经有一支军队准备行动；我已经再度下了决心，一定要从你的胸前割下一块肉来，即使牺牲自己的一只胳臂，也是甘心的。你曾经打败我十二次，每天晚上我都做着和你交战的梦；在我的睡梦之中，我们常常一起倒在地上，争着解开彼此盔上的扣子，拳击着彼此的咽喉，等到梦醒以后，已经无缘无故地累得半死了。尊贵的马歇斯，即使我们和罗马毫无仇恨，只是因为你被他们放逐了出来，我们也会动员一切十二岁以上七十岁以下的男子，把战争的汹涌的洪流倾倒在罗马忘恩的心脏里。来啊！进去和我们那些善意的元老们握握手，他们现在正要向我告别；他们虽然还没有想到要把罗马吞并，可是已经准备向你们的领土进攻了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00960","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 感谢神明！\u003c/p>\n","text":"科利奥兰纳斯 感谢神明！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00961","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 所以，沉鸷雄毅的将军，要是你愿意为报复自己的仇恨而做我们的前导，我可以分我的一半军力归你节制；你既然对于自己国中的虚实了如指掌，就可以凭着你自己的经验决定进军的方策；或者直接向罗马本城进攻，或者在僻远的所在猛力骚扰，让他们在灭亡以前，先受到一些惊恐。可是进来吧；让我先介绍你见见几个人，取得他们的准许。一千个欢迎！我们已经尽释前嫌，变成了一心一德的友人。把你的手给我；欢迎！\u003cb class=\"epub-calibre3\">（科利奥兰纳斯、奥菲狄乌斯同下。）\u003c/b>\u003c/p>\n","text":"奥菲狄乌斯 所以，沉鸷雄毅的将军，要是你愿意为报复自己的仇恨而做我们的前导，我可以分我的一半军力归你节制；你既然对于自己国中的虚实了如指掌，就可以凭着你自己的经验决定进军的方策；或者直接向罗马本城进攻，或者在僻远的所在猛力骚扰，让他们在灭亡以前，先受到一些惊恐。可是进来吧；让我先介绍你见见几个人，取得他们的准许。一千个欢迎！我们已经尽释前嫌，变成了一心一德的友人。把你的手给我；欢迎！（科利奥兰纳斯、奥菲狄乌斯同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00962","html":"\u003cp class=\"epub-calibre1\">仆甲 \u003cb class=\"epub-calibre3\">（上前）\u003c/b>真是意想不到的变化！\u003c/p>\n","text":"仆甲 （上前）真是意想不到的变化！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00963","html":"\u003cp class=\"epub-calibre1\">仆乙 我可以举手为誓，我还想用棍子打他呢；可是我心里总觉得他这个人是不能凭他的衣服判断他是个什么人的。\u003c/p>\n","text":"仆乙 我可以举手为誓，我还想用棍子打他呢；可是我心里总觉得他这个人是不能凭他的衣服判断他是个什么人的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00964","html":"\u003cp class=\"epub-calibre1\">仆甲 他的臂膀多么结实！他用两个指头把我掇来掇去，就像人们拈弄一个陀螺似的。\u003c/p>\n","text":"仆甲 他的臂膀多么结实！他用两个指头把我掇来掇去，就像人们拈弄一个陀螺似的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00965","html":"\u003cp class=\"epub-calibre1\">仆乙 \u003cimg src=\"data/chinese-collection/images/00154.jpeg\" alt=\"\" loading=\"lazy\" class=\"epub-inline epub-image\">，我瞧着他的脸，就知道他有一点不同凡俗的地方；我觉得他的脸上有一种——我不知道应该怎么说。\u003c/p>\n","text":"仆乙 ，我瞧着他的脸，就知道他有一点不同凡俗的地方；我觉得他的脸上有一种——我不知道应该怎么说。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00966","html":"\u003cp class=\"epub-calibre1\">仆甲 他的确是这样；瞧上去好像——我早就知道他有一点不是我所窥测得到的东西。\u003c/p>\n","text":"仆甲 他的确是这样；瞧上去好像——我早就知道他有一点不是我所窥测得到的东西。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00967","html":"\u003cp class=\"epub-calibre1\">仆乙 我可以发誓，我也这样想；他简直是世界上最稀有的人物。\u003c/p>\n","text":"仆乙 我可以发誓，我也这样想；他简直是世界上最稀有的人物。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00968","html":"\u003cp class=\"epub-calibre1\">仆甲 我想是的；可是他是比你所知道的一个人更伟大的军人。\u003c/p>\n","text":"仆甲 我想是的；可是他是比你所知道的一个人更伟大的军人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00969","html":"\u003cp class=\"epub-calibre1\">仆乙 谁？我的主人吗？\u003c/p>\n","text":"仆乙 谁？我的主人吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00970","html":"\u003cp class=\"epub-calibre1\">仆甲 \u003cimg src=\"data/chinese-collection/images/00154.jpeg\" alt=\"\" loading=\"lazy\" class=\"epub-inline epub-image\">，那就不用说了。\u003c/p>\n","text":"仆甲 ，那就不用说了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00971","html":"\u003cp class=\"epub-calibre1\">仆乙 我的主人一个人可以抵得过像他这样的六个人。\u003c/p>\n","text":"仆乙 我的主人一个人可以抵得过像他这样的六个人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00972","html":"\u003cp class=\"epub-calibre1\">仆甲 不，那也不见得；我看还是他了不得。\u003c/p>\n","text":"仆甲 不，那也不见得；我看还是他了不得。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00973","html":"\u003cp class=\"epub-calibre1\">仆乙 哼，那可不能这么说；讲到保卫城市，我们大帅的本领是超人一等的。\u003c/p>\n","text":"仆乙 哼，那可不能这么说；讲到保卫城市，我们大帅的本领是超人一等的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00974","html":"\u003cp class=\"epub-calibre1\">仆甲 是的，就是进攻起来也不弱呢。\u003c/p>\n","text":"仆甲 是的，就是进攻起来也不弱呢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00975","html":"\u003cp class=\"epub-block1\">仆丙重上。\u003c/p>\n","text":"仆丙重上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00976","html":"\u003cp class=\"epub-calibre1\">仆丙 奴才们哪！我可以告诉你们好多消息。\u003c/p>\n","text":"仆丙 奴才们哪！我可以告诉你们好多消息。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00977","html":"\u003cp class=\"epub-calibre1\">仆甲 仆乙 什么，什么，什么？讲给我们听听。\u003c/p>\n","text":"仆甲 仆乙 什么，什么，什么？讲给我们听听。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00978","html":"\u003cp class=\"epub-calibre1\">仆丙 在所有的国家之中，我顶不愿意做一个罗马人；我宁可做一个判了死罪的囚犯。\u003c/p>\n","text":"仆丙 在所有的国家之中，我顶不愿意做一个罗马人；我宁可做一个判了死罪的囚犯。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00979","html":"\u003cp class=\"epub-calibre1\">仆甲 仆乙 为什么？为什么？\u003c/p>\n","text":"仆甲 仆乙 为什么？为什么？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00980","html":"\u003cp class=\"epub-calibre1\">仆丙 嘿，刚才来的那个人，就是常常打败我们的大帅的那个卡厄斯·马歇斯呢。\u003c/p>\n","text":"仆丙 嘿，刚才来的那个人，就是常常打败我们的大帅的那个卡厄斯·马歇斯呢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00981","html":"\u003cp class=\"epub-calibre1\">仆甲 你为什么说“打败我们的大帅”？\u003c/p>\n","text":"仆甲 你为什么说“打败我们的大帅”？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00982","html":"\u003cp class=\"epub-calibre1\">仆丙 我并不说“打败我们的大帅”；可是他一向是他的劲敌。\u003c/p>\n","text":"仆丙 我并不说“打败我们的大帅”；可是他一向是他的劲敌。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00983","html":"\u003cp class=\"epub-calibre1\">仆乙 算了吧，我们都是自己人好朋友；我们的大帅总是败在他手里，我常常听见他自己这样说。\u003c/p>\n","text":"仆乙 算了吧，我们都是自己人好朋友；我们的大帅总是败在他手里，我常常听见他自己这样说。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00984","html":"\u003cp class=\"epub-calibre1\">仆甲 说句老实话，我们的大帅实在打他不过；在科利奥里城前，他曾经把他像切肉一样宰着呢。\u003c/p>\n","text":"仆甲 说句老实话，我们的大帅实在打他不过；在科利奥里城前，他曾经把他像切肉一样宰着呢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00985","html":"\u003cp class=\"epub-calibre1\">仆乙 要是他喜欢吃人肉，也许还会把他煮熟了吃下去哩。\u003c/p>\n","text":"仆乙 要是他喜欢吃人肉，也许还会把他煮熟了吃下去哩。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00986","html":"\u003cp class=\"epub-calibre1\">仆甲 可是再讲你的新闻吧。\u003c/p>\n","text":"仆甲 可是再讲你的新闻吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00987","html":"\u003cp class=\"epub-calibre1\">仆丙 嘿，他在里边受到这样的敬礼，好像他就是战神的儿子一样；坐在食桌的上首；那些元老们有什么问题问他的时候，总是脱下帽子站在他的面前。我们的大帅自己也把他当作一个情人似的敬奉，握着他的手，翻起了眼白听他讲话。可是最要紧的消息是，我们的大帅已经腰斩得只剩半截了，还有那半截因为全体在座诸人的要求和同意，已经给了那个人了。他说他要去把看守罗马城门的人扯着耳朵拖出来；他要斩除挡住他的路的一切障碍，使他的所过之处都成为一片平地。\u003c/p>\n","text":"仆丙 嘿，他在里边受到这样的敬礼，好像他就是战神的儿子一样；坐在食桌的上首；那些元老们有什么问题问他的时候，总是脱下帽子站在他的面前。我们的大帅自己也把他当作一个情人似的敬奉，握着他的手，翻起了眼白听他讲话。可是最要紧的消息是，我们的大帅已经腰斩得只剩半截了，还有那半截因为全体在座诸人的要求和同意，已经给了那个人了。他说他要去把看守罗马城门的人扯着耳朵拖出来；他要斩除挡住他的路的一切障碍，使他的所过之处都成为一片平地。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00988","html":"\u003cp class=\"epub-calibre1\">仆乙 他一定做得到这样的事。\u003c/p>\n","text":"仆乙 他一定做得到这样的事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00989","html":"\u003cp class=\"epub-calibre1\">仆丙 做得到！他当然做得到：因为你瞧，他虽然有许多敌人，也有许多朋友；那些朋友在他沮丧失势的时候，却不敢自称为他的朋友，不敢露面出来。\u003c/p>\n","text":"仆丙 做得到！他当然做得到：因为你瞧，他虽然有许多敌人，也有许多朋友；那些朋友在他沮丧失势的时候，却不敢自称为他的朋友，不敢露面出来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00990","html":"\u003cp class=\"epub-calibre1\">仆甲 沮丧失势！怎么讲？\u003c/p>\n","text":"仆甲 沮丧失势！怎么讲？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00991","html":"\u003cp class=\"epub-calibre1\">仆丙 可是他们要是看见他恢复元气，再振声威，就会像雨后的兔子一样从他们的洞里钻了出来，环绕在他的身边了。\u003c/p>\n","text":"仆丙 可是他们要是看见他恢复元气，再振声威，就会像雨后的兔子一样从他们的洞里钻了出来，环绕在他的身边了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00992","html":"\u003cp class=\"epub-calibre1\">仆甲 可是什么时候出兵呢？\u003c/p>\n","text":"仆甲 可是什么时候出兵呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00993","html":"\u003cp class=\"epub-calibre1\">仆丙 明天；今天；立刻。今天下午你们就可以听见鼓声；这是他们宴会中的一个余兴，在他们抹干嘴唇以前就要办好。\u003c/p>\n","text":"仆丙 明天；今天；立刻。今天下午你们就可以听见鼓声；这是他们宴会中的一个余兴，在他们抹干嘴唇以前就要办好。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00994","html":"\u003cp class=\"epub-calibre1\">仆乙 啊，那么我们就可以热闹起来啦。这种和平不过锈了铁，增加了许多裁缝，让那些没事做的人编些歌曲唱唱。\u003c/p>\n","text":"仆乙 啊，那么我们就可以热闹起来啦。这种和平不过锈了铁，增加了许多裁缝，让那些没事做的人编些歌曲唱唱。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00995","html":"\u003cp class=\"epub-calibre1\">仆甲 还是战争好，我说；它胜过和平就像白昼胜过黑夜一样。战争是活泼的、清醒的，热闹的、兴奋的；和平是麻木不仁的、平淡无味的、寂无声息的、昏睡的、没有感觉的。和平所产生的私生子，比战争所杀死的人更多。\u003c/p>\n","text":"仆甲 还是战争好，我说；它胜过和平就像白昼胜过黑夜一样。战争是活泼的、清醒的，热闹的、兴奋的；和平是麻木不仁的、平淡无味的、寂无声息的、昏睡的、没有感觉的。和平所产生的私生子，比战争所杀死的人更多。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00996","html":"\u003cp class=\"epub-calibre1\">仆乙 对呀：战争可以说是一个强奸妇女的狂徒，因而和平就无疑是专事培植乌龟的能手了。\u003c/p>\n","text":"仆乙 对呀：战争可以说是一个强奸妇女的狂徒，因而和平就无疑是专事培植乌龟的能手了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00997","html":"\u003cp class=\"epub-calibre1\">仆甲 是呀，它使人们彼此仇恨。\u003c/p>\n","text":"仆甲 是呀，它使人们彼此仇恨。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00998","html":"\u003cp class=\"epub-calibre1\">仆丙 理由是有了和平，人们就不那么需要彼此照顾了。我愿意用我的钱打赌还是战争好。我希望看见罗马人像伏尔斯人一样贱。他们都从席上起来了，他们都从席上起来了。\u003c/p>\n","text":"仆丙 理由是有了和平，人们就不那么需要彼此照顾了。我愿意用我的钱打赌还是战争好。我希望看见罗马人像伏尔斯人一样贱。他们都从席上起来了，他们都从席上起来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-00999","html":"\u003cp class=\"epub-calibre1\">众 仆 进去，进去，进去，进去！\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"众 仆 进去，进去，进去，进去！（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第五场 同前。奥菲狄乌斯家中厅堂","headingLevel":4,"sourceAnchor":"a746","actNumber":4,"sceneNumber":5},{"id":"part0031-section-026","label":"第四幕 · 第六场 罗马。广场","kind":"scene","blocks":[{"id":"part0031-01000","html":"\u003ch4 id=\"epub-part0031-a747\" class=\"epub-calibre12\">第六场 罗马。广场\u003c/h4>\n","text":"第六场 罗马。广场\n","sourceAnchor":"a747","tag":"h4"},{"id":"part0031-01001","html":"\u003cp class=\"epub-block1\">西西涅斯及勃鲁托斯上。\u003c/p>\n","text":"西西涅斯及勃鲁托斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01002","html":"\u003cp class=\"epub-calibre1\">西西涅斯 我们没有听见他的消息，也不必怕他有什么图谋。人民现在已经由狂乱的状态回复到安宁平静，他也无能为力了。因为一切进行得如此顺利，我们已经使他的朋友们感到惭愧，他们是宁愿瞧见纷争的群众在街道上闹事——虽然那样对于他们自身也是同样有害——而不愿瞧见我们的百工商贾们安居乐业、歌舞升平的。\u003c/p>\n","text":"西西涅斯 我们没有听见他的消息，也不必怕他有什么图谋。人民现在已经由狂乱的状态回复到安宁平静，他也无能为力了。因为一切进行得如此顺利，我们已经使他的朋友们感到惭愧，他们是宁愿瞧见纷争的群众在街道上闹事——虽然那样对于他们自身也是同样有害——而不愿瞧见我们的百工商贾们安居乐业、歌舞升平的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01003","html":"\u003cp class=\"epub-block1\">米尼涅斯上。\u003c/p>\n","text":"米尼涅斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01004","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 我们总算没有错过了时机。这是米尼涅斯吗？\u003c/p>\n","text":"勃鲁托斯 我们总算没有错过了时机。这是米尼涅斯吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01005","html":"\u003cp class=\"epub-calibre1\">西西涅斯 正是他，正是他。啊！他近来变得和气多啦。您好，老人家！\u003c/p>\n","text":"西西涅斯 正是他，正是他。啊！他近来变得和气多啦。您好，老人家！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01006","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 你们两位都好！\u003c/p>\n","text":"米尼涅斯 你们两位都好！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01007","html":"\u003cp class=\"epub-calibre1\">西西涅斯 您那科利奥兰纳斯除了他的几个朋友以外，没有什么人因为他的不在而惋惜。我们的共和政府依然存在，即使他对它再不高兴一些，也会继续存在下去的。\u003c/p>\n","text":"西西涅斯 您那科利奥兰纳斯除了他的几个朋友以外，没有什么人因为他的不在而惋惜。我们的共和政府依然存在，即使他对它再不高兴一些，也会继续存在下去的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01008","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 一切都很好；要是他的态度能够谦和一些，事情一定会更好的。\u003c/p>\n","text":"米尼涅斯 一切都很好；要是他的态度能够谦和一些，事情一定会更好的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01009","html":"\u003cp class=\"epub-calibre1\">西西涅斯 他在什么地方？你听见人家说起吗？\u003c/p>\n","text":"西西涅斯 他在什么地方？你听见人家说起吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01010","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 不，我没有听到什么；他的母亲和他的妻子也没有听到他的消息。\u003c/p>\n","text":"米尼涅斯 不，我没有听到什么；他的母亲和他的妻子也没有听到他的消息。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01011","html":"\u003cp class=\"epub-block1\">市民三、四人上。\u003c/p>\n","text":"市民三、四人上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01012","html":"\u003cp class=\"epub-calibre1\">众市民 天神保佑你们两位！\u003c/p>\n","text":"众市民 天神保佑你们两位！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01013","html":"\u003cp class=\"epub-calibre1\">西西涅斯 各位朋友，你们都好。\u003c/p>\n","text":"西西涅斯 各位朋友，你们都好。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01014","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 你们大家都好，你们大家都好。\u003c/p>\n","text":"勃鲁托斯 你们大家都好，你们大家都好。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01015","html":"\u003cp class=\"epub-calibre1\">市民甲 我们自己、我们的妻子儿女，都应该跪下来为你们两位祈祷。\u003c/p>\n","text":"市民甲 我们自己、我们的妻子儿女，都应该跪下来为你们两位祈祷。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01016","html":"\u003cp class=\"epub-calibre1\">西西涅斯 愿你们都能享受幸福繁荣的生活！\u003c/p>\n","text":"西西涅斯 愿你们都能享受幸福繁荣的生活！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01017","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 再见，好朋友们；我们希望科利奥兰纳斯也像我们一样爱你们。\u003c/p>\n","text":"勃鲁托斯 再见，好朋友们；我们希望科利奥兰纳斯也像我们一样爱你们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01018","html":"\u003cp class=\"epub-calibre1\">众市民 神明保佑你们！\u003c/p>\n","text":"众市民 神明保佑你们！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01019","html":"\u003cp class=\"epub-calibre1\">西西涅斯 勃鲁托斯 再见，再见。\u003cb class=\"epub-calibre3\">（市民等下。）\u003c/b>\u003c/p>\n","text":"西西涅斯 勃鲁托斯 再见，再见。（市民等下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01020","html":"\u003cp class=\"epub-calibre1\">西西涅斯 这才是太平盛世的光景，比从前这些人在街上到处奔走、叫嚣扰乱的时候好得多啦。\u003c/p>\n","text":"西西涅斯 这才是太平盛世的光景，比从前这些人在街上到处奔走、叫嚣扰乱的时候好得多啦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01021","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 卡厄斯·马歇斯在战阵上是一员能将；可是太傲慢、太目空一世、太野心勃勃、太自负了——\u003c/p>\n","text":"勃鲁托斯 卡厄斯·马歇斯在战阵上是一员能将；可是太傲慢、太目空一世、太野心勃勃、太自负了——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01022","html":"\u003cp class=\"epub-calibre1\">西西涅斯 他只想由他一个人称王道霸，用不着别人帮助。\u003c/p>\n","text":"西西涅斯 他只想由他一个人称王道霸，用不着别人帮助。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01023","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我倒不这样想。\u003c/p>\n","text":"米尼涅斯 我倒不这样想。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01024","html":"\u003cp class=\"epub-calibre1\">西西涅斯 要是他果然当了执政，我们现在就要发现他是这样一个人而后悔不及了。\u003c/p>\n","text":"西西涅斯 要是他果然当了执政，我们现在就要发现他是这样一个人而后悔不及了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01025","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 幸亏神明默护，不让他当选，罗马去掉了这个人，可以从此安宁了。\u003c/p>\n","text":"勃鲁托斯 幸亏神明默护，不让他当选，罗马去掉了这个人，可以从此安宁了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01026","html":"\u003cp class=\"epub-block1\">一警吏上。\u003c/p>\n","text":"一警吏上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01027","html":"\u003cp class=\"epub-calibre1\">警吏 两位尊贵的护民官，据一个给我们关在牢里的奴隶说，伏尔斯人派了两支军队，已经开进了罗马领土，毁灭他们所碰到的一切，存心要来向我们挑起一场恶战。\u003c/p>\n","text":"警吏 两位尊贵的护民官，据一个给我们关在牢里的奴隶说，伏尔斯人派了两支军队，已经开进了罗马领土，毁灭他们所碰到的一切，存心要来向我们挑起一场恶战。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01028","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 那一定是奥菲狄乌斯；当罗马有马歇斯挺身保卫的时候，他就像一只缩头的蜗牛，不敢钻出壳来张望一眼，现在他听见马歇斯已经被放逐出去，又要把他的角伸出来了。\u003c/p>\n","text":"米尼涅斯 那一定是奥菲狄乌斯；当罗马有马歇斯挺身保卫的时候，他就像一只缩头的蜗牛，不敢钻出壳来张望一眼，现在他听见马歇斯已经被放逐出去，又要把他的角伸出来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01029","html":"\u003cp class=\"epub-calibre1\">西西涅斯 得啦，您何必提起马歇斯呢？\u003c/p>\n","text":"西西涅斯 得啦，您何必提起马歇斯呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01030","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 去把这个造谣惑众的家伙抽一顿鞭子。伏尔斯人决不敢来侵犯我们。\u003c/p>\n","text":"勃鲁托斯 去把这个造谣惑众的家伙抽一顿鞭子。伏尔斯人决不敢来侵犯我们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01031","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 决不敢！我们有过去的记录可以证明他们会干这样的事；在我的一生之中，已经看到过三次同样的例子了。可是你们在处罚这家伙以前，应该把他问清楚，他从什么地方听到这句话，免得屈打了一个把确实消息报告你们、叫你们预防祸事的好人。\u003c/p>\n","text":"米尼涅斯 决不敢！我们有过去的记录可以证明他们会干这样的事；在我的一生之中，已经看到过三次同样的例子了。可是你们在处罚这家伙以前，应该把他问清楚，他从什么地方听到这句话，免得屈打了一个把确实消息报告你们、叫你们预防祸事的好人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01032","html":"\u003cp class=\"epub-calibre1\">西西涅斯 不劳指教，我知道决不会有这种事。\u003c/p>\n","text":"西西涅斯 不劳指教，我知道决不会有这种事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01033","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 不可能的。\u003c/p>\n","text":"勃鲁托斯 不可能的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01034","html":"\u003cp class=\"epub-block1\">一使者上。\u003c/p>\n","text":"一使者上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01035","html":"\u003cp class=\"epub-calibre1\">使者 贵族们都急急忙忙地到元老院去了；他们不知道听到了什么消息，一个个脸色都变了。\u003c/p>\n","text":"使者 贵族们都急急忙忙地到元老院去了；他们不知道听到了什么消息，一个个脸色都变了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01036","html":"\u003cp class=\"epub-calibre1\">西西涅斯 都是这个奴才。——去把他鞭打示众；完全是他造谣生事。\u003c/p>\n","text":"西西涅斯 都是这个奴才。——去把他鞭打示众；完全是他造谣生事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01037","html":"\u003cp class=\"epub-calibre1\">使者 是的，大人，这奴隶的话已经有人证实；而且还有更可怕的消息。\u003c/p>\n","text":"使者 是的，大人，这奴隶的话已经有人证实；而且还有更可怕的消息。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01038","html":"\u003cp class=\"epub-calibre1\">西西涅斯 什么更可怕的消息？\u003c/p>\n","text":"西西涅斯 什么更可怕的消息？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01039","html":"\u003cp class=\"epub-calibre1\">使者 许多人都在那里公开传说，我也不知道他们从哪儿听来的，说是马歇斯已经和奥菲狄乌斯联合，带领一支军队来攻打罗马了；他发誓为自己复仇，把罗马人无论老幼，一起杀尽。\u003c/p>\n","text":"使者 许多人都在那里公开传说，我也不知道他们从哪儿听来的，说是马歇斯已经和奥菲狄乌斯联合，带领一支军队来攻打罗马了；他发誓为自己复仇，把罗马人无论老幼，一起杀尽。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01040","html":"\u003cp class=\"epub-calibre1\">西西涅斯 会有这样的事！\u003c/p>\n","text":"西西涅斯 会有这样的事！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01041","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 完全是谣言；他们想用这样的话煽惑那些懦弱的人，让他们希望善良的马歇斯回来。\u003c/p>\n","text":"勃鲁托斯 完全是谣言；他们想用这样的话煽惑那些懦弱的人，让他们希望善良的马歇斯回来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01042","html":"\u003cp class=\"epub-calibre1\">西西涅斯 正是这个诡计。\u003c/p>\n","text":"西西涅斯 正是这个诡计。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01043","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 这话恐怕未必；他跟奥菲狄乌斯是势不两立的仇人，决没有调和的可能。\u003c/p>\n","text":"米尼涅斯 这话恐怕未必；他跟奥菲狄乌斯是势不两立的仇人，决没有调和的可能。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01044","html":"\u003cp class=\"epub-block1\">另一使者上。\u003c/p>\n","text":"另一使者上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01045","html":"\u003cp class=\"epub-calibre1\">使者乙 请各位大人到元老院去。卡厄斯·马歇斯由奥菲狄乌斯辅佐，已经率领了一支声势浩大的军队，向我们的领土进犯了；他们一路过来势如破竹，到处纵火焚烧，掳夺一空。\u003c/p>\n","text":"使者乙 请各位大人到元老院去。卡厄斯·马歇斯由奥菲狄乌斯辅佐，已经率领了一支声势浩大的军队，向我们的领土进犯了；他们一路过来势如破竹，到处纵火焚烧，掳夺一空。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01046","html":"\u003cp class=\"epub-block1\">考密涅斯上。\u003c/p>\n","text":"考密涅斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01047","html":"\u003cp class=\"epub-calibre1\">考密涅斯 啊！你们干得好事！\u003c/p>\n","text":"考密涅斯 啊！你们干得好事！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01048","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 什么消息？什么消息？\u003c/p>\n","text":"米尼涅斯 什么消息？什么消息？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01049","html":"\u003cp class=\"epub-calibre1\">考密涅斯 你们已经帮助你们的敌人来强奸你们自己的女儿，把全城的铅块熔灌在你们的头顶，亲眼看你们的妻子被人污辱——\u003c/p>\n","text":"考密涅斯 你们已经帮助你们的敌人来强奸你们自己的女儿，把全城的铅块熔灌在你们的头顶，亲眼看你们的妻子被人污辱——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01050","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 什么消息？什么消息？\u003c/p>\n","text":"米尼涅斯 什么消息？什么消息？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01051","html":"\u003cp class=\"epub-calibre1\">考密涅斯 你们的神庙化为灰烬，你们所倚赖的特权压缩得只剩锥孔一样大小。\u003c/p>\n","text":"考密涅斯 你们的神庙化为灰烬，你们所倚赖的特权压缩得只剩锥孔一样大小。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01052","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 请你把消息告诉我吧。——哼，你们干得好事！——请问什么消息？假如马歇斯和伏尔斯人联合起来——\u003c/p>\n","text":"米尼涅斯 请你把消息告诉我吧。——哼，你们干得好事！——请问什么消息？假如马歇斯和伏尔斯人联合起来——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01053","html":"\u003cp class=\"epub-calibre1\">考密涅斯 假如！他就是他们的神。他领导着他们的那副气概，好像凭着造化的本领，也造不出他这样一个顶天立地的男儿一样；他们跟随着他来攻击我们这些小儿，也像孩子们追捕夏天的蝴蝶、屠夫们杀戮苍蝇一样有把握。\u003c/p>\n","text":"考密涅斯 假如！他就是他们的神。他领导着他们的那副气概，好像凭着造化的本领，也造不出他这样一个顶天立地的男儿一样；他们跟随着他来攻击我们这些小儿，也像孩子们追捕夏天的蝴蝶、屠夫们杀戮苍蝇一样有把握。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01054","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 你们干得好事，你们和你们那些穿围裙的家伙！你们那样看重那些手工匠的话，那些吃大蒜的人们吐出来的气息！\u003c/p>\n","text":"米尼涅斯 你们干得好事，你们和你们那些穿围裙的家伙！你们那样看重那些手工匠的话，那些吃大蒜的人们吐出来的气息！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01055","html":"\u003cp class=\"epub-calibre1\">考密涅斯 他将要荡平你们的罗马。\u003c/p>\n","text":"考密涅斯 他将要荡平你们的罗马。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01056","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 就像赫剌克勒斯从树上摇落一颗烂熟的果子一样容易。你们干得好事！\u003c/p>\n","text":"米尼涅斯 就像赫剌克勒斯从树上摇落一颗烂熟的果子一样容易。你们干得好事！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01057","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 可是这是真的吗？\u003c/p>\n","text":"勃鲁托斯 可是这是真的吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01058","html":"\u003cp class=\"epub-calibre1\">考密涅斯 还会不真吗？等着瞧吧，你们的脸色都要吓白了。各处属地都望风响应，欣然脱离我们的羁縻；企图抵抗的，都被讥笑为勇敢的愚夫，因为不自量力而覆亡。谁能责怪他的不是呢？你们的敌人和他的敌人都知道他是一个不可轻视的人。\u003c/p>\n","text":"考密涅斯 还会不真吗？等着瞧吧，你们的脸色都要吓白了。各处属地都望风响应，欣然脱离我们的羁縻；企图抵抗的，都被讥笑为勇敢的愚夫，因为不自量力而覆亡。谁能责怪他的不是呢？你们的敌人和他的敌人都知道他是一个不可轻视的人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01059","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我们全都完了，除非这位英雄大发慈悲。\u003c/p>\n","text":"米尼涅斯 我们全都完了，除非这位英雄大发慈悲。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01060","html":"\u003cp class=\"epub-calibre1\">考密涅斯 谁去求他开恩呢？护民官是不好意思去向他求情的；人民不值得他怜悯，正像豺狼不值得牧人怜悯一样；至于他的要好的朋友们，要是他们向他说，“照顾照顾罗马吧，”那么他们也就和他所憎恨的人一鼻孔出气，也就是他的仇敌了。\u003c/p>\n","text":"考密涅斯 谁去求他开恩呢？护民官是不好意思去向他求情的；人民不值得他怜悯，正像豺狼不值得牧人怜悯一样；至于他的要好的朋友们，要是他们向他说，“照顾照顾罗马吧，”那么他们也就和他所憎恨的人一鼻孔出气，也就是他的仇敌了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01061","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 不错，要是他在我的家里放起火来，我也没有脸向他说，“请您住手。”——你们干得好事，你们和你们那些手段！\u003c/p>\n","text":"米尼涅斯 不错，要是他在我的家里放起火来，我也没有脸向他说，“请您住手。”——你们干得好事，你们和你们那些手段！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01062","html":"\u003cp class=\"epub-calibre1\">考密涅斯 你们使罗马发生空前的战栗，它从来没有像今天这样濒于绝望的境地。\u003c/p>\n","text":"考密涅斯 你们使罗马发生空前的战栗，它从来没有像今天这样濒于绝望的境地。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01063","html":"\u003cp class=\"epub-calibre1\">西西涅斯 勃鲁托斯 不要说这是我们的错处。\u003c/p>\n","text":"西西涅斯 勃鲁托斯 不要说这是我们的错处。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01064","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 怎么！那么是我们的错处吗？我们都是敬爱他的，可是像一群畜生和懦怯的贵族似的，让你们那群贱民为所欲为，把他轰出了城。\u003c/p>\n","text":"米尼涅斯 怎么！那么是我们的错处吗？我们都是敬爱他的，可是像一群畜生和懦怯的贵族似的，让你们那群贱民为所欲为，把他轰出了城。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01065","html":"\u003cp class=\"epub-calibre1\">考密涅斯 可是我怕他们又要用高声的叫喊迎接他进来了。塔勒斯·奥菲狄乌斯，人类中间第二个令人畏惧的名字，像他的部属一样服从他的号令。罗马倘要抵抗他们，除了准备与城俱亡以外，已经力竭计穷、无法防御了。\u003c/p>\n","text":"考密涅斯 可是我怕他们又要用高声的叫喊迎接他进来了。塔勒斯·奥菲狄乌斯，人类中间第二个令人畏惧的名字，像他的部属一样服从他的号令。罗马倘要抵抗他们，除了准备与城俱亡以外，已经力竭计穷、无法防御了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01066","html":"\u003cp class=\"epub-block1\">一群市民上。\u003c/p>\n","text":"一群市民上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01067","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 这群东西来了。奥菲狄乌斯也和他在一起吗？你们抛掷你们恶臭油腻的帽子，鼓噪着把科利奥兰纳斯放逐出去，就这样使罗马的空气变得污浊了。现在他来了；每一个兵士头上的每一根头发，都会变成惩罚你们的鞭子；他要把你们的头颅一个一个砍下来，报答你们的好意。算了，要是他把我们一起烧成了一个炭块，也是活该。\u003c/p>\n","text":"米尼涅斯 这群东西来了。奥菲狄乌斯也和他在一起吗？你们抛掷你们恶臭油腻的帽子，鼓噪着把科利奥兰纳斯放逐出去，就这样使罗马的空气变得污浊了。现在他来了；每一个兵士头上的每一根头发，都会变成惩罚你们的鞭子；他要把你们的头颅一个一个砍下来，报答你们的好意。算了，要是他把我们一起烧成了一个炭块，也是活该。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01068","html":"\u003cp class=\"epub-calibre1\">众市民 真的，我们听见了可怕的消息。\u003c/p>\n","text":"众市民 真的，我们听见了可怕的消息。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01069","html":"\u003cp class=\"epub-calibre1\">市民甲 拿我自己来说，当我说把他放逐的时候，我也说这是一件很可惋惜的事。\u003c/p>\n","text":"市民甲 拿我自己来说，当我说把他放逐的时候，我也说这是一件很可惋惜的事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01070","html":"\u003cp class=\"epub-calibre1\">市民乙 我也这样说。\u003c/p>\n","text":"市民乙 我也这样说。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01071","html":"\u003cp class=\"epub-calibre1\">市民丙 我也这样说；说句老实话，我们中间有许多人都这样说。我们所干的事，都是为了大众的利益；虽然我们同意放逐他，可是那也并不是我们的本意。\u003c/p>\n","text":"市民丙 我也这样说；说句老实话，我们中间有许多人都这样说。我们所干的事，都是为了大众的利益；虽然我们同意放逐他，可是那也并不是我们的本意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01072","html":"\u003cp class=\"epub-calibre1\">考密涅斯 你们都是些好东西，你们的同意！\u003c/p>\n","text":"考密涅斯 你们都是些好东西，你们的同意！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01073","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 你们干得好事，你们和你们的鼓噪！我们要不要到议会里去？\u003c/p>\n","text":"米尼涅斯 你们干得好事，你们和你们的鼓噪！我们要不要到议会里去？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01074","html":"\u003cp class=\"epub-calibre1\">考密涅斯 啊，是，是；不去又有什么事情好做？\u003cb class=\"epub-calibre3\">（考密涅斯、米尼涅斯同下。）\u003c/b>\u003c/p>\n","text":"考密涅斯 啊，是，是；不去又有什么事情好做？（考密涅斯、米尼涅斯同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01075","html":"\u003cp class=\"epub-calibre1\">西西涅斯 各位！你们回家去吧；不要发急。这两个人是一党，他们虽然面子上装得很害怕，心里却但愿真有这样的事。回去吧，不要露出惊慌的样子来。\u003c/p>\n","text":"西西涅斯 各位！你们回家去吧；不要发急。这两个人是一党，他们虽然面子上装得很害怕，心里却但愿真有这样的事。回去吧，不要露出惊慌的样子来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01076","html":"\u003cp class=\"epub-calibre1\">市民甲 但愿神明照顾我们！来，朋友们，我们回去吧。我们把他放逐的时候，我早就说我们做了一件错事。\u003c/p>\n","text":"市民甲 但愿神明照顾我们！来，朋友们，我们回去吧。我们把他放逐的时候，我早就说我们做了一件错事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01077","html":"\u003cp class=\"epub-calibre1\">市民乙 我们大家都这样说。可是走吧，我们回去吧。\u003cb class=\"epub-calibre3\">（众市民下。）\u003c/b>\u003c/p>\n","text":"市民乙 我们大家都这样说。可是走吧，我们回去吧。（众市民下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01078","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 我不喜欢这种消息。\u003c/p>\n","text":"勃鲁托斯 我不喜欢这种消息。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01079","html":"\u003cp class=\"epub-calibre1\">西西涅斯 我也不喜欢。\u003c/p>\n","text":"西西涅斯 我也不喜欢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01080","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 我们到议会去吧。要是有人能够证明这消息是个谣言，我愿意把我一半的家产赏给他！\u003c/p>\n","text":"勃鲁托斯 我们到议会去吧。要是有人能够证明这消息是个谣言，我愿意把我一半的家产赏给他！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01081","html":"\u003cp class=\"epub-calibre1\">西西涅斯 我们走吧。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"西西涅斯 我们走吧。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第六场 罗马。广场","headingLevel":4,"sourceAnchor":"a747","actNumber":4,"sceneNumber":6},{"id":"part0031-section-027","label":"第四幕 · 第七场 离罗马不远的营地","kind":"scene","blocks":[{"id":"part0031-01082","html":"\u003ch4 id=\"epub-part0031-a748\" class=\"epub-calibre12\">第七场 离罗马不远的营地\u003c/h4>\n","text":"第七场 离罗马不远的营地\n","sourceAnchor":"a748","tag":"h4"},{"id":"part0031-01083","html":"\u003cp class=\"epub-block1\">奥菲狄乌斯及其副将上。\u003c/p>\n","text":"奥菲狄乌斯及其副将上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01084","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 他们仍旧向那罗马人纷纷投附吗？\u003c/p>\n","text":"奥菲狄乌斯 他们仍旧向那罗马人纷纷投附吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01085","html":"\u003cp class=\"epub-calibre1\">副将 我不知道他有一种什么魔力，可是他们简直把他当作食前的祈祷、席上的谈话，和餐后的谢恩一样一刻不离口。您的声名，主帅，在这次战役中已经相形见绌，甚至于您自己的部下对您的信仰也一天不如一天了。\u003c/p>\n","text":"副将 我不知道他有一种什么魔力，可是他们简直把他当作食前的祈祷、席上的谈话，和餐后的谢恩一样一刻不离口。您的声名，主帅，在这次战役中已经相形见绌，甚至于您自己的部下对您的信仰也一天不如一天了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01086","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 我现在也没有法子，虽然可以用计策排挤他，可是那会影响到军事的进行。当我第一次拥抱他的时候，我想不到他在我的面前也会倨傲到这个样子；可是这也是他天性如此，改变不过来的脾气，我也只好原谅他了。\u003c/p>\n","text":"奥菲狄乌斯 我现在也没有法子，虽然可以用计策排挤他，可是那会影响到军事的进行。当我第一次拥抱他的时候，我想不到他在我的面前也会倨傲到这个样子；可是这也是他天性如此，改变不过来的脾气，我也只好原谅他了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01087","html":"\u003cp class=\"epub-calibre1\">副将 可是主帅，为您着想，我倒希望这次您没有和他负起共同的责任，或者您自己统率全军，或者让他独自主持一切。\u003c/p>\n","text":"副将 可是主帅，为您着想，我倒希望这次您没有和他负起共同的责任，或者您自己统率全军，或者让他独自主持一切。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01088","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 我很懂得你的意思；你等着瞧吧，等到我跟他最后清算的日子，怕他不跌翻在我的手里。虽然看上去好像他的行事非常堂皇正大，对伏尔斯政府也十分尽忠，作战的时候像龙一样勇猛，一拔出剑来就可以克敌制胜，他自己也因此沾沾自喜，一般凡俗的眼光也莫不以为如此；可是他还有一件事情留下没有做，在我们最后清算的日子，它将要使我们两人中间有一个人牺牲。\u003c/p>\n","text":"奥菲狄乌斯 我很懂得你的意思；你等着瞧吧，等到我跟他最后清算的日子，怕他不跌翻在我的手里。虽然看上去好像他的行事非常堂皇正大，对伏尔斯政府也十分尽忠，作战的时候像龙一样勇猛，一拔出剑来就可以克敌制胜，他自己也因此沾沾自喜，一般凡俗的眼光也莫不以为如此；可是他还有一件事情留下没有做，在我们最后清算的日子，它将要使我们两人中间有一个人牺牲。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01089","html":"\u003cp class=\"epub-calibre1\">副将 请教主帅，您看来他会不会把罗马征服？\u003c/p>\n","text":"副将 请教主帅，您看来他会不会把罗马征服？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01090","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 他还没有坐下，他的威力就已经压倒一切。罗马的元老和贵族们都是他的朋友；护民官不是军人；他们的人民会卤莽地把他放逐，也会卤莽地收回成命。我想他对于罗马，就像白鹭对于鱼类一样，天性中自有一种使人俯首就范的力量。本来他是他们的一个忠勇的仆人，可是他不能使他的荣誉维持不坠。也许因为他的一帆风顺的命运，使他沾上骄傲的习气，损坏了他的完善的人格；也许因为他见事不明，不善于利用他自己的机会；也许因为他本性难移，只适宜于顶盔披甲，不适宜于雍容揖让，刚毅严肃本来是治军的正道，他却用来对待和平时期的民众；这几重原因他虽然并不完全犯着，可是每一种都犯几分，只要犯了其中之一，就可以使他为人民所畏惧，因而被他们憎恨以至于放逐。正像一个怀璧亡身的人一样，他的功劳一经出口，就会被它自己所噎死。所以我们的美德是随着时间而变更价值的；权力的本身虽可称道，可是当它高踞宝座的时候，已经伏下它的葬身的基础了。一个火焰驱走另一个火焰，一枚钉打掉另一枚钉；权利因权利而转移，强力被强力所征服。来，我们去吧。卡厄斯，当你握有整个罗马的时候，你是一个最贫穷的人；那时候你就在我的手掌之中了。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"奥菲狄乌斯 他还没有坐下，他的威力就已经压倒一切。罗马的元老和贵族们都是他的朋友；护民官不是军人；他们的人民会卤莽地把他放逐，也会卤莽地收回成命。我想他对于罗马，就像白鹭对于鱼类一样，天性中自有一种使人俯首就范的力量。本来他是他们的一个忠勇的仆人，可是他不能使他的荣誉维持不坠。也许因为他的一帆风顺的命运，使他沾上骄傲的习气，损坏了他的完善的人格；也许因为他见事不明，不善于利用他自己的机会；也许因为他本性难移，只适宜于顶盔披甲，不适宜于雍容揖让，刚毅严肃本来是治军的正道，他却用来对待和平时期的民众；这几重原因他虽然并不完全犯着，可是每一种都犯几分，只要犯了其中之一，就可以使他为人民所畏惧，因而被他们憎恨以至于放逐。正像一个怀璧亡身的人一样，他的功劳一经出口，就会被它自己所噎死。所以我们的美德是随着时间而变更价值的；权力的本身虽可称道，可是当它高踞宝座的时候，已经伏下它的葬身的基础了。一个火焰驱走另一个火焰，一枚钉打掉另一枚钉；权利因权利而转移，强力被强力所征服。来，我们去吧。卡厄斯，当你握有整个罗马的时候，你是一个最贫穷的人；那时候你就在我的手掌之中了。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第七场 离罗马不远的营地","headingLevel":4,"sourceAnchor":"a748","actNumber":4,"sceneNumber":7},{"id":"part0031-section-028","label":"第五幕","kind":"act","blocks":[{"id":"part0031-01091","html":"\u003ch3 id=\"epub-part0031-a749\" class=\"epub-calibre11\">第五幕\u003c/h3>\n","text":"第五幕\n","sourceAnchor":"a749","tag":"h3"}],"heading":"第五幕","headingLevel":3,"sourceAnchor":"a749","actNumber":5},{"id":"part0031-section-029","label":"第五幕 · 第一场 罗马。广场","kind":"scene","blocks":[{"id":"part0031-01092","html":"\u003ch4 id=\"epub-part0031-a750\" class=\"epub-calibre12\">第一场 罗马。广场\u003c/h4>\n","text":"第一场 罗马。广场\n","sourceAnchor":"a750","tag":"h4"},{"id":"part0031-01093","html":"\u003cp class=\"epub-block1\">米尼涅斯、考密涅斯、西西涅斯、勃鲁托斯及余人等上。\u003c/p>\n","text":"米尼涅斯、考密涅斯、西西涅斯、勃鲁托斯及余人等上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01094","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 不，我不去。你们已经听见他从前的主将怎么说了，他对于他的爱护是无微不至的。他虽然把我叫做父亲，可是那又有什么用处呢？你们把他放逐出去，还是你们去向他央求，在他营帐之前一哩路的地方俯伏下来，膝行而进，请他大发慈悲吧。不，他既然不愿听考密涅斯的话，那么我还是安住家里的好。\u003c/p>\n","text":"米尼涅斯 不，我不去。你们已经听见他从前的主将怎么说了，他对于他的爱护是无微不至的。他虽然把我叫做父亲，可是那又有什么用处呢？你们把他放逐出去，还是你们去向他央求，在他营帐之前一哩路的地方俯伏下来，膝行而进，请他大发慈悲吧。不，他既然不愿听考密涅斯的话，那么我还是安住家里的好。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01095","html":"\u003cp class=\"epub-calibre1\">考密涅斯 他假装不认识我。\u003c/p>\n","text":"考密涅斯 他假装不认识我。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01096","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 你们听见了吗？\u003c/p>\n","text":"米尼涅斯 你们听见了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01097","html":"\u003cp class=\"epub-calibre1\">考密涅斯 可是从前他却用我的名字称呼我。我向他提起我们过去的交情，我们在一起流过的血；可是无论我叫他科利奥兰纳斯或者其他的名字，他都不应一声；他仿佛是一个无名无姓的东西，等着用罗马城中的烈火替他自己熔铸出一个名字来。\u003c/p>\n","text":"考密涅斯 可是从前他却用我的名字称呼我。我向他提起我们过去的交情，我们在一起流过的血；可是无论我叫他科利奥兰纳斯或者其他的名字，他都不应一声；他仿佛是一个无名无姓的东西，等着用罗马城中的烈火替他自己熔铸出一个名字来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01098","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 哼，好，你们干得好事！一对护民官替罗马降低了炭价，不朽的功绩！\u003c/p>\n","text":"米尼涅斯 哼，好，你们干得好事！一对护民官替罗马降低了炭价，不朽的功绩！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01099","html":"\u003cp class=\"epub-calibre1\">考密涅斯 我对他说，宽恕人家所不能宽恕的，是一种多么高贵的行为；他却回答我，一个国家向它所处罚的罪人求恕，是一件多么无聊的事。\u003c/p>\n","text":"考密涅斯 我对他说，宽恕人家所不能宽恕的，是一种多么高贵的行为；他却回答我，一个国家向它所处罚的罪人求恕，是一件多么无聊的事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01100","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 很好，他当然要说这样的话啦。\u003c/p>\n","text":"米尼涅斯 很好，他当然要说这样的话啦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01101","html":"\u003cp class=\"epub-calibre1\">考密涅斯 我叫他想想他自己的亲戚朋友；他回答我说，他等不及把他们从一大堆恶臭发霉的糠屑中间选择出来；他说他不能为了不忍烧去一两粒谷子的缘故，永远忍受着难闻的气味。\u003c/p>\n","text":"考密涅斯 我叫他想想他自己的亲戚朋友；他回答我说，他等不及把他们从一大堆恶臭发霉的糠屑中间选择出来；他说他不能为了不忍烧去一两粒谷子的缘故，永远忍受着难闻的气味。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01102","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 为了一两粒谷子的缘故！我就是这样一粒谷子；他的母亲、妻子，他的孩子，还有这位好汉子，我们都是这样的谷粒；你们是发霉的糠屑，你们的臭味已经熏到月亮上去了。为了你们的缘故，我们也只好同归于尽！\u003c/p>\n","text":"米尼涅斯 为了一两粒谷子的缘故！我就是这样一粒谷子；他的母亲、妻子，他的孩子，还有这位好汉子，我们都是这样的谷粒；你们是发霉的糠屑，你们的臭味已经熏到月亮上去了。为了你们的缘故，我们也只好同归于尽！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01103","html":"\u003cp class=\"epub-calibre1\">西西涅斯 不，请您不要恼怒；要是您不肯在这样危急的时候帮助我们，那么您也不要在我们的患难之中责备我们。可是我们相信，要是您愿意替您的祖国请命，那么凭着您的巧妙的口才，一定可以使我们那位同国之人放下干戈，比我们所能召集的军队更有力量。\u003c/p>\n","text":"西西涅斯 不，请您不要恼怒；要是您不肯在这样危急的时候帮助我们，那么您也不要在我们的患难之中责备我们。可是我们相信，要是您愿意替您的祖国请命，那么凭着您的巧妙的口才，一定可以使我们那位同国之人放下干戈，比我们所能召集的军队更有力量。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01104","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 不，我不愿多管闲事。\u003c/p>\n","text":"米尼涅斯 不，我不愿多管闲事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01105","html":"\u003cp class=\"epub-calibre1\">西西涅斯 请您去这一趟吧。\u003c/p>\n","text":"西西涅斯 请您去这一趟吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01106","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我干得了什么事呢？\u003c/p>\n","text":"米尼涅斯 我干得了什么事呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01107","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 只要您去向马歇斯试一试您对他的交情能不能为罗马做一点事。\u003c/p>\n","text":"勃鲁托斯 只要您去向马歇斯试一试您对他的交情能不能为罗马做一点事。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01108","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 好；要是马歇斯理也不理我，就像他对待考密涅斯一样对待我，那便怎样呢？要是我在他的无情的冷淡之下抱着满怀的懊恼失望而归，那可怎么办呢？\u003c/p>\n","text":"米尼涅斯 好；要是马歇斯理也不理我，就像他对待考密涅斯一样对待我，那便怎样呢？要是我在他的无情的冷淡之下抱着满怀的懊恼失望而归，那可怎么办呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01109","html":"\u003cp class=\"epub-calibre1\">西西涅斯 无论此去成功失败，您的好意总是会得到罗马的感谢的。\u003c/p>\n","text":"西西涅斯 无论此去成功失败，您的好意总是会得到罗马的感谢的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01110","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 好，我就去试一试；也许他会听我的话。可是他对考密涅斯咬紧嘴唇，哼呀哈的，却叫我担着老大的心事。也许考密涅斯没有看准适当的时间，那个时候他还没有吃过饭；一个人在腹中空虚、血液没有温暖的时候，往往会噘着嘴生气，不大肯布施人，更不容易宽恕别人的过失；可是当我们把酒食填下了脏腑，使全身的血管增加热力以后，我们的灵魂就要比未进饮食以前温柔得多了。所以我要留心看着他，等他餐罢以后，方才向他提出我的请求，竭力说得他回心转意。\u003c/p>\n","text":"米尼涅斯 好，我就去试一试；也许他会听我的话。可是他对考密涅斯咬紧嘴唇，哼呀哈的，却叫我担着老大的心事。也许考密涅斯没有看准适当的时间，那个时候他还没有吃过饭；一个人在腹中空虚、血液没有温暖的时候，往往会噘着嘴生气，不大肯布施人，更不容易宽恕别人的过失；可是当我们把酒食填下了脏腑，使全身的血管增加热力以后，我们的灵魂就要比未进饮食以前温柔得多了。所以我要留心看着他，等他餐罢以后，方才向他提出我的请求，竭力说得他回心转意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01111","html":"\u003cp class=\"epub-calibre1\">勃鲁托斯 您已经知道用怎样的途径激发他的天良，我们相信您一定不会有错。\u003c/p>\n","text":"勃鲁托斯 您已经知道用怎样的途径激发他的天良，我们相信您一定不会有错。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01112","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 好，不论结果如何，我去试一试再说。成功失败，不久就可以见个分晓。\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"米尼涅斯 好，不论结果如何，我去试一试再说。成功失败，不久就可以见个分晓。（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01113","html":"\u003cp class=\"epub-calibre1\">考密涅斯 他决不会听他的话。\u003c/p>\n","text":"考密涅斯 他决不会听他的话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01114","html":"\u003cp class=\"epub-calibre1\">西西涅斯 不听他？\u003c/p>\n","text":"西西涅斯 不听他？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01115","html":"\u003cp class=\"epub-calibre1\">考密涅斯 我告诉你，他坐在黄金的椅上，他的眼睛红得像要把罗马烧起来一般，他的冤愤就是监守他的恻隐之心的狱吏。我跪在他的面前，他淡淡地说了一声“起来”，用他的无言的手把我挥走。他准备做的事，他将用书面告诉我；他不愿做的事，他已经立誓在先，决无改移。所以一切希望都已归于乌有了，除非他的母亲和妻子去向他当面哀求；听说她们已经准备前去求他保全他的祖国了，所以让我们就去恳促她们赶快动身吧。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"考密涅斯 我告诉你，他坐在黄金的椅上，他的眼睛红得像要把罗马烧起来一般，他的冤愤就是监守他的恻隐之心的狱吏。我跪在他的面前，他淡淡地说了一声“起来”，用他的无言的手把我挥走。他准备做的事，他将用书面告诉我；他不愿做的事，他已经立誓在先，决无改移。所以一切希望都已归于乌有了，除非他的母亲和妻子去向他当面哀求；听说她们已经准备前去求他保全他的祖国了，所以让我们就去恳促她们赶快动身吧。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第一场 罗马。广场","headingLevel":4,"sourceAnchor":"a750","actNumber":5,"sceneNumber":1},{"id":"part0031-section-030","label":"第五幕 · 第二场 罗马城前的伏尔斯人营地","kind":"scene","blocks":[{"id":"part0031-01116","html":"\u003ch4 id=\"epub-part0031-a751\" class=\"epub-calibre12\">第二场 罗马城前的伏尔斯人营地\u003c/h4>\n","text":"第二场 罗马城前的伏尔斯人营地\n","sourceAnchor":"a751","tag":"h4"},{"id":"part0031-01117","html":"\u003cp class=\"epub-block1\">二守卒立岗位前防守；米尼涅斯上。\u003c/p>\n","text":"二守卒立岗位前防守；米尼涅斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01118","html":"\u003cp class=\"epub-calibre1\">守卒甲 站住！你是什么地方来的？\u003c/p>\n","text":"守卒甲 站住！你是什么地方来的？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01119","html":"\u003cp class=\"epub-calibre1\">守卒乙 站住！回去！\u003c/p>\n","text":"守卒乙 站住！回去！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01120","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 你们这样尽职，很好；可是对不起你们，我是一个政府官吏，要来见科利奥兰纳斯说话。\u003c/p>\n","text":"米尼涅斯 你们这样尽职，很好；可是对不起你们，我是一个政府官吏，要来见科利奥兰纳斯说话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01121","html":"\u003cp class=\"epub-calibre1\">守卒甲 从什么地方来的？\u003c/p>\n","text":"守卒甲 从什么地方来的？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01122","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 从罗马来的。\u003c/p>\n","text":"米尼涅斯 从罗马来的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01123","html":"\u003cp class=\"epub-calibre1\">守卒甲 你不能通过；你必须回去。我们主将有令，凡是从罗马来的人，一概不见。\u003c/p>\n","text":"守卒甲 你不能通过；你必须回去。我们主将有令，凡是从罗马来的人，一概不见。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01124","html":"\u003cp class=\"epub-calibre1\">守卒乙 等你看见你们的罗马被烈焰拥抱的时候，你再来跟科利奥兰纳斯说话吧。\u003c/p>\n","text":"守卒乙 等你看见你们的罗马被烈焰拥抱的时候，你再来跟科利奥兰纳斯说话吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01125","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我的好朋友们，要是你们曾经听见你们的主将说起罗马和他在罗马的朋友们，那么我的名字一定接触过你们的耳朵：我是米尼涅斯。\u003c/p>\n","text":"米尼涅斯 我的好朋友们，要是你们曾经听见你们的主将说起罗马和他在罗马的朋友们，那么我的名字一定接触过你们的耳朵：我是米尼涅斯。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01126","html":"\u003cp class=\"epub-calibre1\">守卒甲 很好，回去吧；你的名字不能使你在这儿通行无阻。\u003c/p>\n","text":"守卒甲 很好，回去吧；你的名字不能使你在这儿通行无阻。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01127","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我告诉你吧，朋友，你的主将是我的好朋友；我曾经是记载他的善行的一卷书，人家可以从我的嘴里读到他的无比的名声，因为我对于我的朋友们的好处总是极口称扬的，尤其是他，我有时候因为说溜了嘴，就像一个球碰到了光滑的地面一样，会不知不觉地夸张过分，越过了限定的界线。所以，朋友，你必须让我通过。\u003c/p>\n","text":"米尼涅斯 我告诉你吧，朋友，你的主将是我的好朋友；我曾经是记载他的善行的一卷书，人家可以从我的嘴里读到他的无比的名声，因为我对于我的朋友们的好处总是极口称扬的，尤其是他，我有时候因为说溜了嘴，就像一个球碰到了光滑的地面一样，会不知不觉地夸张过分，越过了限定的界线。所以，朋友，你必须让我通过。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01128","html":"\u003cp class=\"epub-calibre1\">守卒甲 先生，即使您替他说过的谎话，就跟您自己说过的话一样多，即使说谎是一件善事，您也不能在这儿通过。所以您还是回去吧。\u003c/p>\n","text":"守卒甲 先生，即使您替他说过的谎话，就跟您自己说过的话一样多，即使说谎是一件善事，您也不能在这儿通过。所以您还是回去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01129","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 朋友，请你记好我的名字是米尼涅斯，一向都是站在你主将一边的。\u003c/p>\n","text":"米尼涅斯 朋友，请你记好我的名字是米尼涅斯，一向都是站在你主将一边的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01130","html":"\u003cp class=\"epub-calibre1\">守卒乙 不管你替他扯过多少谎，我奉着他的命令，却必须老实告诉你，你不能通过。所以你回去吧。\u003c/p>\n","text":"守卒乙 不管你替他扯过多少谎，我奉着他的命令，却必须老实告诉你，你不能通过。所以你回去吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01131","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 你知道他已经吃过饭了没有？我一定要等他饭后方才跟他说话。\u003c/p>\n","text":"米尼涅斯 你知道他已经吃过饭了没有？我一定要等他饭后方才跟他说话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01132","html":"\u003cp class=\"epub-calibre1\">守卒甲 你是一个罗马人，是不是？\u003c/p>\n","text":"守卒甲 你是一个罗马人，是不是？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01133","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我是罗马人，你的主将也是罗马人。\u003c/p>\n","text":"米尼涅斯 我是罗马人，你的主将也是罗马人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01134","html":"\u003cp class=\"epub-calibre1\">守卒甲 那么你应当像他一样痛恨罗马。你们把保卫罗马的人逐出门外，在一阵群众的狂暴的愚昧中，把你们的干盾给了你们的敌人，现在你们却想用老妇人的不费力的呻吟、你们女儿们的童贞的手掌或是像你这样一个老朽的瘫痪的说项，来抵御他的复仇的怒焰吗？你们想要用像这样微弱的呼吸，来吹灭将要焚毁你们城市的烈火吗？不，你完全想错了；所以赶快回到罗马去，准备引颈就戮吧。你们的劫运已经无可避免，我们的主将发誓不再宽恕你们。\u003c/p>\n","text":"守卒甲 那么你应当像他一样痛恨罗马。你们把保卫罗马的人逐出门外，在一阵群众的狂暴的愚昧中，把你们的干盾给了你们的敌人，现在你们却想用老妇人的不费力的呻吟、你们女儿们的童贞的手掌或是像你这样一个老朽的瘫痪的说项，来抵御他的复仇的怒焰吗？你们想要用像这样微弱的呼吸，来吹灭将要焚毁你们城市的烈火吗？不，你完全想错了；所以赶快回到罗马去，准备引颈就戮吧。你们的劫运已经无可避免，我们的主将发誓不再宽恕你们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01135","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 哼，要是你的长官知道我在这儿，他一定会对我以礼相待的。\u003c/p>\n","text":"米尼涅斯 哼，要是你的长官知道我在这儿，他一定会对我以礼相待的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01136","html":"\u003cp class=\"epub-calibre1\">守卒乙 算了吧，我的长官不认识你。\u003c/p>\n","text":"守卒乙 算了吧，我的长官不认识你。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01137","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我是说你的主将。\u003c/p>\n","text":"米尼涅斯 我是说你的主将。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01138","html":"\u003cp class=\"epub-calibre1\">守卒甲 我的主将不知道有你这样一个人。回去，走，否则我要叫你流出你身上所有的两三滴血了；回去回去。\u003c/p>\n","text":"守卒甲 我的主将不知道有你这样一个人。回去，走，否则我要叫你流出你身上所有的两三滴血了；回去回去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01139","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 不，不，朋友，朋友——\u003c/p>\n","text":"米尼涅斯 不，不，朋友，朋友——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01140","html":"\u003cp class=\"epub-block1\">科利奥兰纳斯及奥菲狄乌斯上。\u003c/p>\n","text":"科利奥兰纳斯及奥菲狄乌斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01141","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 什么事？\u003c/p>\n","text":"科利奥兰纳斯 什么事？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01142","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 现在，伙计，我也不要麻烦你替我传报了。你现在就可以知道我是一个被人敬礼的人；一个卑微的哨兵，是不能挡住我不让我看见我的孩儿科利奥兰纳斯的。你只要看他怎样款待我，就可以猜想得到你是不是将要上绞架，或者受到其他欣赏起来更长久、受苦得更残酷的死刑了；现在你给我留心看着，想一想你的未来的遭遇而晕过去吧。\u003cb class=\"epub-calibre3\">（向科利奥兰纳斯）\u003c/b>愿荣耀的天神们每时每刻护佑着你，像你的米尼涅斯老爹一样眷爱你！啊，我的孩子！我的孩子！你在准备用火烧我们；瞧，我要用我眼睛里的泪水把它浇熄。他们好容易劝我到这儿来；可是我因为相信除了我自己以外，再也没有别人可以说动你，所以就让叹息把我吹出了城门，来求你宽恕罗马，和你的迫切待命的同胞们。愿善良的神明们缓和你的愤怒，要是你还有几分气恼未消，请你发泄在这个奴才的身上吧，他像一块石头一样，挡住了我不让见你。\u003c/p>\n","text":"米尼涅斯 现在，伙计，我也不要麻烦你替我传报了。你现在就可以知道我是一个被人敬礼的人；一个卑微的哨兵，是不能挡住我不让我看见我的孩儿科利奥兰纳斯的。你只要看他怎样款待我，就可以猜想得到你是不是将要上绞架，或者受到其他欣赏起来更长久、受苦得更残酷的死刑了；现在你给我留心看着，想一想你的未来的遭遇而晕过去吧。（向科利奥兰纳斯）愿荣耀的天神们每时每刻护佑着你，像你的米尼涅斯老爹一样眷爱你！啊，我的孩子！我的孩子！你在准备用火烧我们；瞧，我要用我眼睛里的泪水把它浇熄。他们好容易劝我到这儿来；可是我因为相信除了我自己以外，再也没有别人可以说动你，所以就让叹息把我吹出了城门，来求你宽恕罗马，和你的迫切待命的同胞们。愿善良的神明们缓和你的愤怒，要是你还有几分气恼未消，请你发泄在这个奴才的身上吧，他像一块石头一样，挡住了我不让见你。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01143","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 去！\u003c/p>\n","text":"科利奥兰纳斯 去！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01144","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 怎么！去！\u003c/p>\n","text":"米尼涅斯 怎么！去！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01145","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我不知道什么妻子、母亲、儿女。我现在替别人做着事情，虽然是为自己报仇，可是我的行动要受伏尔斯人的支配。讲到我们过去的交情，那么还是让它在无情的遗忘里冷淡下去，不要用同情的怜悯唤起它的记忆吧。所以你去吧；你们的城门经不起我大军的一击，我的耳朵却不会被你们的呼吁所打动。可是为了我们的友谊，把这拿去吧；\u003cb class=\"epub-calibre3\">（以信交米尼涅斯）\u003c/b>这是我写给你的，我本想叫人送给你。还有一句话，米尼涅斯，我不想听你说话。奥菲狄乌斯，这个人是我在罗马的好朋友，可是你瞧我怎样对待他！\u003c/p>\n","text":"科利奥兰纳斯 我不知道什么妻子、母亲、儿女。我现在替别人做着事情，虽然是为自己报仇，可是我的行动要受伏尔斯人的支配。讲到我们过去的交情，那么还是让它在无情的遗忘里冷淡下去，不要用同情的怜悯唤起它的记忆吧。所以你去吧；你们的城门经不起我大军的一击，我的耳朵却不会被你们的呼吁所打动。可是为了我们的友谊，把这拿去吧；（以信交米尼涅斯）这是我写给你的，我本想叫人送给你。还有一句话，米尼涅斯，我不想听你说话。奥菲狄乌斯，这个人是我在罗马的好朋友，可是你瞧我怎样对待他！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01146","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 您有一个很坚决的意志。\u003cb class=\"epub-calibre3\">（科利奥兰纳斯、奥菲狄乌斯同下。）\u003c/b>\u003c/p>\n","text":"奥菲狄乌斯 您有一个很坚决的意志。（科利奥兰纳斯、奥菲狄乌斯同下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01147","html":"\u003cp class=\"epub-calibre1\">守卒甲 先生，您的大名是米尼涅斯吗？\u003c/p>\n","text":"守卒甲 先生，您的大名是米尼涅斯吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01148","html":"\u003cp class=\"epub-calibre1\">守卒乙 这一个名字是一道很有法力的符咒。现在您知道从哪条路回家去了。\u003c/p>\n","text":"守卒乙 这一个名字是一道很有法力的符咒。现在您知道从哪条路回家去了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01149","html":"\u003cp class=\"epub-calibre1\">守卒甲 您有没有听见我们因为不让大驾通过，挨了怎样一顿痛骂？\u003c/p>\n","text":"守卒甲 您有没有听见我们因为不让大驾通过，挨了怎样一顿痛骂？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01150","html":"\u003cp class=\"epub-calibre1\">守卒乙 为了什么理由您说我要晕过去呢？\u003c/p>\n","text":"守卒乙 为了什么理由您说我要晕过去呢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01151","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 整个世界和你们的主将都不在我的心上；至于像你们这种东西，那么我简直不知道世上有你们存在，你们是太渺小了。自己愿意死的人，不怕别人把他杀死。让你们的主将去大施威风吧。讲到你们，那么愿你们一辈子做个没出息的小兵；愿你们的困苦与年俱增！你们叫我去，我也要对你们说，滚开！\u003cb class=\"epub-calibre3\">（下。）\u003c/b>\u003c/p>\n","text":"米尼涅斯 整个世界和你们的主将都不在我的心上；至于像你们这种东西，那么我简直不知道世上有你们存在，你们是太渺小了。自己愿意死的人，不怕别人把他杀死。让你们的主将去大施威风吧。讲到你们，那么愿你们一辈子做个没出息的小兵；愿你们的困苦与年俱增！你们叫我去，我也要对你们说，滚开！（下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01152","html":"\u003cp class=\"epub-calibre1\">守卒甲 他不是一个等闲之辈。\u003c/p>\n","text":"守卒甲 他不是一个等闲之辈。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01153","html":"\u003cp class=\"epub-calibre1\">守卒乙 我们的主将是个好汉；他是岩石，是风吹不折的橡树。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"守卒乙 我们的主将是个好汉；他是岩石，是风吹不折的橡树。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第二场 罗马城前的伏尔斯人营地","headingLevel":4,"sourceAnchor":"a751","actNumber":5,"sceneNumber":2},{"id":"part0031-section-031","label":"第五幕 · 第三场 科利奥兰纳斯营帐","kind":"scene","blocks":[{"id":"part0031-01154","html":"\u003ch4 id=\"epub-part0031-a752\" class=\"epub-calibre12\">第三场 科利奥兰纳斯营帐\u003c/h4>\n","text":"第三场 科利奥兰纳斯营帐\n","sourceAnchor":"a752","tag":"h4"},{"id":"part0031-01155","html":"\u003cp class=\"epub-block1\">科利奥兰纳斯、奥菲狄乌斯及余人等上。\u003c/p>\n","text":"科利奥兰纳斯、奥菲狄乌斯及余人等上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01156","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我们明天将要在罗马城前驻扎下我们的大军。我的从征的助手，你必须向伏尔斯政府报告我怎样坦白地执行我的任务的情形。\u003c/p>\n","text":"科利奥兰纳斯 我们明天将要在罗马城前驻扎下我们的大军。我的从征的助手，你必须向伏尔斯政府报告我怎样坦白地执行我的任务的情形。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01157","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 您只知道履行他们的意旨，充耳不闻罗马人民的呼吁，不让一句低声的私语进入您的耳中；即使那些自信和您交情深厚、决不会遭您拒绝的朋友，也不能不失望而归。\u003c/p>\n","text":"奥菲狄乌斯 您只知道履行他们的意旨，充耳不闻罗马人民的呼吁，不让一句低声的私语进入您的耳中；即使那些自信和您交情深厚、决不会遭您拒绝的朋友，也不能不失望而归。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01158","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 最后来的那位老人家，就是我使他怀着一颗碎裂的心回去的那位，爱我胜如一个父亲；他简直把我像天神一样崇拜。他们把最后的希望寄托在他身上，叫他来向我说情；我虽然用冷酷的态度对待他，可是为了顾念往日的交情起见，仍旧向他提出最初的条件，那是他们所已经拒绝、现在也无法接受的。我不曾向他们作过什么让步；以后要是他们再派什么人来向我请求，无论是政府方面的使者，或是私人方面的朋友，我都一概不去理会他们。\u003cb class=\"epub-calibre3\">（内呼声）\u003c/b>嘿！这是什么呼声？难道我刚发了誓，就有人来引诱我背誓吗？我一定不。\u003c/p>\n","text":"科利奥兰纳斯 最后来的那位老人家，就是我使他怀着一颗碎裂的心回去的那位，爱我胜如一个父亲；他简直把我像天神一样崇拜。他们把最后的希望寄托在他身上，叫他来向我说情；我虽然用冷酷的态度对待他，可是为了顾念往日的交情起见，仍旧向他提出最初的条件，那是他们所已经拒绝、现在也无法接受的。我不曾向他们作过什么让步；以后要是他们再派什么人来向我请求，无论是政府方面的使者，或是私人方面的朋友，我都一概不去理会他们。（内呼声）嘿！这是什么呼声？难道我刚发了誓，就有人来引诱我背誓吗？我一定不。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01159","html":"\u003cp class=\"epub-block1\">维吉利娅、伏伦妮娅各穿丧服，率小马歇斯、凡勒利娅及侍从等上。\u003c/p>\n","text":"维吉利娅、伏伦妮娅各穿丧服，率小马歇斯、凡勒利娅及侍从等上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01160","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我的妻子走在最前面；跟着她来的就是塑成我这躯体的高贵的模型，她的手里还挽着她的嫡亲的孙儿。可是去吧，感情！一切天性中的伦常，都给我毁灭了吧！让倔强成为一种美德。那屈膝的敬礼，还有那可以使天神背誓的鸽子一样温柔的眼光，又都值得了什么呢？我要是被温情所溶解，那么我就要变得和别人同样软弱了。我的母亲向我鞠躬了，好像俄林波斯山也会向一个土丘低头恳求一样；我的年幼的孩儿也露着求情的脸色，伟大的天性不禁喊出，“不要拒绝他！”让伏尔斯人耕耘着罗马的废壤，把整个意大利夷为田亩吧；我决不做一头服从本能的呆鹅，我要漠然无动于衷，就像我是我自己的创造者，不知道还有什么亲族一样。\u003c/p>\n","text":"科利奥兰纳斯 我的妻子走在最前面；跟着她来的就是塑成我这躯体的高贵的模型，她的手里还挽着她的嫡亲的孙儿。可是去吧，感情！一切天性中的伦常，都给我毁灭了吧！让倔强成为一种美德。那屈膝的敬礼，还有那可以使天神背誓的鸽子一样温柔的眼光，又都值得了什么呢？我要是被温情所溶解，那么我就要变得和别人同样软弱了。我的母亲向我鞠躬了，好像俄林波斯山也会向一个土丘低头恳求一样；我的年幼的孩儿也露着求情的脸色，伟大的天性不禁喊出，“不要拒绝他！”让伏尔斯人耕耘着罗马的废壤，把整个意大利夷为田亩吧；我决不做一头服从本能的呆鹅，我要漠然无动于衷，就像我是我自己的创造者，不知道还有什么亲族一样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01161","html":"\u003cp class=\"epub-calibre1\">维吉利娅 我的主，我的丈夫！\u003c/p>\n","text":"维吉利娅 我的主，我的丈夫！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01162","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我现在不是用我在罗马时候的那双眼睛瞧着你了。\u003c/p>\n","text":"科利奥兰纳斯 我现在不是用我在罗马时候的那双眼睛瞧着你了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01163","html":"\u003cp class=\"epub-calibre1\">维吉利娅 悲哀改变了我们的容貌，所以您才会这样想。\u003c/p>\n","text":"维吉利娅 悲哀改变了我们的容貌，所以您才会这样想。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01164","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 像一个愚笨的伶人似的，我现在已经忘记了我所扮演的角色，将要受众人的耻笑了。我的最亲爱的，原谅我的残酷吧；可是不要因此而向我说，“原谅我们的罗马人。”啊！给我一个像我的放逐一样长久、像我的复仇一样甜蜜的吻吧！善妒的天后可以为我证明，爱人，我这一个吻就是上次你给我的，我的忠心的嘴唇一直为它保持着贞操。天啊！我是多么饶舌，忘记了向全世界最高贵的母亲致敬。母亲，您的儿子向您下跪了；\u003cb class=\"epub-calibre3\">（跪）\u003c/b>我应该向您表示不同于一般儿子的最深的敬意。\u003c/p>\n","text":"科利奥兰纳斯 像一个愚笨的伶人似的，我现在已经忘记了我所扮演的角色，将要受众人的耻笑了。我的最亲爱的，原谅我的残酷吧；可是不要因此而向我说，“原谅我们的罗马人。”啊！给我一个像我的放逐一样长久、像我的复仇一样甜蜜的吻吧！善妒的天后可以为我证明，爱人，我这一个吻就是上次你给我的，我的忠心的嘴唇一直为它保持着贞操。天啊！我是多么饶舌，忘记了向全世界最高贵的母亲致敬。母亲，您的儿子向您下跪了；（跪）我应该向您表示不同于一般儿子的最深的敬意。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01165","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 啊！站起来受我的祝福；让坚硬的石块做我的膝垫，我现在跪在你的面前，颠倒向我的儿子致敬了。\u003cb class=\"epub-calibre3\">（跪。）\u003c/b>\u003c/p>\n","text":"伏伦妮娅 啊！站起来受我的祝福；让坚硬的石块做我的膝垫，我现在跪在你的面前，颠倒向我的儿子致敬了。（跪。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01166","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 这是什么意思？您向我下跪！向您有罪的儿子下跪！那么让硗瘠的海滨的石子向天星飞射，让作乱的狂风弯折凌霄的松柏，去打击赤热的太阳吧；一切不可能的事都要变成可能，一切不会实现的奇迹都要变成轻易的工作了。\u003c/p>\n","text":"科利奥兰纳斯 这是什么意思？您向我下跪！向您有罪的儿子下跪！那么让硗瘠的海滨的石子向天星飞射，让作乱的狂风弯折凌霄的松柏，去打击赤热的太阳吧；一切不可能的事都要变成可能，一切不会实现的奇迹都要变成轻易的工作了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01167","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 你是我的战士；你这雄伟的躯体上一部分是我的心血。你认识这位夫人吗？\u003c/p>\n","text":"伏伦妮娅 你是我的战士；你这雄伟的躯体上一部分是我的心血。你认识这位夫人吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01168","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 坡勃力科拉的尊贵的姊妹，罗马的明月；她的贞洁有如从最皎白的雪凝冻而成，悬挂在狄安娜神庙檐下的冰柱；亲爱的凡勒利娅！\u003c/p>\n","text":"科利奥兰纳斯 坡勃力科拉的尊贵的姊妹，罗马的明月；她的贞洁有如从最皎白的雪凝冻而成，悬挂在狄安娜神庙檐下的冰柱；亲爱的凡勒利娅！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01169","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 这是你自己的一个小小的缩影，\u003cb class=\"epub-calibre3\">（指小儿）\u003c/b>等他长大成人以后，他就会完全像你一样。\u003c/p>\n","text":"伏伦妮娅 这是你自己的一个小小的缩影，（指小儿）等他长大成人以后，他就会完全像你一样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01170","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 愿至高无上的乔武允许战神把义勇的精神启发你的思想，让你不会屈服于耻辱之下，在战争中间做一座伟大的海标，受得住一切风浪的袭击，使那些望着你的人都能得救！\u003c/p>\n","text":"科利奥兰纳斯 愿至高无上的乔武允许战神把义勇的精神启发你的思想，让你不会屈服于耻辱之下，在战争中间做一座伟大的海标，受得住一切风浪的袭击，使那些望着你的人都能得救！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01171","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 跪下来，孩子。\u003c/p>\n","text":"伏伦妮娅 跪下来，孩子。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01172","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我的好孩子！\u003c/p>\n","text":"科利奥兰纳斯 我的好孩子！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01173","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 他，你的妻子，这位夫人，以及我自己，现在都来向你请求了。\u003c/p>\n","text":"伏伦妮娅 他，你的妻子，这位夫人，以及我自己，现在都来向你请求了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01174","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 请您不要说下去；或者在您没有向我提出什么要求以前，先记住这一点：我所立誓决不允许的事情，不能因为你们的请求而答应你们。不要叫我撤回我的军队，或者再向罗马的手工匠屈服；不要对我说我在什么地方太不近人情；也不要想用你们冷静的理智浇熄我的复仇的怒火。\u003c/p>\n","text":"科利奥兰纳斯 请您不要说下去；或者在您没有向我提出什么要求以前，先记住这一点：我所立誓决不允许的事情，不能因为你们的请求而答应你们。不要叫我撤回我的军队，或者再向罗马的手工匠屈服；不要对我说我在什么地方太不近人情；也不要想用你们冷静的理智浇熄我的复仇的怒火。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01175","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 啊！别说了，别说了；你已经拒绝我们一切的要求，因为我们除了你所已经拒绝的以外，更没有什么其他的要求了；可是我们还是要向你请求，那么要是你拒绝了我们，我们就可以归怨于你的忍心。所以，听我们说吧。\u003c/p>\n","text":"伏伦妮娅 啊！别说了，别说了；你已经拒绝我们一切的要求，因为我们除了你所已经拒绝的以外，更没有什么其他的要求了；可是我们还是要向你请求，那么要是你拒绝了我们，我们就可以归怨于你的忍心。所以，听我们说吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01176","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 奥菲狄乌斯，还有你们这些伏尔斯人，请你们听着；因为凡是从罗马来的言语，我都要公之于众人。您的要求是什么？\u003c/p>\n","text":"科利奥兰纳斯 奥菲狄乌斯，还有你们这些伏尔斯人，请你们听着；因为凡是从罗马来的言语，我都要公之于众人。您的要求是什么？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01177","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 即使我们静默不言，你也可以从我们的衣服和容态上，看出我们自从你放逐以后，过着怎样的生活。请你想一想，我们到这儿来，是怎样比世间所有的妇女不幸万分，因为我们看见了你，本来应该眼睛里荡漾着喜悦，心坎里跳跃着欣慰，可是现在反而悲泣流泪，忧惧颤栗；母亲、妻子、儿子，都要看着她的孩子、她的丈夫和他的父亲亲手挖出他祖国的心脏来。你的敌意对于可怜的我们是无上的酷刑，你使我们不能向神明祈祷，那本来是每一个人所能享受的安慰。因为，唉！我们虽然和祖国的命运是不可分的，可是我们的命运又是和你的胜利不可分的，我们怎么能为我们的祖国祈祷呢？唉！我们倘不是失去我们的国家，我们亲爱的保姆，就是失去你，我们在国内唯一的安慰。无论哪一方得胜，虽然都符合我们的愿望，可是总免不了一个悲惨的结果：我们不是看见你像一个通敌的叛徒一般，戴上镣铐牵过市街，就是看见你意气扬扬地践踏在祖国的废墟上，高举着胜利的旗帜，因为你已经勇敢地溅了你妻子儿女的血。至于我自己，那么，孩子，我不愿等候命运宣判战争的最后胜负；要是我不能把你劝服，使你放弃了陷一个国家于灭亡的行动，而采取一种兼利双方的途径，那么相信我，我决不让你侵犯你的国家，除非先从你生身母亲的身上践踏过去。\u003c/p>\n","text":"伏伦妮娅 即使我们静默不言，你也可以从我们的衣服和容态上，看出我们自从你放逐以后，过着怎样的生活。请你想一想，我们到这儿来，是怎样比世间所有的妇女不幸万分，因为我们看见了你，本来应该眼睛里荡漾着喜悦，心坎里跳跃着欣慰，可是现在反而悲泣流泪，忧惧颤栗；母亲、妻子、儿子，都要看着她的孩子、她的丈夫和他的父亲亲手挖出他祖国的心脏来。你的敌意对于可怜的我们是无上的酷刑，你使我们不能向神明祈祷，那本来是每一个人所能享受的安慰。因为，唉！我们虽然和祖国的命运是不可分的，可是我们的命运又是和你的胜利不可分的，我们怎么能为我们的祖国祈祷呢？唉！我们倘不是失去我们的国家，我们亲爱的保姆，就是失去你，我们在国内唯一的安慰。无论哪一方得胜，虽然都符合我们的愿望，可是总免不了一个悲惨的结果：我们不是看见你像一个通敌的叛徒一般，戴上镣铐牵过市街，就是看见你意气扬扬地践踏在祖国的废墟上，高举着胜利的旗帜，因为你已经勇敢地溅了你妻子儿女的血。至于我自己，那么，孩子，我不愿等候命运宣判战争的最后胜负；要是我不能把你劝服，使你放弃了陷一个国家于灭亡的行动，而采取一种兼利双方的途径，那么相信我，我决不让你侵犯你的国家，除非先从你生身母亲的身上践踏过去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01178","html":"\u003cp class=\"epub-calibre1\">维吉利娅 \u003cimg src=\"data/chinese-collection/images/00155.jpeg\" alt=\"\" loading=\"lazy\" class=\"epub-inline epub-image\">，我替您生下这个孩子，继续您的家声，您现在也必须从我的身上践踏过去。\u003c/p>\n","text":"维吉利娅 ，我替您生下这个孩子，继续您的家声，您现在也必须从我的身上践踏过去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01179","html":"\u003cp class=\"epub-calibre1\">小马歇斯 我可不让他踏；我要逃走，等我年纪长大了，我也要打仗。\u003c/p>\n","text":"小马歇斯 我可不让他踏；我要逃走，等我年纪长大了，我也要打仗。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01180","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 看见孩子和女人的脸，容易使人心肠变软。我已经坐得太久了。\u003cb class=\"epub-calibre3\">（起立。）\u003c/b>\u003c/p>\n","text":"科利奥兰纳斯 看见孩子和女人的脸，容易使人心肠变软。我已经坐得太久了。（起立。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01181","html":"\u003cp class=\"epub-calibre1\">伏伦妮娅 不，不要就这样离开我们。要是我们的请求，是要你为了拯救罗马人的缘故而毁灭你所臣事的伏尔斯人，那么你可以责备我们不该损害你的信誉；不，我们的请求只是要你替双方和解，伏尔斯人可以说，“我们已经表示了这样的慈悲，”罗马人也可以说，“我们已经接受了这样的恩典，”同时两方面都向你欢呼称颂，“祝福你替我们缔结和平！”你知道，我的伟大的儿子，战争的结果是不能确定的，可是这一点却可以确定：要是你征服了罗马，你所收得的利益，不过是一个永远伴着唾骂的恶名；历史上将要记载：“这个人本来是很英勇的，可是他在最后一次的行动里亲手涂去了他的令名，毁灭了他的国家，他的名字永受后世的憎恨。”儿子，对你的母亲不能默默无言哪：你已保全了体面，就该同天神一样做得光彩，虽然用雷电撕裂云层，却不妨霹雳一声，震倒一棵橡树，何必让生灵涂炭呢。你为什么不说话呢？你以为一个高贵的人，是应该不忘旧怨的吗？媳妇，你说话呀；他不理会你的哭泣呢。你也说话呀，孩子；也许你的天真会比我们的理由更能使他感动。没有一个人和他母亲的关系更密切了；可是他现在却让我像一个用脚镣锁着的囚人一样叨叨絮语，置若罔闻。你从来不曾对你亲爱的母亲表示过一点孝敬；她却像一头痴心爱着它头胎雏儿的母鸡似的，把你教养成人，送你献身疆场，又迎接你满载着光荣归来。要是我的请求是不正当的，你尽可以挥斥我回去；否则你就是不忠不孝，天神将要降祸于你，因为你不曾向你的母亲尽一个人子的义务。他转身去了；跪下来，让我们用屈膝羞辱他。附属于他那科利奥兰纳斯的姓氏上的，只有骄傲，没有一点怜悯。跪下来；完了，这是我们最后的哀求；我们现在要回到罗马去，和我们的邻人们死在一起。不，瞧着我们吧。这个小孩不会说他要些什么，只是陪着我们下跪举手，他代替我们呼吁的理由，比你拒绝的理由有力得多。来，我们去吧。这人有一个伏尔斯的母亲，他的妻子在科利奥里，他的孩子也许像他一样。可是请你给我们一个答复；我要等我们的城市在大火中焚烧以后，方才停止我的声音，那时候我也没有什么好说了。\u003c/p>\n","text":"伏伦妮娅 不，不要就这样离开我们。要是我们的请求，是要你为了拯救罗马人的缘故而毁灭你所臣事的伏尔斯人，那么你可以责备我们不该损害你的信誉；不，我们的请求只是要你替双方和解，伏尔斯人可以说，“我们已经表示了这样的慈悲，”罗马人也可以说，“我们已经接受了这样的恩典，”同时两方面都向你欢呼称颂，“祝福你替我们缔结和平！”你知道，我的伟大的儿子，战争的结果是不能确定的，可是这一点却可以确定：要是你征服了罗马，你所收得的利益，不过是一个永远伴着唾骂的恶名；历史上将要记载：“这个人本来是很英勇的，可是他在最后一次的行动里亲手涂去了他的令名，毁灭了他的国家，他的名字永受后世的憎恨。”儿子，对你的母亲不能默默无言哪：你已保全了体面，就该同天神一样做得光彩，虽然用雷电撕裂云层，却不妨霹雳一声，震倒一棵橡树，何必让生灵涂炭呢。你为什么不说话呢？你以为一个高贵的人，是应该不忘旧怨的吗？媳妇，你说话呀；他不理会你的哭泣呢。你也说话呀，孩子；也许你的天真会比我们的理由更能使他感动。没有一个人和他母亲的关系更密切了；可是他现在却让我像一个用脚镣锁着的囚人一样叨叨絮语，置若罔闻。你从来不曾对你亲爱的母亲表示过一点孝敬；她却像一头痴心爱着它头胎雏儿的母鸡似的，把你教养成人，送你献身疆场，又迎接你满载着光荣归来。要是我的请求是不正当的，你尽可以挥斥我回去；否则你就是不忠不孝，天神将要降祸于你，因为你不曾向你的母亲尽一个人子的义务。他转身去了；跪下来，让我们用屈膝羞辱他。附属于他那科利奥兰纳斯的姓氏上的，只有骄傲，没有一点怜悯。跪下来；完了，这是我们最后的哀求；我们现在要回到罗马去，和我们的邻人们死在一起。不，瞧着我们吧。这个小孩不会说他要些什么，只是陪着我们下跪举手，他代替我们呼吁的理由，比你拒绝的理由有力得多。来，我们去吧。这人有一个伏尔斯的母亲，他的妻子在科利奥里，他的孩子也许像他一样。可是请你给我们一个答复；我要等我们的城市在大火中焚烧以后，方才停止我的声音，那时候我也没有什么好说了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01182","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 \u003cb class=\"epub-calibre3\">（握伏伦妮娅手，沉默）\u003c/b>啊，母亲，母亲！您做了一件什么事啦？瞧！天都裂了开来，神明在俯视这一场悖逆的情景而讥笑我们了。啊，我的母亲！母亲！啊！您替罗马赢得了一场幸运的胜利；可是相信我，啊！相信我，被您战败的您的儿子，却已经遭遇着严重的危险了。可是让它来吧。奥菲狄乌斯，虽然我不能帮助你们战胜，可是我愿意为双方斡旋和平。好奥菲狄乌斯，要是你处在我的地位，你会听你的母亲这样说而不答应她吗？\u003c/p>\n","text":"科利奥兰纳斯 （握伏伦妮娅手，沉默）啊，母亲，母亲！您做了一件什么事啦？瞧！天都裂了开来，神明在俯视这一场悖逆的情景而讥笑我们了。啊，我的母亲！母亲！啊！您替罗马赢得了一场幸运的胜利；可是相信我，啊！相信我，被您战败的您的儿子，却已经遭遇着严重的危险了。可是让它来吧。奥菲狄乌斯，虽然我不能帮助你们战胜，可是我愿意为双方斡旋和平。好奥菲狄乌斯，要是你处在我的地位，你会听你的母亲这样说而不答应她吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01183","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 我心里非常感动。\u003c/p>\n","text":"奥菲狄乌斯 我心里非常感动。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01184","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 我敢发誓你一定受到感动。将军，要我的眼睛里流下同情的眼泪来，可不是一件容易的事呢。可是，好将军，你们想要缔结怎样的和平，请你告诉我；我自己并不到罗马，仍旧跟着你们一起回去；请你帮助我促成这一个目的吧。啊，母亲！妻子！\u003c/p>\n","text":"科利奥兰纳斯 我敢发誓你一定受到感动。将军，要我的眼睛里流下同情的眼泪来，可不是一件容易的事呢。可是，好将军，你们想要缔结怎样的和平，请你告诉我；我自己并不到罗马，仍旧跟着你们一起回去；请你帮助我促成这一个目的吧。啊，母亲！妻子！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01185","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 \u003cb class=\"epub-calibre3\">（旁白）\u003c/b>我很高兴你已经使慈悲和荣誉两种观念在你的心里互相抵触了；我可以利用这一个机会，恢复我以前的地位。\u003cb class=\"epub-calibre3\">（诸妇人向科利奥兰纳斯作手势示意。）\u003c/b>\u003c/p>\n","text":"奥菲狄乌斯 （旁白）我很高兴你已经使慈悲和荣誉两种观念在你的心里互相抵触了；我可以利用这一个机会，恢复我以前的地位。（诸妇人向科利奥兰纳斯作手势示意。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01186","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 好，那慢慢再说。我们先在一起喝杯酒；你们可以带一个比言语更确实的证据回去，那是我们在同样情形之下也会照样签署的。来，跟我们进去。夫人们，罗马应该为你们建造一座庙宇；意大利所有的刀剑和她的联合的军力，都不能缔结这样的和平。\u003cb class=\"epub-calibre3\">（同下。）\u003c/b>\u003c/p>\n","text":"科利奥兰纳斯 好，那慢慢再说。我们先在一起喝杯酒；你们可以带一个比言语更确实的证据回去，那是我们在同样情形之下也会照样签署的。来，跟我们进去。夫人们，罗马应该为你们建造一座庙宇；意大利所有的刀剑和她的联合的军力，都不能缔结这样的和平。（同下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第三场 科利奥兰纳斯营帐","headingLevel":4,"sourceAnchor":"a752","actNumber":5,"sceneNumber":3},{"id":"part0031-section-032","label":"第五幕 · 第四场 罗马。广场","kind":"scene","blocks":[{"id":"part0031-01187","html":"\u003ch4 id=\"epub-part0031-a753\" class=\"epub-calibre12\">第四场 罗马。广场\u003c/h4>\n","text":"第四场 罗马。广场\n","sourceAnchor":"a753","tag":"h4"},{"id":"part0031-01188","html":"\u003cp class=\"epub-block1\">米尼涅斯及西西涅斯上。\u003c/p>\n","text":"米尼涅斯及西西涅斯上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01189","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 你看见那边庙堂上的基石吗？\u003c/p>\n","text":"米尼涅斯 你看见那边庙堂上的基石吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01190","html":"\u003cp class=\"epub-calibre1\">西西涅斯 看见了又怎样？\u003c/p>\n","text":"西西涅斯 看见了又怎样？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01191","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 要是你能够用你的小指头把它移动，那么，罗马的妇女们，尤其是他的母亲，也许有几分希望可以把他说服。可是我说，再也不会有什么希望了。我们只是在伸着头颈等候人家来切断我们的咽喉。\u003c/p>\n","text":"米尼涅斯 要是你能够用你的小指头把它移动，那么，罗马的妇女们，尤其是他的母亲，也许有几分希望可以把他说服。可是我说，再也不会有什么希望了。我们只是在伸着头颈等候人家来切断我们的咽喉。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01192","html":"\u003cp class=\"epub-calibre1\">西西涅斯 难道在这样短短的时间里，一个人会改变得这样厉害吗？\u003c/p>\n","text":"西西涅斯 难道在这样短短的时间里，一个人会改变得这样厉害吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01193","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 毛虫和蝴蝶是大不相同的，可是蝴蝶就是从毛虫变化而成的。这马歇斯已经从一个人变成一条龙了；他已经生了翅膀，不再是一个爬行的东西了。\u003c/p>\n","text":"米尼涅斯 毛虫和蝴蝶是大不相同的，可是蝴蝶就是从毛虫变化而成的。这马歇斯已经从一个人变成一条龙了；他已经生了翅膀，不再是一个爬行的东西了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01194","html":"\u003cp class=\"epub-calibre1\">西西涅斯 他本来是很孝敬他的母亲的。\u003c/p>\n","text":"西西涅斯 他本来是很孝敬他的母亲的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01195","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 他本来也很爱我；可是他现在就像一匹八岁的马，完全忘记他的母亲了。他脸上那股凶相，可以使熟葡萄变酸；他走起路来，就像一辆战车开过，把土地都震陷了；他的目光可以穿透甲胄；他的说话有如丧钟，哼一声也像大炮的轰鸣。他坐在尊严的宝座上，好像只有亚历山大才可以和他对抗。他的命令一发出，事情就已经办好。他全然是一个天神，只缺少永生和一个可以雄踞的天庭。\u003c/p>\n","text":"米尼涅斯 他本来也很爱我；可是他现在就像一匹八岁的马，完全忘记他的母亲了。他脸上那股凶相，可以使熟葡萄变酸；他走起路来，就像一辆战车开过，把土地都震陷了；他的目光可以穿透甲胄；他的说话有如丧钟，哼一声也像大炮的轰鸣。他坐在尊严的宝座上，好像只有亚历山大才可以和他对抗。他的命令一发出，事情就已经办好。他全然是一个天神，只缺少永生和一个可以雄踞的天庭。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01196","html":"\u003cp class=\"epub-calibre1\">西西涅斯 要是你说得他不错，那么他还缺少天神应有的慈悲。\u003c/p>\n","text":"西西涅斯 要是你说得他不错，那么他还缺少天神应有的慈悲。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01197","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 我不过照他的本相描写他。你瞧着吧，他的母亲将会从他那儿带些什么慈悲来。他要是会发慈悲，那么雄虎身上也会有乳汁了；我们这不幸的城市就可以发现这一个真理，这一切都是为了你们的缘故！\u003c/p>\n","text":"米尼涅斯 我不过照他的本相描写他。你瞧着吧，他的母亲将会从他那儿带些什么慈悲来。他要是会发慈悲，那么雄虎身上也会有乳汁了；我们这不幸的城市就可以发现这一个真理，这一切都是为了你们的缘故！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01198","html":"\u003cp class=\"epub-calibre1\">西西涅斯 但愿神明护佑我们！\u003c/p>\n","text":"西西涅斯 但愿神明护佑我们！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01199","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 不，神明在这种事情上是不会护佑我们的。当我们把他放逐的时候，我们就已经冒犯了神明；现在他回来杀我们的头，神明也不会可怜我们。\u003c/p>\n","text":"米尼涅斯 不，神明在这种事情上是不会护佑我们的。当我们把他放逐的时候，我们就已经冒犯了神明；现在他回来杀我们的头，神明也不会可怜我们。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01200","html":"\u003cp class=\"epub-block1\">一使者上。\u003c/p>\n","text":"一使者上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01201","html":"\u003cp class=\"epub-calibre1\">使者 先生，您要是爱惜性命，赶快逃回家里躲起来吧。民众已经把你们那一位护民官捉住，把他拖来拖去，大家发誓说要是那几位罗马妇女不把好消息带回来，就要把他寸寸磔死。\u003c/p>\n","text":"使者 先生，您要是爱惜性命，赶快逃回家里躲起来吧。民众已经把你们那一位护民官捉住，把他拖来拖去，大家发誓说要是那几位罗马妇女不把好消息带回来，就要把他寸寸磔死。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01202","html":"\u003cp class=\"epub-block1\">另一使者上。\u003c/p>\n","text":"另一使者上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01203","html":"\u003cp class=\"epub-calibre1\">西西涅斯 有什么消息？\u003c/p>\n","text":"西西涅斯 有什么消息？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01204","html":"\u003cp class=\"epub-calibre1\">使者乙 好消息！好消息！那几位夫人已经得到胜利，伏尔斯军队撤退了，马歇斯也去了。罗马从来不曾有过这样欢乐的日子；就是击退塔昆的时候，也不及今天这样高兴。\u003c/p>\n","text":"使者乙 好消息！好消息！那几位夫人已经得到胜利，伏尔斯军队撤退了，马歇斯也去了。罗马从来不曾有过这样欢乐的日子；就是击退塔昆的时候，也不及今天这样高兴。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01205","html":"\u003cp class=\"epub-calibre1\">西西涅斯 朋友，你能够确定这句话是真的吗？全然是正确的吗？\u003c/p>\n","text":"西西涅斯 朋友，你能够确定这句话是真的吗？全然是正确的吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01206","html":"\u003cp class=\"epub-calibre1\">使者乙 正像我知道太阳是一团火一样正确。您究竟躲在什么地方，才会不相信这句话呢？好消息传进城里，是比潮水冲过桥孔还快的。你听！\u003cb class=\"epub-calibre3\">（喇叭箫鼓声同时并奏，内欢呼声）\u003c/b>喇叭、号筒、弦琴、横笛、手鼓、铙钹，还有欢呼的罗马人，使太阳都跳起舞来了。您听！\u003cb class=\"epub-calibre3\">（内欢呼声。）\u003c/b>\u003c/p>\n","text":"使者乙 正像我知道太阳是一团火一样正确。您究竟躲在什么地方，才会不相信这句话呢？好消息传进城里，是比潮水冲过桥孔还快的。你听！（喇叭箫鼓声同时并奏，内欢呼声）喇叭、号筒、弦琴、横笛、手鼓、铙钹，还有欢呼的罗马人，使太阳都跳起舞来了。您听！（内欢呼声。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01207","html":"\u003cp class=\"epub-calibre1\">米尼涅斯 这果然是好消息。我要去迎接那几位夫人。这位伏伦妮娅抵得过全城的执政、元老和贵族；比起像你们这样的护民官来，那么盈海盈陆的护民官，也抵不上她一个人。你们今天祷告得很有灵验；今天早上我还不愿出一个铜子来买你们一万条喉咙哩。听，他们多么快乐！\u003cb class=\"epub-calibre3\">（乐声，欢呼声继续。）\u003c/b>\u003c/p>\n","text":"米尼涅斯 这果然是好消息。我要去迎接那几位夫人。这位伏伦妮娅抵得过全城的执政、元老和贵族；比起像你们这样的护民官来，那么盈海盈陆的护民官，也抵不上她一个人。你们今天祷告得很有灵验；今天早上我还不愿出一个铜子来买你们一万条喉咙哩。听，他们多么快乐！（乐声，欢呼声继续。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01208","html":"\u003cp class=\"epub-calibre1\">西西涅斯 第一，你带了这样好消息来，愿神明祝福你；第二，请你接受我的感谢。\u003c/p>\n","text":"西西涅斯 第一，你带了这样好消息来，愿神明祝福你；第二，请你接受我的感谢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01209","html":"\u003cp class=\"epub-calibre1\">使者乙 先生，我们大家都应该感谢上天。\u003c/p>\n","text":"使者乙 先生，我们大家都应该感谢上天。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01210","html":"\u003cp class=\"epub-calibre1\">西西涅斯 她们已经离城很近了吗？\u003c/p>\n","text":"西西涅斯 她们已经离城很近了吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01211","html":"\u003cp class=\"epub-calibre1\">使者乙 快要进城来了。\u003c/p>\n","text":"使者乙 快要进城来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01212","html":"\u003cp class=\"epub-calibre1\">西西涅斯 我们也去迎接她们，凑凑热闹。\u003cb class=\"epub-calibre3\">（欲去。）\u003c/b>\u003c/p>\n","text":"西西涅斯 我们也去迎接她们，凑凑热闹。（欲去。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01213","html":"\u003cp class=\"epub-block1\">伏伦妮娅、维吉利娅、凡勒利娅等由元老、贵族、民众等簇拥而上，自台前穿过。\u003c/p>\n","text":"伏伦妮娅、维吉利娅、凡勒利娅等由元老、贵族、民众等簇拥而上，自台前穿过。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01214","html":"\u003cp class=\"epub-calibre1\">元老甲 瞧我们的女恩人，罗马的生命！召集你们的部族，赞美神明，燃起庆祝的火炬来；在她们的面前散布鲜花；用欢迎他母亲的呼声，代替你们从前要求放逐马歇斯的鼓噪，大家喊，“欢迎，夫人们，欢迎！”\u003c/p>\n","text":"元老甲 瞧我们的女恩人，罗马的生命！召集你们的部族，赞美神明，燃起庆祝的火炬来；在她们的面前散布鲜花；用欢迎他母亲的呼声，代替你们从前要求放逐马歇斯的鼓噪，大家喊，“欢迎，夫人们，欢迎！”\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01215","html":"\u003cp class=\"epub-calibre1\">众人 欢迎，夫人们，欢迎！\u003cb class=\"epub-calibre3\">（鼓角各奏花腔；众人下。）\u003c/b>\u003c/p>\n","text":"众人 欢迎，夫人们，欢迎！（鼓角各奏花腔；众人下。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第四场 罗马。广场","headingLevel":4,"sourceAnchor":"a753","actNumber":5,"sceneNumber":4},{"id":"part0031-section-033","label":"第五幕 · 第五场 科利奥里。广场","kind":"scene","blocks":[{"id":"part0031-01216","html":"\u003ch4 id=\"epub-part0031-a754\" class=\"epub-calibre12\">第五场 科利奥里。广场\u003c/h4>\n","text":"第五场 科利奥里。广场\n","sourceAnchor":"a754","tag":"h4"},{"id":"part0031-01217","html":"\u003cp class=\"epub-block1\">塔勒斯·奥菲狄乌斯及侍从等上。\u003c/p>\n","text":"塔勒斯·奥菲狄乌斯及侍从等上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01218","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 你们去通知城里的官员们，说我已经到了；把这封信交给他们，叫他们读了以后，就到市场上去，我要在那边当着他们和民众，证明这信里所写的话。我所控告的那个人，现在大概也进了城，他也想在民众面前用言语替他自己辩解；你们快去吧。\u003cb class=\"epub-calibre3\">（侍从等下。）\u003c/b>\u003c/p>\n","text":"奥菲狄乌斯 你们去通知城里的官员们，说我已经到了；把这封信交给他们，叫他们读了以后，就到市场上去，我要在那边当着他们和民众，证明这信里所写的话。我所控告的那个人，现在大概也进了城，他也想在民众面前用言语替他自己辩解；你们快去吧。（侍从等下。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01219","html":"\u003cp class=\"epub-block1\">奥菲狄乌斯党羽三四人上。\u003c/p>\n","text":"奥菲狄乌斯党羽三四人上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01220","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 非常欢迎！\u003c/p>\n","text":"奥菲狄乌斯 非常欢迎！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01221","html":"\u003cp class=\"epub-calibre1\">党徒甲 我们的主帅安好？\u003c/p>\n","text":"党徒甲 我们的主帅安好？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01222","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 别提啦，我正像一个被自己的布施所毒害、被自己的善心所杀死的人。\u003c/p>\n","text":"奥菲狄乌斯 别提啦，我正像一个被自己的布施所毒害、被自己的善心所杀死的人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01223","html":"\u003cp class=\"epub-calibre1\">党徒乙 主帅，要是您仍旧希望我们帮助您实行原来的计划，我们一定愿意替您解除您的重大的危险。\u003c/p>\n","text":"党徒乙 主帅，要是您仍旧希望我们帮助您实行原来的计划，我们一定愿意替您解除您的重大的危险。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01224","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 现在我还不能说；我们必须在明白人民的心理以后，再决定怎么办。\u003c/p>\n","text":"奥菲狄乌斯 现在我还不能说；我们必须在明白人民的心理以后，再决定怎么办。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01225","html":"\u003cp class=\"epub-calibre1\">党徒丙 当你们两人继续对立的时候，人民的喜怒也不会有一定的方向；可是你们中间无论哪一个人倒下以后，还有那一个人就可以为众望所归。\u003c/p>\n","text":"党徒丙 当你们两人继续对立的时候，人民的喜怒也不会有一定的方向；可是你们中间无论哪一个人倒下以后，还有那一个人就可以为众望所归。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01226","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 我知道；我必须找到一个振振有辞的借口，方才可以对他作无情的抨击。他是我提拔起来的人，我用自己的名誉担保他的忠心；可是他这样跻登贵显以后，就用谄媚的露水灌溉他的新栽的树木，引诱我的朋友们归附他，为了这一个目的，他方才有意抑制他的粗暴倔强、不受拘束的性格，装出一副卑躬屈节的态度。\u003c/p>\n","text":"奥菲狄乌斯 我知道；我必须找到一个振振有辞的借口，方才可以对他作无情的抨击。他是我提拔起来的人，我用自己的名誉担保他的忠心；可是他这样跻登贵显以后，就用谄媚的露水灌溉他的新栽的树木，引诱我的朋友们归附他，为了这一个目的，他方才有意抑制他的粗暴倔强、不受拘束的性格，装出一副卑躬屈节的态度。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01227","html":"\u003cp class=\"epub-calibre1\">党徒丙 主帅，他在候选执政的时候，因为过于傲慢而落选——\u003c/p>\n","text":"党徒丙 主帅，他在候选执政的时候，因为过于傲慢而落选——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01228","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 那正是我要说起的事：他因为得罪了罗马的民众，被他们放逐出境，他就到我的家里来，向我伸颈就戮；我收容了他，使他成为我的同僚，一切满足他的要求；甚至于为了帮助他完成他的目的起见，让他在我的部队中间亲自挑选最勇壮的兵士；我自己也尽力协助他，和他分任劳苦，却让他一个人收到名誉。我这样挫抑着自己，非但毫无怨尤，而且还自以为成人之美，是一件值得自豪的事。直到后来，我仿佛变成了他的下属，而不是他的同僚了；他对我老是露出不屑的神气，好像我是一个贪利之徒一样。\u003c/p>\n","text":"奥菲狄乌斯 那正是我要说起的事：他因为得罪了罗马的民众，被他们放逐出境，他就到我的家里来，向我伸颈就戮；我收容了他，使他成为我的同僚，一切满足他的要求；甚至于为了帮助他完成他的目的起见，让他在我的部队中间亲自挑选最勇壮的兵士；我自己也尽力协助他，和他分任劳苦，却让他一个人收到名誉。我这样挫抑着自己，非但毫无怨尤，而且还自以为成人之美，是一件值得自豪的事。直到后来，我仿佛变成了他的下属，而不是他的同僚了；他对我老是露出不屑的神气，好像我是一个贪利之徒一样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01229","html":"\u003cp class=\"epub-calibre1\">党徒甲 他正是这样，主帅；全军都觉得非常奇怪。后来我们向罗马长驱直进，满以为这次一定可以大获全胜——\u003c/p>\n","text":"党徒甲 他正是这样，主帅；全军都觉得非常奇怪。后来我们向罗马长驱直进，满以为这次一定可以大获全胜——\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01230","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 正是；为了这一次的事情，我也一定要把他亲手扑杀。单单几滴像谎话一样不值钱的女人的眼泪，就会使他出卖了我们在这次伟大的行动中所抛掷的血汗和劳力。他非死不可，他的没落才是我出头的机会。可是听！\u003cb class=\"epub-calibre3\">（鼓角声，夹杂人民高呼声。）\u003c/b>\u003c/p>\n","text":"奥菲狄乌斯 正是；为了这一次的事情，我也一定要把他亲手扑杀。单单几滴像谎话一样不值钱的女人的眼泪，就会使他出卖了我们在这次伟大的行动中所抛掷的血汗和劳力。他非死不可，他的没落才是我出头的机会。可是听！（鼓角声，夹杂人民高呼声。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01231","html":"\u003cp class=\"epub-calibre1\">党徒甲 您走进您自己的故乡，就像到一处驿站一样，不曾有一个人欢迎您回来；可是他回来的时候，那喧哗的声音却把天都震破了。\u003c/p>\n","text":"党徒甲 您走进您自己的故乡，就像到一处驿站一样，不曾有一个人欢迎您回来；可是他回来的时候，那喧哗的声音却把天都震破了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01232","html":"\u003cp class=\"epub-calibre1\">党徒乙 那些健忘的傻瓜们，没有想到他曾经杀死他们的子女，却拼命张开他们卑贱的喉咙来向他称颂。\u003c/p>\n","text":"党徒乙 那些健忘的傻瓜们，没有想到他曾经杀死他们的子女，却拼命张开他们卑贱的喉咙来向他称颂。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01233","html":"\u003cp class=\"epub-calibre1\">党徒丙 所以您应该趁他没有为自己辩白、凭着他的利嘴鼓动人心以前，就让他死在您的剑下，我们一定会帮助您。等他死了以后，您就可以用您自己的话宣布他的罪状，即使他有天大的理由，也只好和他的尸体一同埋葬了。\u003c/p>\n","text":"党徒丙 所以您应该趁他没有为自己辩白、凭着他的利嘴鼓动人心以前，就让他死在您的剑下，我们一定会帮助您。等他死了以后，您就可以用您自己的话宣布他的罪状，即使他有天大的理由，也只好和他的尸体一同埋葬了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01234","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 不要说下去；官员们来了。\u003c/p>\n","text":"奥菲狄乌斯 不要说下去；官员们来了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01235","html":"\u003cp class=\"epub-block1\">城中众官员上。\u003c/p>\n","text":"城中众官员上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01236","html":"\u003cp class=\"epub-calibre1\">众官 您回来了，欢迎得很！\u003c/p>\n","text":"众官 您回来了，欢迎得很！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01237","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 我不值得受各位这样的欢迎。可是，各位大人，你们有没有用心读过我写给你们的信？\u003c/p>\n","text":"奥菲狄乌斯 我不值得受各位这样的欢迎。可是，各位大人，你们有没有用心读过我写给你们的信？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01238","html":"\u003cp class=\"epub-calibre1\">众官 我们已经读过了。\u003c/p>\n","text":"众官 我们已经读过了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01239","html":"\u003cp class=\"epub-calibre1\">官甲 并且很觉得痛心。他以前所犯的种种错误，我想未始不可以从宽处分；可是他这样越过一切的界限，轻轻地放弃了我们厉兵秣马去谋取的利益，擅作主张，和一个濒于屈膝的城市缔结休战的条约，这是绝对不可容恕的。\u003c/p>\n","text":"官甲 并且很觉得痛心。他以前所犯的种种错误，我想未始不可以从宽处分；可是他这样越过一切的界限，轻轻地放弃了我们厉兵秣马去谋取的利益，擅作主张，和一个濒于屈膝的城市缔结休战的条约，这是绝对不可容恕的。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01240","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 他来了；你们可以听听他怎么说。\u003c/p>\n","text":"奥菲狄乌斯 他来了；你们可以听听他怎么说。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01241","html":"\u003cp class=\"epub-block1\">科利奥兰纳斯上，旗鼓前导，一群市民随上。\u003c/p>\n","text":"科利奥兰纳斯上，旗鼓前导，一群市民随上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01242","html":"\u003cp class=\"epub-center\">\u003cimg src=\"data/chinese-collection/images/00156.jpeg\" alt=\"\" loading=\"lazy\" class=\"epub-calibre2 epub-image\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01243","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 祝福，各位大人！我回来了，仍旧是你们的兵士，仍旧像我去国的时候一样对自己的祖国没有一点眷恋，一心一意接受你们伟大的命令。让我报告你们知道，我已经顺利地执行了我的使命，用鲜血打开了一条大道，直达罗马的城前。我们这次带回来的战利品，足足抵偿出征费用的三分之一而有余。我们已经缔结和约，使安息人得到极大的光荣，但是对罗马人也并不过于难堪。这儿就是已经由罗马的执政和贵族签字，并由元老院盖印核准的我们所议定的条件，现在我把它呈献给各位了。\u003c/p>\n","text":"科利奥兰纳斯 祝福，各位大人！我回来了，仍旧是你们的兵士，仍旧像我去国的时候一样对自己的祖国没有一点眷恋，一心一意接受你们伟大的命令。让我报告你们知道，我已经顺利地执行了我的使命，用鲜血打开了一条大道，直达罗马的城前。我们这次带回来的战利品，足足抵偿出征费用的三分之一而有余。我们已经缔结和约，使安息人得到极大的光荣，但是对罗马人也并不过于难堪。这儿就是已经由罗马的执政和贵族签字，并由元老院盖印核准的我们所议定的条件，现在我把它呈献给各位了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01244","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 不要读它，各位大人；对这个叛徒说，他已经越权滥用你们的权力，罪在不赦了。\u003c/p>\n","text":"奥菲狄乌斯 不要读它，各位大人；对这个叛徒说，他已经越权滥用你们的权力，罪在不赦了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01245","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 叛徒！怎么？\u003c/p>\n","text":"科利奥兰纳斯 叛徒！怎么？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01246","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 是的，叛徒，马歇斯。\u003c/p>\n","text":"奥菲狄乌斯 是的，叛徒，马歇斯。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01247","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 马歇斯！\u003c/p>\n","text":"科利奥兰纳斯 马歇斯！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01248","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 是的，马歇斯，卡厄斯·马歇斯。你以为我会在科利奥里用你那个盗窃得来的名字科利奥兰纳斯称呼你吗？各位执政的大臣，他已经不忠不信地辜负了你们的付托，为了几滴眼泪的缘故，把你们的罗马城放弃在他的母亲妻子的手里——听着，我说罗马是“你们的城市”。他破坏他的盟誓和决心，就像拉断一绞烂丝一样，也没有咨询其他将领的意见，就这样痛哭号呼地牺牲了你们的胜利；他这种卑怯的行动，使孩儿们也代他羞愧，勇士们都面面相觑，愕然失色。\u003c/p>\n","text":"奥菲狄乌斯 是的，马歇斯，卡厄斯·马歇斯。你以为我会在科利奥里用你那个盗窃得来的名字科利奥兰纳斯称呼你吗？各位执政的大臣，他已经不忠不信地辜负了你们的付托，为了几滴眼泪的缘故，把你们的罗马城放弃在他的母亲妻子的手里——听着，我说罗马是“你们的城市”。他破坏他的盟誓和决心，就像拉断一绞烂丝一样，也没有咨询其他将领的意见，就这样痛哭号呼地牺牲了你们的胜利；他这种卑怯的行动，使孩儿们也代他羞愧，勇士们都面面相觑，愕然失色。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01249","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你听见吗，战神马斯？\u003c/p>\n","text":"科利奥兰纳斯 你听见吗，战神马斯？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01250","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 不要提起天神的名字，你这善哭的孩子！\u003c/p>\n","text":"奥菲狄乌斯 不要提起天神的名字，你这善哭的孩子！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01251","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 嘿！\u003c/p>\n","text":"科利奥兰纳斯 嘿！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01252","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 我的话就是这样。\u003c/p>\n","text":"奥菲狄乌斯 我的话就是这样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01253","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 你这漫天说谎的家伙，我的心都气得快要胀破了。孩子！啊，你这奴才！恕我，各位大人，这是我第一次迫不得已的骂人。请各位秉公判断，痛斥这狗子的妄言。他身上还留着我鞭笞的痕迹，我总要把他打下坟墓里去。\u003c/p>\n","text":"科利奥兰纳斯 你这漫天说谎的家伙，我的心都气得快要胀破了。孩子！啊，你这奴才！恕我，各位大人，这是我第一次迫不得已的骂人。请各位秉公判断，痛斥这狗子的妄言。他身上还留着我鞭笞的痕迹，我总要把他打下坟墓里去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01254","html":"\u003cp class=\"epub-calibre1\">官甲 两个人都不要闹，听我说话。\u003c/p>\n","text":"官甲 两个人都不要闹，听我说话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01255","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 把我斩成片段吧，伏尔斯人；成人和儿童们，让你们的剑上都沾着我的血吧。孩子！说谎的狗！要是你们的历史上记载的是实事，那么你们可以翻开来看一看，我曾经怎样像一头鸽棚里的鹰似的，在科利奥里城里单拳独掌，把你们这些伏尔斯人打得落花流水。孩子！\u003c/p>\n","text":"科利奥兰纳斯 把我斩成片段吧，伏尔斯人；成人和儿童们，让你们的剑上都沾着我的血吧。孩子！说谎的狗！要是你们的历史上记载的是实事，那么你们可以翻开来看一看，我曾经怎样像一头鸽棚里的鹰似的，在科利奥里城里单拳独掌，把你们这些伏尔斯人打得落花流水。孩子！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01256","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 嘿，各位大人；你们愿意让这个亵渎神圣、大言不惭的狂徒当着你们的耳目，夸耀他的盲目的侥幸，使你们回想到你们的耻辱吗？\u003c/p>\n","text":"奥菲狄乌斯 嘿，各位大人；你们愿意让这个亵渎神圣、大言不惭的狂徒当着你们的耳目，夸耀他的盲目的侥幸，使你们回想到你们的耻辱吗？\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01257","html":"\u003cp class=\"epub-calibre1\">众党徒 杀死他，杀死他！\u003c/p>\n","text":"众党徒 杀死他，杀死他！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01258","html":"\u003cp class=\"epub-calibre1\">众市民 撕碎他的身体！——立刻杀死他！——他杀死我的儿子！——我的女儿！——他杀死了我的族兄玛克斯！——他杀死了我的父亲！\u003c/p>\n","text":"众市民 撕碎他的身体！——立刻杀死他！——他杀死我的儿子！——我的女儿！——他杀死了我的族兄玛克斯！——他杀死了我的父亲！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01259","html":"\u003cp class=\"epub-calibre1\">官乙 静下来，喂！不许行暴；静下来！这人是一个英雄，他的名誉广播世间。他对于我们所犯的罪行，必须用合法的手续审判。站住，奥菲狄乌斯，不要扰乱治安。\u003c/p>\n","text":"官乙 静下来，喂！不许行暴；静下来！这人是一个英雄，他的名誉广播世间。他对于我们所犯的罪行，必须用合法的手续审判。站住，奥菲狄乌斯，不要扰乱治安。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01260","html":"\u003cp class=\"epub-calibre1\">科利奥兰纳斯 啊！要是我的剑在手头，即使有六个奥菲狄乌斯，或者他的所有的党徒都在我的面前，我也一定要结果他的性命！\u003c/p>\n","text":"科利奥兰纳斯 啊！要是我的剑在手头，即使有六个奥菲狄乌斯，或者他的所有的党徒都在我的面前，我也一定要结果他的性命！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01261","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 放肆的恶徒！\u003c/p>\n","text":"奥菲狄乌斯 放肆的恶徒！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01262","html":"\u003cp class=\"epub-calibre1\">众党徒 杀，杀，杀，杀，杀死他！\u003cb class=\"epub-calibre3\">（奥菲狄乌斯及众党徒拔剑杀科利奥兰纳斯，科利奥兰纳斯倒地；奥菲狄乌斯立于科利奥兰纳斯尸体上。）\u003c/b>\u003c/p>\n","text":"众党徒 杀，杀，杀，杀，杀死他！（奥菲狄乌斯及众党徒拔剑杀科利奥兰纳斯，科利奥兰纳斯倒地；奥菲狄乌斯立于科利奥兰纳斯尸体上。）\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01263","html":"\u003cp class=\"epub-calibre1\">众官 住手，住手，住手，住手！\u003c/p>\n","text":"众官 住手，住手，住手，住手！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01264","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 各位朋友，听我说话。\u003c/p>\n","text":"奥菲狄乌斯 各位朋友，听我说话。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01265","html":"\u003cp class=\"epub-calibre1\">官甲 啊，塔勒斯！\u003c/p>\n","text":"官甲 啊，塔勒斯！\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01266","html":"\u003cp class=\"epub-calibre1\">官乙 你已经做了一件将要使勇士们悲泣的事了。\u003c/p>\n","text":"官乙 你已经做了一件将要使勇士们悲泣的事了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01267","html":"\u003cp class=\"epub-calibre1\">官丙 不要踏在他的身上。各位朋友，静下来。收好你们的剑。\u003c/p>\n","text":"官丙 不要踏在他的身上。各位朋友，静下来。收好你们的剑。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01268","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 各位大人，这次暴行完全是他自己向我们挑衅的结果，你们已经亲眼瞧见他的行为，一定知道这一个人的存在对于你们是一种多大的危险，现在我们已经除去这一个祸患，你们应该引为莫大的幸事。请你们把我传到你们的元老院里去质询吧，我愿意呈献我自己做你们的忠仆，或者受你们最严厉的处分。\u003c/p>\n","text":"奥菲狄乌斯 各位大人，这次暴行完全是他自己向我们挑衅的结果，你们已经亲眼瞧见他的行为，一定知道这一个人的存在对于你们是一种多大的危险，现在我们已经除去这一个祸患，你们应该引为莫大的幸事。请你们把我传到你们的元老院里去质询吧，我愿意呈献我自己做你们的忠仆，或者受你们最严厉的处分。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01269","html":"\u003cp class=\"epub-calibre1\">官甲 把他的尸体搬去；你们大家为他悲泣，用最隆重的敬礼表示哀思吧。\u003c/p>\n","text":"官甲 把他的尸体搬去；你们大家为他悲泣，用最隆重的敬礼表示哀思吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01270","html":"\u003cp class=\"epub-calibre1\">官乙 他自己的躁急，免去了奥菲狄乌斯大部分的责任。事情已经到这个地步，我们还是商量善后的处置吧。\u003c/p>\n","text":"官乙 他自己的躁急，免去了奥菲狄乌斯大部分的责任。事情已经到这个地步，我们还是商量善后的处置吧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01271","html":"\u003cp class=\"epub-calibre1\">奥菲狄乌斯 我的愤怒已经消失，我感到深深的悔恨。把他抬起来；让三个重要的军人帮着抬他的尸体，我自己也做其中的一个。鼓手，在你的鼓上敲出沉痛的节奏来；把你们的钢矛倒拖在地上行走。虽然他在这城里杀死了许多人的丈夫儿女，使他们至今吞声饮泣，可是他必须有一个光荣的葬礼。大家帮着我。\u003cb class=\"epub-calibre3\">（众抬科利奥兰纳斯尸体同下；奏丧礼进行曲。）\u003c/b>\u003c/p>\n","text":"奥菲狄乌斯 我的愤怒已经消失，我感到深深的悔恨。把他抬起来；让三个重要的军人帮着抬他的尸体，我自己也做其中的一个。鼓手，在你的鼓上敲出沉痛的节奏来；把你们的钢矛倒拖在地上行走。虽然他在这城里杀死了许多人的丈夫儿女，使他们至今吞声饮泣，可是他必须有一个光荣的葬礼。大家帮着我。（众抬科利奥兰纳斯尸体同下；奏丧礼进行曲。）\n","sourceAnchor":null,"tag":"p"}],"heading":"第五场 科利奥里。广场","headingLevel":4,"sourceAnchor":"a754","actNumber":5,"sceneNumber":5},{"id":"part0031-section-034","label":"注释","kind":"notes","blocks":[{"id":"part0031-01272","html":"\u003chr class=\"epub-calibre14\">","text":"","sourceAnchor":null,"tag":"hr"},{"id":"part0031-01273","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0031-m001\">\u003c/a>\u003ca href=\"#epub-part0031-w001\" data-source-anchor=\"w001\">[1]\u003c/a>珀涅罗珀是俄底修斯之妻，以贞节著称，在家乡等候了俄底修斯二十年。\u003c/p>\n","text":" [1]珀涅罗珀是俄底修斯之妻，以贞节著称，在家乡等候了俄底修斯二十年。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01274","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0031-m002\">\u003c/a>\u003ca href=\"#epub-part0031-w002\" data-source-anchor=\"w002\">[2]\u003c/a>凯图（Cato，公元前234—公元前149），古罗马的爱国军人。\u003c/p>\n","text":" [2]凯图（Cato，公元前234—公元前149），古罗马的爱国军人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0031-01275","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0031-m003\">\u003c/a>\u003ca href=\"#epub-part0031-w003\" data-source-anchor=\"w003\">[3]\u003c/a>大帕岩是加比托林山的悬崖，古罗马人将叛国犯人由此推下摔死。\u003c/p>\n","text":" [3]大帕岩是加比托林山的悬崖，古罗马人将叛国犯人由此推下摔死。\n","sourceAnchor":null,"tag":"p"}],"heading":"","headingLevel":null,"sourceAnchor":null}],"language":"zh","alignment":"none","source":{"type":"user-provided-epub","title":"莎士比亚全集","publisher":"人民文学出版社","isbn":"978-7-02-010568-7","epubSha256":"e0385e88e1428b9accb344d45650a0f52ea1d917cbb12009036b2fb32fd9b747","attribution":"朱生豪等译（逐作保留原书署名）","path":"text/part0031.html","blockCount":1276,"imageCount":7,"textSha256":"44d130e7f8b8084b45ae1555c802ea3101b61abb2fd9ba021bdd531b6dbb43fc","anchorSections":{"a721":"part0031-section-000","a722":"part0031-section-001","a723":"part0031-section-002","a724":"part0031-section-003","a725":"part0031-section-004","w001":"part0031-section-004","a726":"part0031-section-005","w002":"part0031-section-005","a727":"part0031-section-006","a728":"part0031-section-007","a729":"part0031-section-008","a730":"part0031-section-009","a731":"part0031-section-010","a732":"part0031-section-011","a733":"part0031-section-012","a734":"part0031-section-013","a735":"part0031-section-014","a736":"part0031-section-015","a737":"part0031-section-016","a738":"part0031-section-017","w003":"part0031-section-017","a739":"part0031-section-018","a740":"part0031-section-019","a741":"part0031-section-020","a742":"part0031-section-021","a743":"part0031-section-022","a744":"part0031-section-023","a745":"part0031-section-024","a746":"part0031-section-025","a747":"part0031-section-026","a748":"part0031-section-027","a749":"part0031-section-028","a750":"part0031-section-029","a751":"part0031-section-030","a752":"part0031-section-031","a753":"part0031-section-032","a754":"part0031-section-033","m001":"part0031-section-034","m002":"part0031-section-034","m003":"part0031-section-034"},"note":"用户提供的多译者 EPUB；保留原书署名、注释与图像。未作逐句双语对齐。"}};
